insert into public.markets (slug, icon, sort, relevance, content) values ('artisans', 'wrench', 1, 5, '{"en":{"name":"Artisans","who":"Plumbers, electricians, carpenters, painters, locksmiths — skilled trades working for private clients and small businesses.","why":"Their work is excellent, but prospects check them online before calling — and often find nothing convincing.","problem":"Word of mouth is no longer enough, the business is poorly presented online, and requests get lost between calls, texts and social media.","angle":"Don’t sell “a small website”: sell the result — more trust, requests that arrive complete, and a business that looks as professional online as on site.","message":"Hello {{firstName}}, I came across {{company}}. Quick question: when someone hears about you and looks you up online, what do they find? I work with Studio ATS, which gives trades a professional presence that collects complete requests (job, place, timing) even while you’re on site. Worth 10 minutes? {{affiliateUrl}}","searches":["plombier [city]","électricien [city]","menuisier [city]","artisan peintre [city]"],"pains":["Word of mouth alone doesn’t fill the calendar","The business is poorly presented online","Prospects check the company online before calling","Requests get lost while working on site","No time to answer every message quickly","Dependence on social networks they don’t control"],"needs":["Look credible in 10 seconds","Receive requests with the right details","Not spend evenings on admin"],"outcomes":["More trust from people who don’t know them yet","A professional presence that matches the quality of their work","Requests centralised in one place","Available 24/7, even while on a job","Better conversion of visitors into real requests"],"discovery":["How do most of your new clients find you today?","What happens when someone looks you up online?","How many calls or messages do you miss while on a job?","Which jobs would you like more of?"],"avoid":"Never pitch it as “a small website” — talk about trust, complete requests and time saved."},"fr":{"name":"Artisans","who":"Plombiers, électriciens, menuisiers, peintres, serruriers — métiers du bâtiment et de l’entretien travaillant pour des particuliers et des petites entreprises.","why":"Leur travail est excellent, mais les prospects les vérifient en ligne avant d’appeler — et trouvent souvent peu de choses rassurantes.","problem":"Le bouche-à-oreille ne suffit plus, l’activité est mal présentée en ligne et les demandes se perdent entre appels, SMS et réseaux sociaux.","angle":"Ne vendez pas « un petit site internet » : vendez le résultat — plus de confiance, des demandes complètes et une entreprise aussi professionnelle en ligne que sur le chantier.","message":"Bonjour {{firstName}}, j’ai découvert {{company}}. Petite question : quand quelqu’un entend parler de vous et vous cherche en ligne, que trouve-t-il ? Je travaille avec Studio ATS, qui donne aux artisans une présence professionnelle qui recueille des demandes complètes (travaux, lieu, délai), même pendant que vous êtes sur un chantier. Ça vaut 10 minutes ? {{affiliateUrl}}","searches":["plombier [ville]","électricien [ville]","menuisier [ville]","artisan peintre [ville]"],"pains":["Le bouche-à-oreille seul ne remplit plus le planning","L’activité est mal présentée en ligne","Les prospects vérifient l’entreprise avant d’appeler","Des demandes se perdent pendant les chantiers","Peu de temps pour répondre vite à chaque message","Une dépendance à des réseaux sociaux qu’ils ne maîtrisent pas"],"needs":["Inspirer confiance en 10 secondes","Recevoir des demandes avec les bonnes informations","Ne pas passer ses soirées sur l’administratif"],"outcomes":["Davantage de confiance de la part de ceux qui ne les connaissent pas encore","Une présence professionnelle à la hauteur de leur travail","Des demandes centralisées au même endroit","Une disponibilité permanente, même en intervention","Une meilleure conversion des visiteurs en vraies demandes"],"discovery":["Comment la plupart de vos nouveaux clients vous trouvent-ils aujourd’hui ?","Que se passe-t-il quand quelqu’un vous cherche en ligne ?","Combien d’appels ou de messages manquez-vous pendant un chantier ?","Quels types de travaux aimeriez-vous faire davantage ?"],"avoid":"Ne le présentez jamais comme « un petit site » — parlez de confiance, de demandes complètes et de temps gagné."},"de":{"name":"Handwerker","who":"Klempner, Elektriker, Tischler, Maler, Schlüsseldienste — Handwerksbetriebe, die für Privatkunden und kleine Unternehmen arbeiten.","why":"Ihre Arbeit ist ausgezeichnet, aber Interessenten prüfen sie online, bevor sie anrufen — und finden oft nichts Überzeugendes.","problem":"Mundpropaganda reicht nicht mehr, der Betrieb ist online schlecht dargestellt, und Anfragen gehen zwischen Anrufen, SMS und sozialen Netzwerken verloren.","angle":"Verkaufen Sie nicht „eine kleine Website“: Verkaufen Sie das Ergebnis — mehr Vertrauen, vollständige Anfragen und einen Betrieb, der online so professionell wirkt wie auf der Baustelle.","message":"Hallo {{firstName}}, ich bin auf {{company}} gestoßen. Kurze Frage: Wenn jemand von Ihnen hört und Sie online sucht — was findet er? Ich arbeite mit Studio ATS, das Handwerksbetrieben eine professionelle Präsenz gibt, die vollständige Anfragen sammelt (Arbeiten, Ort, Zeitrahmen), sogar während Sie auf der Baustelle sind. 10 Minuten wert? {{affiliateUrl}}","searches":["Klempner [Stadt]","Elektriker [Stadt]","Tischler [Stadt]","Malerbetrieb [Stadt]"],"pains":["Mundpropaganda allein füllt den Kalender nicht mehr","Der Betrieb ist online schlecht dargestellt","Interessenten prüfen den Betrieb online, bevor sie anrufen","Anfragen gehen während der Arbeit verloren","Keine Zeit, jede Nachricht schnell zu beantworten","Abhängigkeit von sozialen Netzwerken, die man nicht kontrolliert"],"needs":["In 10 Sekunden glaubwürdig wirken","Anfragen mit den richtigen Details erhalten","Die Abende nicht mit Verwaltung verbringen"],"outcomes":["Mehr Vertrauen bei Menschen, die sie noch nicht kennen","Eine professionelle Präsenz, die der Qualität ihrer Arbeit entspricht","Anfragen an einem Ort gebündelt","Rund um die Uhr erreichbar, auch während eines Einsatzes","Mehr Besucher, die zu echten Anfragen werden"],"discovery":["Wie finden die meisten Ihrer neuen Kunden heute zu Ihnen?","Was passiert, wenn jemand Sie online sucht?","Wie viele Anrufe oder Nachrichten verpassen Sie während eines Einsatzes?","Von welchen Aufträgen hätten Sie gern mehr?"],"avoid":"Präsentieren Sie es nie als „kleine Website“ — sprechen Sie über Vertrauen, vollständige Anfragen und gesparte Zeit."},"es":{"name":"Artesanos y oficios","who":"Fontaneros, electricistas, carpinteros, pintores, cerrajeros — oficios que trabajan para particulares y pequeñas empresas.","why":"Su trabajo es excelente, pero los prospectos los buscan en internet antes de llamar — y a menudo no encuentran nada convincente.","problem":"El boca a boca ya no basta, el negocio está mal presentado en internet y las solicitudes se pierden entre llamadas, SMS y redes sociales.","angle":"No venda «una pequeña web»: venda el resultado — más confianza, solicitudes que llegan completas y un negocio tan profesional en internet como en la obra.","message":"Hola {{firstName}}, he visto {{company}}. Una pregunta rápida: cuando alguien oye hablar de usted y le busca en internet, ¿qué encuentra? Trabajo con Studio ATS, que da a los oficios una presencia profesional que recoge solicitudes completas (trabajo, lugar, plazo) incluso mientras usted está en la obra. ¿Merece 10 minutos? {{affiliateUrl}}","searches":["fontanero [ciudad]","electricista [ciudad]","carpintero [ciudad]","pintor [ciudad]"],"pains":["El boca a boca ya no llena la agenda","El negocio está mal presentado en internet","Los prospectos revisan la empresa en internet antes de llamar","Las solicitudes se pierden mientras trabajan en la obra","Sin tiempo para responder rápido a cada mensaje","Dependencia de redes sociales que no controlan"],"needs":["Parecer fiables en 10 segundos","Recibir solicitudes con los datos adecuados","No pasar las noches con papeleo"],"outcomes":["Más confianza de quien aún no los conoce","Una presencia profesional a la altura de su trabajo","Solicitudes centralizadas en un solo lugar","Disponibles 24/7, incluso en plena obra","Más visitantes que se convierten en solicitudes reales"],"discovery":["¿Cómo le encuentran hoy la mayoría de sus nuevos clientes?","¿Qué pasa cuando alguien le busca en internet?","¿Cuántas llamadas o mensajes pierde mientras trabaja?","¿De qué tipo de trabajos le gustaría tener más?"],"avoid":"Nunca lo presente como «una pequeña web» — hable de confianza, solicitudes completas y tiempo ganado."},"pt":{"name":"Artesãos e ofícios","who":"Canalizadores, eletricistas, carpinteiros, pintores, serralheiros — ofícios que trabalham para particulares e pequenas empresas.","why":"O trabalho deles é excelente, mas os contactos procuram-nos online antes de ligar — e muitas vezes não encontram nada convincente.","problem":"O passa-palavra já não chega, o negócio está mal apresentado online e os pedidos perdem-se entre chamadas, SMS e redes sociais.","angle":"Não venda «um pequeno site»: venda o resultado — mais confiança, pedidos que chegam completos e um negócio tão profissional online como em obra.","message":"Olá {{firstName}}, descobri a {{company}}. Uma pergunta rápida: quando alguém ouve falar de si e o procura online, o que encontra? Trabalho com a Studio ATS, que dá aos ofícios uma presença profissional que recolhe pedidos completos (trabalho, local, prazo) mesmo enquanto está em obra. Vale 10 minutos? {{affiliateUrl}}","searches":["canalizador [cidade]","eletricista [cidade]","carpinteiro [cidade]","pintor [cidade]"],"pains":["O passa-palavra sozinho já não enche a agenda","O negócio está mal apresentado online","Os contactos verificam a empresa online antes de ligar","Os pedidos perdem-se durante as obras","Pouco tempo para responder depressa a cada mensagem","Dependência de redes sociais que não controlam"],"needs":["Parecer credível em 10 segundos","Receber pedidos com os detalhes certos","Não passar as noites em burocracia"],"outcomes":["Mais confiança de quem ainda não os conhece","Uma presença profissional à altura do trabalho","Pedidos centralizados num só lugar","Disponíveis 24/7, mesmo em obra","Mais visitantes que se tornam pedidos reais"],"discovery":["Como é que a maioria dos seus novos clientes o encontra hoje?","O que acontece quando alguém o procura online?","Quantas chamadas ou mensagens perde durante uma obra?","De que tipo de trabalhos gostaria de ter mais?"],"avoid":"Nunca o apresente como «um pequeno site» — fale de confiança, pedidos completos e tempo poupado."},"it":{"name":"Artigiani","who":"Idraulici, elettricisti, falegnami, imbianchini, fabbri — mestieri che lavorano per privati e piccole imprese.","why":"Il loro lavoro è eccellente, ma i contatti li cercano online prima di chiamare — e spesso non trovano nulla di convincente.","problem":"Il passaparola non basta più, l’attività è presentata male online e le richieste si perdono tra chiamate, SMS e social.","angle":"Non vendere «un piccolo sito»: vendi il risultato — più fiducia, richieste complete e un’attività professionale online come in cantiere.","message":"Buongiorno {{firstName}}, ho scoperto {{company}}. Una domanda veloce: quando qualcuno sente parlare di lei e la cerca online, cosa trova? Lavoro con Studio ATS, che dà agli artigiani una presenza professionale che raccoglie richieste complete (lavoro, luogo, tempi) anche mentre è in cantiere. Vale 10 minuti? {{affiliateUrl}}","searches":["idraulico [città]","elettricista [città]","falegname [città]","imbianchino [città]"],"pains":["Il solo passaparola non riempie più l’agenda","L’attività è presentata male online","I contatti verificano l’azienda online prima di chiamare","Le richieste si perdono mentre si lavora in cantiere","Poco tempo per rispondere in fretta a ogni messaggio","Dipendenza da social che non controllano"],"needs":["Sembrare affidabili in 10 secondi","Ricevere richieste con i dettagli giusti","Non passare le serate in pratiche"],"outcomes":["Più fiducia da parte di chi non li conosce ancora","Una presenza professionale all’altezza del loro lavoro","Richieste centralizzate in un unico posto","Raggiungibili 24/7, anche durante un lavoro","Più visitatori che diventano richieste reali"],"discovery":["Come la trovano oggi la maggior parte dei suoi nuovi clienti?","Cosa succede quando qualcuno la cerca online?","Quante chiamate o messaggi perde durante un lavoro?","Di quali lavori vorrebbe averne di più?"],"avoid":"Non presentarlo mai come «un piccolo sito» — parla di fiducia, richieste complete e tempo risparmiato."},"nl":{"name":"Vakmensen","who":"Loodgieters, elektriciens, timmerlieden, schilders, slotenmakers — vakmensen die voor particulieren en kleine bedrijven werken.","why":"Hun werk is uitstekend, maar prospects zoeken ze online op voordat ze bellen — en vinden vaak niets overtuigends.","problem":"Mond-tot-mondreclame is niet meer genoeg, het bedrijf staat slecht online, en aanvragen raken zoek tussen telefoontjes, sms’jes en sociale media.","angle":"Verkoop geen “klein websiteje”: verkoop het resultaat — meer vertrouwen, aanvragen die compleet binnenkomen en een bedrijf dat online net zo professioneel overkomt als op de klus.","message":"Hallo {{firstName}}, ik kwam {{company}} tegen. Korte vraag: als iemand over jullie hoort en jullie online opzoekt, wat vindt diegene dan? Ik werk met Studio ATS, dat vakmensen een professionele uitstraling geeft die complete aanvragen verzamelt (klus, plaats, planning), zelfs terwijl je op de klus bent. 10 minuten waard? {{affiliateUrl}}","searches":["loodgieter [stad]","elektricien [stad]","timmerman [stad]","schildersbedrijf [stad]"],"pains":["Mond-tot-mondreclame alleen vult de agenda niet meer","Het bedrijf staat slecht online","Prospects checken het bedrijf online voordat ze bellen","Aanvragen raken zoek tijdens het werk op de klus","Geen tijd om elk bericht snel te beantwoorden","Afhankelijk van sociale media waar ze geen controle over hebben"],"needs":["In 10 seconden geloofwaardig overkomen","Aanvragen ontvangen met de juiste details","Geen avonden kwijt zijn aan administratie"],"outcomes":["Meer vertrouwen bij mensen die hen nog niet kennen","Een professionele uitstraling die past bij de kwaliteit van hun werk","Aanvragen gebundeld op één plek","24/7 bereikbaar, ook tijdens een klus","Meer bezoekers die echte aanvragen worden"],"discovery":["Hoe vinden de meeste nieuwe klanten jullie vandaag?","Wat gebeurt er als iemand jullie online opzoekt?","Hoeveel oproepen of berichten mis je tijdens een klus?","Van welke klussen zou je er graag meer hebben?"],"avoid":"Presenteer het nooit als “een klein websiteje” — praat over vertrouwen, complete aanvragen en tijdwinst."},"ar":{"name":"الحِرفيون","who":"السبّاكون والكهربائيون والنجّارون والدهّانون والأقفاليون — حِرفيون يعملون لصالح الأفراد والشركات الصغيرة.","why":"عملهم ممتاز، لكن العملاء المحتملين يتحققون منهم على الإنترنت قبل الاتصال — وغالبًا لا يجدون شيئًا مقنعًا.","problem":"لم تعد التوصية الشفهية كافية، والنشاط معروض بشكل سيئ على الإنترنت، وتضيع الطلبات بين المكالمات والرسائل النصية ووسائل التواصل.","angle":"لا تبِع «موقعًا صغيرًا»: بِع النتيجة — ثقة أكبر، وطلبات تصل كاملة، ونشاطًا يبدو على الإنترنت محترفًا كما هو في موقع العمل.","message":"مرحبًا {{firstName}}، اطّلعت على {{company}}. سؤال سريع: عندما يسمع أحد عنكم ويبحث عنكم على الإنترنت، ماذا يجد؟ أعمل مع Studio ATS الذي يمنح الحِرفيين حضورًا مهنيًا يجمع طلبات كاملة (العمل والمكان والتوقيت) حتى وأنتم في موقع العمل. هل يستحق ذلك 10 دقائق؟ {{affiliateUrl}}","searches":["سبّاك [المدينة]","كهربائي [المدينة]","نجّار [المدينة]","دهّان [المدينة]"],"pains":["التوصية الشفهية وحدها لم تعد تملأ جدول الأعمال","النشاط معروض بشكل سيئ على الإنترنت","يتحقق العملاء المحتملون من الشركة على الإنترنت قبل الاتصال","تضيع الطلبات أثناء العمل في الموقع","لا وقت للرد بسرعة على كل رسالة","الاعتماد على شبكات اجتماعية لا يتحكمون بها"],"needs":["الظهور بمظهر موثوق خلال 10 ثوانٍ","تلقي طلبات بالتفاصيل الصحيحة","عدم قضاء الأمسيات في الأعمال الإدارية"],"outcomes":["ثقة أكبر لدى من لا يعرفونهم بعد","حضور مهني يليق بجودة عملهم","طلبات مجمّعة في مكان واحد","متاحون على مدار الساعة، حتى أثناء العمل","زوار أكثر يتحولون إلى طلبات حقيقية"],"discovery":["كيف يجدكم معظم عملائكم الجدد اليوم؟","ماذا يحدث عندما يبحث عنكم أحد على الإنترنت؟","كم مكالمة أو رسالة تفوتكم أثناء العمل؟","ما نوع الأعمال التي تودّون الحصول على المزيد منها؟"],"avoid":"لا تقدّمه أبدًا على أنه «موقع صغير» — تحدّث عن الثقة والطلبات الكاملة والوقت الموفَّر."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('construction', 'hardhat', 2, 4, '{"en":{"name":"Construction companies","who":"Builders, roofers, masons and general contractors handling larger projects for private and professional clients.","why":"Projects are large and clients compare several companies — credibility and a clear first request make the difference.","problem":"Quote requests arrive incomplete, site visits are wasted on projects that don’t fit, and past work is not shown anywhere.","angle":"Show finished projects and qualify every request (type, surface, budget, timing) before anyone drives to a site.","message":"Hello {{firstName}}, I saw {{company}}’s work. How many quote requests turn out to be out of scope once you’re on site? Studio ATS shows your best projects and asks the right questions before the visit. Shall I show you in 10 minutes?","searches":["entreprise de maçonnerie [city]","couvreur [city]","entreprise générale bâtiment [city]"],"pains":["Incomplete quote requests","Wasted site visits","Past projects not visible online","Hard to stand out when clients compare"],"outcomes":["Requests qualified before the visit","Credibility through real references","One place for every request"],"discovery":["How do you decide which quote requests deserve a visit?","Where can a prospect see your finished projects today?"],"avoid":"Don’t talk technology — talk about fewer wasted visits and better-prepared quotes."},"fr":{"name":"Entreprises du bâtiment","who":"Constructeurs, couvreurs, maçons et entreprises générales réalisant des chantiers importants pour particuliers et professionnels.","why":"Les projets sont importants et les clients comparent plusieurs entreprises — la crédibilité et une première demande claire font la différence.","problem":"Les demandes de devis arrivent incomplètes, des visites sont perdues sur des projets hors cible, et les réalisations ne sont montrées nulle part.","angle":"Montrez les chantiers réalisés et qualifiez chaque demande (type, surface, budget, délai) avant de vous déplacer.","message":"Bonjour {{firstName}}, j’ai vu les réalisations de {{company}}. Combien de demandes de devis se révèlent hors cible une fois sur place ? Studio ATS présente vos plus beaux chantiers et pose les bonnes questions avant la visite. Je vous montre en 10 minutes ?","searches":["entreprise de maçonnerie [ville]","couvreur [ville]","entreprise générale bâtiment [ville]"],"pains":["Des demandes de devis incomplètes","Des visites de chantier inutiles","Des réalisations invisibles en ligne","Difficile de se démarquer face à la concurrence"],"outcomes":["Des demandes qualifiées avant la visite","Une crédibilité appuyée sur de vraies références","Un seul endroit pour toutes les demandes"],"discovery":["Comment décidez-vous quelles demandes méritent une visite ?","Où un prospect peut-il voir vos chantiers terminés aujourd’hui ?"],"avoid":"Ne parlez pas technologie — parlez de visites inutiles évitées et de devis mieux préparés."},"de":{"name":"Bauunternehmen","who":"Bauunternehmen, Dachdecker, Maurer und Generalunternehmer mit größeren Projekten für Privat- und Geschäftskunden.","why":"Die Projekte sind groß und Kunden vergleichen mehrere Firmen — Glaubwürdigkeit und eine klare erste Anfrage machen den Unterschied.","problem":"Angebotsanfragen kommen unvollständig an, Besichtigungen werden für unpassende Projekte verschwendet, und abgeschlossene Arbeiten sind nirgends zu sehen.","angle":"Zeigen Sie fertige Projekte und qualifizieren Sie jede Anfrage (Art, Fläche, Budget, Zeitrahmen), bevor jemand zur Baustelle fährt.","message":"Hallo {{firstName}}, ich habe die Arbeiten von {{company}} gesehen. Wie viele Angebotsanfragen erweisen sich vor Ort als unpassend? Studio ATS zeigt Ihre besten Projekte und stellt vor der Besichtigung die richtigen Fragen. Soll ich es Ihnen in 10 Minuten zeigen?","searches":["Bauunternehmen [Stadt]","Dachdecker [Stadt]","Generalunternehmer Bau [Stadt]"],"pains":["Unvollständige Angebotsanfragen","Verschwendete Besichtigungen","Abgeschlossene Projekte online nicht sichtbar","Schwer, sich im Vergleich abzuheben"],"outcomes":["Vor der Besichtigung qualifizierte Anfragen","Glaubwürdigkeit durch echte Referenzen","Ein Ort für jede Anfrage"],"discovery":["Wie entscheiden Sie, welche Angebotsanfragen eine Besichtigung verdienen?","Wo kann ein Interessent heute Ihre fertigen Projekte sehen?"],"avoid":"Sprechen Sie nicht über Technik — sprechen Sie über weniger verschwendete Besichtigungen und besser vorbereitete Angebote."},"es":{"name":"Empresas de construcción","who":"Constructoras, techadores, albañiles y contratistas generales con proyectos importantes para particulares y profesionales.","why":"Los proyectos son grandes y los clientes comparan varias empresas — la credibilidad y una primera solicitud clara marcan la diferencia.","problem":"Las solicitudes de presupuesto llegan incompletas, se pierden visitas en proyectos que no encajan y los trabajos realizados no se muestran en ningún sitio.","angle":"Muestre obras terminadas y cualifique cada solicitud (tipo, superficie, presupuesto, plazo) antes de desplazarse.","message":"Hola {{firstName}}, he visto los trabajos de {{company}}. ¿Cuántas solicitudes de presupuesto resultan no encajar una vez en la obra? Studio ATS muestra sus mejores proyectos y hace las preguntas adecuadas antes de la visita. ¿Se lo enseño en 10 minutos?","searches":["empresa de construcción [ciudad]","tejados y cubiertas [ciudad]","contratista general [ciudad]"],"pains":["Solicitudes de presupuesto incompletas","Visitas de obra inútiles","Proyectos realizados invisibles en internet","Difícil destacar cuando el cliente compara"],"outcomes":["Solicitudes cualificadas antes de la visita","Credibilidad con referencias reales","Un solo lugar para todas las solicitudes"],"discovery":["¿Cómo decide qué solicitudes de presupuesto merecen una visita?","¿Dónde puede ver hoy un prospecto sus obras terminadas?"],"avoid":"No hable de tecnología — hable de menos visitas inútiles y presupuestos mejor preparados."},"pt":{"name":"Empresas de construção","who":"Construtoras, telhadores, pedreiros e empreiteiros gerais com obras maiores para particulares e profissionais.","why":"As obras são grandes e os clientes comparam várias empresas — a credibilidade e um primeiro pedido claro fazem a diferença.","problem":"Os pedidos de orçamento chegam incompletos, perdem-se visitas em obras que não encaixam e os trabalhos feitos não aparecem em lado nenhum.","angle":"Mostre obras concluídas e qualifique cada pedido (tipo, área, orçamento, prazo) antes de alguém se deslocar.","message":"Olá {{firstName}}, vi os trabalhos da {{company}}. Quantos pedidos de orçamento se revelam fora do âmbito quando chega à obra? A Studio ATS mostra os seus melhores projetos e faz as perguntas certas antes da visita. Mostro-lhe em 10 minutos?","searches":["empresa de construção [cidade]","telhados [cidade]","empreiteiro geral [cidade]"],"pains":["Pedidos de orçamento incompletos","Visitas de obra inúteis","Obras concluídas invisíveis online","Difícil destacar-se quando o cliente compara"],"outcomes":["Pedidos qualificados antes da visita","Credibilidade com referências reais","Um só lugar para todos os pedidos"],"discovery":["Como decide que pedidos de orçamento merecem uma visita?","Onde pode hoje um contacto ver as suas obras concluídas?"],"avoid":"Não fale de tecnologia — fale de menos visitas inúteis e orçamentos mais bem preparados."},"it":{"name":"Imprese edili","who":"Costruttori, copritetti, muratori e imprese generali con cantieri importanti per privati e professionisti.","why":"I progetti sono grandi e i clienti confrontano più imprese — la credibilità e una prima richiesta chiara fanno la differenza.","problem":"Le richieste di preventivo arrivano incomplete, si sprecano sopralluoghi su progetti non adatti e i lavori realizzati non si vedono da nessuna parte.","angle":"Mostra i cantieri conclusi e qualifica ogni richiesta (tipo, superficie, budget, tempi) prima di muoversi.","message":"Buongiorno {{firstName}}, ho visto i lavori di {{company}}. Quante richieste di preventivo si rivelano fuori ambito una volta sul posto? Studio ATS mostra i vostri progetti migliori e fa le domande giuste prima del sopralluogo. Glielo mostro in 10 minuti?","searches":["impresa edile [città]","rifacimento tetti [città]","impresa di costruzioni [città]"],"pains":["Richieste di preventivo incomplete","Sopralluoghi inutili","Lavori realizzati invisibili online","Difficile distinguersi quando il cliente confronta"],"outcomes":["Richieste qualificate prima del sopralluogo","Credibilità grazie a referenze reali","Un unico posto per tutte le richieste"],"discovery":["Come decidete quali richieste di preventivo meritano un sopralluogo?","Dove può vedere oggi un contatto i vostri cantieri conclusi?"],"avoid":"Non parlare di tecnologia — parla di meno sopralluoghi inutili e preventivi meglio preparati."},"nl":{"name":"Bouwbedrijven","who":"Aannemers, dakdekkers, metselaars en hoofdaannemers met grotere projecten voor particuliere en zakelijke klanten.","why":"De projecten zijn groot en klanten vergelijken meerdere bedrijven — geloofwaardigheid en een duidelijke eerste aanvraag maken het verschil.","problem":"Offerteaanvragen komen onvolledig binnen, bezichtigingen worden verspild aan projecten die niet passen, en eerder werk is nergens te zien.","angle":"Laat afgeronde projecten zien en kwalificeer elke aanvraag (type, oppervlakte, budget, planning) voordat iemand naar een bouwplaats rijdt.","message":"Hallo {{firstName}}, ik zag het werk van {{company}}. Hoeveel offerteaanvragen blijken ter plekke niet te passen? Studio ATS laat je beste projecten zien en stelt vóór het bezoek de juiste vragen. Zal ik het in 10 minuten laten zien?","searches":["aannemer [stad]","dakdekker [stad]","bouwbedrijf [stad]"],"pains":["Onvolledige offerteaanvragen","Verspilde bezichtigingen","Afgeronde projecten online onzichtbaar","Moeilijk opvallen als klanten vergelijken"],"outcomes":["Aanvragen gekwalificeerd vóór het bezoek","Geloofwaardigheid met echte referenties","Eén plek voor elke aanvraag"],"discovery":["Hoe bepaal je welke offerteaanvragen een bezoek waard zijn?","Waar kan een prospect nu je afgeronde projecten zien?"],"avoid":"Praat niet over technologie — praat over minder verspilde bezoeken en beter voorbereide offertes."},"ar":{"name":"شركات البناء","who":"شركات البناء ومركّبو الأسقف والبنّاؤون والمقاولون العامّون الذين ينفّذون مشاريع كبيرة لعملاء أفراد ومهنيين.","why":"المشاريع كبيرة ويقارن العملاء بين عدة شركات — المصداقية وطلب أول واضح يصنعان الفرق.","problem":"تصل طلبات عروض الأسعار ناقصة، وتُهدر زيارات المواقع على مشاريع غير مناسبة، والأعمال المنجزة غير معروضة في أي مكان.","angle":"اعرض المشاريع المنجزة وأهّل كل طلب (النوع والمساحة والميزانية والتوقيت) قبل أن يتوجّه أحد إلى الموقع.","message":"مرحبًا {{firstName}}، رأيت أعمال {{company}}. كم من طلبات عروض الأسعار يتبيّن أنها خارج النطاق بمجرد الوصول إلى الموقع؟ يعرض Studio ATS أفضل مشاريعكم ويطرح الأسئلة الصحيحة قبل الزيارة. هل أريكم ذلك في 10 دقائق؟","searches":["شركة مقاولات [المدينة]","تركيب أسقف [المدينة]","مقاول عام [المدينة]"],"pains":["طلبات عروض أسعار ناقصة","زيارات مواقع مهدرة","مشاريع منجزة غير ظاهرة على الإنترنت","صعوبة التميّز عند مقارنة العملاء"],"outcomes":["طلبات مؤهَّلة قبل الزيارة","مصداقية عبر مراجع حقيقية","مكان واحد لكل الطلبات"],"discovery":["كيف تقرّرون أي طلبات عروض الأسعار تستحق زيارة؟","أين يمكن لعميل محتمل أن يرى مشاريعكم المنجزة اليوم؟"],"avoid":"لا تتحدث عن التقنية — تحدّث عن زيارات مهدرة أقل وعروض أسعار أفضل إعدادًا."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('garages', 'car', 3, 4, '{"en":{"name":"Garages & auto services","who":"Independent garages, body shops, tyre and car-care specialists.","why":"Drivers compare garages online and want to know quickly if their job can be handled and when.","problem":"The phone rings during repairs, booking requests lack the vehicle and the issue, and the garage looks outdated online.","angle":"Let drivers describe their vehicle and need, and request a slot — without interrupting the workshop.","message":"Hello {{firstName}}, quick question for {{company}}: how do drivers book with you today — mostly by phone during repairs? Studio ATS lets them describe the vehicle and the job and request a slot online. Worth a look?","searches":["garage automobile [city]","carrosserie [city]","garage indépendant [city]"],"pains":["Phone interruptions during repairs","Requests without vehicle or issue details","An outdated online image"],"outcomes":["Complete requests (vehicle, issue, availability)","Fewer interruptions in the workshop","A modern, trustworthy presence"],"discovery":["How many calls do you take while working on a car?","What information is always missing when someone calls?"],"avoid":"Don’t promise more customers — talk about complete requests and fewer interruptions."},"fr":{"name":"Garages & services auto","who":"Garages indépendants, carrossiers, spécialistes pneus et entretien.","why":"Les conducteurs comparent les garages en ligne et veulent savoir vite si leur intervention est possible et quand.","problem":"Le téléphone sonne pendant les réparations, les demandes arrivent sans le véhicule ni la panne, et le garage paraît daté en ligne.","angle":"Laissez les conducteurs décrire leur véhicule et leur besoin, puis demander un créneau — sans interrompre l’atelier.","message":"Bonjour {{firstName}}, petite question pour {{company}} : comment vos clients prennent-ils rendez-vous aujourd’hui — surtout par téléphone pendant les réparations ? Studio ATS leur permet de décrire le véhicule et l’intervention et de demander un créneau en ligne. Ça vaut un coup d’œil ?","searches":["garage automobile [ville]","carrosserie [ville]","garage indépendant [ville]"],"pains":["Des interruptions téléphoniques pendant les réparations","Des demandes sans détails sur le véhicule ou la panne","Une image en ligne datée"],"outcomes":["Des demandes complètes (véhicule, panne, disponibilités)","Moins d’interruptions à l’atelier","Une présence moderne et rassurante"],"discovery":["Combien d’appels prenez-vous pendant une réparation ?","Quelle information manque toujours quand on vous appelle ?"],"avoid":"Ne promettez pas plus de clients — parlez de demandes complètes et de moins d’interruptions."},"de":{"name":"Werkstätten & Kfz-Service","who":"Freie Werkstätten, Karosseriebetriebe, Reifen- und Fahrzeugpflegespezialisten.","why":"Autofahrer vergleichen Werkstätten online und wollen schnell wissen, ob und wann ihr Auftrag erledigt werden kann.","problem":"Das Telefon klingelt während der Reparaturen, Terminanfragen enthalten weder Fahrzeug noch Problem, und die Werkstatt wirkt online veraltet.","angle":"Lassen Sie Autofahrer Fahrzeug und Anliegen beschreiben und einen Termin anfragen — ohne die Werkstatt zu unterbrechen.","message":"Hallo {{firstName}}, kurze Frage an {{company}}: Wie buchen Autofahrer heute bei Ihnen — meist per Telefon während der Reparaturen? Mit Studio ATS beschreiben sie Fahrzeug und Auftrag und fragen online einen Termin an. Einen Blick wert?","searches":["Autowerkstatt [Stadt]","Karosseriebau [Stadt]","freie Werkstatt [Stadt]"],"pains":["Telefonunterbrechungen während der Reparaturen","Anfragen ohne Angaben zu Fahrzeug oder Problem","Ein veraltetes Online-Bild"],"outcomes":["Vollständige Anfragen (Fahrzeug, Problem, Verfügbarkeit)","Weniger Unterbrechungen in der Werkstatt","Eine moderne, vertrauenswürdige Präsenz"],"discovery":["Wie viele Anrufe nehmen Sie an, während Sie an einem Auto arbeiten?","Welche Information fehlt immer, wenn jemand anruft?"],"avoid":"Versprechen Sie keine zusätzlichen Kunden — sprechen Sie über vollständige Anfragen und weniger Unterbrechungen."},"es":{"name":"Talleres y servicios del automóvil","who":"Talleres independientes, chapistas, especialistas en neumáticos y mantenimiento del vehículo.","why":"Los conductores comparan talleres en internet y quieren saber rápido si pueden atender su caso y cuándo.","problem":"El teléfono suena durante las reparaciones, las solicitudes llegan sin el vehículo ni la avería y el taller parece anticuado en internet.","angle":"Deje que los conductores describan su vehículo y su necesidad y pidan cita — sin interrumpir el taller.","message":"Hola {{firstName}}, una pregunta para {{company}}: ¿cómo piden cita hoy los conductores — sobre todo por teléfono durante las reparaciones? Con Studio ATS describen el vehículo y el trabajo y piden cita en línea. ¿Le echa un vistazo?","searches":["taller mecánico [ciudad]","chapa y pintura [ciudad]","taller independiente [ciudad]"],"pains":["Interrupciones telefónicas durante las reparaciones","Solicitudes sin datos del vehículo ni de la avería","Una imagen anticuada en internet"],"outcomes":["Solicitudes completas (vehículo, avería, disponibilidad)","Menos interrupciones en el taller","Una presencia moderna y fiable"],"discovery":["¿Cuántas llamadas atiende mientras trabaja en un coche?","¿Qué información falta siempre cuando le llaman?"],"avoid":"No prometa más clientes — hable de solicitudes completas y menos interrupciones."},"pt":{"name":"Oficinas e serviços auto","who":"Oficinas independentes, bate-chapas, especialistas em pneus e manutenção automóvel.","why":"Os condutores comparam oficinas online e querem saber depressa se o trabalho pode ser feito e quando.","problem":"O telefone toca durante as reparações, os pedidos chegam sem o veículo nem a avaria e a oficina parece antiquada online.","angle":"Deixe os condutores descrever o veículo e a necessidade e pedir uma marcação — sem interromper a oficina.","message":"Olá {{firstName}}, uma pergunta para a {{company}}: como marcam hoje os condutores — sobretudo por telefone durante as reparações? Com a Studio ATS descrevem o veículo e o trabalho e pedem uma marcação online. Vale uma vista de olhos?","searches":["oficina automóvel [cidade]","bate-chapa [cidade]","oficina independente [cidade]"],"pains":["Interrupções telefónicas durante as reparações","Pedidos sem dados do veículo ou da avaria","Uma imagem online antiquada"],"outcomes":["Pedidos completos (veículo, avaria, disponibilidade)","Menos interrupções na oficina","Uma presença moderna e de confiança"],"discovery":["Quantas chamadas atende enquanto trabalha num carro?","Que informação falta sempre quando lhe ligam?"],"avoid":"Não prometa mais clientes — fale de pedidos completos e menos interrupções."},"it":{"name":"Officine e servizi auto","who":"Officine indipendenti, carrozzerie, gommisti e specialisti della manutenzione auto.","why":"Gli automobilisti confrontano le officine online e vogliono sapere in fretta se e quando il lavoro si può fare.","problem":"Il telefono squilla durante le riparazioni, le richieste arrivano senza veicolo né guasto e l’officina sembra datata online.","angle":"Lascia che gli automobilisti descrivano il veicolo e l’esigenza e chiedano un appuntamento — senza interrompere l’officina.","message":"Buongiorno {{firstName}}, una domanda per {{company}}: come prenotano oggi gli automobilisti — soprattutto al telefono durante le riparazioni? Con Studio ATS descrivono il veicolo e il lavoro e chiedono un appuntamento online. Vale un’occhiata?","searches":["officina meccanica [città]","carrozzeria [città]","officina indipendente [città]"],"pains":["Interruzioni telefoniche durante le riparazioni","Richieste senza dati sul veicolo o sul guasto","Un’immagine online datata"],"outcomes":["Richieste complete (veicolo, guasto, disponibilità)","Meno interruzioni in officina","Una presenza moderna e affidabile"],"discovery":["Quante chiamate prende mentre lavora su un’auto?","Quale informazione manca sempre quando la chiamano?"],"avoid":"Non promettere più clienti — parla di richieste complete e meno interruzioni."},"nl":{"name":"Garages & autoservice","who":"Onafhankelijke garages, schadeherstelbedrijven, banden- en autopoetsspecialisten.","why":"Automobilisten vergelijken garages online en willen snel weten of en wanneer hun klus gedaan kan worden.","problem":"De telefoon gaat tijdens reparaties, afspraakverzoeken missen de auto en het probleem, en de garage oogt online gedateerd.","angle":"Laat automobilisten hun auto en hun wens beschrijven en een tijdslot aanvragen — zonder de werkplaats te onderbreken.","message":"Hallo {{firstName}}, korte vraag voor {{company}}: hoe maken automobilisten nu een afspraak — vooral telefonisch tijdens reparaties? Met Studio ATS beschrijven ze de auto en de klus en vragen ze online een tijdslot aan. Een blik waard?","searches":["autogarage [stad]","autoschadeherstel [stad]","onafhankelijke garage [stad]"],"pains":["Telefonische onderbrekingen tijdens reparaties","Aanvragen zonder gegevens over auto of probleem","Een gedateerd online imago"],"outcomes":["Complete aanvragen (auto, probleem, beschikbaarheid)","Minder onderbrekingen in de werkplaats","Een moderne, betrouwbare uitstraling"],"discovery":["Hoeveel telefoontjes neem je aan terwijl je aan een auto werkt?","Welke informatie ontbreekt altijd als iemand belt?"],"avoid":"Beloof geen extra klanten — praat over complete aanvragen en minder onderbrekingen."},"ar":{"name":"الورش وخدمات السيارات","who":"الورش المستقلة وورش السمكرة ومتخصّصو الإطارات والعناية بالسيارات.","why":"يقارن السائقون بين الورش على الإنترنت ويريدون أن يعرفوا بسرعة ما إذا كان يمكن إنجاز عملهم ومتى.","problem":"يرنّ الهاتف أثناء الإصلاحات، وتصل طلبات الحجز دون بيانات السيارة والعطل، وتبدو الورشة قديمة على الإنترنت.","angle":"دع السائقين يصفون سيارتهم وحاجتهم ويطلبون موعدًا — دون مقاطعة الورشة.","message":"مرحبًا {{firstName}}، سؤال سريع لـ {{company}}: كيف يحجز السائقون لديكم اليوم — غالبًا بالهاتف أثناء الإصلاحات؟ مع Studio ATS يصفون السيارة والعمل ويطلبون موعدًا عبر الإنترنت. هل يستحق ذلك نظرة؟","searches":["ورشة سيارات [المدينة]","سمكرة ودهان [المدينة]","ورشة مستقلة [المدينة]"],"pains":["مقاطعات هاتفية أثناء الإصلاحات","طلبات دون بيانات السيارة أو العطل","صورة قديمة على الإنترنت"],"outcomes":["طلبات كاملة (السيارة والعطل والتوفّر)","مقاطعات أقل في الورشة","حضور حديث وموثوق"],"discovery":["كم مكالمة تتلقّون أثناء العمل على سيارة؟","ما المعلومة التي تنقص دائمًا عندما يتصل أحد؟"],"avoid":"لا تَعِد بعملاء أكثر — تحدّث عن طلبات كاملة ومقاطعات أقل."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('health-wellness', 'health', 4, 4, '{"en":{"name":"Health & wellness","who":"Independent practitioners in wellness and non-medical care: coaches, massage therapists, beauty and wellbeing studios.","why":"Clients choose on trust and need to understand the approach and the practical details before booking.","problem":"Questions repeat by message, the offer is unclear online, and booking requests arrive without context.","angle":"A reassuring space that explains the approach, answers the usual questions and collects clean appointment requests.","message":"Hello {{firstName}}, I discovered {{company}}. Do new clients often ask the same questions before booking? Studio ATS presents your approach clearly and collects appointment requests with the right context. Open to a short demo?","searches":["praticien bien-être [city]","institut de beauté [city]","coach [city]"],"pains":["The same questions answered again and again","An offer that is unclear online","Booking requests without context"],"outcomes":["A reassuring, clear presentation","Fewer repetitive questions","Structured appointment requests"],"discovery":["What do new clients ask most before booking?","How do they book with you today?"],"avoid":"Regulated medical professions have strict communication rules — do not make health claims; stick to organisation and presentation."},"fr":{"name":"Santé & bien-être","who":"Praticiens indépendants du bien-être et des soins non médicaux : coachs, masseurs, instituts de beauté et de bien-être.","why":"Les clients choisissent sur la confiance et veulent comprendre l’approche et les modalités avant de réserver.","problem":"Les questions se répètent par message, l’offre est floue en ligne et les demandes de rendez-vous arrivent sans contexte.","angle":"Un espace rassurant qui explique l’approche, répond aux questions habituelles et recueille des demandes de rendez-vous claires.","message":"Bonjour {{firstName}}, j’ai découvert {{company}}. Vos nouveaux clients posent-ils souvent les mêmes questions avant de réserver ? Studio ATS présente clairement votre approche et recueille des demandes de rendez-vous avec le bon contexte. Partant pour une courte démo ?","searches":["praticien bien-être [ville]","institut de beauté [ville]","coach [ville]"],"pains":["Toujours les mêmes questions","Une offre peu claire en ligne","Des demandes de rendez-vous sans contexte"],"outcomes":["Une présentation claire et rassurante","Moins de questions répétitives","Des demandes de rendez-vous structurées"],"discovery":["Que vous demandent le plus souvent les nouveaux clients avant de réserver ?","Comment réservent-ils chez vous aujourd’hui ?"],"avoid":"Les professions médicales réglementées ont des règles de communication strictes — aucune allégation de santé ; restez sur l’organisation et la présentation."},"de":{"name":"Gesundheit & Wohlbefinden","who":"Selbstständige im Wellness- und nicht-medizinischen Bereich: Coaches, Masseure, Kosmetik- und Wellnessstudios.","why":"Kunden entscheiden nach Vertrauen und wollen Ansatz und praktische Details vor der Buchung verstehen.","problem":"Dieselben Fragen kommen immer wieder per Nachricht, das Angebot ist online unklar, und Terminanfragen kommen ohne Kontext an.","angle":"Ein beruhigender Ort, der den Ansatz erklärt, die üblichen Fragen beantwortet und saubere Terminanfragen sammelt.","message":"Hallo {{firstName}}, ich habe {{company}} entdeckt. Stellen neue Kunden vor der Buchung oft dieselben Fragen? Studio ATS stellt Ihren Ansatz klar dar und sammelt Terminanfragen mit dem richtigen Kontext. Offen für eine kurze Demo?","searches":["Wellness Praxis [Stadt]","Kosmetikstudio [Stadt]","Coach [Stadt]"],"pains":["Immer wieder dieselben Fragen beantworten","Ein online unklares Angebot","Terminanfragen ohne Kontext"],"outcomes":["Eine beruhigende, klare Darstellung","Weniger wiederkehrende Fragen","Strukturierte Terminanfragen"],"discovery":["Was fragen neue Kunden vor der Buchung am häufigsten?","Wie buchen sie heute bei Ihnen?"],"avoid":"Für reglementierte Heilberufe gelten strenge Werberegeln — keine Gesundheitsversprechen; bleiben Sie bei Organisation und Präsentation."},"es":{"name":"Salud y bienestar","who":"Profesionales independientes del bienestar y de cuidados no médicos: coaches, masajistas, centros de estética y bienestar.","why":"Los clientes eligen por confianza y necesitan entender el enfoque y los detalles prácticos antes de reservar.","problem":"Las mismas preguntas llegan una y otra vez por mensaje, la oferta no está clara en internet y las solicitudes de cita llegan sin contexto.","angle":"Un espacio tranquilizador que explica el enfoque, responde a las preguntas habituales y recoge solicitudes de cita claras.","message":"Hola {{firstName}}, he descubierto {{company}}. ¿Los nuevos clientes suelen hacer las mismas preguntas antes de reservar? Studio ATS presenta su enfoque con claridad y recoge solicitudes de cita con el contexto adecuado. ¿Le apetece una demo breve?","searches":["centro de bienestar [ciudad]","centro de estética [ciudad]","coach [ciudad]"],"pains":["Responder una y otra vez a las mismas preguntas","Una oferta poco clara en internet","Solicitudes de cita sin contexto"],"outcomes":["Una presentación clara y tranquilizadora","Menos preguntas repetitivas","Solicitudes de cita estructuradas"],"discovery":["¿Qué preguntan más los nuevos clientes antes de reservar?","¿Cómo reservan hoy con usted?"],"avoid":"Las profesiones sanitarias reguladas tienen normas de comunicación estrictas — no haga afirmaciones de salud; céntrese en la organización y la presentación."},"pt":{"name":"Saúde e bem-estar","who":"Profissionais independentes de bem-estar e cuidados não médicos: coaches, massagistas, centros de estética e bem-estar.","why":"Os clientes escolhem pela confiança e precisam de perceber a abordagem e os detalhes práticos antes de marcar.","problem":"As mesmas perguntas repetem-se por mensagem, a oferta não é clara online e os pedidos de marcação chegam sem contexto.","angle":"Um espaço tranquilizador que explica a abordagem, responde às perguntas habituais e recolhe pedidos de marcação claros.","message":"Olá {{firstName}}, descobri a {{company}}. Os novos clientes fazem muitas vezes as mesmas perguntas antes de marcar? A Studio ATS apresenta a sua abordagem com clareza e recolhe pedidos de marcação com o contexto certo. Aberto a uma demo curta?","searches":["centro de bem-estar [cidade]","centro de estética [cidade]","coach [cidade]"],"pains":["Responder vezes sem conta às mesmas perguntas","Uma oferta pouco clara online","Pedidos de marcação sem contexto"],"outcomes":["Uma apresentação clara e tranquilizadora","Menos perguntas repetitivas","Pedidos de marcação estruturados"],"discovery":["O que perguntam mais os novos clientes antes de marcar?","Como é que marcam consigo hoje?"],"avoid":"As profissões de saúde regulamentadas têm regras de comunicação estritas — não faça alegações de saúde; fique pela organização e apresentação."},"it":{"name":"Salute e benessere","who":"Professionisti indipendenti del benessere e delle cure non mediche: coach, massaggiatori, centri estetici e di benessere.","why":"I clienti scelgono in base alla fiducia e devono capire l’approccio e i dettagli pratici prima di prenotare.","problem":"Le stesse domande arrivano di continuo via messaggio, l’offerta non è chiara online e le richieste di appuntamento arrivano senza contesto.","angle":"Uno spazio rassicurante che spiega l’approccio, risponde alle domande abituali e raccoglie richieste di appuntamento chiare.","message":"Buongiorno {{firstName}}, ho scoperto {{company}}. I nuovi clienti fanno spesso le stesse domande prima di prenotare? Studio ATS presenta il suo approccio con chiarezza e raccoglie richieste di appuntamento con il giusto contesto. Le va una breve demo?","searches":["centro benessere [città]","centro estetico [città]","coach [città]"],"pains":["Rispondere sempre alle stesse domande","Un’offerta poco chiara online","Richieste di appuntamento senza contesto"],"outcomes":["Una presentazione chiara e rassicurante","Meno domande ripetitive","Richieste di appuntamento strutturate"],"discovery":["Cosa chiedono più spesso i nuovi clienti prima di prenotare?","Come prenotano oggi da lei?"],"avoid":"Le professioni sanitarie regolamentate hanno regole di comunicazione rigide — nessuna promessa sulla salute; resta su organizzazione e presentazione."},"nl":{"name":"Gezondheid & welzijn","who":"Zelfstandige professionals in welzijn en niet-medische zorg: coaches, masseurs, schoonheids- en wellnessstudio’s.","why":"Klanten kiezen op vertrouwen en willen de aanpak en praktische details begrijpen voordat ze boeken.","problem":"Steeds dezelfde vragen per bericht, het aanbod is online onduidelijk en afspraakverzoeken komen zonder context binnen.","angle":"Een geruststellende plek die de aanpak uitlegt, de gebruikelijke vragen beantwoordt en heldere afspraakverzoeken verzamelt.","message":"Hallo {{firstName}}, ik ontdekte {{company}}. Stellen nieuwe klanten vaak dezelfde vragen voordat ze boeken? Studio ATS presenteert je aanpak helder en verzamelt afspraakverzoeken met de juiste context. Zin in een korte demo?","searches":["wellnesspraktijk [stad]","schoonheidssalon [stad]","coach [stad]"],"pains":["Steeds weer dezelfde vragen beantwoorden","Een aanbod dat online onduidelijk is","Afspraakverzoeken zonder context"],"outcomes":["Een geruststellende, heldere presentatie","Minder herhaalde vragen","Gestructureerde afspraakverzoeken"],"discovery":["Wat vragen nieuwe klanten het vaakst voordat ze boeken?","Hoe boeken ze nu bij jou?"],"avoid":"Voor gereglementeerde zorgberoepen gelden strenge communicatieregels — doe geen gezondheidsclaims; blijf bij organisatie en presentatie."},"ar":{"name":"الصحة والعافية","who":"ممارسون مستقلون في مجال العافية والرعاية غير الطبية: مدرّبون ومعالجون بالتدليك ومراكز تجميل وعافية.","why":"يختار العملاء بناءً على الثقة ويحتاجون إلى فهم الأسلوب والتفاصيل العملية قبل الحجز.","problem":"تتكرر الأسئلة نفسها عبر الرسائل، والعرض غير واضح على الإنترنت، وتصل طلبات المواعيد دون سياق.","angle":"مساحة مطمئنة تشرح الأسلوب، وتجيب عن الأسئلة المعتادة، وتجمع طلبات مواعيد واضحة.","message":"مرحبًا {{firstName}}، اكتشفت {{company}}. هل يطرح العملاء الجدد غالبًا الأسئلة نفسها قبل الحجز؟ يعرض Studio ATS أسلوبكم بوضوح ويجمع طلبات المواعيد بالسياق الصحيح. هل تودّون عرضًا تجريبيًا قصيرًا؟","searches":["مركز عافية [المدينة]","مركز تجميل [المدينة]","مدرّب [المدينة]"],"pains":["الإجابة مرارًا عن الأسئلة نفسها","عرض غير واضح على الإنترنت","طلبات مواعيد دون سياق"],"outcomes":["عرض واضح ومطمئن","أسئلة متكررة أقل","طلبات مواعيد منظَّمة"],"discovery":["ما أكثر ما يسأل عنه العملاء الجدد قبل الحجز؟","كيف يحجزون لديكم اليوم؟"],"avoid":"للمهن الصحية المنظَّمة قواعد تواصل صارمة — لا تقدّم ادعاءات صحية؛ اقتصر على التنظيم والعرض."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('independents', 'user', 5, 3, '{"en":{"name":"Freelancers & independents","who":"Freelancers and solo professionals selling their expertise: designers, developers, trainers, translators.","why":"Alone, they need to look established and qualify requests without spending hours in back-and-forth.","problem":"Requests arrive by email and LinkedIn with no budget or timing, and the offer is hard to understand from a profile page.","angle":"Look like an established studio and receive requests that already contain scope, timing and budget.","message":"Hi {{firstName}}, I follow your work. When a new client contacts you, do you usually get a clear brief? Studio ATS gives independents a professional space that presents the offer and qualifies each request. Want to see it?","searches":["freelance [specialty] [city]","consultant indépendant [specialty]","LinkedIn: freelance [specialty]"],"pains":["Vague requests with no budget","Hours of back-and-forth before a quote","An offer that is hard to grasp online"],"outcomes":["An established, professional image","Qualified briefs","More time for billable work"],"discovery":["What does a typical first request look like?","How long does it take you to qualify a new project?"],"avoid":"Don’t oversell automation — focus on credibility and better briefs."},"fr":{"name":"Indépendants & freelances","who":"Freelances et professionnels seuls vendant leur expertise : designers, développeurs, formateurs, traducteurs.","why":"Seuls, ils doivent paraître établis et qualifier les demandes sans passer des heures en allers-retours.","problem":"Les demandes arrivent par email et LinkedIn sans budget ni délai, et l’offre est difficile à comprendre depuis un simple profil.","angle":"Paraître comme un studio établi et recevoir des demandes qui précisent déjà périmètre, délai et budget.","message":"Bonjour {{firstName}}, je suis votre travail. Quand un nouveau client vous contacte, avez-vous en général un brief clair ? Studio ATS donne aux indépendants un espace professionnel qui présente l’offre et qualifie chaque demande. Envie de voir ?","searches":["freelance [spécialité] [ville]","consultant indépendant [spécialité]","LinkedIn : freelance [spécialité]"],"pains":["Des demandes vagues sans budget","Des heures d’allers-retours avant un devis","Une offre difficile à saisir en ligne"],"outcomes":["Une image établie et professionnelle","Des briefs qualifiés","Plus de temps pour le travail facturable"],"discovery":["À quoi ressemble une première demande typique ?","Combien de temps vous faut-il pour qualifier un nouveau projet ?"],"avoid":"Ne survendez pas l’automatisation — insistez sur la crédibilité et de meilleurs briefs."},"de":{"name":"Freiberufler & Selbstständige","who":"Freiberufler und Solo-Selbstständige, die ihr Fachwissen verkaufen: Designer, Entwickler, Trainer, Übersetzer.","why":"Allein müssen sie etabliert wirken und Anfragen qualifizieren, ohne Stunden im Hin und Her zu verbringen.","problem":"Anfragen kommen per E-Mail und LinkedIn ohne Budget oder Zeitrahmen, und das Angebot ist auf einer Profilseite schwer zu verstehen.","angle":"Wirken Sie wie ein etabliertes Studio und erhalten Sie Anfragen, die Umfang, Zeitrahmen und Budget bereits enthalten.","message":"Hallo {{firstName}}, ich verfolge Ihre Arbeit. Wenn ein neuer Kunde Sie kontaktiert — bekommen Sie meist ein klares Briefing? Studio ATS gibt Selbstständigen einen professionellen Bereich, der das Angebot präsentiert und jede Anfrage qualifiziert. Möchten Sie es sehen?","searches":["Freelancer [Fachgebiet] [Stadt]","freiberuflicher Berater [Fachgebiet]","LinkedIn: Freelancer [Fachgebiet]"],"pains":["Vage Anfragen ohne Budget","Stundenlanges Hin und Her vor einem Angebot","Ein online schwer greifbares Angebot"],"outcomes":["Ein etabliertes, professionelles Image","Qualifizierte Briefings","Mehr Zeit für abrechenbare Arbeit"],"discovery":["Wie sieht eine typische erste Anfrage aus?","Wie lange brauchen Sie, um ein neues Projekt zu qualifizieren?"],"avoid":"Übertreiben Sie nicht mit Automatisierung — konzentrieren Sie sich auf Glaubwürdigkeit und bessere Briefings."},"es":{"name":"Autónomos e independientes","who":"Autónomos y profesionales independientes que venden su experiencia: diseñadores, desarrolladores, formadores, traductores.","why":"Al trabajar solos, necesitan parecer consolidados y cualificar solicitudes sin pasar horas en idas y venidas.","problem":"Las solicitudes llegan por correo y LinkedIn sin presupuesto ni plazos, y la oferta es difícil de entender desde un perfil.","angle":"Parezca un estudio consolidado y reciba solicitudes que ya incluyen alcance, plazos y presupuesto.","message":"Hola {{firstName}}, sigo su trabajo. Cuando un nuevo cliente le contacta, ¿suele recibir un briefing claro? Studio ATS da a los independientes un espacio profesional que presenta la oferta y cualifica cada solicitud. ¿Quiere verlo?","searches":["freelance [especialidad] [ciudad]","consultor independiente [especialidad]","LinkedIn: freelance [especialidad]"],"pains":["Solicitudes vagas sin presupuesto","Horas de idas y venidas antes de un presupuesto","Una oferta difícil de entender en internet"],"outcomes":["Una imagen consolidada y profesional","Briefings cualificados","Más tiempo para el trabajo facturable"],"discovery":["¿Cómo es una primera solicitud típica?","¿Cuánto tarda en cualificar un nuevo proyecto?"],"avoid":"No exagere con la automatización — céntrese en la credibilidad y en mejores briefings."},"pt":{"name":"Freelancers e independentes","who":"Freelancers e profissionais independentes que vendem a sua experiência: designers, programadores, formadores, tradutores.","why":"Sozinhos, precisam de parecer estabelecidos e de qualificar pedidos sem passar horas em trocas de mensagens.","problem":"Os pedidos chegam por e-mail e LinkedIn sem orçamento nem prazo, e a oferta é difícil de perceber num perfil.","angle":"Pareça um estúdio estabelecido e receba pedidos que já trazem âmbito, prazo e orçamento.","message":"Olá {{firstName}}, acompanho o seu trabalho. Quando um novo cliente o contacta, costuma receber um briefing claro? A Studio ATS dá aos independentes um espaço profissional que apresenta a oferta e qualifica cada pedido. Quer ver?","searches":["freelancer [especialidade] [cidade]","consultor independente [especialidade]","LinkedIn: freelancer [especialidade]"],"pains":["Pedidos vagos sem orçamento","Horas de trocas de mensagens antes de um orçamento","Uma oferta difícil de perceber online"],"outcomes":["Uma imagem estabelecida e profissional","Briefings qualificados","Mais tempo para trabalho faturável"],"discovery":["Como é um primeiro pedido típico?","Quanto tempo demora a qualificar um novo projeto?"],"avoid":"Não exagere na automação — foque-se na credibilidade e em melhores briefings."},"it":{"name":"Freelance e indipendenti","who":"Freelance e professionisti indipendenti che vendono la propria competenza: designer, sviluppatori, formatori, traduttori.","why":"Da soli, devono sembrare affermati e qualificare le richieste senza passare ore in scambi di messaggi.","problem":"Le richieste arrivano via e-mail e LinkedIn senza budget né tempi, e l’offerta è difficile da capire da un profilo.","angle":"Sembra uno studio affermato e ricevi richieste che contengono già ambito, tempi e budget.","message":"Ciao {{firstName}}, seguo il tuo lavoro. Quando un nuovo cliente ti contatta, ricevi di solito un brief chiaro? Studio ATS dà agli indipendenti uno spazio professionale che presenta l’offerta e qualifica ogni richiesta. Vuoi vederlo?","searches":["freelance [specializzazione] [città]","consulente indipendente [specializzazione]","LinkedIn: freelance [specializzazione]"],"pains":["Richieste vaghe senza budget","Ore di scambi prima di un preventivo","Un’offerta difficile da capire online"],"outcomes":["Un’immagine affermata e professionale","Brief qualificati","Più tempo per il lavoro fatturabile"],"discovery":["Com’è una prima richiesta tipica?","Quanto tempo ti serve per qualificare un nuovo progetto?"],"avoid":"Non esagerare con l’automazione — concentrati su credibilità e brief migliori."},"nl":{"name":"Freelancers & zzp’ers","who":"Freelancers en zelfstandigen die hun expertise verkopen: ontwerpers, ontwikkelaars, trainers, vertalers.","why":"Als eenpitter moeten ze gevestigd overkomen en aanvragen kwalificeren zonder uren heen-en-weer te mailen.","problem":"Aanvragen komen via e-mail en LinkedIn zonder budget of planning, en het aanbod is lastig te begrijpen vanaf een profielpagina.","angle":"Kom over als een gevestigde studio en ontvang aanvragen die scope, planning en budget al bevatten.","message":"Hoi {{firstName}}, ik volg je werk. Als een nieuwe klant contact opneemt, krijg je dan meestal een duidelijke briefing? Studio ATS geeft zelfstandigen een professionele omgeving die het aanbod presenteert en elke aanvraag kwalificeert. Wil je het zien?","searches":["freelance [specialisme] [stad]","zelfstandig adviseur [specialisme]","LinkedIn: freelancer [specialisme]"],"pains":["Vage aanvragen zonder budget","Urenlang heen-en-weer vóór een offerte","Een aanbod dat online moeilijk te begrijpen is"],"outcomes":["Een gevestigd, professioneel imago","Gekwalificeerde briefings","Meer tijd voor declarabel werk"],"discovery":["Hoe ziet een typische eerste aanvraag eruit?","Hoe lang ben je bezig met het kwalificeren van een nieuw project?"],"avoid":"Overdrijf niet met automatisering — focus op geloofwaardigheid en betere briefings."},"ar":{"name":"المستقلون وأصحاب الأعمال الحرة","who":"مستقلون ومهنيون يعملون بمفردهم ويبيعون خبرتهم: مصممون ومطوّرون ومدرّبون ومترجمون.","why":"لأنهم يعملون بمفردهم، يحتاجون إلى الظهور بمظهر راسخ وتأهيل الطلبات دون قضاء ساعات في المراسلات.","problem":"تصل الطلبات عبر البريد وLinkedIn دون ميزانية أو توقيت، ويصعب فهم العرض من صفحة ملف شخصي.","angle":"اظهر كاستوديو راسخ وتلقَّ طلبات تتضمن مسبقًا النطاق والتوقيت والميزانية.","message":"مرحبًا {{firstName}}، أتابع عملك. عندما يتواصل معك عميل جديد، هل تتلقى عادةً موجزًا واضحًا؟ يمنح Studio ATS المستقلين مساحة مهنية تعرض العرض وتؤهّل كل طلب. هل تودّ رؤيته؟","searches":["مستقل [التخصص] [المدينة]","مستشار مستقل [التخصص]","LinkedIn: مستقل [التخصص]"],"pains":["طلبات غامضة بلا ميزانية","ساعات من المراسلات قبل عرض السعر","عرض يصعب فهمه على الإنترنت"],"outcomes":["صورة راسخة ومهنية","موجزات مؤهَّلة","وقت أكثر للعمل المدفوع"],"discovery":["كيف يبدو الطلب الأول المعتاد؟","كم من الوقت تحتاج لتأهيل مشروع جديد؟"],"avoid":"لا تبالغ في الحديث عن الأتمتة — ركّز على المصداقية وموجزات أفضل."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('agencies', 'megaphone', 6, 3, '{"en":{"name":"Agencies","who":"Small creative, communication and marketing agencies.","why":"They sell to demanding clients and need a showcase and an intake process that match their positioning.","problem":"The agency’s own site is often the last priority; new business requests are mixed with everything else.","angle":"A new-business engine the agency doesn’t have to build or maintain itself.","message":"Hi {{firstName}}, agencies often build great things for clients and have no time for their own new-business flow. How do prospects brief {{company}} today? Studio ATS handles showcase + qualified intake for you. Worth 10 minutes?","searches":["agence de communication [city]","agence créative [city]","agence marketing [city]"],"pains":["Their own site is never a priority","New-business requests mixed with daily email","Briefs arrive without budget"],"outcomes":["A showcase that reflects their level","A structured new-business intake","Nothing to build or maintain internally"],"discovery":["Who handles new-business requests at the agency?","When did you last update your own site?"],"avoid":"Agencies can build websites — sell the time saved and the done-for-you intake, not the site."},"fr":{"name":"Agences","who":"Petites agences créatives, de communication et de marketing.","why":"Elles vendent à des clients exigeants et ont besoin d’une vitrine et d’une prise de brief à la hauteur de leur positionnement.","problem":"Le site de l’agence passe toujours en dernier ; les demandes de nouveaux clients se mélangent au reste.","angle":"Un moteur de new business que l’agence n’a ni à construire ni à maintenir.","message":"Bonjour {{firstName}}, les agences construisent souvent de belles choses pour leurs clients et n’ont pas le temps pour leur propre prospection. Comment les prospects briefent-ils {{company}} aujourd’hui ? Studio ATS gère vitrine et prise de brief qualifiée pour vous. Ça vaut 10 minutes ?","searches":["agence de communication [ville]","agence créative [ville]","agence marketing [ville]"],"pains":["Leur propre site n’est jamais prioritaire","Des demandes mélangées aux emails quotidiens","Des briefs sans budget"],"outcomes":["Une vitrine à la hauteur de leur niveau","Une prise de brief structurée","Rien à construire ni à maintenir en interne"],"discovery":["Qui gère les demandes de nouveaux clients à l’agence ?","Quand avez-vous mis à jour votre propre site pour la dernière fois ?"],"avoid":"Une agence sait faire des sites — vendez le temps gagné et la prise de brief clé en main, pas le site."},"de":{"name":"Agenturen","who":"Kleine Kreativ-, Kommunikations- und Marketingagenturen.","why":"Sie verkaufen an anspruchsvolle Kunden und brauchen ein Schaufenster und einen Anfrageprozess, die zu ihrer Positionierung passen.","problem":"Die eigene Website hat oft die niedrigste Priorität; Neugeschäftsanfragen gehen im Rest unter.","angle":"Eine Neugeschäfts-Maschine, die die Agentur nicht selbst bauen oder pflegen muss.","message":"Hallo {{firstName}}, Agenturen bauen oft großartige Dinge für Kunden und haben keine Zeit für ihren eigenen Neugeschäftsprozess. Wie briefen Interessenten {{company}} heute? Studio ATS übernimmt Schaufenster + qualifizierte Anfrageaufnahme für Sie. 10 Minuten wert?","searches":["Kommunikationsagentur [Stadt]","Kreativagentur [Stadt]","Marketingagentur [Stadt]"],"pains":["Die eigene Website ist nie Priorität","Neugeschäftsanfragen zwischen den täglichen E-Mails","Briefings kommen ohne Budget"],"outcomes":["Ein Schaufenster, das ihrem Niveau entspricht","Eine strukturierte Neugeschäfts-Aufnahme","Nichts intern zu bauen oder zu pflegen"],"discovery":["Wer kümmert sich in der Agentur um Neugeschäftsanfragen?","Wann haben Sie Ihre eigene Website zuletzt aktualisiert?"],"avoid":"Agenturen können Websites bauen — verkaufen Sie die gesparte Zeit und die erledigte Anfrageaufnahme, nicht die Website."},"es":{"name":"Agencias","who":"Pequeñas agencias creativas, de comunicación y de marketing.","why":"Venden a clientes exigentes y necesitan un escaparate y un proceso de entrada a la altura de su posicionamiento.","problem":"La web propia de la agencia suele ser la última prioridad; las solicitudes de nuevos negocios se mezclan con todo lo demás.","angle":"Un motor de nuevos negocios que la agencia no tiene que construir ni mantener.","message":"Hola {{firstName}}, las agencias suelen crear cosas geniales para sus clientes y no tienen tiempo para su propio proceso comercial. ¿Cómo le envían hoy un briefing a {{company}}? Studio ATS se encarga del escaparate + la entrada de solicitudes cualificadas. ¿Merece 10 minutos?","searches":["agencia de comunicación [ciudad]","agencia creativa [ciudad]","agencia de marketing [ciudad]"],"pains":["Su propia web nunca es prioritaria","Solicitudes de nuevos negocios mezcladas con el correo diario","Briefings sin presupuesto"],"outcomes":["Un escaparate a la altura de su nivel","Una entrada de nuevos negocios estructurada","Nada que construir ni mantener internamente"],"discovery":["¿Quién gestiona las solicitudes de nuevos negocios en la agencia?","¿Cuándo actualizaron su propia web por última vez?"],"avoid":"Las agencias saben hacer webs — venda el tiempo ahorrado y la entrada de solicitudes ya resuelta, no la web."},"pt":{"name":"Agências","who":"Pequenas agências criativas, de comunicação e de marketing.","why":"Vendem a clientes exigentes e precisam de uma montra e de um processo de entrada à altura do seu posicionamento.","problem":"O site da própria agência é muitas vezes a última prioridade; os pedidos de novos negócios misturam-se com tudo o resto.","angle":"Um motor de novos negócios que a agência não tem de construir nem manter.","message":"Olá {{firstName}}, as agências criam muitas vezes coisas fantásticas para os clientes e não têm tempo para o seu próprio processo comercial. Como é que os contactos enviam hoje um briefing à {{company}}? A Studio ATS trata da montra + entrada de pedidos qualificados por si. Vale 10 minutos?","searches":["agência de comunicação [cidade]","agência criativa [cidade]","agência de marketing [cidade]"],"pains":["O próprio site nunca é prioridade","Pedidos de novos negócios misturados com o e-mail do dia a dia","Briefings sem orçamento"],"outcomes":["Uma montra à altura do seu nível","Uma entrada de novos negócios estruturada","Nada para construir nem manter internamente"],"discovery":["Quem trata dos pedidos de novos negócios na agência?","Quando atualizaram pela última vez o vosso próprio site?"],"avoid":"As agências sabem fazer sites — venda o tempo poupado e a entrada de pedidos já resolvida, não o site."},"it":{"name":"Agenzie","who":"Piccole agenzie creative, di comunicazione e di marketing.","why":"Vendono a clienti esigenti e hanno bisogno di una vetrina e di un processo di ingresso all’altezza del loro posizionamento.","problem":"Il sito dell’agenzia è spesso l’ultima priorità; le richieste di nuovi clienti si mescolano a tutto il resto.","angle":"Un motore di nuovo business che l’agenzia non deve costruire né mantenere.","message":"Ciao {{firstName}}, le agenzie creano spesso cose bellissime per i clienti e non hanno tempo per il proprio processo commerciale. Come mandano oggi un brief a {{company}} i potenziali clienti? Studio ATS gestisce vetrina + raccolta qualificata delle richieste per voi. Vale 10 minuti?","searches":["agenzia di comunicazione [città]","agenzia creativa [città]","agenzia di marketing [città]"],"pains":["Il proprio sito non è mai una priorità","Richieste di nuovi clienti mescolate alle e-mail quotidiane","Brief senza budget"],"outcomes":["Una vetrina all’altezza del loro livello","Una raccolta strutturata del nuovo business","Niente da costruire o mantenere internamente"],"discovery":["Chi gestisce le richieste di nuovi clienti in agenzia?","Quando avete aggiornato l’ultima volta il vostro sito?"],"avoid":"Le agenzie sanno fare siti — vendi il tempo risparmiato e la raccolta delle richieste già pronta, non il sito."},"nl":{"name":"Bureaus","who":"Kleine creatieve, communicatie- en marketingbureaus.","why":"Ze verkopen aan veeleisende klanten en hebben een etalage en intakeproces nodig dat bij hun positionering past.","problem":"De eigen website van het bureau heeft vaak de laagste prioriteit; nieuwe-klantaanvragen raken vermengd met de rest.","angle":"Een new-businessmotor die het bureau zelf niet hoeft te bouwen of te onderhouden.","message":"Hoi {{firstName}}, bureaus bouwen vaak prachtige dingen voor klanten en hebben geen tijd voor hun eigen new business. Hoe briefen prospects {{company}} nu? Studio ATS regelt etalage + gekwalificeerde intake voor jullie. 10 minuten waard?","searches":["communicatiebureau [stad]","creatief bureau [stad]","marketingbureau [stad]"],"pains":["De eigen website is nooit een prioriteit","New-businessaanvragen tussen de dagelijkse mail","Briefings zonder budget"],"outcomes":["Een etalage die hun niveau weerspiegelt","Een gestructureerde new-businessintake","Niets intern te bouwen of te onderhouden"],"discovery":["Wie behandelt bij het bureau de aanvragen van nieuwe klanten?","Wanneer hebben jullie je eigen website voor het laatst bijgewerkt?"],"avoid":"Bureaus kunnen zelf websites bouwen — verkoop de tijdwinst en de kant-en-klare intake, niet de website."},"ar":{"name":"الوكالات","who":"وكالات صغيرة للإبداع والاتصال والتسويق.","why":"يبيعون لعملاء متطلّبين ويحتاجون إلى واجهة وعملية استقبال طلبات تليق بتموضعهم.","problem":"موقع الوكالة نفسه غالبًا آخر الأولويات؛ وتختلط طلبات الأعمال الجديدة بكل شيء آخر.","angle":"محرّك لجلب أعمال جديدة لا تحتاج الوكالة إلى بنائه أو صيانته بنفسها.","message":"مرحبًا {{firstName}}، كثيرًا ما تبني الوكالات أشياء رائعة لعملائها ولا تجد وقتًا لمسار أعمالها الجديدة. كيف يرسل العملاء المحتملون موجزاتهم إلى {{company}} اليوم؟ يتولى Studio ATS الواجهة + استقبال الطلبات المؤهَّلة نيابة عنكم. هل يستحق ذلك 10 دقائق؟","searches":["وكالة اتصال [المدينة]","وكالة إبداعية [المدينة]","وكالة تسويق [المدينة]"],"pains":["موقعهم الخاص ليس أولوية أبدًا","طلبات الأعمال الجديدة وسط البريد اليومي","موجزات تصل بلا ميزانية"],"outcomes":["واجهة تعكس مستواهم","استقبال منظَّم للأعمال الجديدة","لا شيء يُبنى أو يُصان داخليًا"],"discovery":["من يتولى طلبات الأعمال الجديدة في الوكالة؟","متى حدّثتم موقعكم آخر مرة؟"],"avoid":"الوكالات قادرة على بناء المواقع — بِع الوقت الموفَّر واستقبال الطلبات الجاهز، لا الموقع."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('service-providers', 'handshake', 7, 4, '{"en":{"name":"Service providers","who":"Cleaning, maintenance, moving, home-help and other service companies working on quotes.","why":"Every quote requires information; incomplete requests cost time and slow the answer.","problem":"Requests arrive without surface, address or dates, and the company answers too late to win the job.","angle":"Collect everything needed for a quote in the first request, and answer faster than competitors.","message":"Hello {{firstName}}, how do quote requests reach {{company}} today, and what’s usually missing? Studio ATS collects the details you need for a quote in the first request. Shall I show you?","searches":["entreprise de nettoyage [city]","déménagement [city]","entreprise de services [city]"],"pains":["Incomplete quote requests","Slow answers that lose jobs","Too much time spent on the phone"],"outcomes":["Quote-ready requests","Faster answers","A clear, professional presentation of services"],"discovery":["What information do you need for a quote?","How quickly can you usually answer a request?"],"avoid":"Don’t promise to win more quotes — talk about faster, better-prepared answers."},"fr":{"name":"Prestataires de services","who":"Nettoyage, maintenance, déménagement, aide à domicile et autres entreprises de services travaillant sur devis.","why":"Chaque devis demande des informations ; les demandes incomplètes coûtent du temps et ralentissent la réponse.","problem":"Les demandes arrivent sans surface, adresse ni dates, et l’entreprise répond trop tard pour décrocher le travail.","angle":"Recueillir tout ce qu’il faut pour un devis dès la première demande, et répondre plus vite que la concurrence.","message":"Bonjour {{firstName}}, comment les demandes de devis arrivent-elles chez {{company}} aujourd’hui, et que manque-t-il souvent ? Studio ATS recueille dès la première demande les informations nécessaires au devis. Je vous montre ?","searches":["entreprise de nettoyage [ville]","déménagement [ville]","entreprise de services [ville]"],"pains":["Des demandes de devis incomplètes","Des réponses lentes qui font perdre des chantiers","Trop de temps au téléphone"],"outcomes":["Des demandes prêtes pour le devis","Des réponses plus rapides","Une présentation claire et professionnelle des services"],"discovery":["De quelles informations avez-vous besoin pour un devis ?","En combien de temps répondez-vous en général à une demande ?"],"avoid":"Ne promettez pas de gagner plus de devis — parlez de réponses plus rapides et mieux préparées."},"de":{"name":"Dienstleister","who":"Reinigungs-, Wartungs-, Umzugs-, Haushaltshilfe- und andere Dienstleistungsunternehmen, die mit Angeboten arbeiten.","why":"Jedes Angebot braucht Informationen; unvollständige Anfragen kosten Zeit und verzögern die Antwort.","problem":"Anfragen kommen ohne Fläche, Adresse oder Termine an, und das Unternehmen antwortet zu spät, um den Auftrag zu gewinnen.","angle":"Sammeln Sie alles, was für ein Angebot nötig ist, schon in der ersten Anfrage — und antworten Sie schneller als die Konkurrenz.","message":"Hallo {{firstName}}, wie erreichen Angebotsanfragen {{company}} heute, und was fehlt meistens? Studio ATS sammelt die Angaben, die Sie für ein Angebot brauchen, schon in der ersten Anfrage. Soll ich es Ihnen zeigen?","searches":["Reinigungsfirma [Stadt]","Umzugsunternehmen [Stadt]","Dienstleistungsunternehmen [Stadt]"],"pains":["Unvollständige Angebotsanfragen","Langsame Antworten, die Aufträge kosten","Zu viel Zeit am Telefon"],"outcomes":["Angebotsreife Anfragen","Schnellere Antworten","Eine klare, professionelle Darstellung der Leistungen"],"discovery":["Welche Informationen brauchen Sie für ein Angebot?","Wie schnell können Sie eine Anfrage meist beantworten?"],"avoid":"Versprechen Sie nicht, mehr Angebote zu gewinnen — sprechen Sie über schnellere, besser vorbereitete Antworten."},"es":{"name":"Empresas de servicios","who":"Empresas de limpieza, mantenimiento, mudanzas, ayuda a domicilio y otros servicios que trabajan con presupuesto.","why":"Cada presupuesto requiere información; las solicitudes incompletas cuestan tiempo y retrasan la respuesta.","problem":"Las solicitudes llegan sin superficie, dirección ni fechas, y la empresa responde demasiado tarde para conseguir el trabajo.","angle":"Recoja todo lo necesario para un presupuesto en la primera solicitud y responda más rápido que la competencia.","message":"Hola {{firstName}}, ¿cómo le llegan hoy las solicitudes de presupuesto a {{company}} y qué suele faltar? Studio ATS recoge los datos que necesita para un presupuesto en la primera solicitud. ¿Se lo enseño?","searches":["empresa de limpieza [ciudad]","mudanzas [ciudad]","empresa de servicios [ciudad]"],"pains":["Solicitudes de presupuesto incompletas","Respuestas lentas que hacen perder trabajos","Demasiado tiempo al teléfono"],"outcomes":["Solicitudes listas para presupuestar","Respuestas más rápidas","Una presentación clara y profesional de los servicios"],"discovery":["¿Qué información necesita para un presupuesto?","¿Con qué rapidez suele poder responder a una solicitud?"],"avoid":"No prometa ganar más presupuestos — hable de respuestas más rápidas y mejor preparadas."},"pt":{"name":"Prestadores de serviços","who":"Empresas de limpeza, manutenção, mudanças, apoio domiciliário e outros serviços que trabalham por orçamento.","why":"Cada orçamento exige informação; pedidos incompletos custam tempo e atrasam a resposta.","problem":"Os pedidos chegam sem área, morada ou datas, e a empresa responde tarde demais para ganhar o trabalho.","angle":"Recolha tudo o que é preciso para um orçamento logo no primeiro pedido e responda mais depressa do que a concorrência.","message":"Olá {{firstName}}, como chegam hoje os pedidos de orçamento à {{company}} e o que costuma faltar? A Studio ATS recolhe logo no primeiro pedido os dados de que precisa para um orçamento. Mostro-lhe?","searches":["empresa de limpezas [cidade]","mudanças [cidade]","empresa de serviços [cidade]"],"pains":["Pedidos de orçamento incompletos","Respostas lentas que fazem perder trabalhos","Demasiado tempo ao telefone"],"outcomes":["Pedidos prontos para orçamentar","Respostas mais rápidas","Uma apresentação clara e profissional dos serviços"],"discovery":["Que informação precisa para um orçamento?","Com que rapidez costuma responder a um pedido?"],"avoid":"Não prometa ganhar mais orçamentos — fale de respostas mais rápidas e mais bem preparadas."},"it":{"name":"Aziende di servizi","who":"Imprese di pulizia, manutenzione, traslochi, assistenza domestica e altri servizi che lavorano su preventivo.","why":"Ogni preventivo richiede informazioni; le richieste incomplete costano tempo e rallentano la risposta.","problem":"Le richieste arrivano senza superficie, indirizzo o date, e l’azienda risponde troppo tardi per aggiudicarsi il lavoro.","angle":"Raccogli tutto ciò che serve per un preventivo già nella prima richiesta e rispondi più in fretta della concorrenza.","message":"Buongiorno {{firstName}}, come arrivano oggi le richieste di preventivo a {{company}} e cosa manca di solito? Studio ATS raccoglie già nella prima richiesta i dati che le servono per un preventivo. Glielo mostro?","searches":["impresa di pulizie [città]","traslochi [città]","azienda di servizi [città]"],"pains":["Richieste di preventivo incomplete","Risposte lente che fanno perdere lavori","Troppo tempo al telefono"],"outcomes":["Richieste pronte per il preventivo","Risposte più rapide","Una presentazione chiara e professionale dei servizi"],"discovery":["Quali informazioni le servono per un preventivo?","Quanto velocemente riesce di solito a rispondere a una richiesta?"],"avoid":"Non promettere di vincere più preventivi — parla di risposte più rapide e meglio preparate."},"nl":{"name":"Dienstverleners","who":"Schoonmaak-, onderhouds-, verhuis-, thuishulp- en andere dienstverleners die met offertes werken.","why":"Elke offerte vraagt om informatie; onvolledige aanvragen kosten tijd en vertragen het antwoord.","problem":"Aanvragen komen binnen zonder oppervlakte, adres of data, en het bedrijf reageert te laat om de klus binnen te halen.","angle":"Verzamel alles wat nodig is voor een offerte al in de eerste aanvraag, en reageer sneller dan de concurrent.","message":"Hallo {{firstName}}, hoe komen offerteaanvragen nu bij {{company}} binnen, en wat ontbreekt er meestal? Studio ATS verzamelt al in de eerste aanvraag de gegevens die je voor een offerte nodig hebt. Zal ik het laten zien?","searches":["schoonmaakbedrijf [stad]","verhuisbedrijf [stad]","dienstverlener [stad]"],"pains":["Onvolledige offerteaanvragen","Trage antwoorden die klussen kosten","Te veel tijd aan de telefoon"],"outcomes":["Offerteklare aanvragen","Snellere antwoorden","Een heldere, professionele presentatie van de diensten"],"discovery":["Welke informatie heb je nodig voor een offerte?","Hoe snel kun je meestal op een aanvraag reageren?"],"avoid":"Beloof niet dat ze meer offertes winnen — praat over snellere, beter voorbereide antwoorden."},"ar":{"name":"مقدّمو الخدمات","who":"شركات التنظيف والصيانة والنقل والمساعدة المنزلية وغيرها من الخدمات التي تعمل بعروض الأسعار.","why":"يتطلب كل عرض سعر معلومات؛ والطلبات الناقصة تكلّف وقتًا وتؤخر الرد.","problem":"تصل الطلبات دون المساحة أو العنوان أو التواريخ، وترد الشركة متأخرة جدًا للفوز بالعمل.","angle":"اجمع كل ما يلزم لعرض السعر منذ الطلب الأول، ورُدّ أسرع من المنافسين.","message":"مرحبًا {{firstName}}، كيف تصل طلبات عروض الأسعار إلى {{company}} اليوم، وما الذي ينقص عادةً؟ يجمع Studio ATS منذ الطلب الأول البيانات التي تحتاجونها لعرض السعر. هل أريكم ذلك؟","searches":["شركة تنظيف [المدينة]","نقل أثاث [المدينة]","شركة خدمات [المدينة]"],"pains":["طلبات عروض أسعار ناقصة","ردود بطيئة تضيّع الأعمال","وقت طويل على الهاتف"],"outcomes":["طلبات جاهزة لعرض السعر","ردود أسرع","عرض واضح ومهني للخدمات"],"discovery":["ما المعلومات التي تحتاجونها لعرض السعر؟","ما مدى سرعتكم عادةً في الرد على طلب؟"],"avoid":"لا تَعِد بالفوز بعروض أسعار أكثر — تحدّث عن ردود أسرع وأفضل إعدادًا."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('local-businesses', 'store', 8, 3, '{"en":{"name":"Local businesses","who":"Shops, studios, restaurants with private events, and other local businesses taking bookings or requests.","why":"Locals search online first; a clear presence and an easy request path decide who gets the call.","problem":"Information is scattered across social profiles and directories, and requests arrive through too many channels.","angle":"One clear place that presents the business and turns local searches into structured requests.","message":"Hello {{firstName}}, when people nearby look for {{company}} online, where do they end up? Studio ATS gives local businesses one clear place to present the offer and receive requests. Worth a quick look?","searches":["[activity] [city]","commerce [city]","réservation événement privé [city]"],"pains":["Information scattered across profiles","Requests through too many channels","Little control over their online image"],"outcomes":["One clear, controlled presence","Requests in one place","An easy path from search to request"],"discovery":["Where do new customers find you?","Which requests would you like to receive more easily?"],"avoid":"Don’t compete with free directories — explain what a controlled, professional space adds."},"fr":{"name":"Entreprises locales","who":"Commerces, studios, restaurants avec événements privés et autres entreprises locales recevant réservations ou demandes.","why":"Les habitants cherchent d’abord en ligne ; une présence claire et une demande facile décident de qui reçoit l’appel.","problem":"Les informations sont éparpillées entre profils sociaux et annuaires, et les demandes arrivent par trop de canaux.","angle":"Un seul endroit clair qui présente l’activité et transforme les recherches locales en demandes structurées.","message":"Bonjour {{firstName}}, quand les gens du coin cherchent {{company}} en ligne, où arrivent-ils ? Studio ATS donne aux entreprises locales un endroit clair pour présenter l’offre et recevoir les demandes. Ça vaut un coup d’œil ?","searches":["[activité] [ville]","commerce [ville]","réservation événement privé [ville]"],"pains":["Des informations éparpillées","Des demandes par trop de canaux","Peu de maîtrise de leur image en ligne"],"outcomes":["Une présence claire et maîtrisée","Des demandes centralisées","Un chemin simple de la recherche à la demande"],"discovery":["Où vos nouveaux clients vous trouvent-ils ?","Quelles demandes aimeriez-vous recevoir plus facilement ?"],"avoid":"Ne vous battez pas contre les annuaires gratuits — expliquez ce qu’apporte un espace professionnel maîtrisé."},"de":{"name":"Lokale Unternehmen","who":"Geschäfte, Studios, Restaurants mit privaten Veranstaltungen und andere lokale Betriebe, die Buchungen oder Anfragen annehmen.","why":"Menschen in der Nähe suchen zuerst online; eine klare Präsenz und ein einfacher Anfrageweg entscheiden, wer den Anruf bekommt.","problem":"Informationen sind über soziale Profile und Verzeichnisse verstreut, und Anfragen kommen über zu viele Kanäle.","angle":"Ein klarer Ort, der das Unternehmen präsentiert und lokale Suchen in strukturierte Anfragen verwandelt.","message":"Hallo {{firstName}}, wenn Menschen in der Nähe online nach {{company}} suchen — wo landen sie? Studio ATS gibt lokalen Unternehmen einen klaren Ort, um das Angebot zu präsentieren und Anfragen zu erhalten. Einen kurzen Blick wert?","searches":["[Tätigkeit] [Stadt]","Geschäft [Stadt]","Location private Feier [Stadt]"],"pains":["Informationen über Profile verstreut","Anfragen über zu viele Kanäle","Wenig Kontrolle über das eigene Online-Bild"],"outcomes":["Eine klare, kontrollierte Präsenz","Anfragen an einem Ort","Ein einfacher Weg von der Suche zur Anfrage"],"discovery":["Wo finden neue Kunden Sie?","Welche Anfragen würden Sie gern einfacher erhalten?"],"avoid":"Konkurrieren Sie nicht mit kostenlosen Verzeichnissen — erklären Sie, was ein kontrollierter, professioneller Bereich zusätzlich bringt."},"es":{"name":"Negocios locales","who":"Tiendas, estudios, restaurantes con eventos privados y otros negocios locales que reciben reservas o solicitudes.","why":"La gente de la zona busca primero en internet; una presencia clara y un camino sencillo para solicitar deciden quién recibe la llamada.","problem":"La información está dispersa entre perfiles sociales y directorios, y las solicitudes llegan por demasiados canales.","angle":"Un lugar claro que presenta el negocio y convierte las búsquedas locales en solicitudes estructuradas.","message":"Hola {{firstName}}, cuando la gente de la zona busca {{company}} en internet, ¿dónde acaba? Studio ATS da a los negocios locales un lugar claro para presentar su oferta y recibir solicitudes. ¿Le echa un vistazo?","searches":["[actividad] [ciudad]","comercio [ciudad]","espacio para eventos privados [ciudad]"],"pains":["Información dispersa entre perfiles","Solicitudes por demasiados canales","Poco control sobre su imagen en internet"],"outcomes":["Una presencia clara y controlada","Solicitudes en un solo lugar","Un camino sencillo de la búsqueda a la solicitud"],"discovery":["¿Dónde le encuentran los nuevos clientes?","¿Qué solicitudes le gustaría recibir con más facilidad?"],"avoid":"No compita con los directorios gratuitos — explique lo que aporta un espacio profesional y controlado."},"pt":{"name":"Negócios locais","who":"Lojas, estúdios, restaurantes com eventos privados e outros negócios locais que recebem reservas ou pedidos.","why":"Quem vive perto procura primeiro online; uma presença clara e um caminho simples para pedir decidem quem recebe a chamada.","problem":"A informação está dispersa entre perfis sociais e diretórios, e os pedidos chegam por demasiados canais.","angle":"Um lugar claro que apresenta o negócio e transforma as pesquisas locais em pedidos estruturados.","message":"Olá {{firstName}}, quando as pessoas da zona procuram a {{company}} online, onde vão parar? A Studio ATS dá aos negócios locais um lugar claro para apresentar a oferta e receber pedidos. Vale uma vista de olhos?","searches":["[atividade] [cidade]","comércio [cidade]","espaço para eventos privados [cidade]"],"pains":["Informação dispersa entre perfis","Pedidos por demasiados canais","Pouco controlo sobre a imagem online"],"outcomes":["Uma presença clara e controlada","Pedidos num só lugar","Um caminho simples da pesquisa ao pedido"],"discovery":["Onde é que os novos clientes o encontram?","Que pedidos gostaria de receber com mais facilidade?"],"avoid":"Não concorra com diretórios gratuitos — explique o que um espaço profissional e controlado acrescenta."},"it":{"name":"Attività locali","who":"Negozi, studi, ristoranti con eventi privati e altre attività locali che ricevono prenotazioni o richieste.","why":"Chi abita vicino cerca prima online; una presenza chiara e un modo semplice per chiedere decidono chi riceve la chiamata.","problem":"Le informazioni sono sparse tra profili social e directory, e le richieste arrivano da troppi canali.","angle":"Un unico posto chiaro che presenta l’attività e trasforma le ricerche locali in richieste strutturate.","message":"Buongiorno {{firstName}}, quando le persone della zona cercano {{company}} online, dove finiscono? Studio ATS dà alle attività locali un posto chiaro per presentare l’offerta e ricevere richieste. Vale un’occhiata?","searches":["[attività] [città]","negozio [città]","location per feste private [città]"],"pains":["Informazioni sparse tra i profili","Richieste da troppi canali","Poco controllo sulla propria immagine online"],"outcomes":["Una presenza chiara e controllata","Richieste in un unico posto","Un percorso semplice dalla ricerca alla richiesta"],"discovery":["Dove la trovano i nuovi clienti?","Quali richieste vorrebbe ricevere più facilmente?"],"avoid":"Non competere con le directory gratuite — spiega cosa aggiunge uno spazio professionale e controllato."},"nl":{"name":"Lokale ondernemers","who":"Winkels, studio’s, restaurants met besloten evenementen en andere lokale bedrijven die reserveringen of aanvragen ontvangen.","why":"Mensen in de buurt zoeken eerst online; een duidelijke uitstraling en een makkelijke weg om aan te vragen bepalen wie gebeld wordt.","problem":"Informatie staat verspreid over sociale profielen en gidsen, en aanvragen komen via te veel kanalen binnen.","angle":"Eén duidelijke plek die het bedrijf presenteert en lokale zoekopdrachten omzet in gestructureerde aanvragen.","message":"Hallo {{firstName}}, als mensen in de buurt {{company}} online zoeken, waar komen ze dan terecht? Studio ATS geeft lokale ondernemers één duidelijke plek om het aanbod te presenteren en aanvragen te ontvangen. Een korte blik waard?","searches":["[activiteit] [stad]","winkel [stad]","locatie besloten feest [stad]"],"pains":["Informatie verspreid over profielen","Aanvragen via te veel kanalen","Weinig controle over hun online imago"],"outcomes":["Eén duidelijke, beheerde uitstraling","Aanvragen op één plek","Een makkelijke weg van zoekopdracht naar aanvraag"],"discovery":["Waar vinden nieuwe klanten je?","Welke aanvragen zou je graag makkelijker ontvangen?"],"avoid":"Concurreer niet met gratis gidsen — leg uit wat een beheerde, professionele omgeving toevoegt."},"ar":{"name":"الأنشطة المحلية","who":"متاجر واستوديوهات ومطاعم تستضيف مناسبات خاصة وأنشطة محلية أخرى تتلقى حجوزات أو طلبات.","why":"يبحث سكان المنطقة على الإنترنت أولًا؛ والحضور الواضح وطريق الطلب السهل يحددان من يتلقى الاتصال.","problem":"المعلومات مبعثرة بين الحسابات الاجتماعية والأدلة، والطلبات تصل عبر قنوات كثيرة جدًا.","angle":"مكان واحد واضح يعرض النشاط ويحوّل عمليات البحث المحلية إلى طلبات منظَّمة.","message":"مرحبًا {{firstName}}، عندما يبحث أهل المنطقة عن {{company}} على الإنترنت، أين ينتهي بهم المطاف؟ يمنح Studio ATS الأنشطة المحلية مكانًا واحدًا واضحًا لعرض العرض وتلقي الطلبات. هل يستحق ذلك نظرة سريعة؟","searches":["[النشاط] [المدينة]","متجر [المدينة]","قاعة مناسبات خاصة [المدينة]"],"pains":["معلومات مبعثرة بين الحسابات","طلبات عبر قنوات كثيرة جدًا","تحكّم ضعيف في صورتهم على الإنترنت"],"outcomes":["حضور واحد واضح ومتحكَّم به","طلبات في مكان واحد","طريق سهل من البحث إلى الطلب"],"discovery":["أين يجدكم العملاء الجدد؟","ما الطلبات التي تودّون تلقيها بسهولة أكبر؟"],"avoid":"لا تنافس الأدلة المجانية — اشرح ما تضيفه مساحة مهنية متحكَّم بها."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('photographers', 'camera', 1, 3, '{"en":{"name":"Photographers","who":"Wedding, portrait, corporate and architecture photographers with a premium offer.","why":"Their portfolio is their shop window — Studio ATS turns it into a booking engine.","problem":"Enquiries arrive through Instagram DMs and a basic form, without date, budget or project type.","angle":"Stop answering vague DMs — receive qualified requests with the date and budget already filled in.","message":"Hi [First name], I love your work on [project]. Quick question: how do most of your clients contact you today? I work with Studio ATS, which turns a photographer’s portfolio into a space that qualifies requests (date, budget, type of shoot) and books calls automatically. Open to a 10-minute look?","searches":["wedding photographer [city]","portrait photographer [city]","#weddingphotographer [city]"]},"fr":{"name":"Photographes","who":"Photographes de mariage, portrait, entreprise et architecture avec une offre premium.","why":"Leur portfolio est leur vitrine — Studio ATS en fait un outil de réservation.","problem":"Les demandes arrivent en DM Instagram et via un formulaire basique, sans date, budget ni type de projet.","angle":"Arrêtez de répondre à des DM vagues — recevez des demandes qualifiées avec date et budget.","message":"Bonjour [Prénom], j’adore votre travail sur [projet]. Petite question : comment la plupart de vos clients vous contactent-ils aujourd’hui ? Je travaille avec Studio ATS, qui transforme le portfolio d’un photographe en espace qui qualifie les demandes (date, budget, type de séance) et programme les appels automatiquement. Ouvert à un aperçu de 10 minutes ?","searches":["photographe mariage [ville]","photographe portrait [ville]","#photographemariage [ville]"]},"de":{"name":"Fotografen","who":"Hochzeits-, Porträt-, Business- und Architekturfotografen mit einem Premium-Angebot.","why":"Ihr Portfolio ist ihr Schaufenster — Studio ATS macht daraus ein Buchungswerkzeug.","problem":"Anfragen kommen per Instagram-Direktnachricht und über ein einfaches Formular, ohne Datum, Budget oder Art des Shootings.","angle":"Schluss mit vagen Direktnachrichten — erhalten Sie qualifizierte Anfragen mit bereits ausgefülltem Datum und Budget.","message":"Hallo [Vorname], Ihre Arbeit an [Projekt] gefällt mir sehr. Kurze Frage: Wie kontaktieren Sie die meisten Kunden heute? Ich arbeite mit Studio ATS, das das Portfolio eines Fotografen in einen Bereich verwandelt, der Anfragen qualifiziert (Datum, Budget, Art des Shootings) und Gespräche automatisch bucht. Offen für einen 10-minütigen Blick?","searches":["Hochzeitsfotograf [Stadt]","Porträtfotograf [Stadt]","#hochzeitsfotograf [Stadt]"]},"es":{"name":"Fotógrafos","who":"Fotógrafos de bodas, retrato, empresa y arquitectura con una oferta premium.","why":"Su portfolio es su escaparate — Studio ATS lo convierte en una herramienta de reservas.","problem":"Las consultas llegan por mensajes directos de Instagram y un formulario básico, sin fecha, presupuesto ni tipo de sesión.","angle":"Deje de responder a mensajes vagos — reciba solicitudes cualificadas con la fecha y el presupuesto ya indicados.","message":"Hola [Nombre], me encanta su trabajo en [proyecto]. Una pregunta rápida: ¿cómo le contactan hoy la mayoría de sus clientes? Trabajo con Studio ATS, que convierte el portfolio de un fotógrafo en un espacio que cualifica las solicitudes (fecha, presupuesto, tipo de sesión) y reserva las llamadas automáticamente. ¿Le apetece verlo en 10 minutos?","searches":["fotógrafo de bodas [ciudad]","fotógrafo de retrato [ciudad]","#fotografodebodas [ciudad]"]},"pt":{"name":"Fotógrafos","who":"Fotógrafos de casamento, retrato, empresa e arquitetura com uma oferta premium.","why":"O portefólio é a montra deles — a Studio ATS transforma-o numa ferramenta de reservas.","problem":"Os pedidos chegam por mensagens diretas do Instagram e por um formulário básico, sem data, orçamento nem tipo de sessão.","angle":"Deixe de responder a mensagens vagas — receba pedidos qualificados com a data e o orçamento já preenchidos.","message":"Olá [Nome], adoro o seu trabalho em [projeto]. Uma pergunta rápida: como é que a maioria dos seus clientes o contacta hoje? Trabalho com a Studio ATS, que transforma o portefólio de um fotógrafo num espaço que qualifica os pedidos (data, orçamento, tipo de sessão) e marca chamadas automaticamente. Aberto a ver em 10 minutos?","searches":["fotógrafo de casamento [cidade]","fotógrafo de retrato [cidade]","#fotografodecasamento [cidade]"]},"it":{"name":"Fotografi","who":"Fotografi di matrimonio, ritratto, aziendali e di architettura con un’offerta premium.","why":"Il portfolio è la loro vetrina — Studio ATS lo trasforma in uno strumento di prenotazione.","problem":"Le richieste arrivano via messaggi diretti di Instagram e da un modulo base, senza data, budget né tipo di servizio.","angle":"Basta rispondere a messaggi vaghi — ricevi richieste qualificate con data e budget già indicati.","message":"Ciao [Nome], adoro il tuo lavoro su [progetto]. Una domanda veloce: come ti contattano oggi la maggior parte dei clienti? Lavoro con Studio ATS, che trasforma il portfolio di un fotografo in uno spazio che qualifica le richieste (data, budget, tipo di servizio) e fissa le chiamate in automatico. Ti va di vederlo in 10 minuti?","searches":["fotografo matrimonio [città]","fotografo ritratti [città]","#fotografomatrimonio [città]"]},"nl":{"name":"Fotografen","who":"Bruilofts-, portret-, bedrijfs- en architectuurfotografen met een premium aanbod.","why":"Hun portfolio is hun etalage — Studio ATS maakt er een boekingsmachine van.","problem":"Aanvragen komen binnen via Instagram-DM’s en een simpel formulier, zonder datum, budget of type shoot.","angle":"Stop met reageren op vage DM’s — ontvang gekwalificeerde aanvragen met datum en budget al ingevuld.","message":"Hoi [Voornaam], ik vind je werk aan [project] prachtig. Korte vraag: hoe nemen de meeste klanten nu contact met je op? Ik werk met Studio ATS, dat het portfolio van een fotograaf omzet in een omgeving die aanvragen kwalificeert (datum, budget, type shoot) en gesprekken automatisch inplant. Zin om er 10 minuten naar te kijken?","searches":["bruiloftsfotograaf [stad]","portretfotograaf [stad]","#trouwfotograaf [stad]"]},"ar":{"name":"المصوّرون","who":"مصوّرو الأعراس والبورتريه والشركات والعمارة الذين يقدّمون عرضًا فاخرًا.","why":"معرض أعمالهم هو واجهتهم — ويحوّله Studio ATS إلى أداة حجز.","problem":"تصل الاستفسارات عبر رسائل Instagram الخاصة ونموذج بسيط، دون تاريخ أو ميزانية أو نوع جلسة التصوير.","angle":"توقّف عن الرد على رسائل غامضة — تلقَّ طلبات مؤهَّلة بتاريخ وميزانية محددين مسبقًا.","message":"مرحبًا [الاسم]، يعجبني كثيرًا عملك في [المشروع]. سؤال سريع: كيف يتواصل معك معظم العملاء اليوم؟ أعمل مع Studio ATS الذي يحوّل معرض أعمال المصوّر إلى مساحة تؤهّل الطلبات (التاريخ والميزانية ونوع الجلسة) وتحجز المكالمات تلقائيًا. هل تودّ إلقاء نظرة لمدة 10 دقائق؟","searches":["مصوّر أعراس [المدينة]","مصوّر بورتريه [المدينة]","#مصور_اعراس [المدينة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('wedding-planners', 'rings', 2, 3, '{"en":{"name":"Wedding planners","who":"Independent planners and agencies organising premium weddings.","why":"Each wedding is a high-value project; every missed request is a lost season slot.","problem":"Couples send the same questions again and again; qualification happens over long email threads.","angle":"Let couples present their project before the first call — you only talk to the right ones.","message":"Hello [First name], your [venue / style] weddings are beautiful. I’m reaching out because Studio ATS helps planners receive couples’ requests already qualified — date, guests, budget, style — and book the discovery call automatically. Would it be useful to see how it works?","searches":["wedding planner [city]","organisatrice mariage [city]","destination wedding planner [region]"]},"fr":{"name":"Wedding planners","who":"Wedding planners indépendants et agences organisant des mariages haut de gamme.","why":"Chaque mariage est un projet à forte valeur ; chaque demande perdue est une date perdue.","problem":"Les couples posent toujours les mêmes questions ; la qualification se fait par longs échanges d’emails.","angle":"Laissez les couples présenter leur projet avant le premier appel — vous ne parlez qu’aux bons.","message":"Bonjour [Prénom], vos mariages [lieu / style] sont superbes. Je vous contacte car Studio ATS aide les wedding planners à recevoir des demandes déjà qualifiées — date, invités, budget, style — et à programmer l’appel découverte automatiquement. Ça vous intéresserait de voir comment ça marche ?","searches":["wedding planner [ville]","organisatrice de mariage [ville]","mariage clé en main [région]"]},"de":{"name":"Hochzeitsplaner","who":"Selbstständige Planer und Agenturen, die Premium-Hochzeiten organisieren.","why":"Jede Hochzeit ist ein wertvolles Projekt; jede verpasste Anfrage ist ein verlorener Termin in der Saison.","problem":"Paare stellen immer wieder dieselben Fragen; die Qualifizierung läuft über lange E-Mail-Verläufe.","angle":"Lassen Sie Paare ihr Projekt vor dem ersten Gespräch vorstellen — Sie sprechen nur mit den richtigen.","message":"Hallo [Vorname], Ihre Hochzeiten in [Location / Stil] sind wunderschön. Ich melde mich, weil Studio ATS Planern hilft, Anfragen von Paaren bereits qualifiziert zu erhalten — Datum, Gäste, Budget, Stil — und das Kennenlerngespräch automatisch zu buchen. Wäre es nützlich zu sehen, wie es funktioniert?","searches":["Hochzeitsplaner [Stadt]","Weddingplanner [Stadt]","Destination-Wedding-Planer [Region]"]},"es":{"name":"Wedding planners","who":"Organizadores independientes y agencias de bodas premium.","why":"Cada boda es un proyecto de alto valor; cada solicitud perdida es una fecha perdida en la temporada.","problem":"Las parejas hacen las mismas preguntas una y otra vez; la cualificación se hace en largos hilos de correo.","angle":"Deje que las parejas presenten su proyecto antes de la primera llamada — solo hablará con las adecuadas.","message":"Hola [Nombre], sus bodas en [lugar / estilo] son preciosas. Le escribo porque Studio ATS ayuda a los wedding planners a recibir solicitudes de parejas ya cualificadas — fecha, invitados, presupuesto, estilo — y a reservar automáticamente la llamada de descubrimiento. ¿Le sería útil ver cómo funciona?","searches":["wedding planner [ciudad]","organizadora de bodas [ciudad]","bodas destino [región]"]},"pt":{"name":"Wedding planners","who":"Organizadores independentes e agências de casamentos premium.","why":"Cada casamento é um projeto de alto valor; cada pedido perdido é uma data perdida na época.","problem":"Os casais fazem sempre as mesmas perguntas; a qualificação acontece em longas trocas de e-mails.","angle":"Deixe os casais apresentar o projeto antes da primeira chamada — só fala com os certos.","message":"Olá [Nome], os seus casamentos em [local / estilo] são lindíssimos. Contacto-o porque a Studio ATS ajuda os wedding planners a receber pedidos de casais já qualificados — data, convidados, orçamento, estilo — e a marcar automaticamente a chamada de descoberta. Seria útil ver como funciona?","searches":["wedding planner [cidade]","organização de casamentos [cidade]","casamentos destino [região]"]},"it":{"name":"Wedding planner","who":"Wedding planner indipendenti e agenzie che organizzano matrimoni di alto livello.","why":"Ogni matrimonio è un progetto di alto valore; ogni richiesta persa è una data persa nella stagione.","problem":"Le coppie fanno sempre le stesse domande; la qualificazione avviene in lunghi scambi di e-mail.","angle":"Lascia che le coppie presentino il loro progetto prima della prima chiamata — parli solo con quelle giuste.","message":"Ciao [Nome], i tuoi matrimoni a [location / stile] sono splendidi. Ti scrivo perché Studio ATS aiuta i wedding planner a ricevere richieste di coppie già qualificate — data, invitati, budget, stile — e a fissare in automatico la chiamata conoscitiva. Ti sarebbe utile vedere come funziona?","searches":["wedding planner [città]","organizzazione matrimoni [città]","destination wedding [regione]"]},"nl":{"name":"Weddingplanners","who":"Zelfstandige planners en bureaus die premium bruiloften organiseren.","why":"Elke bruiloft is een waardevol project; elke gemiste aanvraag is een verloren datum in het seizoen.","problem":"Stellen stellen steeds dezelfde vragen; kwalificeren gebeurt via lange e-mailreeksen.","angle":"Laat stellen hun project presenteren vóór het eerste gesprek — je praat alleen met de juiste.","message":"Hoi [Voornaam], jullie bruiloften op [locatie / stijl] zijn prachtig. Ik neem contact op omdat Studio ATS planners helpt om aanvragen van stellen al gekwalificeerd te ontvangen — datum, gasten, budget, stijl — en het kennismakingsgesprek automatisch in te plannen. Handig om te zien hoe het werkt?","searches":["weddingplanner [stad]","bruiloft organiseren [stad]","destination wedding planner [regio]"]},"ar":{"name":"منظّمو الأعراس","who":"منظّمون مستقلون ووكالات تنظّم أعراسًا فاخرة.","why":"كل عرس مشروع عالي القيمة؛ وكل طلب ضائع هو موعد ضائع في الموسم.","problem":"يطرح الأزواج الأسئلة نفسها مرارًا؛ ويجري التأهيل عبر سلاسل بريد طويلة.","angle":"دع الأزواج يعرضون مشروعهم قبل المكالمة الأولى — فلا تتحدث إلا مع المناسبين.","message":"مرحبًا [الاسم]، أعراسك في [المكان / الأسلوب] رائعة. أتواصل معك لأن Studio ATS يساعد منظّمي الأعراس على تلقي طلبات الأزواج مؤهَّلة مسبقًا — التاريخ والضيوف والميزانية والأسلوب — وحجز المكالمة الاستكشافية تلقائيًا. هل يفيدك أن ترى كيف يعمل؟","searches":["منظّم أعراس [المدينة]","تنظيم حفلات زفاف [المدينة]","أعراس الوجهات [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('videographers', 'video', 3, 3, '{"en":{"name":"Videographers","who":"Wedding, corporate and brand-content videographers and small production studios.","why":"Video projects are expensive — prospects need to see work and understand the process before calling.","problem":"Showreels live on YouTube/Vimeo, requests come in without scope, quoting takes hours.","angle":"Your showreel + a guided brief = requests you can quote immediately.","message":"Hi [First name], great reel on [project]. When a brand contacts you, do you usually get a clear brief? Studio ATS turns your portfolio into a space where prospects describe format, deadline and budget before the call. Worth a quick look?","searches":["videographer [city]","video production company [city]","wedding videographer [region]"]},"fr":{"name":"Vidéastes","who":"Vidéastes mariage, corporate, contenu de marque et petits studios de production.","why":"Un projet vidéo coûte cher — le prospect doit voir le travail et comprendre le process avant d’appeler.","problem":"Les showreels sont sur YouTube/Vimeo, les demandes arrivent sans cadrage, chiffrer prend des heures.","angle":"Votre showreel + un brief guidé = des demandes chiffrables immédiatement.","message":"Bonjour [Prénom], super réalisation sur [projet]. Quand une marque vous contacte, avez-vous en général un brief clair ? Studio ATS transforme votre portfolio en espace où le prospect précise format, délai et budget avant l’appel. Ça vaut un coup d’œil ?","searches":["vidéaste [ville]","société de production vidéo [ville]","vidéaste mariage [région]"]},"de":{"name":"Videografen","who":"Hochzeits-, Business- und Brand-Content-Videografen sowie kleine Produktionsstudios.","why":"Videoprojekte sind teuer — Interessenten wollen Arbeiten sehen und den Ablauf verstehen, bevor sie anrufen.","problem":"Showreels liegen auf YouTube/Vimeo, Anfragen kommen ohne Umfang an, und Angebote kosten Stunden.","angle":"Ihr Showreel + ein geführtes Briefing = Anfragen, für die Sie sofort ein Angebot machen können.","message":"Hallo [Vorname], starkes Reel zu [Projekt]. Wenn eine Marke Sie kontaktiert — bekommen Sie meist ein klares Briefing? Studio ATS macht aus Ihrem Portfolio einen Bereich, in dem Interessenten Format, Deadline und Budget vor dem Gespräch beschreiben. Einen kurzen Blick wert?","searches":["Videograf [Stadt]","Videoproduktion [Stadt]","Hochzeitsvideograf [Region]"]},"es":{"name":"Videógrafos","who":"Videógrafos de bodas, empresa y contenido de marca, y pequeñas productoras.","why":"Los proyectos de vídeo son caros — los prospectos necesitan ver trabajos y entender el proceso antes de llamar.","problem":"Los showreels están en YouTube/Vimeo, las solicitudes llegan sin alcance y presupuestar lleva horas.","angle":"Su showreel + un briefing guiado = solicitudes que puede presupuestar al momento.","message":"Hola [Nombre], gran reel de [proyecto]. Cuando una marca le contacta, ¿suele recibir un briefing claro? Studio ATS convierte su portfolio en un espacio donde los prospectos describen formato, plazo y presupuesto antes de la llamada. ¿Le echa un vistazo?","searches":["videógrafo [ciudad]","productora audiovisual [ciudad]","vídeo de bodas [región]"]},"pt":{"name":"Videógrafos","who":"Videógrafos de casamento, empresa e conteúdo de marca, e pequenas produtoras.","why":"Os projetos de vídeo são caros — os contactos precisam de ver trabalhos e perceber o processo antes de ligar.","problem":"Os showreels estão no YouTube/Vimeo, os pedidos chegam sem âmbito e orçamentar leva horas.","angle":"O seu showreel + um briefing guiado = pedidos que pode orçamentar de imediato.","message":"Olá [Nome], ótimo reel de [projeto]. Quando uma marca o contacta, costuma receber um briefing claro? A Studio ATS transforma o seu portefólio num espaço onde os contactos descrevem formato, prazo e orçamento antes da chamada. Vale uma vista de olhos?","searches":["videógrafo [cidade]","produtora de vídeo [cidade]","vídeo de casamento [região]"]},"it":{"name":"Videomaker","who":"Videomaker per matrimoni, aziende e contenuti di marca, e piccole case di produzione.","why":"I progetti video sono costosi — i contatti devono vedere i lavori e capire il processo prima di chiamare.","problem":"Gli showreel sono su YouTube/Vimeo, le richieste arrivano senza ambito e fare un preventivo richiede ore.","angle":"Il tuo showreel + un brief guidato = richieste che puoi preventivare subito.","message":"Ciao [Nome], ottimo reel su [progetto]. Quando un brand ti contatta, ricevi di solito un brief chiaro? Studio ATS trasforma il tuo portfolio in uno spazio dove i contatti descrivono formato, scadenza e budget prima della chiamata. Vale un’occhiata?","searches":["videomaker [città]","casa di produzione video [città]","video matrimonio [regione]"]},"nl":{"name":"Videografen","who":"Bruilofts-, bedrijfs- en brandcontentvideografen en kleine productiehuizen.","why":"Videoprojecten zijn duur — prospects willen werk zien en het proces begrijpen voordat ze bellen.","problem":"Showreels staan op YouTube/Vimeo, aanvragen komen zonder scope binnen en offreren kost uren.","angle":"Je showreel + een begeleide briefing = aanvragen waarvoor je meteen een offerte kunt maken.","message":"Hoi [Voornaam], sterke reel van [project]. Als een merk contact opneemt, krijg je dan meestal een duidelijke briefing? Studio ATS maakt van je portfolio een omgeving waarin prospects formaat, deadline en budget beschrijven vóór het gesprek. Een korte blik waard?","searches":["videograaf [stad]","videoproductiebedrijf [stad]","trouwvideograaf [regio]"]},"ar":{"name":"مصوّرو الفيديو","who":"مصوّرو فيديو الأعراس والشركات ومحتوى العلامات التجارية، واستوديوهات الإنتاج الصغيرة.","why":"مشاريع الفيديو مكلفة — يحتاج العملاء المحتملون إلى رؤية الأعمال وفهم العملية قبل الاتصال.","problem":"مقاطع العرض على YouTube/Vimeo، والطلبات تصل بلا نطاق، وإعداد عرض السعر يستغرق ساعات.","angle":"مقطع العرض الخاص بك + موجز موجَّه = طلبات يمكنك تسعيرها فورًا.","message":"مرحبًا [الاسم]، مقطع رائع لـ [المشروع]. عندما تتواصل معك علامة تجارية، هل تتلقى عادةً موجزًا واضحًا؟ يحوّل Studio ATS معرض أعمالك إلى مساحة يصف فيها العملاء المحتملون الصيغة والموعد النهائي والميزانية قبل المكالمة. هل يستحق ذلك نظرة سريعة؟","searches":["مصوّر فيديو [المدينة]","شركة إنتاج فيديو [المدينة]","تصوير فيديو أعراس [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('architects', 'ruler', 4, 3, '{"en":{"name":"Architects","who":"Architecture practices working with private clients and small businesses.","why":"Projects have long cycles and high value — first impressions and qualification matter.","problem":"Most requests are too early, too small or out of scope, and take time to filter.","angle":"Present your references like a monograph and filter projects by scope before the first meeting.","message":"Hello [First name], I came across your project [name]. Many practices tell me they spend time on requests that aren’t a fit. Studio ATS presents your references and qualifies each project (type, surface, budget, timing) before the first meeting. Open to a short demo?","searches":["architect [city]","architecte DPLG [city]","residential architect [region]"]},"fr":{"name":"Architectes","who":"Cabinets d’architecture travaillant avec des particuliers et des petites entreprises.","why":"Des cycles longs, une forte valeur — la première impression et la qualification comptent.","problem":"Beaucoup de demandes arrivent trop tôt, sont trop petites ou hors périmètre, et prennent du temps à trier.","angle":"Présentez vos références comme une monographie et filtrez les projets avant le premier rendez-vous.","message":"Bonjour [Prénom], j’ai découvert votre projet [nom]. Beaucoup de cabinets me disent passer du temps sur des demandes qui ne leur correspondent pas. Studio ATS présente vos références et qualifie chaque projet (type, surface, budget, délai) avant le premier rendez-vous. Partant pour une courte démo ?","searches":["architecte [ville]","architecte maison individuelle [ville]","architecte rénovation [région]"]},"de":{"name":"Architekten","who":"Architekturbüros, die mit Privatkunden und kleinen Unternehmen arbeiten.","why":"Projekte haben lange Zyklen und hohen Wert — der erste Eindruck und die Qualifizierung zählen.","problem":"Die meisten Anfragen kommen zu früh, sind zu klein oder passen nicht, und das Filtern kostet Zeit.","angle":"Präsentieren Sie Ihre Referenzen wie eine Monografie und filtern Sie Projekte nach Umfang vor dem ersten Treffen.","message":"Hallo [Vorname], ich bin auf Ihr Projekt [Name] gestoßen. Viele Büros erzählen mir, dass sie Zeit mit unpassenden Anfragen verbringen. Studio ATS präsentiert Ihre Referenzen und qualifiziert jedes Projekt (Art, Fläche, Budget, Zeitrahmen) vor dem ersten Treffen. Offen für eine kurze Demo?","searches":["Architekt [Stadt]","Architekturbüro [Stadt]","Architekt Einfamilienhaus [Region]"]},"es":{"name":"Arquitectos","who":"Estudios de arquitectura que trabajan con particulares y pequeñas empresas.","why":"Los proyectos tienen ciclos largos y alto valor — la primera impresión y la cualificación importan.","problem":"La mayoría de las solicitudes llegan demasiado pronto, son demasiado pequeñas o no encajan, y filtrarlas lleva tiempo.","angle":"Presente sus referencias como una monografía y filtre los proyectos por alcance antes de la primera reunión.","message":"Hola [Nombre], he visto su proyecto [nombre]. Muchos estudios me cuentan que dedican tiempo a solicitudes que no encajan. Studio ATS presenta sus referencias y cualifica cada proyecto (tipo, superficie, presupuesto, plazos) antes de la primera reunión. ¿Le apetece una demo breve?","searches":["arquitecto [ciudad]","estudio de arquitectura [ciudad]","arquitecto vivienda unifamiliar [región]"]},"pt":{"name":"Arquitetos","who":"Gabinetes de arquitetura que trabalham com particulares e pequenas empresas.","why":"Os projetos têm ciclos longos e alto valor — a primeira impressão e a qualificação contam.","problem":"A maioria dos pedidos chega cedo demais, é demasiado pequena ou fora do âmbito, e filtrá-los leva tempo.","angle":"Apresente as suas referências como uma monografia e filtre os projetos por âmbito antes da primeira reunião.","message":"Olá [Nome], descobri o seu projeto [nome]. Muitos gabinetes dizem-me que perdem tempo com pedidos que não encaixam. A Studio ATS apresenta as suas referências e qualifica cada projeto (tipo, área, orçamento, prazo) antes da primeira reunião. Aberto a uma demo curta?","searches":["arquiteto [cidade]","gabinete de arquitetura [cidade]","arquiteto moradias [região]"]},"it":{"name":"Architetti","who":"Studi di architettura che lavorano con privati e piccole imprese.","why":"I progetti hanno cicli lunghi e alto valore — la prima impressione e la qualificazione contano.","problem":"La maggior parte delle richieste arriva troppo presto, è troppo piccola o fuori ambito, e filtrarle richiede tempo.","angle":"Presenta le tue referenze come una monografia e filtra i progetti per ambito prima del primo incontro.","message":"Buongiorno [Nome], ho visto il vostro progetto [nome]. Molti studi mi dicono di perdere tempo con richieste non adatte. Studio ATS presenta le vostre referenze e qualifica ogni progetto (tipo, superficie, budget, tempi) prima del primo incontro. Le va una breve demo?","searches":["architetto [città]","studio di architettura [città]","architetto ville [regione]"]},"nl":{"name":"Architecten","who":"Architectenbureaus die werken voor particulieren en kleine bedrijven.","why":"Projecten hebben lange doorlooptijden en hoge waarde — de eerste indruk en kwalificatie tellen.","problem":"De meeste aanvragen komen te vroeg, zijn te klein of vallen buiten de scope, en filteren kost tijd.","angle":"Presenteer je referenties als een monografie en filter projecten op scope vóór de eerste afspraak.","message":"Hallo [Voornaam], ik zag jullie project [naam]. Veel bureaus vertellen me dat ze tijd kwijt zijn aan aanvragen die niet passen. Studio ATS presenteert je referenties en kwalificeert elk project (type, oppervlakte, budget, planning) vóór de eerste afspraak. Zin in een korte demo?","searches":["architect [stad]","architectenbureau [stad]","architect woning [regio]"]},"ar":{"name":"المهندسون المعماريون","who":"مكاتب هندسة معمارية تعمل مع الأفراد والشركات الصغيرة.","why":"للمشاريع دورات طويلة وقيمة عالية — الانطباع الأول والتأهيل مهمّان.","problem":"معظم الطلبات تأتي مبكرة جدًا أو صغيرة جدًا أو خارج النطاق، وتصفيتها تستغرق وقتًا.","angle":"اعرض مراجعك كدراسة متكاملة وصفِّ المشاريع حسب النطاق قبل الاجتماع الأول.","message":"مرحبًا [الاسم]، اطّلعت على مشروعك [الاسم]. يخبرني كثير من المكاتب أنهم يضيّعون وقتًا في طلبات غير مناسبة. يعرض Studio ATS مراجعك ويؤهّل كل مشروع (النوع والمساحة والميزانية والتوقيت) قبل الاجتماع الأول. هل تودّ عرضًا تجريبيًا قصيرًا؟","searches":["مهندس معماري [المدينة]","مكتب هندسة معمارية [المدينة]","تصميم فلل [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('interior-designers', 'sofa', 5, 3, '{"en":{"name":"Interior designers","who":"Interior designers and decorators working on premium residential or hospitality projects.","why":"Their work is visual and their clients buy on trust and taste.","problem":"Beautiful Instagram, but no structured way to capture and qualify project requests.","angle":"Turn your Instagram audience into structured project requests.","message":"Hi [First name], your [project] is stunning. Do your Instagram followers have an easy way to request a project with you? Studio ATS gives designers a premium portfolio that captures and qualifies requests — room, surface, budget, timing. Happy to show you in 10 minutes.","searches":["interior designer [city]","décoratrice d’intérieur [city]","#interiordesign [city]"]},"fr":{"name":"Architectes d’intérieur","who":"Architectes d’intérieur et décorateurs sur des projets résidentiels ou hôteliers haut de gamme.","why":"Leur travail est visuel et leurs clients achètent sur la confiance et le goût.","problem":"Un bel Instagram, mais aucun moyen structuré de capter et qualifier les demandes.","angle":"Transformez votre audience Instagram en demandes de projets structurées.","message":"Bonjour [Prénom], votre projet [nom] est magnifique. Vos abonnés Instagram ont-ils un moyen simple de vous demander un projet ? Studio ATS offre aux architectes d’intérieur un portfolio premium qui capte et qualifie les demandes — pièce, surface, budget, délai. Je vous montre en 10 minutes ?","searches":["architecte d’intérieur [ville]","décoratrice d’intérieur [ville]","#decorationinterieur [ville]"]},"de":{"name":"Innenarchitekten","who":"Innenarchitekten und Raumausstatter für hochwertige Wohn- oder Hotelprojekte.","why":"Ihre Arbeit ist visuell, und ihre Kunden kaufen nach Vertrauen und Geschmack.","problem":"Ein schönes Instagram, aber kein strukturierter Weg, Projektanfragen zu erfassen und zu qualifizieren.","angle":"Verwandeln Sie Ihr Instagram-Publikum in strukturierte Projektanfragen.","message":"Hallo [Vorname], Ihr Projekt [Projekt] ist beeindruckend. Haben Ihre Instagram-Follower einen einfachen Weg, ein Projekt bei Ihnen anzufragen? Studio ATS gibt Innenarchitekten ein Premium-Portfolio, das Anfragen erfasst und qualifiziert — Raum, Fläche, Budget, Zeitrahmen. Ich zeige es Ihnen gern in 10 Minuten.","searches":["Innenarchitekt [Stadt]","Raumausstatter [Stadt]","#interiordesign [Stadt]"]},"es":{"name":"Interioristas","who":"Interioristas y decoradores que trabajan en proyectos residenciales u hoteleros premium.","why":"Su trabajo es visual y sus clientes compran por confianza y gusto.","problem":"Un Instagram precioso, pero ninguna forma estructurada de captar y cualificar solicitudes de proyecto.","angle":"Convierta su audiencia de Instagram en solicitudes de proyecto estructuradas.","message":"Hola [Nombre], su proyecto [proyecto] es impresionante. ¿Tienen sus seguidores de Instagram una forma fácil de pedirle un proyecto? Studio ATS da a los interioristas un portfolio premium que capta y cualifica las solicitudes — estancia, superficie, presupuesto, plazos. Se lo enseño encantado en 10 minutos.","searches":["interiorista [ciudad]","decorador de interiores [ciudad]","#interiorismo [ciudad]"]},"pt":{"name":"Designers de interiores","who":"Designers de interiores e decoradores em projetos residenciais ou hoteleiros premium.","why":"O trabalho deles é visual e os clientes compram pela confiança e pelo gosto.","problem":"Um Instagram bonito, mas nenhuma forma estruturada de captar e qualificar pedidos de projeto.","angle":"Transforme a sua audiência do Instagram em pedidos de projeto estruturados.","message":"Olá [Nome], o seu projeto [projeto] é impressionante. Os seus seguidores do Instagram têm uma forma fácil de lhe pedir um projeto? A Studio ATS dá aos designers um portefólio premium que capta e qualifica pedidos — divisão, área, orçamento, prazo. Mostro-lhe com gosto em 10 minutos.","searches":["designer de interiores [cidade]","decoração de interiores [cidade]","#designdeinteriores [cidade]"]},"it":{"name":"Interior designer","who":"Interior designer e decoratori che lavorano su progetti residenziali o alberghieri di alto livello.","why":"Il loro lavoro è visivo e i clienti comprano per fiducia e gusto.","problem":"Un bell’Instagram, ma nessun modo strutturato per raccogliere e qualificare le richieste di progetto.","angle":"Trasforma il tuo pubblico di Instagram in richieste di progetto strutturate.","message":"Ciao [Nome], il tuo progetto [progetto] è splendido. I tuoi follower di Instagram hanno un modo semplice per chiederti un progetto? Studio ATS dà agli interior designer un portfolio premium che raccoglie e qualifica le richieste — ambiente, superficie, budget, tempi. Te lo mostro volentieri in 10 minuti.","searches":["interior designer [città]","arredatore d’interni [città]","#interiordesign [città]"]},"nl":{"name":"Interieurontwerpers","who":"Interieurontwerpers en -stylisten die werken aan premium woon- of horecaprojecten.","why":"Hun werk is visueel en hun klanten kopen op vertrouwen en smaak.","problem":"Een mooi Instagram-account, maar geen gestructureerde manier om projectaanvragen te verzamelen en te kwalificeren.","angle":"Zet je Instagram-publiek om in gestructureerde projectaanvragen.","message":"Hoi [Voornaam], je project [project] is prachtig. Hebben je Instagram-volgers een makkelijke manier om een project bij je aan te vragen? Studio ATS geeft interieurontwerpers een premium portfolio dat aanvragen verzamelt en kwalificeert — ruimte, oppervlakte, budget, planning. Ik laat het je graag in 10 minuten zien.","searches":["interieurontwerper [stad]","interieurstylist [stad]","#interieurontwerp [stad]"]},"ar":{"name":"مصمّمو الديكور الداخلي","who":"مصمّمو ديكور داخلي ومنسّقون يعملون على مشاريع سكنية أو فندقية فاخرة.","why":"عملهم بصري، وعملاؤهم يشترون بناءً على الثقة والذوق.","problem":"حساب Instagram جميل، لكن لا توجد طريقة منظَّمة لجمع طلبات المشاريع وتأهيلها.","angle":"حوّل جمهورك على Instagram إلى طلبات مشاريع منظَّمة.","message":"مرحبًا [الاسم]، مشروعك [المشروع] مذهل. هل لدى متابعيك على Instagram طريقة سهلة لطلب مشروع منك؟ يمنح Studio ATS المصمّمين معرض أعمال فاخرًا يجمع الطلبات ويؤهّلها — الغرفة والمساحة والميزانية والتوقيت. يسعدني أن أريك ذلك في 10 دقائق.","searches":["مصمّم ديكور داخلي [المدينة]","تصميم داخلي [المدينة]","#تصميم_داخلي [المدينة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('renovation', 'hammer', 6, 3, '{"en":{"name":"Premium renovation companies","who":"Renovation companies focused on high-end homes and complete refurbishments.","why":"Large tickets, many unqualified quote requests.","problem":"Teams travel for site visits that don’t lead anywhere.","angle":"Qualify every project before the site visit — surface, budget, timing and photos upfront.","message":"Hello [First name], I saw your renovation in [place]. How many site visits a month end up going nowhere? Studio ATS shows your best projects and asks the right questions (surface, budget, timing, photos) before you move. Interested in seeing it?","searches":["rénovation haut de gamme [city]","renovation company [city]","entreprise rénovation appartement [city]"]},"fr":{"name":"Rénovation haut de gamme","who":"Entreprises de rénovation spécialisées dans les biens haut de gamme et les rénovations complètes.","why":"Des paniers élevés, beaucoup de demandes de devis non qualifiées.","problem":"Les équipes se déplacent pour des visites qui n’aboutissent pas.","angle":"Qualifiez chaque projet avant la visite — surface, budget, délai et photos en amont.","message":"Bonjour [Prénom], j’ai vu votre rénovation à [lieu]. Combien de visites par mois ne mènent à rien ? Studio ATS présente vos plus beaux chantiers et pose les bonnes questions (surface, budget, délai, photos) avant que vous vous déplaciez. Ça vous intéresse ?","searches":["rénovation haut de gamme [ville]","entreprise rénovation appartement [ville]","rénovation maison ancienne [région]"]},"de":{"name":"Premium-Renovierungsbetriebe","who":"Renovierungsbetriebe, spezialisiert auf hochwertige Häuser und Komplettsanierungen.","why":"Hohe Auftragswerte, viele unqualifizierte Angebotsanfragen.","problem":"Teams fahren zu Besichtigungen, die zu nichts führen.","angle":"Qualifizieren Sie jedes Projekt vor der Besichtigung — Fläche, Budget, Zeitrahmen und Fotos vorab.","message":"Hallo [Vorname], ich habe Ihre Renovierung in [Ort] gesehen. Wie viele Besichtigungen pro Monat führen zu nichts? Studio ATS zeigt Ihre besten Projekte und stellt die richtigen Fragen (Fläche, Budget, Zeitrahmen, Fotos), bevor Sie losfahren. Interessiert?","searches":["Komplettsanierung [Stadt]","Renovierungsfirma [Stadt]","Wohnungssanierung [Stadt]"]},"es":{"name":"Empresas de reformas premium","who":"Empresas de reformas centradas en viviendas de alto standing y reformas integrales.","why":"Importes elevados, muchas solicitudes de presupuesto sin cualificar.","problem":"Los equipos se desplazan a visitas que no llevan a nada.","angle":"Cualifique cada proyecto antes de la visita — superficie, presupuesto, plazos y fotos por adelantado.","message":"Hola [Nombre], he visto su reforma en [lugar]. ¿Cuántas visitas al mes no llevan a nada? Studio ATS muestra sus mejores proyectos y hace las preguntas adecuadas (superficie, presupuesto, plazos, fotos) antes de que se desplace. ¿Le interesa verlo?","searches":["reformas integrales [ciudad]","empresa de reformas [ciudad]","reforma de pisos [ciudad]"]},"pt":{"name":"Empresas de remodelação premium","who":"Empresas de remodelação focadas em casas de alto padrão e remodelações completas.","why":"Valores elevados, muitos pedidos de orçamento não qualificados.","problem":"As equipas deslocam-se a visitas que não levam a nada.","angle":"Qualifique cada projeto antes da visita — área, orçamento, prazo e fotografias à partida.","message":"Olá [Nome], vi a sua remodelação em [local]. Quantas visitas por mês não levam a nada? A Studio ATS mostra os seus melhores projetos e faz as perguntas certas (área, orçamento, prazo, fotografias) antes de se deslocar. Tem interesse em ver?","searches":["remodelação de casas [cidade]","empresa de remodelações [cidade]","remodelação de apartamentos [cidade]"]},"it":{"name":"Imprese di ristrutturazione premium","who":"Imprese di ristrutturazione specializzate in case di pregio e ristrutturazioni complete.","why":"Importi elevati, molte richieste di preventivo non qualificate.","problem":"Le squadre si spostano per sopralluoghi che non portano a nulla.","angle":"Qualifica ogni progetto prima del sopralluogo — superficie, budget, tempi e foto in anticipo.","message":"Buongiorno [Nome], ho visto la vostra ristrutturazione a [luogo]. Quanti sopralluoghi al mese non portano a nulla? Studio ATS mostra i vostri progetti migliori e fa le domande giuste (superficie, budget, tempi, foto) prima che vi muoviate. Le interessa vederlo?","searches":["ristrutturazioni chiavi in mano [città]","impresa di ristrutturazione [città]","ristrutturazione appartamenti [città]"]},"nl":{"name":"Premium renovatiebedrijven","who":"Renovatiebedrijven gericht op exclusieve woningen en complete verbouwingen.","why":"Hoge orderwaardes, veel ongekwalificeerde offerteaanvragen.","problem":"Teams rijden naar bezichtigingen die nergens toe leiden.","angle":"Kwalificeer elk project vóór de bezichtiging — oppervlakte, budget, planning en foto’s vooraf.","message":"Hallo [Voornaam], ik zag jullie renovatie in [plaats]. Hoeveel bezichtigingen per maand leiden tot niets? Studio ATS laat je beste projecten zien en stelt de juiste vragen (oppervlakte, budget, planning, foto’s) voordat je op pad gaat. Interesse om het te zien?","searches":["totaalrenovatie [stad]","renovatiebedrijf [stad]","appartement verbouwen [stad]"]},"ar":{"name":"شركات الترميم الفاخر","who":"شركات ترميم متخصصة في المنازل الراقية والتجديد الكامل.","why":"قيم مرتفعة، والكثير من طلبات عروض الأسعار غير المؤهَّلة.","problem":"تتنقّل الفرق لزيارات لا تؤدي إلى شيء.","angle":"أهّل كل مشروع قبل الزيارة — المساحة والميزانية والتوقيت والصور مسبقًا.","message":"مرحبًا [الاسم]، رأيت أعمال الترميم التي نفّذتموها في [المكان]. كم زيارة شهريًا لا تؤدي إلى شيء؟ يعرض Studio ATS أفضل مشاريعكم ويطرح الأسئلة الصحيحة (المساحة والميزانية والتوقيت والصور) قبل أن تتنقّلوا. هل يهمّكم رؤيته؟","searches":["ترميم منازل فاخرة [المدينة]","شركة ترميم [المدينة]","تجديد شقق [المدينة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('kitchen-designers', 'kitchen', 7, 3, '{"en":{"name":"Kitchen designers","who":"Kitchen showrooms and independent kitchen designers.","why":"High-value projects that start online and close in the showroom.","problem":"Showroom appointments are booked by phone, with little information about the project.","angle":"Get the showroom appointment booked with the project already described.","message":"Hi [First name], beautiful kitchens on your site. How do prospects book a showroom visit today? Studio ATS lets them describe their project and request an appointment online, so each visit is prepared. 10 minutes to show you?","searches":["cuisiniste [city]","kitchen showroom [city]","custom kitchen designer [region]"]},"fr":{"name":"Cuisinistes","who":"Showrooms de cuisine et concepteurs de cuisines indépendants.","why":"Des projets à forte valeur qui commencent en ligne et se concluent en showroom.","problem":"Les rendez-vous showroom sont pris par téléphone, avec peu d’informations sur le projet.","angle":"Obtenez le rendez-vous showroom avec le projet déjà décrit.","message":"Bonjour [Prénom], très belles cuisines sur votre site. Comment vos prospects réservent-ils une visite showroom aujourd’hui ? Studio ATS leur permet de décrire leur projet et de demander un rendez-vous en ligne : chaque visite est préparée. 10 minutes pour vous montrer ?","searches":["cuisiniste [ville]","cuisine sur mesure [ville]","showroom cuisine [région]"]},"de":{"name":"Küchenplaner","who":"Küchenstudios und unabhängige Küchenplaner.","why":"Wertvolle Projekte, die online beginnen und im Studio abgeschlossen werden.","problem":"Studiotermine werden telefonisch gebucht, mit wenig Informationen zum Projekt.","angle":"Lassen Sie den Studiotermin mit bereits beschriebenem Projekt buchen.","message":"Hallo [Vorname], wunderschöne Küchen auf Ihrer Website. Wie buchen Interessenten heute einen Termin im Studio? Mit Studio ATS beschreiben sie ihr Projekt und fragen online einen Termin an, sodass jeder Besuch vorbereitet ist. 10 Minuten, um es Ihnen zu zeigen?","searches":["Küchenstudio [Stadt]","Küchenplaner [Stadt]","Maßküchen [Region]"]},"es":{"name":"Diseñadores de cocinas","who":"Exposiciones de cocinas y diseñadores de cocinas independientes.","why":"Proyectos de alto valor que empiezan en internet y se cierran en la exposición.","problem":"Las citas en la exposición se reservan por teléfono, con poca información sobre el proyecto.","angle":"Consiga que la cita en la exposición se reserve con el proyecto ya descrito.","message":"Hola [Nombre], cocinas preciosas en su web. ¿Cómo reservan hoy los prospectos una visita a la exposición? Studio ATS les permite describir su proyecto y pedir cita en línea, para que cada visita esté preparada. ¿10 minutos para enseñárselo?","searches":["cocinas a medida [ciudad]","exposición de cocinas [ciudad]","diseñador de cocinas [región]"]},"pt":{"name":"Designers de cozinhas","who":"Showrooms de cozinhas e designers de cozinhas independentes.","why":"Projetos de alto valor que começam online e fecham no showroom.","problem":"As visitas ao showroom são marcadas por telefone, com pouca informação sobre o projeto.","angle":"Faça com que a visita ao showroom seja marcada com o projeto já descrito.","message":"Olá [Nome], cozinhas lindíssimas no seu site. Como marcam hoje os contactos uma visita ao showroom? A Studio ATS permite-lhes descrever o projeto e pedir uma marcação online, para que cada visita esteja preparada. 10 minutos para lhe mostrar?","searches":["cozinhas por medida [cidade]","showroom de cozinhas [cidade]","designer de cozinhas [região]"]},"it":{"name":"Progettisti di cucine","who":"Showroom di cucine e progettisti di cucine indipendenti.","why":"Progetti di alto valore che iniziano online e si chiudono in showroom.","problem":"Gli appuntamenti in showroom si prendono al telefono, con poche informazioni sul progetto.","angle":"Fai prenotare l’appuntamento in showroom con il progetto già descritto.","message":"Buongiorno [Nome], cucine bellissime sul vostro sito. Come prenotano oggi i contatti una visita in showroom? Studio ATS permette loro di descrivere il progetto e chiedere un appuntamento online, così ogni visita è preparata. 10 minuti per mostrarvelo?","searches":["cucine su misura [città]","showroom cucine [città]","progettista cucine [regione]"]},"nl":{"name":"Keukenontwerpers","who":"Keukenshowrooms en zelfstandige keukenontwerpers.","why":"Waardevolle projecten die online beginnen en in de showroom worden afgerond.","problem":"Showroomafspraken worden telefonisch gemaakt, met weinig informatie over het project.","angle":"Laat de showroomafspraak boeken met het project al beschreven.","message":"Hoi [Voornaam], prachtige keukens op je website. Hoe boeken prospects nu een showroombezoek? Met Studio ATS beschrijven ze hun project en vragen ze online een afspraak aan, zodat elk bezoek voorbereid is. 10 minuten om het te laten zien?","searches":["keukenshowroom [stad]","keukenontwerper [stad]","maatwerkkeukens [regio]"]},"ar":{"name":"مصمّمو المطابخ","who":"صالات عرض المطابخ ومصمّمو المطابخ المستقلون.","why":"مشاريع عالية القيمة تبدأ على الإنترنت وتُغلق في صالة العرض.","problem":"تُحجز مواعيد صالة العرض بالهاتف، مع القليل من المعلومات عن المشروع.","angle":"اجعل موعد صالة العرض يُحجز والمشروع موصوف مسبقًا.","message":"مرحبًا [الاسم]، مطابخ رائعة على موقعك. كيف يحجز العملاء المحتملون اليوم زيارة لصالة العرض؟ يتيح لهم Studio ATS وصف مشروعهم وطلب موعد عبر الإنترنت، لتكون كل زيارة مُعدّة مسبقًا. هل لديك 10 دقائق لأريك؟","searches":["مطابخ حسب الطلب [المدينة]","صالة عرض مطابخ [المدينة]","مصمّم مطابخ [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('landscapers', 'leaf', 8, 3, '{"en":{"name":"Landscapers","who":"Landscape designers and garden-creation companies.","why":"Seasonal demand — capturing and qualifying requests early matters.","problem":"Requests peak in spring and many are too small or outside the service area.","angle":"Filter by area, surface and budget automatically, and fill your season with the right projects.","message":"Hello [First name], lovely garden in [place]. When spring requests arrive, how do you sort the good projects? Studio ATS qualifies each request (area, surface, budget) and books the visit. Want to see it?","searches":["paysagiste [city]","landscape designer [city]","création jardin [region]"]},"fr":{"name":"Paysagistes","who":"Paysagistes concepteurs et entreprises de création de jardins.","why":"Demande saisonnière — capter et qualifier tôt les demandes est clé.","problem":"Les demandes explosent au printemps et beaucoup sont trop petites ou hors zone.","angle":"Filtrez automatiquement par zone, surface et budget et remplissez votre saison avec les bons projets.","message":"Bonjour [Prénom], très beau jardin à [lieu]. Quand les demandes du printemps arrivent, comment triez-vous les bons projets ? Studio ATS qualifie chaque demande (zone, surface, budget) et programme la visite. Envie de voir ?","searches":["paysagiste [ville]","création jardin [ville]","architecte paysagiste [région]"]},"de":{"name":"Garten- und Landschaftsbauer","who":"Landschaftsarchitekten und Gartenbaubetriebe.","why":"Saisonale Nachfrage — Anfragen früh zu erfassen und zu qualifizieren zählt.","problem":"Anfragen häufen sich im Frühjahr, und viele sind zu klein oder liegen außerhalb des Einsatzgebiets.","angle":"Filtern Sie automatisch nach Gebiet, Fläche und Budget und füllen Sie Ihre Saison mit den richtigen Projekten.","message":"Hallo [Vorname], schöner Garten in [Ort]. Wenn die Frühjahrsanfragen kommen — wie sortieren Sie die guten Projekte? Studio ATS qualifiziert jede Anfrage (Gebiet, Fläche, Budget) und bucht die Besichtigung. Möchten Sie es sehen?","searches":["Garten- und Landschaftsbau [Stadt]","Landschaftsarchitekt [Stadt]","Gartengestaltung [Region]"]},"es":{"name":"Paisajistas","who":"Paisajistas y empresas de creación de jardines.","why":"Demanda estacional — captar y cualificar las solicitudes pronto es clave.","problem":"Las solicitudes se disparan en primavera y muchas son demasiado pequeñas o quedan fuera de la zona de servicio.","angle":"Filtre automáticamente por zona, superficie y presupuesto y llene su temporada con los proyectos adecuados.","message":"Hola [Nombre], precioso jardín en [lugar]. Cuando llegan las solicitudes de primavera, ¿cómo separa los buenos proyectos? Studio ATS cualifica cada solicitud (zona, superficie, presupuesto) y reserva la visita. ¿Quiere verlo?","searches":["paisajista [ciudad]","diseño de jardines [ciudad]","jardinería y paisajismo [región]"]},"pt":{"name":"Paisagistas","who":"Arquitetos paisagistas e empresas de criação de jardins.","why":"Procura sazonal — captar e qualificar os pedidos cedo é essencial.","problem":"Os pedidos disparam na primavera e muitos são demasiado pequenos ou fora da zona de serviço.","angle":"Filtre automaticamente por zona, área e orçamento e preencha a sua época com os projetos certos.","message":"Olá [Nome], jardim lindíssimo em [local]. Quando chegam os pedidos da primavera, como separa os bons projetos? A Studio ATS qualifica cada pedido (zona, área, orçamento) e marca a visita. Quer ver?","searches":["paisagista [cidade]","arquitetura paisagista [cidade]","criação de jardins [região]"]},"it":{"name":"Paesaggisti","who":"Paesaggisti e imprese di realizzazione giardini.","why":"Domanda stagionale — raccogliere e qualificare le richieste per tempo è fondamentale.","problem":"Le richieste esplodono in primavera e molte sono troppo piccole o fuori zona.","angle":"Filtra automaticamente per zona, superficie e budget e riempi la tua stagione con i progetti giusti.","message":"Buongiorno [Nome], bellissimo giardino a [luogo]. Quando arrivano le richieste di primavera, come selezionate i progetti buoni? Studio ATS qualifica ogni richiesta (zona, superficie, budget) e fissa il sopralluogo. Volete vederlo?","searches":["paesaggista [città]","progettazione giardini [città]","realizzazione giardini [regione]"]},"nl":{"name":"Hoveniers","who":"Tuinarchitecten en hoveniersbedrijven.","why":"Seizoensgebonden vraag — aanvragen vroeg verzamelen en kwalificeren is belangrijk.","problem":"Aanvragen pieken in het voorjaar en veel zijn te klein of buiten het werkgebied.","angle":"Filter automatisch op gebied, oppervlakte en budget en vul je seizoen met de juiste projecten.","message":"Hallo [Voornaam], mooie tuin in [plaats]. Als de voorjaarsaanvragen binnenkomen, hoe selecteer je dan de goede projecten? Studio ATS kwalificeert elke aanvraag (gebied, oppervlakte, budget) en plant het bezoek in. Wil je het zien?","searches":["hovenier [stad]","tuinarchitect [stad]","tuinaanleg [regio]"]},"ar":{"name":"منسّقو الحدائق","who":"مهندسو تنسيق المواقع وشركات إنشاء الحدائق.","why":"طلب موسمي — جمع الطلبات وتأهيلها مبكرًا أمر مهم.","problem":"تبلغ الطلبات ذروتها في الربيع، وكثير منها صغير جدًا أو خارج منطقة الخدمة.","angle":"صفِّ تلقائيًا حسب المنطقة والمساحة والميزانية، واملأ موسمك بالمشاريع المناسبة.","message":"مرحبًا [الاسم]، حديقة جميلة في [المكان]. عندما تصل طلبات الربيع، كيف تفرز المشاريع الجيدة؟ يؤهّل Studio ATS كل طلب (المنطقة والمساحة والميزانية) ويحجز الزيارة. هل تودّ رؤيته؟","searches":["تنسيق حدائق [المدينة]","مهندس تنسيق مواقع [المدينة]","إنشاء حدائق [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('pool-installers', 'waves', 9, 3, '{"en":{"name":"Pool installers","who":"Pool builders and installers for private homes.","why":"High-ticket projects with a long decision process.","problem":"Many quote requests, few serious projects, and no automatic follow-up.","angle":"Automatic follow-ups keep your quote top of mind during a long decision.","message":"Hi [First name], I saw your pool projects in [region]. How do you follow up quotes while clients decide? Studio ATS qualifies requests and sends automatic follow-ups so good projects don’t go cold. Shall I show you?","searches":["pisciniste [city]","pool builder [region]","construction piscine [region]"]},"fr":{"name":"Piscinistes","who":"Constructeurs et installateurs de piscines pour particuliers.","why":"Des projets à fort panier avec une décision longue.","problem":"Beaucoup de demandes de devis, peu de projets sérieux, et aucune relance automatique.","angle":"Les relances automatiques gardent votre devis en tête pendant une longue décision.","message":"Bonjour [Prénom], j’ai vu vos réalisations en [région]. Comment relancez-vous vos devis pendant que le client réfléchit ? Studio ATS qualifie les demandes et envoie des relances automatiques pour que les bons projets ne refroidissent pas. Je vous montre ?","searches":["pisciniste [ville]","construction piscine [région]","piscine coque [région]"]},"de":{"name":"Poolbauer","who":"Pool- und Schwimmbadbauer für Privathäuser.","why":"Hochpreisige Projekte mit einem langen Entscheidungsprozess.","problem":"Viele Angebotsanfragen, wenige ernsthafte Projekte und kein automatisches Nachfassen.","angle":"Automatisches Nachfassen hält Ihr Angebot während einer langen Entscheidung präsent.","message":"Hallo [Vorname], ich habe Ihre Poolprojekte in [Region] gesehen. Wie fassen Sie bei Angeboten nach, während Kunden entscheiden? Studio ATS qualifiziert Anfragen und sendet automatische Nachfassnachrichten, damit gute Projekte nicht einschlafen. Soll ich es Ihnen zeigen?","searches":["Poolbau [Stadt]","Schwimmbadbau [Region]","Pool bauen lassen [Region]"]},"es":{"name":"Constructores de piscinas","who":"Constructores e instaladores de piscinas para viviendas particulares.","why":"Proyectos de alto importe con un proceso de decisión largo.","problem":"Muchas solicitudes de presupuesto, pocos proyectos serios y ningún seguimiento automático.","angle":"Los seguimientos automáticos mantienen su presupuesto presente durante una decisión larga.","message":"Hola [Nombre], he visto sus piscinas en [región]. ¿Cómo hace el seguimiento de los presupuestos mientras los clientes deciden? Studio ATS cualifica las solicitudes y envía seguimientos automáticos para que los buenos proyectos no se enfríen. ¿Se lo enseño?","searches":["construcción de piscinas [ciudad]","piscinas a medida [región]","empresa de piscinas [región]"]},"pt":{"name":"Construtores de piscinas","who":"Construtores e instaladores de piscinas para moradias.","why":"Projetos de valor elevado com um processo de decisão longo.","problem":"Muitos pedidos de orçamento, poucos projetos sérios e nenhum seguimento automático.","angle":"Os seguimentos automáticos mantêm o seu orçamento presente durante uma decisão longa.","message":"Olá [Nome], vi as suas piscinas em [região]. Como faz o seguimento dos orçamentos enquanto os clientes decidem? A Studio ATS qualifica os pedidos e envia seguimentos automáticos para que os bons projetos não arrefeçam. Mostro-lhe?","searches":["construção de piscinas [cidade]","piscinas por medida [região]","empresa de piscinas [região]"]},"it":{"name":"Costruttori di piscine","who":"Costruttori e installatori di piscine per abitazioni private.","why":"Progetti di importo elevato con un processo decisionale lungo.","problem":"Molte richieste di preventivo, pochi progetti seri e nessun follow-up automatico.","angle":"I follow-up automatici tengono vivo il tuo preventivo durante una decisione lunga.","message":"Buongiorno [Nome], ho visto le vostre piscine in [regione]. Come seguite i preventivi mentre i clienti decidono? Studio ATS qualifica le richieste e invia follow-up automatici perché i progetti buoni non si raffreddino. Ve lo mostro?","searches":["costruzione piscine [città]","piscine interrate [regione]","impresa piscine [regione]"]},"nl":{"name":"Zwembadbouwers","who":"Bouwers en installateurs van zwembaden voor particuliere woningen.","why":"Projecten met een hoge orderwaarde en een lang beslisproces.","problem":"Veel offerteaanvragen, weinig serieuze projecten en geen automatische opvolging.","angle":"Automatische opvolging houdt je offerte in beeld tijdens een lange beslissing.","message":"Hallo [Voornaam], ik zag jullie zwembadprojecten in [regio]. Hoe volgen jullie offertes op terwijl klanten beslissen? Studio ATS kwalificeert aanvragen en stuurt automatische opvolging, zodat goede projecten niet afkoelen. Zal ik het laten zien?","searches":["zwembadbouwer [stad]","zwembad laten bouwen [regio]","zwembadbedrijf [regio]"]},"ar":{"name":"منشئو المسابح","who":"بنّاؤو ومركّبو المسابح للمنازل الخاصة.","why":"مشاريع عالية القيمة بعملية اتخاذ قرار طويلة.","problem":"الكثير من طلبات عروض الأسعار، وقليل من المشاريع الجادة، ولا متابعة تلقائية.","angle":"تُبقي المتابعات التلقائية عرض سعرك حاضرًا خلال قرار طويل.","message":"مرحبًا [الاسم]، رأيت مشاريع المسابح التي نفّذتموها في [المنطقة]. كيف تتابعون عروض الأسعار بينما يقرّر العملاء؟ يؤهّل Studio ATS الطلبات ويرسل متابعات تلقائية حتى لا تفتر المشاريع الجيدة. هل أريكم ذلك؟","searches":["إنشاء مسابح [المدينة]","مسابح حسب الطلب [المنطقة]","شركة مسابح [المنطقة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('b2b-consultants', 'briefcase', 10, 3, '{"en":{"name":"B2B consultants","who":"Independent consultants and boutique firms selling high-value engagements.","why":"Each engagement is significant; credibility and qualification drive the sale.","problem":"Lead generation relies on LinkedIn and referrals, with no structured intake.","angle":"Convert your LinkedIn visibility into qualified discovery calls.","message":"Hello [First name], I follow your posts on [topic]. When someone is interested, where do you send them? Studio ATS gives consultants a credible space that presents case studies, qualifies needs and books discovery calls. Worth 10 minutes?","searches":["consultant [specialty] [city]","cabinet de conseil [specialty]","LinkedIn: consultant indépendant [specialty]"]},"fr":{"name":"Consultants B2B","who":"Consultants indépendants et petits cabinets vendant des missions à forte valeur.","why":"Chaque mission compte ; crédibilité et qualification font la vente.","problem":"La prospection repose sur LinkedIn et le bouche-à-oreille, sans prise de contact structurée.","angle":"Transformez votre visibilité LinkedIn en appels découverte qualifiés.","message":"Bonjour [Prénom], je suis vos publications sur [sujet]. Quand quelqu’un est intéressé, où l’envoyez-vous ? Studio ATS donne aux consultants un espace crédible qui présente les cas clients, qualifie le besoin et programme l’appel découverte. Ça vaut 10 minutes ?","searches":["consultant [spécialité] [ville]","cabinet de conseil [spécialité]","LinkedIn : consultant indépendant [spécialité]"]},"de":{"name":"B2B-Berater","who":"Selbstständige Berater und Boutique-Beratungen mit hochwertigen Mandaten.","why":"Jedes Mandat ist bedeutend; Glaubwürdigkeit und Qualifizierung entscheiden über den Verkauf.","problem":"Die Leadgenerierung hängt an LinkedIn und Empfehlungen, ohne strukturierte Aufnahme.","angle":"Verwandeln Sie Ihre LinkedIn-Sichtbarkeit 