ultor independente [especialidade]"]},"it":{"name":"Consulenti B2B","who":"Consulenti indipendenti e società boutique che vendono incarichi di alto valore.","why":"Ogni incarico è importante; credibilità e qualificazione guidano la vendita.","problem":"L’acquisizione dipende da LinkedIn e dal passaparola, senza un processo di ingresso strutturato.","angle":"Trasforma la tua visibilità su LinkedIn in chiamate conoscitive qualificate.","message":"Buongiorno [Nome], seguo i suoi post su [tema]. Quando qualcuno è interessato, dove lo indirizza? Studio ATS dà ai consulenti uno spazio credibile che presenta casi di studio, qualifica le esigenze e fissa le chiamate conoscitive. Vale 10 minuti?","searches":["consulente [specializzazione] [città]","società di consulenza [specializzazione]","LinkedIn: consulente indipendente [specializzazione]"]},"nl":{"name":"B2B-consultants","who":"Zelfstandige consultants en boutique-adviesbureaus met waardevolle opdrachten.","why":"Elke opdracht is aanzienlijk; geloofwaardigheid en kwalificatie bepalen de verkoop.","problem":"Leadgeneratie leunt op LinkedIn en aanbevelingen, zonder gestructureerde intake.","angle":"Zet je LinkedIn-zichtbaarheid om in gekwalificeerde kennismakingsgesprekken.","message":"Hallo [Voornaam], ik volg je posts over [onderwerp]. Als iemand geïnteresseerd is, waar stuur je diegene dan naartoe? Studio ATS geeft consultants een geloofwaardige omgeving die cases presenteert, behoeften kwalificeert en kennismakingsgesprekken inplant. 10 minuten waard?","searches":["consultant [specialisme] [stad]","adviesbureau [specialisme]","LinkedIn: zelfstandig consultant [specialisme]"]},"ar":{"name":"مستشارو الأعمال B2B","who":"مستشارون مستقلون وشركات استشارية متخصصة تبيع مهام عالية القيمة.","why":"كل مهمة كبيرة؛ والمصداقية والتأهيل هما ما يصنع البيع.","problem":"يعتمد جلب العملاء على LinkedIn والتوصيات، دون عملية استقبال منظَّمة.","angle":"حوّل ظهورك على LinkedIn إلى مكالمات استكشافية مؤهَّلة.","message":"مرحبًا [الاسم]، أتابع منشوراتك عن [الموضوع]. عندما يهتم أحد، إلى أين توجّهه؟ يمنح Studio ATS المستشارين مساحة موثوقة تعرض دراسات الحالة، وتؤهّل الاحتياجات، وتحجز المكالمات الاستكشافية. هل يستحق ذلك 10 دقائق؟","searches":["مستشار [التخصص] [المدينة]","شركة استشارات [التخصص]","LinkedIn: مستشار مستقل [التخصص]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('recruitment', 'users', 11, 3, '{"en":{"name":"Recruitment firms","who":"Boutique recruitment and executive-search firms.","why":"Winning a new client account has high value; trust is built before the first call.","problem":"Client and candidate requests mix together; client acquisition is manual.","angle":"Separate client and candidate journeys and qualify hiring needs automatically.","message":"Hi [First name], I noticed your firm specialises in [sector]. How do new client companies contact you today? Studio ATS separates client and candidate requests and qualifies hiring needs before the call. Open to a quick look?","searches":["cabinet de recrutement [sector] [city]","executive search [city]","recruitment agency [niche]"]},"fr":{"name":"Cabinets de recrutement","who":"Cabinets de recrutement spécialisés et chasseurs de têtes.","why":"Gagner un nouveau client a une forte valeur ; la confiance se construit avant l’appel.","problem":"Les demandes clients et candidats se mélangent ; l’acquisition client est manuelle.","angle":"Séparez les parcours clients et candidats et qualifiez les besoins de recrutement automatiquement.","message":"Bonjour [Prénom], votre cabinet est spécialisé en [secteur]. Comment les entreprises clientes vous contactent-elles aujourd’hui ? Studio ATS sépare les demandes clients et candidats et qualifie le besoin avant l’appel. Ouvert à un rapide aperçu ?","searches":["cabinet de recrutement [secteur] [ville]","chasseur de têtes [ville]","recrutement [niche]"]},"de":{"name":"Personalberatungen","who":"Boutique-Personalberatungen und Executive-Search-Firmen.","why":"Ein neuer Kunde ist viel wert; Vertrauen entsteht vor dem ersten Gespräch.","problem":"Kunden- und Kandidatenanfragen vermischen sich; die Kundengewinnung läuft manuell.","angle":"Trennen Sie die Wege für Kunden und Kandidaten und qualifizieren Sie den Personalbedarf automatisch.","message":"Hallo [Vorname], ich habe gesehen, dass Ihre Beratung auf [Branche] spezialisiert ist. Wie kontaktieren neue Kundenunternehmen Sie heute? Studio ATS trennt Kunden- und Kandidatenanfragen und qualifiziert den Personalbedarf vor dem Gespräch. Offen für einen kurzen Blick?","searches":["Personalberatung [Branche] [Stadt]","Executive Search [Stadt]","Personalvermittlung [Nische]"]},"es":{"name":"Firmas de selección","who":"Consultoras de selección boutique y firmas de executive search.","why":"Ganar una nueva empresa cliente tiene mucho valor; la confianza se construye antes de la primera llamada.","problem":"Las solicitudes de clientes y candidatos se mezclan; la captación de clientes es manual.","angle":"Separe los recorridos de clientes y candidatos y cualifique automáticamente las necesidades de contratación.","message":"Hola [Nombre], he visto que su firma está especializada en [sector]. ¿Cómo le contactan hoy las nuevas empresas cliente? Studio ATS separa las solicitudes de clientes y candidatos y cualifica las necesidades de contratación antes de la llamada. ¿Le echa un vistazo?","searches":["consultora de selección [sector] [ciudad]","executive search [ciudad]","agencia de reclutamiento [nicho]"]},"pt":{"name":"Empresas de recrutamento","who":"Consultoras de recrutamento boutique e empresas de executive search.","why":"Conquistar uma nova empresa cliente tem muito valor; a confiança constrói-se antes da primeira chamada.","problem":"Os pedidos de clientes e de candidatos misturam-se; a angariação de clientes é manual.","angle":"Separe os percursos de clientes e candidatos e qualifique automaticamente as necessidades de contratação.","message":"Olá [Nome], reparei que a sua empresa é especializada em [setor]. Como é que as novas empresas clientes o contactam hoje? A Studio ATS separa os pedidos de clientes e de candidatos e qualifica as necessidades de contratação antes da chamada. Aberto a uma vista de olhos?","searches":["empresa de recrutamento [setor] [cidade]","executive search [cidade]","agência de recrutamento [nicho]"]},"it":{"name":"Società di selezione","who":"Società di selezione boutique ed executive search.","why":"Acquisire una nuova azienda cliente ha molto valore; la fiducia si costruisce prima della prima chiamata.","problem":"Le richieste di clienti e candidati si mescolano; l’acquisizione dei clienti è manuale.","angle":"Separa i percorsi di clienti e candidati e qualifica in automatico le esigenze di assunzione.","message":"Buongiorno [Nome], ho notato che la vostra società è specializzata in [settore]. Come vi contattano oggi le nuove aziende clienti? Studio ATS separa le richieste di clienti e candidati e qualifica le esigenze di assunzione prima della chiamata. Le va di dare un’occhiata?","searches":["società di selezione [settore] [città]","executive search [città]","agenzia per il lavoro [nicchia]"]},"nl":{"name":"Recruitmentbureaus","who":"Boutique-recruitmentbureaus en executive-searchbureaus.","why":"Een nieuwe opdrachtgever binnenhalen is veel waard; vertrouwen ontstaat vóór het eerste gesprek.","problem":"Aanvragen van opdrachtgevers en kandidaten lopen door elkaar; acquisitie van opdrachtgevers gaat handmatig.","angle":"Scheid de trajecten voor opdrachtgevers en kandidaten en kwalificeer de personeelsbehoefte automatisch.","message":"Hoi [Voornaam], ik zag dat jullie bureau gespecialiseerd is in [sector]. Hoe nemen nieuwe opdrachtgevers nu contact op? Studio ATS scheidt aanvragen van opdrachtgevers en kandidaten en kwalificeert de personeelsbehoefte vóór het gesprek. Zin in een korte blik?","searches":["recruitmentbureau [sector] [stad]","executive search [stad]","wervingsbureau [niche]"]},"ar":{"name":"شركات التوظيف","who":"شركات توظيف متخصصة وشركات البحث عن كبار التنفيذيين.","why":"كسب شركة عميلة جديدة ذو قيمة عالية؛ والثقة تُبنى قبل المكالمة الأولى.","problem":"تختلط طلبات العملاء والمرشّحين؛ وجلب العملاء يتم يدويًا.","angle":"افصل مساري العملاء والمرشّحين وأهّل احتياجات التوظيف تلقائيًا.","message":"مرحبًا [الاسم]، لاحظت أن شركتك متخصصة في [القطاع]. كيف تتواصل معك الشركات العميلة الجديدة اليوم؟ يفصل Studio ATS طلبات العملاء عن طلبات المرشّحين ويؤهّل احتياجات التوظيف قبل المكالمة. هل تودّ نظرة سريعة؟","searches":["شركة توظيف [القطاع] [المدينة]","البحث عن التنفيذيين [المدينة]","وكالة توظيف [المجال]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('event-professionals', 'sparkles', 12, 3, '{"en":{"name":"Premium event professionals","who":"Caterers, venues, event agencies, florists and decorators working on premium events.","why":"Each event is a high-value booking with a date that can only be sold once.","problem":"Availability, guest count and budget are exchanged over many messages.","angle":"Capture date, guest count and budget in the first request — answer only the right events.","message":"Hello [First name], your [event] setup was superb. How do clients check availability with you today? Studio ATS captures date, guests and budget in the first request and books the call. Want to see it?","searches":["traiteur événementiel [city]","lieu de réception [city]","event agency [city]"]},"fr":{"name":"Événementiel premium","who":"Traiteurs, lieux de réception, agences événementielles, fleuristes et décorateurs haut de gamme.","why":"Chaque événement est une réservation à forte valeur sur une date qu’on ne vend qu’une fois.","problem":"Disponibilité, nombre d’invités et budget s’échangent en de nombreux messages.","angle":"Captez date, invités et budget dès la première demande — ne répondez qu’aux bons événements.","message":"Bonjour [Prénom], votre mise en place pour [événement] était superbe. Comment vos clients vérifient-ils vos disponibilités aujourd’hui ? Studio ATS capte date, invités et budget dès la première demande et programme l’appel. Envie de voir ?","searches":["traiteur événementiel [ville]","lieu de réception [ville]","agence événementielle [ville]"]},"de":{"name":"Premium-Eventdienstleister","who":"Caterer, Locations, Eventagenturen, Floristen und Dekorateure für Premium-Veranstaltungen.","why":"Jedes Event ist eine wertvolle Buchung, mit einem Datum, das nur einmal verkauft werden kann.","problem":"Verfügbarkeit, Gästezahl und Budget werden über viele Nachrichten ausgetauscht.","angle":"Erfassen Sie Datum, Gästezahl und Budget in der ersten Anfrage — antworten Sie nur auf die richtigen Events.","message":"Hallo [Vorname], Ihr Aufbau für [Event] war großartig. Wie prüfen Kunden heute Ihre Verfügbarkeit? Studio ATS erfasst Datum, Gäste und Budget in der ersten Anfrage und bucht das Gespräch. Möchten Sie es sehen?","searches":["Event-Catering [Stadt]","Eventlocation [Stadt]","Eventagentur [Stadt]"]},"es":{"name":"Profesionales de eventos premium","who":"Catering, espacios, agencias de eventos, floristas y decoradores que trabajan en eventos premium.","why":"Cada evento es una reserva de alto valor con una fecha que solo se puede vender una vez.","problem":"Disponibilidad, número de invitados y presupuesto se intercambian en muchos mensajes.","angle":"Capte fecha, número de invitados y presupuesto en la primera solicitud — responda solo a los eventos adecuados.","message":"Hola [Nombre], su montaje para [evento] fue magnífico. ¿Cómo consultan hoy los clientes su disponibilidad? Studio ATS capta fecha, invitados y presupuesto en la primera solicitud y reserva la llamada. ¿Quiere verlo?","searches":["catering para eventos [ciudad]","espacio para eventos [ciudad]","agencia de eventos [ciudad]"]},"pt":{"name":"Profissionais de eventos premium","who":"Catering, espaços, agências de eventos, floristas e decoradores em eventos premium.","why":"Cada evento é uma reserva de alto valor com uma data que só se vende uma vez.","problem":"Disponibilidade, número de convidados e orçamento são trocados em muitas mensagens.","angle":"Capte data, número de convidados e orçamento logo no primeiro pedido — responda só aos eventos certos.","message":"Olá [Nome], a sua montagem para [evento] estava fantástica. Como verificam hoje os clientes a sua disponibilidade? A Studio ATS capta data, convidados e orçamento logo no primeiro pedido e marca a chamada. Quer ver?","searches":["catering para eventos [cidade]","espaço para eventos [cidade]","agência de eventos [cidade]"]},"it":{"name":"Professionisti di eventi premium","who":"Catering, location, agenzie di eventi, fioristi e allestitori che lavorano su eventi di alto livello.","why":"Ogni evento è una prenotazione di alto valore con una data che si può vendere una sola volta.","problem":"Disponibilità, numero di ospiti e budget si scambiano in tanti messaggi.","angle":"Raccogli data, numero di ospiti e budget nella prima richiesta — rispondi solo agli eventi giusti.","message":"Buongiorno [Nome], il vostro allestimento per [evento] era splendido. Come verificano oggi i clienti la vostra disponibilità? Studio ATS raccoglie data, ospiti e budget nella prima richiesta e fissa la chiamata. Volete vederlo?","searches":["catering per eventi [città]","location per eventi [città]","agenzia eventi [città]"]},"nl":{"name":"Premium evenementenprofessionals","who":"Cateraars, locaties, evenementenbureaus, bloemisten en decorateurs voor premium evenementen.","why":"Elk evenement is een waardevolle boeking met een datum die maar één keer verkocht kan worden.","problem":"Beschikbaarheid, aantal gasten en budget worden via veel berichten uitgewisseld.","angle":"Leg datum, aantal gasten en budget vast in de eerste aanvraag — reageer alleen op de juiste evenementen.","message":"Hallo [Voornaam], jullie opstelling voor [evenement] was prachtig. Hoe checken klanten nu jullie beschikbaarheid? Studio ATS legt datum, gasten en budget vast in de eerste aanvraag en plant het gesprek in. Wil je het zien?","searches":["eventcatering [stad]","evenementenlocatie [stad]","evenementenbureau [stad]"]},"ar":{"name":"محترفو الفعاليات الفاخرة","who":"متعهّدو الضيافة وقاعات المناسبات ووكالات الفعاليات ومنسّقو الزهور والديكور للفعاليات الفاخرة.","why":"كل فعالية حجز عالي القيمة بتاريخ لا يُباع إلا مرة واحدة.","problem":"تُتبادل معلومات التوفّر وعدد الضيوف والميزانية عبر رسائل كثيرة.","angle":"اجمع التاريخ وعدد الضيوف والميزانية منذ الطلب الأول — ولا ترد إلا على الفعاليات المناسبة.","message":"مرحبًا [الاسم]، كان تجهيزك لـ [الفعالية] رائعًا. كيف يتحقق العملاء اليوم من توفّرك؟ يجمع Studio ATS التاريخ والضيوف والميزانية منذ الطلب الأول ويحجز المكالمة. هل تودّ رؤيته؟","searches":["ضيافة فعاليات [المدينة]","قاعة مناسبات [المدينة]","وكالة فعاليات [المدينة]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'en', 'First contact — portfolio businesses', 'Subject: [Company] — turning visitors into booked calls
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'en', 'Follow-up after 3 days', 'Subject: Re: [Company] — turning visitors into booked calls
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'en', 'Short intro', 'Hi [First name] 👋 I saw your work on [project] — really nice. I work with Studio ATS: it turns your portfolio into a space that qualifies requests and books calls automatically. Can I send you a 2-minute overview?', 2 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'en', 'After a call', 'Thanks for the call, [First name]! Here’s the Studio ATS page we discussed: [your link]. Let me know if you have any questions.', 3 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'en', 'Connection note', 'Hi [First name], I help [profession] turn their online visibility into qualified appointments. Would love to connect.', 4 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'en', 'Message after connecting', 'Thanks for connecting, [First name]. I noticed [Company] works on [type of project]. How do new clients usually reach you? I work with Studio ATS, which qualifies requests and books discovery calls automatically. Happy to share a short overview if useful: [your link]', 5 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'en', 'DM — portfolio creators', 'Hi! Your feed is beautiful 🙌 Quick question: when someone wants to book you, do they just DM? Studio ATS turns your portfolio into a booking space that asks date, budget and project type upfront. Want me to send the link?', 6 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'en', 'Cold call script', '1. Opening — "Hi [First name], it’s [Your name]. I’ll be brief: I help [profession] turn website visitors into qualified appointments. Do you have 30 seconds?"
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I already have a website.”', 'That’s great — Studio ATS isn’t about replacing a nice site. The question is what happens after the visit: are requests qualified? Are follow-ups automatic? Do you know which sources bring real clients? The website is one component; Studio ATS is the whole path to the appointment.', 8 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“It’s too expensive.”', 'It’s a fair question. How much is one new client worth to you? Studio ATS is €6,000 a year, everything included. For a professional whose clients have high value, the question is whether it helps convert the requests you already get. [Avoid promising results — let them do their own math.]', 9 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I only work with Instagram.”', 'Instagram is excellent for being discovered. Studio ATS is where that attention turns into a structured request — with date, budget and project details — instead of another DM to chase. It complements Instagram; it doesn’t replace it.', 10 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I don’t need automation.”', 'Understood. Automation here just means the confirmation email, the reminder and the follow-up go out on time — the things that get forgotten on busy weeks. You stay in control of every conversation.', 11 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I need to think about it.”', 'Of course. To help you think it through: what would need to be true for this to be worth it for you? I’ll send you the overview [your link] and check back on [day] — does that work?', 12 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'fr', 'Premier contact — métiers à portfolio', 'Objet : [Entreprise] — transformer vos visiteurs en rendez-vous
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'fr', 'Relance à 3 jours', 'Objet : Re : [Entreprise] — transformer vos visiteurs en rendez-vous
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'fr', 'Intro courte', 'Bonjour [Prénom] 👋 J’ai vu votre travail sur [projet], très beau. Je travaille avec Studio ATS : il transforme votre portfolio en espace qui qualifie les demandes et programme les appels automatiquement. Je vous envoie une présentation de 2 minutes ?', 15 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'fr', 'Note d’invitation', 'Bonjour [Prénom], j’aide les [métier] à transformer leur visibilité en ligne en rendez-vous qualifiés. Ravi d’échanger.', 16 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'fr', 'DM — créateurs à portfolio', 'Bonjour ! Votre feed est superbe 🙌 Petite question : quand quelqu’un veut vous réserver, il vous écrit en DM ? Studio ATS transforme votre portfolio en espace de réservation qui demande date, budget et type de projet. Je vous envoie le lien ?', 17 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'fr', 'Script d’appel', '1. Accroche — « Bonjour [Prénom], [Votre nom]. Je serai bref : j’aide les [métier] à transformer les visiteurs de leur site en rendez-vous qualifiés. Vous avez 30 secondes ? »
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« J’ai déjà un site. »', 'Très bien — Studio ATS ne remplace pas un beau site. La question, c’est ce qui se passe après la visite : les demandes sont-elles qualifiées ? Les relances automatiques ? Savez-vous quelles sources amènent de vrais clients ? Le site est une composante ; Studio ATS, c’est tout le chemin jusqu’au rendez-vous.', 19 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« C’est trop cher. »', 'C’est une bonne question. Combien vaut un nouveau client pour vous ? Studio ATS coûte 6 000 € par an, tout compris. Pour un professionnel dont les clients ont une forte valeur, la question est de savoir s’il aide à convertir les demandes que vous recevez déjà. [Ne promettez pas de résultat — laissez le prospect faire son propre calcul.]', 20 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je travaille uniquement avec Instagram. »', 'Instagram est excellent pour être découvert. Studio ATS est l’endroit où cette attention devient une demande structurée — avec date, budget et détails — au lieu d’un énième DM à relancer. Il complète Instagram, il ne le remplace pas.', 21 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je n’ai pas besoin d’automatisation. »', 'Je comprends. Ici, l’automatisation signifie simplement que l’email de confirmation, le rappel et la relance partent à temps — ce qu’on oublie les semaines chargées. Vous gardez la main sur chaque conversation.', 22 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je dois réfléchir. »', 'Bien sûr. Pour vous aider : qu’est-ce qui devrait être vrai pour que ça en vaille la peine pour vous ? Je vous envoie la présentation [votre lien] et je reviens vers vous [jour] — ça vous va ?', 23 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'fr', 'Après un appel', 'Merci pour l’échange, [Prénom] ! Voici la page Studio ATS dont nous avons parlé : [votre lien]. N’hésitez pas si vous avez des questions.', 24 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'fr', 'Message après la mise en relation', 'Merci pour la mise en relation, [Prénom]. J’ai vu que [Entreprise] travaille sur [type de projet]. Comment vos nouveaux clients vous contactent-ils en général ? Je travaille avec Studio ATS, qui qualifie les demandes et programme automatiquement les appels de découverte. Je vous partage une courte présentation si c’est utile : [votre lien]', 25 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'de', 'Erstkontakt — Portfolio-Berufe', 'Betreff: [Unternehmen] — aus Besuchern gebuchte Termine machen
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'de', 'Nachfassen nach 3 Tagen', 'Betreff: Re: [Unternehmen] — aus Besuchern gebuchte Termine machen
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'de', 'Kurze Vorstellung', 'Hallo [Vorname] 👋 Ich habe Ihre Arbeit an [Projekt] gesehen — wirklich schön. Ich arbeite mit Studio ATS: Es verwandelt Ihr Portfolio in einen Bereich, der Anfragen qualifiziert und Gespräche automatisch bucht. Darf ich Ihnen einen 2-Minuten-Überblick schicken?', 28 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'de', 'Nach einem Gespräch', 'Danke für das Gespräch, [Vorname]! Hier ist die Studio-ATS-Seite, über die wir gesprochen haben: [Ihr Link]. Melden Sie sich gern bei Fragen.', 29 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'de', 'Kontaktanfrage', 'Hallo [Vorname], ich helfe [Beruf], ihre Online-Sichtbarkeit in qualifizierte Termine zu verwandeln. Ich würde mich über eine Vernetzung freuen.', 30 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'de', 'Nachricht nach der Vernetzung', 'Danke für die Vernetzung, [Vorname]. Ich habe gesehen, dass [Unternehmen] an [Projektart] arbeitet. Wie erreichen Sie neue Kunden normalerweise? Ich arbeite mit Studio ATS, das Anfragen qualifiziert und Erstgespräche automatisch bucht. Gern teile ich einen kurzen Überblick: [Ihr Link]', 31 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'de', 'DM — Portfolio-Kreative', 'Hallo! Ihr Feed ist wunderschön 🙌 Kurze Frage: Wenn jemand Sie buchen möchte, schreibt er Ihnen einfach eine DM? Studio ATS verwandelt Ihr Portfolio in einen Buchungsbereich, der Datum, Budget und Projektart gleich zu Beginn abfragt. Soll ich Ihnen den Link schicken?', 32 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'de', 'Kaltakquise-Leitfaden', '1. Einstieg — „Hallo [Vorname], hier ist [Ihr Name]. Ich fasse mich kurz: Ich helfe [Beruf], Website-Besucher in qualifizierte Termine zu verwandeln. Haben Sie 30 Sekunden?“
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'de', '„Ich habe schon eine Website.“', 'Sehr gut — bei Studio ATS geht es nicht darum, eine schöne Website zu ersetzen. Die Frage ist, was nach dem Besuch passiert: Werden Anfragen qualifiziert? Läuft das Nachfassen automatisch? Wissen Sie, welche Quellen echte Kunden bringen? Die Website ist ein Baustein; Studio ATS ist der ganze Weg bis zum Termin.', 34 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'de', '„Das ist zu teuer.“', 'Eine berechtigte Frage. Wie viel ist Ihnen ein neuer Kunde wert? Studio ATS kostet 6.000 € pro Jahr, alles inklusive. Für Profis mit hochwertigen Kunden ist die Frage, ob es hilft, die Anfragen umzuwandeln, die Sie bereits erhalten. [Keine Ergebnisse versprechen — lassen Sie den Interessenten selbst rechnen.]', 35 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'de', '„Ich arbeite nur mit Instagram.“', 'Instagram ist hervorragend, um entdeckt zu werden. Studio ATS ist der Ort, an dem diese Aufmerksamkeit zu einer strukturierten Anfrage wird — mit Datum, Budget und Projektdetails — statt einer weiteren DM, der man hinterherlaufen muss. Es ergänzt Instagram, es ersetzt es nicht.', 36 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'de', '„Ich brauche keine Automatisierung.“', 'Verstehe. Automatisierung bedeutet hier nur, dass Bestätigungs-E-Mail, Erinnerung und Nachfassen rechtzeitig rausgehen — die Dinge, die in vollen Wochen vergessen werden. Sie behalten die Kontrolle über jedes Gespräch.', 37 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'de', '„Ich muss darüber nachdenken.“', 'Natürlich. Um Ihnen dabei zu helfen: Was müsste zutreffen, damit es sich für Sie lohnt? Ich schicke Ihnen den Überblick [Ihr Link] und melde mich am [Tag] wieder — passt das?', 38 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'es', 'Primer contacto — oficios con portafolio', 'Asunto: [Empresa] — convertir visitantes en citas reservadas
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'es', 'Seguimiento a los 3 días', 'Asunto: Re: [Empresa] — convertir visitantes en citas reservadas
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'es', 'Presentación breve', 'Hola [Nombre] 👋 He visto tu trabajo en [proyecto], muy bonito. Trabajo con Studio ATS: convierte tu portafolio en un espacio que cualifica las solicitudes y reserva llamadas automáticamente. ¿Te envío una presentación de 2 minutos?', 41 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'es', 'Después de una llamada', '¡Gracias por la llamada, [Nombre]! Aquí tienes la página de Studio ATS de la que hablamos: [tu enlace]. Si tienes cualquier pregunta, dímelo.', 42 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'es', 'Nota de conexión', 'Hola [Nombre], ayudo a [profesión] a convertir su visibilidad online en citas cualificadas. Me encantaría conectar.', 43 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'es', 'Mensaje tras conectar', 'Gracias por conectar, [Nombre]. He visto que [Empresa] trabaja en [tipo de proyecto]. ¿Cómo suelen contactarte los nuevos clientes? Trabajo con Studio ATS, que cualifica las solicitudes y reserva llamadas de descubrimiento automáticamente. Si te resulta útil, te comparto una breve presentación: [tu enlace]', 44 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'es', 'DM — creadores con portafolio', '¡Hola! Tu feed es precioso 🙌 Una pregunta: cuando alguien quiere reservarte, ¿simplemente te escribe por DM? Studio ATS convierte tu portafolio en un espacio de reservas que pide fecha, presupuesto y tipo de proyecto desde el principio. ¿Te paso el enlace?', 45 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'es', 'Guion de llamada en frío', '1. Apertura — «Hola [Nombre], soy [Tu nombre]. Seré breve: ayudo a [profesión] a convertir a los visitantes de su web en citas cualificadas. ¿Tienes 30 segundos?»
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'es', '«Ya tengo una web».', 'Genial — Studio ATS no pretende sustituir una buena web. La cuestión es qué pasa después de la visita: ¿se cualifican las solicitudes? ¿Los seguimientos son automáticos? ¿Sabes qué fuentes traen clientes reales? La web es una pieza; Studio ATS es todo el camino hasta la cita.', 47 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'es', '«Es demasiado caro».', 'Es una pregunta justa. ¿Cuánto vale para ti un cliente nuevo? Studio ATS cuesta 6.000 € al año, todo incluido. Para un profesional cuyos clientes tienen un valor alto, la cuestión es si ayuda a convertir las solicitudes que ya recibes. [No prometas resultados — deja que el prospecto haga sus propias cuentas.]', 48 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'es', '«Solo trabajo con Instagram».', 'Instagram es excelente para que te descubran. Studio ATS es donde esa atención se convierte en una solicitud estructurada — con fecha, presupuesto y detalles del proyecto — en lugar de otro DM que perseguir. Complementa Instagram; no lo sustituye.', 49 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'es', '«No necesito automatización».', 'Entendido. Aquí la automatización solo significa que el correo de confirmación, el recordatorio y el seguimiento salen a tiempo — lo que se olvida en las semanas con mucho trabajo. Tú sigues controlando cada conversación.', 50 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'es', '«Tengo que pensarlo».', 'Por supuesto. Para ayudarte a decidir: ¿qué tendría que cumplirse para que valiera la pena para ti? Te envío la presentación [tu enlace] y te escribo el [día] — ¿te parece bien?', 51 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'pt', 'Primeiro contacto — profissões com portfólio', 'Assunto: [Empresa] — transformar visitantes em reuniões marcadas
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'pt', 'Seguimento ao fim de 3 dias', 'Assunto: Re: [Empresa] — transformar visitantes em reuniões marcadas
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'pt', 'Apresentação curta', 'Olá [Nome] 👋 Vi o seu trabalho em [projeto] — muito bonito. Trabalho com o Studio ATS: transforma o seu portfólio num espaço que qualifica pedidos e marca chamadas automaticamente. Posso enviar-lhe uma apresentação de 2 minutos?', 54 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'pt', 'Depois de uma chamada', 'Obrigado pela chamada, [Nome]! Aqui está a página do Studio ATS de que falámos: [o seu link]. Diga-me se tiver alguma dúvida.', 55 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'pt', 'Nota de convite', 'Olá [Nome], ajudo [profissão] a transformar a sua visibilidade online em reuniões qualificadas. Gostaria muito de nos ligarmos.', 56 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'pt', 'Mensagem após a ligação', 'Obrigado por aceitar o convite, [Nome]. Reparei que a [Empresa] trabalha em [tipo de projeto]. Como é que os novos clientes costumam chegar até si? Trabalho com o Studio ATS, que qualifica pedidos e marca chamadas de descoberta automaticamente. Se for útil, partilho uma breve apresentação: [o seu link]', 57 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'pt', 'DM — criadores com portfólio', 'Olá! O seu feed é lindo 🙌 Uma pergunta: quando alguém o quer contratar, envia simplesmente uma DM? O Studio ATS transforma o seu portfólio num espaço de reservas que pede data, orçamento e tipo de projeto logo à partida. Quer que lhe envie o link?', 58 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'pt', 'Guião de chamada a frio', '1. Abertura — «Olá [Nome], fala [O seu nome]. Vou ser breve: ajudo [profissão] a transformar os visitantes do site em reuniões qualificadas. Tem 30 segundos?»
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'pt', '«Já tenho um site.»', 'Ótimo — o Studio ATS não serve para substituir um bom site. A questão é o que acontece depois da visita: os pedidos são qualificados? Os seguimentos são automáticos? Sabe que fontes trazem clientes reais? O site é uma peça; o Studio ATS é todo o caminho até à reunião.', 60 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'pt', '«É demasiado caro.»', 'É uma pergunta justa. Quanto vale para si um novo cliente? O Studio ATS custa 6 000 € por ano, tudo incluído. Para um profissional cujos clientes têm um valor elevado, a questão é se ajuda a converter os pedidos que já recebe. [Não prometa resultados — deixe o potencial cliente fazer as suas próprias contas.]', 61 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'pt', '«Só trabalho com o Instagram.»', 'O Instagram é excelente para ser descoberto. O Studio ATS é onde essa atenção se transforma num pedido estruturado — com data, orçamento e detalhes do projeto — em vez de mais uma DM para seguir. Complementa o Instagram; não o substitui.', 62 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'pt', '«Não preciso de automatização.»', 'Compreendo. Aqui, automatização significa apenas que o email de confirmação, o lembrete e o seguimento saem a tempo — aquilo que se esquece nas semanas mais cheias. Continua a controlar cada conversa.', 63 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'pt', '«Preciso de pensar.»', 'Claro. Para ajudar a pensar: o que teria de ser verdade para que valesse a pena para si? Envio-lhe a apresentação [o seu link] e volto a contactá-lo em [dia] — pode ser?', 64 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'it', 'Primo contatto — professioni con portfolio', 'Oggetto: [Azienda] — trasformare i visitatori in appuntamenti prenotati
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'it', 'Follow-up dopo 3 giorni', 'Oggetto: Re: [Azienda] — trasformare i visitatori in appuntamenti prenotati
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'it', 'Presentazione breve', 'Ciao [Nome] 👋 Ho visto il tuo lavoro su [progetto], davvero bello. Lavoro con Studio ATS: trasforma il tuo portfolio in uno spazio che qualifica le richieste e prenota le chiamate automaticamente. Ti mando una panoramica di 2 minuti?', 67 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'it', 'Dopo una chiamata', 'Grazie per la chiamata, [Nome]! Ecco la pagina di Studio ATS di cui abbiamo parlato: [il tuo link]. Fammi sapere se hai domande.', 68 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'it', 'Nota di collegamento', 'Ciao [Nome], aiuto [professione] a trasformare la loro visibilità online in appuntamenti qualificati. Mi farebbe piacere collegarci.', 69 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'it', 'Messaggio dopo il collegamento', 'Grazie per il collegamento, [Nome]. Ho notato che [Azienda] lavora su [tipo di progetto]. Di solito come ti contattano i nuovi clienti? Lavoro con Studio ATS, che qualifica le richieste e prenota automaticamente le chiamate conoscitive. Se ti è utile, ti condivido una breve panoramica: [il tuo link]', 70 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'it', 'DM — creativi con portfolio', 'Ciao! Il tuo feed è bellissimo 🙌 Una domanda: quando qualcuno vuole prenotarti, ti scrive semplicemente in DM? Studio ATS trasforma il tuo portfolio in uno spazio di prenotazione che chiede subito data, budget e tipo di progetto. Ti mando il link?', 71 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'it', 'Script per chiamata a freddo', '1. Apertura — «Ciao [Nome], sono [Il tuo nome]. Sarò breve: aiuto [professione] a trasformare i visitatori del sito in appuntamenti qualificati. Hai 30 secondi?»
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'it', '«Ho già un sito.»', 'Ottimo — Studio ATS non serve a sostituire un bel sito. La domanda è cosa succede dopo la visita: le richieste vengono qualificate? I follow-up sono automatici? Sai quali fonti portano clienti veri? Il sito è un tassello; Studio ATS è tutto il percorso fino all’appuntamento.', 73 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'it', '«È troppo caro.»', 'È una domanda legittima. Quanto vale per te un nuovo cliente? Studio ATS costa 6.000 € all’anno, tutto incluso. Per un professionista i cui clienti hanno un valore elevato, la domanda è se aiuta a convertire le richieste che ricevi già. [Non promettere risultati — lascia che il potenziale cliente faccia i propri conti.]', 74 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'it', '«Lavoro solo con Instagram.»', 'Instagram è ottimo per farsi scoprire. Studio ATS è il luogo in cui quell’attenzione diventa una richiesta strutturata — con data, budget e dettagli del progetto — invece dell’ennesimo DM da rincorrere. Completa Instagram, non lo sostituisce.', 75 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'it', '«Non ho bisogno di automazione.»', 'Capisco. Qui automazione significa solo che l’email di conferma, il promemoria e il follow-up partono in tempo — le cose che si dimenticano nelle settimane piene. Mantieni il controllo di ogni conversazione.', 76 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'it', '«Devo pensarci.»', 'Certo. Per aiutarti a riflettere: cosa dovrebbe essere vero perché ne valga la pena per te? Ti mando la panoramica [il tuo link] e ti ricontatto [giorno] — ti va bene?', 77 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'nl', 'Eerste contact — portfolioberoepen', 'Onderwerp: [Bedrijf] — van bezoekers naar geboekte afspraken
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'nl', 'Opvolging na 3 dagen', 'Onderwerp: Re: [Bedrijf] — van bezoekers naar geboekte afspraken
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'nl', 'Korte introductie', 'Hoi [Voornaam] 👋 Ik zag je werk aan [project] — echt mooi. Ik werk met Studio ATS: het maakt van je portfolio een ruimte die aanvragen kwalificeert en gesprekken automatisch inplant. Mag ik je een overzicht van 2 minuten sturen?', 80 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'nl', 'Na een gesprek', 'Bedankt voor het gesprek, [Voornaam]! Hier is de Studio ATS-pagina waar we het over hadden: [jouw link]. Laat het me weten als je vragen hebt.', 81 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'nl', 'Connectieverzoek', 'Hoi [Voornaam], ik help [beroep] hun online zichtbaarheid om te zetten in gekwalificeerde afspraken. Ik zou graag met je connecten.', 82 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'nl', 'Bericht na het connecten', 'Bedankt voor het connecten, [Voornaam]. Ik zag dat [Bedrijf] werkt aan [type project]. Hoe komen nieuwe klanten meestal bij je terecht? Ik werk met Studio ATS, dat aanvragen kwalificeert en kennismakingsgesprekken automatisch inplant. Als het nuttig is, deel ik graag een kort overzicht: [jouw link]', 83 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'nl', 'DM — portfoliomakers', 'Hoi! Je feed is prachtig 🙌 Korte vraag: als iemand je wil boeken, sturen ze dan gewoon een DM? Studio ATS maakt van je portfolio een boekingsruimte die meteen naar datum, budget en type project vraagt. Zal ik je de link sturen?', 84 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'nl', 'Script voor koude acquisitie', '1. Opening — "Hallo [Voornaam], met [Jouw naam]. Ik houd het kort: ik help [beroep] websitebezoekers om te zetten in gekwalificeerde afspraken. Heb je 30 seconden?"
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'nl', '‘Ik heb al een website.’', 'Prima — Studio ATS is er niet om een mooie website te vervangen. De vraag is wat er na het bezoek gebeurt: worden aanvragen gekwalificeerd? Gaat de opvolging automatisch? Weet je welke bronnen echte klanten opleveren? De website is één onderdeel; Studio ATS is de hele weg naar de afspraak.', 86 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'nl', '‘Het is te duur.’', 'Een terechte vraag. Hoeveel is één nieuwe klant voor jou waard? Studio ATS kost € 6.000 per jaar, alles inbegrepen. Voor een professional met klanten van hoge waarde is de vraag of het helpt de aanvragen om te zetten die je al krijgt. [Beloof geen resultaten — laat de prospect zelf rekenen.]', 87 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'nl', '‘Ik werk alleen met Instagram.’', 'Instagram is uitstekend om ontdekt te worden. Studio ATS is de plek waar die aandacht een gestructureerde aanvraag wordt — met datum, budget en projectdetails — in plaats van nog een DM om achteraan te zitten. Het vult Instagram aan; het vervangt het niet.', 88 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'nl', '‘Ik heb geen automatisering nodig.’', 'Begrijpelijk. Automatisering betekent hier alleen dat de bevestigingsmail, de herinnering en de opvolging op tijd verstuurd worden — de dingen die in drukke weken vergeten worden. Jij houdt de regie over elk gesprek.', 89 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'nl', '‘Ik moet erover nadenken.’', 'Natuurlijk. Om je te helpen: wat zou er waar moeten zijn om het voor jou de moeite waard te maken? Ik stuur je het overzicht [jouw link] en kom er op [dag] op terug — is dat goed?', 90 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'ar', 'التواصل الأول — المهن القائمة على معرض الأعمال', 'الموضوع: [الشركة] — تحويل الزوار إلى مواعيد محجوزة
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'ar', 'متابعة بعد 3 أيام', 'الموضوع: رد: [الشركة] — تحويل الزوار إلى مواعيد محجوزة
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'ar', 'تعريف قصير', 'مرحبًا [الاسم الأول] 👋 رأيت عملك في [المشروع] — رائع حقًا. أعمل مع Studio ATS: يحوّل معرض أعمالك إلى مساحة تؤهّل الطلبات وتحجز المكالمات تلقائيًا. هل أرسل لك عرضًا عامًا مدته دقيقتان؟', 93 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'ar', 'بعد مكالمة', 'شكرًا على المكالمة يا [الاسم الأول]! إليك صفحة Studio ATS التي تحدثنا عنها: [رابطك]. أخبرني إن كانت لديك أي أسئلة.', 94 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'ar', 'ملاحظة طلب التواصل', 'مرحبًا [الاسم الأول]، أساعد [المهنة] على تحويل حضورهم عبر الإنترنت إلى مواعيد مؤهَّلة. يسعدني التواصل معك.', 95 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'ar', 'رسالة بعد قبول التواصل', 'شكرًا على قبول التواصل يا [الاسم الأول]. لاحظت أن [الشركة] تعمل على [نوع المشروع]. كيف يصل إليك العملاء الجدد عادةً؟ أعمل مع Studio ATS، الذي يؤهّل الطلبات ويحجز مكالمات التعارف تلقائيًا. يسعدني مشاركة عرض قصير إن كان مفيدًا: [رابطك]', 96 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'ar', 'رسالة مباشرة — المبدعون أصحاب معارض الأعمال', 'مرحبًا! حسابك جميل جدًا 🙌 سؤال سريع: عندما يريد أحدهم حجزك، هل يرسل لك رسالة مباشرة فقط؟ Studio ATS يحوّل معرض أعمالك إلى مساحة حجز تسأل عن التاريخ والميزانية ونوع المشروع منذ البداية. هل أرسل لك الرابط؟', 97 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'ar', 'نص المكالمة الباردة', '1. الافتتاح — «مرحبًا [الاسم الأول]، معك [اسمك]. سأكون مختصرًا: أساعد [المهنة] على تحويل زوار مواقعهم إلى مواعيد مؤهَّلة. هل لديك 30 ثانية؟»
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'ar', '«لديّ موقع بالفعل.»', 'ممتاز — Studio ATS لا يهدف إلى استبدال موقع جميل. السؤال هو ما الذي يحدث بعد الزيارة: هل تُؤهَّل الطلبات؟ هل المتابعات تلقائية؟ هل تعرف أي المصادر تجلب عملاء حقيقيين؟ الموقع جزء واحد؛ أما Studio ATS فهو المسار الكامل حتى الموعد.', 99 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'ar', '«إنه مكلف جدًا.»', 'سؤال وجيه. كم يساوي عميل جديد بالنسبة لك؟ تكلفة Studio ATS هي 6,000 يورو سنويًا، شاملة كل شيء. بالنسبة لمهني يتمتع عملاؤه بقيمة عالية، السؤال هو ما إذا كان يساعد على تحويل الطلبات التي تتلقاها أصلًا. [لا تَعِد بنتائج — دع العميل المحتمل يجري حساباته بنفسه.]', 100 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'ar', '«أعمل فقط عبر إنستغرام.»', 'إنستغرام ممتاز ليكتشفك الناس. أما Studio ATS فهو المكان الذي يتحول فيه هذا الاهتمام إلى طلب منظَّم — بالتاريخ والميزانية وتفاصيل المشروع — بدلًا من رسالة مباشرة أخرى تحتاج إلى ملاحقتها. إنه يكمّل إنستغرام ولا يحل محله.', 101 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'ar', '«لا أحتاج إلى الأتمتة.»', 'مفهوم. الأتمتة هنا تعني فقط أن رسالة التأكيد والتذكير والمتابعة تُرسَل في وقتها — وهي الأمور التي تُنسى في الأسابيع المزدحمة. تبقى أنت المتحكم في كل محادثة.', 102 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'ar', '«أحتاج إلى التفكير في الأمر.»', 'بالتأكيد. لمساعدتك على التفكير: ما الذي يجب أن يتحقق ليكون الأمر مجديًا لك؟ سأرسل لك العرض العام [رابطك] وأعود إليك يوم [اليوم] — هل يناسبك ذلك؟', 103 from public.products where slug = 'studio';
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'en', 1, 'active', p.id, null, null, null, 'Studio ATS — standard sales page', 'Default structure for every affiliate sales page.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Turn your traffic into opportunities.","heroSubtitle":"An online commercial studio for professionals whose every new client has real value. Present your work, qualify requests and book appointments — in one place.","problemTitle":"Great work. Lost requests.","problemBody":"Enquiries arrive through a contact form, social media, messages and email. Nobody knows which ones are serious, follow-ups are forgotten, and good prospects go cold.","solutionTitle":"More than a website.","solutionBody":"The site is only one part. Studio ATS is the whole path from first visit to booked appointment — designed, set up and maintained for you.","valueTitle":"What you actually get","valueItems":["A presence that inspires trust at first glance","Requests that arrive with the right information","Every contact and request in one place","Follow-ups that go out on time"],"howTitle":"How it works","howSteps":[{"title":"Request","body":"Tell us about your business in a short form."},{"title":"Call","body":"We qualify your needs together."},{"title":"Build","body":"We design and configure your Studio ATS."},{"title":"Launch","body":"You start receiving structured requests."}],"benefitsTitle":"Why it matters for your business","benefits":[{"title":"Trust","body":"Prospects check you online before calling. Make that first impression count."},{"title":"Time","body":"Know budget, timing and project type before you pick up the phone."},{"title":"Nothing to manage","body":"Built, hosted and maintained by the Studio ATS team."}],"includedTitle":"What’s included","whoTitle":"Who it’s for","whoBody":"Professionals and companies whose clients are worth a lot, with a visual or premium offer and inbound requests to convert.","faqTitle":"Questions you may have","offerTitle":"One plan. Everything included.","offerNote":"Price excl. VAT where applicable. Final terms in the contract.","ctaTitle":"Ready to talk about your business?","ctaBody":"Leave your details — no commitment. We’ll get back to you to understand your needs."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'fr', 1, 'active', p.id, null, null, null, 'Studio ATS — page commerciale standard', 'Structure par défaut de toutes les pages commerciales affiliées.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Transformez votre trafic en opportunités.","heroSubtitle":"Un studio commercial en ligne pour les professionnels dont chaque nouveau client compte. Présentez votre travail, qualifiez les demandes et obtenez des rendez-vous — au même endroit.","problemTitle":"Un beau travail. Des demandes perdues.","problemBody":"Les demandes arrivent par formulaire, réseaux sociaux, messages et email. Personne ne sait lesquelles sont sérieuses, les relances sont oubliées et les bons prospects refroidissent.","solutionTitle":"Bien plus qu’un site.","solutionBody":"Le site n’est qu’une partie. Studio ATS, c’est tout le parcours, de la première visite au rendez-vous — conçu, mis en place et maintenu pour vous.","valueTitle":"Ce que vous obtenez vraiment","valueItems":["Une présence qui inspire confiance au premier regard","Des demandes qui arrivent avec les bonnes informations","Tous les contacts et demandes au même endroit","Des relances envoyées au bon moment"],"howTitle":"Comment ça marche","howSteps":[{"title":"Demande","body":"Présentez votre activité dans un court formulaire."},{"title":"Appel","body":"Nous qualifions ensemble vos besoins."},{"title":"Création","body":"Nous concevons et configurons votre Studio ATS."},{"title":"Lancement","body":"Vous recevez des demandes structurées."}],"benefitsTitle":"Pourquoi c’est important pour votre activité","benefits":[{"title":"Confiance","body":"Les prospects vous vérifient en ligne avant d’appeler. Soignez cette première impression."},{"title":"Temps","body":"Connaissez budget, délai et type de projet avant de décrocher."},{"title":"Rien à gérer","body":"Conçu, hébergé et maintenu par l’équipe Studio ATS."}],"includedTitle":"Ce qui est inclus","whoTitle":"Pour qui","whoBody":"Les professionnels et entreprises dont chaque client compte, avec une offre visuelle ou premium et des demandes entrantes à convertir.","faqTitle":"Vos questions","offerTitle":"Une formule. Tout inclus.","offerNote":"Prix HT le cas échéant. Conditions définitives au contrat.","ctaTitle":"Prêt à parler de votre activité ?","ctaBody":"Laissez vos coordonnées — sans engagement. Nous revenons vers vous pour comprendre vos besoins."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'en', 1, 'active', p.id, 'artisans', null, null, 'Artisans variant', null, '{"template":"studio-default","heroTitle":"Your work is excellent. Your online presence should be too.","heroSubtitle":"Prospects look you up before they call. Studio ATS gives your business a professional presence and collects complete requests — even while you’re on a job.","problemTitle":"Word of mouth isn’t enough anymore.","problemBody":"People who don’t know you yet check you online first. If they find little, they call someone else — and the requests that do arrive are scattered and incomplete.","ctaTitle":"Let’s look at your business together","ctaBody":"Leave your details and describe your trade in one line. No commitment."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'fr', 1, 'active', p.id, 'artisans', null, null, 'Variante artisans', null, '{"template":"studio-default","heroTitle":"Votre travail est excellent. Votre présence en ligne doit l’être aussi.","heroSubtitle":"Les prospects vous cherchent avant d’appeler. Studio ATS donne à votre entreprise une présence professionnelle et recueille des demandes complètes — même pendant vos chantiers.","problemTitle":"Le bouche-à-oreille ne suffit plus.","problemBody":"Ceux qui ne vous connaissent pas encore vous vérifient d’abord en ligne. S’ils trouvent peu de choses, ils appellent quelqu’un d’autre — et les demandes qui arrivent sont éparpillées et incomplètes.","ctaTitle":"Regardons ensemble votre activité","ctaBody":"Laissez vos coordonnées et décrivez votre métier en une ligne. Sans engagement."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'en', 1, 'active', p.id, null, null, null, 'Generate more qualified inquiries', null, '{"promise":"Requests that arrive with budget, timing and details.","heroTitle":"Receive requests you can actually answer.","heroSubtitle":"Studio ATS asks the right questions before the first call, so every request arrives with the information you need."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'fr', 1, 'active', p.id, null, null, null, 'Recevoir des demandes plus qualifiées', null, '{"promise":"Des demandes qui arrivent avec budget, délai et détails.","heroTitle":"Recevez des demandes auxquelles vous pouvez vraiment répondre.","heroSubtitle":"Studio ATS pose les bonnes questions avant le premier appel : chaque demande arrive avec les informations dont vous avez besoin."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'en', 1, 'active', p.id, null, null, null, 'Look as professional online as you are', null, '{"promise":"A presence that matches the quality of the work.","heroTitle":"Look as professional online as you are in real life.","heroSubtitle":"Prospects check you before they call. Give them a presence that inspires trust in seconds."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'fr', 1, 'active', p.id, null, null, null, 'Paraître aussi professionnel en ligne qu’en vrai', null, '{"promise":"Une présence à la hauteur de la qualité du travail.","heroTitle":"Soyez aussi professionnel en ligne que dans la réalité.","heroSubtitle":"Les prospects vous vérifient avant d’appeler. Offrez-leur une présence qui inspire confiance en quelques secondes."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'en', 1, 'active', p.id, null, null, null, 'Stop losing requests', null, '{"promise":"Every request captured and centralised, even while busy.","heroTitle":"Stop losing requests while you work.","heroSubtitle":"Every request lands in one place with the right details — and follow-ups go out on time."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'fr', 1, 'active', p.id, null, null, null, 'Ne plus perdre de demandes', null, '{"promise":"Chaque demande captée et centralisée, même quand on est occupé.","heroTitle":"Ne perdez plus de demandes pendant que vous travaillez.","heroSubtitle":"Chaque demande arrive au même endroit avec les bons détails — et les relances partent au bon moment."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'en', 1, 'active', p.id, null, null, null, 'Sell Studio ATS — the method', 'The 10 steps of a Studio ATS sale, for any target. Open a target to get its problems and angle injected.', '{"intro":"Sell the outcome, not the technology. Your job is to understand their situation, show them what they lose today, and send them the right page.","steps":[{"key":"understand","title":"Understand them","body":"Before contacting, look at how they present themselves online today and how a new client can reach them.","bullets":["Check their site, social profiles and reviews","Note one specific thing you like about their work"]},{"key":"opening","title":"Opening","body":"Start with them, not with Studio ATS. One genuine remark, one question.","bullets":["“I came across your work on …”","“Quick question: how do most new clients find you?”"]},{"key":"discovery","title":"Discovery","body":"Ask, then listen. Let them describe how requests arrive and what happens next.","bullets":["How do new clients contact you today?","What information is usually missing?","What happens when you can’t answer immediately?"]},{"key":"pain","title":"Identify the pain","body":"Name the problem with their words. Don’t invent one they don’t have."},{"key":"present","title":"Present Studio ATS","body":"Connect Studio ATS to the problem they just described — one sentence, not a feature list.","bullets":["“That’s exactly what Studio ATS handles: …”"]},{"key":"value","title":"Demonstrate value","body":"Talk about outcomes: trust, complete requests, time saved, nothing to manage. Never promise figures."},{"key":"objections","title":"Handle objections","body":"An objection is a question in disguise. Ask what’s behind it before answering."},{"key":"offer","title":"Send the offer","body":"Send your sales page for their sector: it explains everything and the price comes from Studio ATS."},{"key":"follow_up","title":"Follow up","body":"No reply after a few days? One short, useful follow-up — then respect their answer."},{"key":"close","title":"Close","body":"Agree on a clear next step: a call, a request on the page, or the purchase online."}]}'::jsonb, array['method', 'discovery', 'closing']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'fr', 1, 'active', p.id, null, null, null, 'Vendre Studio ATS — la méthode', 'Les 10 étapes d’une vente Studio ATS, pour toute cible. Ouvrez une cible pour y injecter ses problèmes et son angle.', '{"intro":"Vendez le résultat, pas la technologie. Votre rôle : comprendre leur situation, montrer ce qu’ils perdent aujourd’hui, et envoyer la bonne page.","steps":[{"key":"understand","title":"Les comprendre","body":"Avant de contacter, regardez comment ils se présentent en ligne et comment un nouveau client peut les joindre.","bullets":["Regardez leur site, leurs réseaux et leurs avis","Notez une chose précise que vous appréciez dans leur travail"]},{"key":"opening","title":"Ouverture","body":"Commencez par eux, pas par Studio ATS. Une remarque sincère, une question.","bullets":["« J’ai découvert votre travail sur … »","« Petite question : comment vos nouveaux clients vous trouvent-ils ? »"]},{"key":"discovery","title":"Découverte","body":"Questionnez, puis écoutez. Laissez-les décrire comment arrivent les demandes et ce qui se passe ensuite.","bullets":["Comment les nouveaux clients vous contactent-ils ?","Quelle information manque souvent ?","Que se passe-t-il quand vous ne pouvez pas répondre tout de suite ?"]},{"key":"pain","title":"Identifier le problème","body":"Nommez le problème avec leurs mots. N’inventez pas un problème qu’ils n’ont pas."},{"key":"present","title":"Présenter Studio ATS","body":"Reliez Studio ATS au problème qu’ils viennent de décrire — une phrase, pas une liste de fonctionnalités.","bullets":["« C’est exactement ce que Studio ATS prend en charge : … »"]},{"key":"value","title":"Montrer la valeur","body":"Parlez résultats : confiance, demandes complètes, temps gagné, rien à gérer. Ne promettez jamais de chiffres."},{"key":"objections","title":"Traiter les objections","body":"Une objection est une question déguisée. Demandez ce qu’il y a derrière avant de répondre."},{"key":"offer","title":"Envoyer l’offre","body":"Envoyez votre page commerciale pour leur secteur : elle explique tout et le prix vient de Studio ATS."},{"key":"follow_up","title":"Relancer","body":"Pas de réponse après quelques jours ? Une relance courte et utile — puis respectez leur réponse."},{"key":"close","title":"Conclure","body":"Convenez d’une prochaine étape claire : un appel, une demande sur la page, ou l’achat en ligne."}]}'::jsonb, array['méthode', 'découverte', 'closing']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'en', 1, 'active', p.id, 'artisans', null, null, 'Sell Studio ATS to an artisan', 'Phone-first, short, concrete. Artisans are busy: respect their time.', '{"intro":"Artisans buy from people who understand their job. Talk about their clients and their time — never about “websites”.","steps":[{"key":"understand","title":"Understand them","body":"They are on site most of the day, get work through word of mouth, and answer calls between two jobs. Their reputation is their main asset.","bullets":["Look them up as a client would: what do you find?","Note their trade, area and the type of jobs they show"]},{"key":"opening","title":"Opening","body":"Call early morning or end of day. Be brief and specific.","bullets":["“I looked you up as a client would — can I share what I noticed? It takes 2 minutes.”"]},{"key":"discovery","title":"Discovery","body":"Three questions are enough.","bullets":["How do most of your new clients find you?","What happens when someone who doesn’t know you looks you up?","How many calls do you miss while you’re on a job?"]},{"key":"pain","title":"Identify the pain","body":"Usually: word of mouth has limits, the business looks less professional online than in reality, requests get lost."},{"key":"present","title":"Present Studio ATS","body":"“Studio ATS gives your business a professional presence that works while you’re on site: people see your work and send complete requests — job, place, timing.”"},{"key":"value","title":"Demonstrate value","body":"Trust from people who don’t know you yet. Requests you can answer in one go. Nothing to manage yourself."},{"key":"objections","title":"Handle objections","body":"Expect: “I already have social media”, “my clients come by word of mouth”, “I don’t have time”."},{"key":"offer","title":"Send the offer","body":"Send your artisan sales page by SMS or WhatsApp right after the call, while the conversation is fresh."},{"key":"follow_up","title":"Follow up","body":"Two to three days later, one short message: “Did you have time to look? Any question I can answer?”"},{"key":"close","title":"Close","body":"Propose the next step: a request on the page, a call with the Studio ATS team, or the purchase online when available."}]}'::jsonb, array['artisan', 'phone', 'word of mouth', 'social media']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'fr', 1, 'active', p.id, 'artisans', null, null, 'Vendre Studio ATS à un artisan', 'Téléphone d’abord, court, concret. Les artisans sont occupés : respectez leur temps.', '{"intro":"Les artisans achètent à ceux qui comprennent leur métier. Parlez de leurs clients et de leur temps — jamais de « site internet ».","steps":[{"key":"understand","title":"Les comprendre","body":"Ils sont sur les chantiers la plupart de la journée, travaillent par bouche-à-oreille et répondent entre deux interventions. Leur réputation est leur principal atout.","bullets":["Cherchez-les comme le ferait un client : que trouvez-vous ?","Notez leur métier, leur zone et les travaux qu’ils montrent"]},{"key":"opening","title":"Ouverture","body":"Appelez tôt le matin ou en fin de journée. Soyez bref et précis.","bullets":["« Je vous ai cherché comme le ferait un client — je peux vous dire ce que j’ai remarqué ? Ça prend 2 minutes. »"]},{"key":"discovery","title":"Découverte","body":"Trois questions suffisent.","bullets":["Comment la plupart de vos nouveaux clients vous trouvent-ils ?","Que se passe-t-il quand quelqu’un qui ne vous connaît pas vous cherche ?","Combien d’appels manquez-vous pendant un chantier ?"]},{"key":"pain","title":"Identifier le problème","body":"En général : le bouche-à-oreille a ses limites, l’entreprise paraît moins professionnelle en ligne qu’en vrai, des demandes se perdent."},{"key":"present","title":"Présenter Studio ATS","body":"« Studio ATS donne à votre entreprise une présence professionnelle qui travaille pendant vos chantiers : on voit vos réalisations et on vous envoie des demandes complètes — travaux, lieu, délai. »"},{"key":"value","title":"Montrer la valeur","body":"La confiance de ceux qui ne vous connaissent pas encore. Des demandes auxquelles on répond en une fois. Rien à gérer soi-même."},{"key":"objections","title":"Traiter les objections","body":"Attendez-vous à : « j’ai déjà les réseaux sociaux », « mes clients viennent par le bouche-à-oreille », « je n’ai pas le temps »."},{"key":"offer","title":"Envoyer l’offre","body":"Envoyez votre page artisans par SMS ou WhatsApp juste après l’appel, tant que l’échange est frais."},{"key":"follow_up","title":"Relancer","body":"Deux à trois jours plus tard, un message court : « Vous avez eu le temps de regarder ? Une question ? »"},{"key":"close","title":"Conclure","body":"Proposez la prochaine étape : une demande sur la page, un appel avec l’équipe Studio ATS, ou l’achat en ligne quand il est disponible."}]}'::jsonb, array['artisan', 'téléphone', 'bouche-à-oreille', 'réseaux sociaux']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'en', 1, 'active', p.id, null, 'phone', null, 'Discovery call (any target)', '5 minutes to understand, qualify and agree on a next step.', '{"intro":"Tick each step as you go. Talk less than them.","steps":[{"type":"opening","text":"Hello {{firstName}}, it’s {{advisorName}}. I’m calling about how new clients reach {{company}} — do you have 2 minutes?"},{"type":"question","text":"How do most of your new clients find you today?"},{"type":"listen","text":"Word of mouth only? Social media? Requests by phone during work?","hint":"Write down their exact words."},{"type":"question","text":"What happens when someone who doesn’t know you looks you up online?"},{"type":"problem","text":"They find little, or requests arrive scattered and incomplete."},{"type":"response","text":"That’s what Studio ATS handles: a professional presence that inspires trust and collects complete requests — built and maintained for you."},{"type":"objection","text":"“I already have social media.”"},{"type":"answer","text":"Social media shows your work. Studio ATS turns the interest into a complete request. Where do people send you a request today?"},{"type":"cta","text":"Can I send you the page for your sector? It explains everything, including the price, in 3 minutes."}]}'::jsonb, array['phone', 'discovery', 'call']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'fr', 1, 'active', p.id, null, 'phone', null, 'Appel découverte (toute cible)', '5 minutes pour comprendre, qualifier et convenir d’une prochaine étape.', '{"intro":"Cochez chaque étape au fil de l’appel. Parlez moins qu’eux.","steps":[{"type":"opening","text":"Bonjour {{firstName}}, c’est {{advisorName}}. Je vous appelle au sujet de la façon dont les nouveaux clients contactent {{company}} — vous avez 2 minutes ?"},{"type":"question","text":"Comment la plupart de vos nouveaux clients vous trouvent-ils aujourd’hui ?"},{"type":"listen","text":"Uniquement le bouche-à-oreille ? Les réseaux ? Des appels pendant le travail ?","hint":"Notez leurs mots exacts."},{"type":"question","text":"Que se passe-t-il quand quelqu’un qui ne vous connaît pas vous cherche en ligne ?"},{"type":"problem","text":"Il trouve peu de choses, ou les demandes arrivent éparpillées et incomplètes."},{"type":"response","text":"C’est ce que Studio ATS prend en charge : une présence professionnelle qui inspire confiance et recueille des demandes complètes — conçue et maintenue pour vous."},{"type":"objection","text":"« J’ai déjà les réseaux sociaux. »"},{"type":"answer","text":"Les réseaux montrent votre travail. Studio ATS transforme l’intérêt en demande complète. Aujourd’hui, où les gens vous envoient-ils une demande ?"},{"type":"cta","text":"Je peux vous envoyer la page de votre secteur ? Elle explique tout, prix compris, en 3 minutes."}]}'::jsonb, array['téléphone', 'découverte', 'appel']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'en', 1, 'active', p.id, 'artisans', 'phone', null, 'Artisan — first call', 'Short call between two jobs.', '{"steps":[{"type":"opening","text":"Hello {{firstName}}, {{advisorName}} here. I looked up {{company}} as a client would — can I tell you what I noticed? Two minutes."},{"type":"question","text":"Most of your work comes through word of mouth, right?"},{"type":"listen","text":"Pride in their reputation; maybe quieter periods; missed calls on site."},{"type":"question","text":"And when a friend recommends you, what does that person find when they look you up?"},{"type":"problem","text":"Little or nothing that reflects the quality of the work — some people call someone else."},{"type":"response","text":"Studio ATS gives you a professional presence that works while you’re on site: people see your work and send you complete requests."},{"type":"objection","text":"“I don’t have time for that.”"},{"type":"answer","text":"That’s the point: the Studio ATS team builds and maintains it. You just receive the requests."},{"type":"cta","text":"I’ll text you the page for artisans — have a look tonight, and I’ll call you back Thursday?"}]}'::jsonb, array['artisan', 'phone', 'word of mouth']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'fr', 1, 'active', p.id, 'artisans', 'phone', null, 'Artisan — premier appel', 'Appel court entre deux chantiers.', '{"steps":[{"type":"opening","text":"Bonjour {{firstName}}, {{advisorName}} à l’appareil. J’ai cherché {{company}} comme le ferait un client — je peux vous dire ce que j’ai remarqué ? Deux minutes."},{"type":"question","text":"L’essentiel de votre travail vient du bouche-à-oreille, c’est bien ça ?"},{"type":"listen","text":"Fierté de leur réputation ; périodes plus calmes ; appels manqués sur les chantiers."},{"type":"question","text":"Et quand un ami vous recommande, que trouve cette personne quand elle vous cherche ?"},{"type":"problem","text":"Peu ou rien qui reflète la qualité du travail — certains appellent quelqu’un d’autre."},{"type":"response","text":"Studio ATS vous donne une présence professionnelle qui travaille pendant vos chantiers : on voit vos réalisations et on vous envoie des demandes complètes."},{"type":"objection","text":"« Je n’ai pas le temps pour ça. »"},{"type":"answer","text":"Justement : l’équipe Studio ATS le conçoit et le maintient. Vous recevez simplement les demandes."},{"type":"cta","text":"Je vous envoie par SMS la page pour les artisans — regardez ce soir, et je vous rappelle jeudi ?"}]}'::jsonb, array['artisan', 'téléphone', 'bouche-à-oreille']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'en', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'First contact — short message', null, '{"text":"Hello {{firstName}}, I came across {{company}} and liked your work. Quick question: how do most new clients reach you today? I work with Studio ATS, which helps professionals turn online interest into complete requests. Here’s a 3-minute overview for your sector: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'fr', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Premier contact — message court', null, '{"text":"Bonjour {{firstName}}, j’ai découvert {{company}} et j’ai aimé votre travail. Petite question : comment vos nouveaux clients vous contactent-ils aujourd’hui ? Je travaille avec Studio ATS, qui aide les professionnels à transformer l’intérêt en ligne en demandes complètes. Voici un aperçu de 3 minutes pour votre secteur : {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'en', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'First contact — LinkedIn', null, '{"text":"Hi {{firstName}}, I enjoy what you share about {{sector}}. When someone is interested in working with {{company}}, where do you send them? I help professionals set up Studio ATS, a space that presents their work and qualifies each request. Open to a quick look?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'fr', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Premier contact — LinkedIn', null, '{"text":"Bonjour {{firstName}}, j’apprécie ce que vous partagez sur {{sector}}. Quand quelqu’un souhaite travailler avec {{company}}, où l’envoyez-vous ? J’accompagne des professionnels sur Studio ATS, un espace qui présente leur travail et qualifie chaque demande. Partant pour un rapide coup d’œil ?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
