insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'en', 1, 'active', p.id, null, 'other', 'no_response', 'No response — last message', null, '{"text":"Hello {{firstName}}, I don’t want to bother you: I’ll stop following up. If improving how new clients reach {{company}} becomes a priority, the page stays available: {{affiliateUrl}}. Have a great week."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
