insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'fr', 1, 'active', p.id, null, 'email', 'renewal', 'Client — prise de nouvelles', null, '{"text":"Bonjour {{firstName}}, comment se passe Studio ATS pour {{company}} ? Si quelque chose peut être amélioré, dites-le-moi et je transmets à l’équipe Studio ATS."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'en', 1, 'active', p.id, null, 'email', 'first_contact', 'First contact', null, '{"subject":"{{company}} — turning online interest into requests","preview":"A quick question about how new clients reach you.","body":"Hello {{firstName}},\n\nI came across {{company}} and genuinely liked your work.\n\nQuick question: when someone discovers you online, what happens next? Many professionals receive requests through a mix of forms, social media and messages — without the details they need.\n\nStudio ATS handles that: a professional space that presents your work, qualifies each request and helps book the appointment. It is built and maintained for you.\n\nHere is a 3-minute overview for your sector:","cta":"See the overview"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'fr', 1, 'active', p.id, null, 'email', 'first_contact', 'Premier contact', null, '{"subject":"{{company}} — transformer l’intérêt en ligne en demandes","preview":"Une question rapide sur la façon dont vos nouveaux clients vous contactent.","body":"Bonjour {{firstName}},\n\nJ’ai découvert {{company}} et j’ai sincèrement apprécié votre travail.\n\nPetite question : quand quelqu’un vous découvre en ligne, que se passe-t-il ensuite ? Beaucoup de professionnels reçoivent des demandes par formulaire, réseaux et messages — sans les informations dont ils ont besoin.\n\nStudio ATS s’en charge : un espace professionnel qui présente votre travail, qualifie chaque demande et facilite la prise de rendez-vous. Il est conçu et maintenu pour vous.\n\nVoici un aperçu de 3 minutes pour votre secteur :","cta":"Voir l’aperçu"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'en', 1, 'active', p.id, null, 'email', 'follow_up', 'Follow-up after 3 days', null, '{"subject":"Re: {{company}} — turning online interest into requests","preview":"Bringing this back to the top of your inbox.","body":"Hello {{firstName}},\n\nJust bringing this back to the top of your inbox. If requests arriving without the right details sound familiar, Studio ATS is worth 3 minutes.\n\nIf it’s not a priority right now, no problem at all — tell me and I won’t follow up again.","cta":"See the page"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'fr', 1, 'active', p.id, null, 'email', 'follow_up', 'Relance après 3 jours', null, '{"subject":"Re : {{company}} — transformer l’intérêt en ligne en demandes","preview":"Je remonte mon message en haut de votre boîte.","body":"Bonjour {{firstName}},\n\nJe remonte simplement mon message. Si des demandes sans les bonnes informations vous parlent, Studio ATS vaut 3 minutes.\n\nSi ce n’est pas une priorité en ce moment, aucun problème — dites-le-moi et je ne vous relancerai plus.","cta":"Voir la page"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'en', 1, 'active', p.id, null, 'email', 'after_call', 'After the call — recap', null, '{"subject":"Our call — next steps for {{company}}","preview":"What we discussed and the next step.","body":"Hello {{firstName}},\n\nThank you for your time today. What I understood:\n• how new clients reach you today\n• what you’d like to improve\n\nEverything about Studio ATS — what’s included, how it works and the official price — is on this page:","cta":"Open my Studio ATS page"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'fr', 1, 'active', p.id, null, 'email', 'after_call', 'Après l’appel — récapitulatif', null, '{"subject":"Notre échange — prochaines étapes pour {{company}}","preview":"Ce que nous avons évoqué et la suite.","body":"Bonjour {{firstName}},\n\nMerci pour votre temps aujourd’hui. Ce que j’ai compris :\n• comment les nouveaux clients vous contactent aujourd’hui\n• ce que vous aimeriez améliorer\n\nTout sur Studio ATS — ce qui est inclus, le fonctionnement et le prix officiel — est sur cette page :","cta":"Ouvrir ma page Studio ATS"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'en', 1, 'active', p.id, null, 'email', 'proposal', 'Proposal', null, '{"subject":"The Studio ATS offer for {{company}}","preview":"Everything in one page, price included.","body":"Hello {{firstName}},\n\nAs promised, here is the full Studio ATS offer for {{company}}. You’ll find what’s included, how the set-up works, and the official price and terms.\n\nI’m available for any question.","cta":"See the offer"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'fr', 1, 'active', p.id, null, 'email', 'proposal', 'Proposition', null, '{"subject":"L’offre Studio ATS pour {{company}}","preview":"Tout sur une page, prix compris.","body":"Bonjour {{firstName}},\n\nComme promis, voici l’offre Studio ATS complète pour {{company}}. Vous y trouverez ce qui est inclus, le déroulement de la mise en place, ainsi que le prix et les conditions officiels.\n\nJe reste disponible pour toute question.","cta":"Voir l’offre"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'en', 1, 'active', p.id, null, 'email', 'objection', 'Social presence isn’t enough', null, '{"subject":"Social media shows your work. Does it bring you requests?","preview":"Why social media and Studio ATS are complementary.","body":"Hello {{firstName}},\n\nYour social media shows your work well — keep it. The question is what happens after someone is interested: a message lost among others, a request without details, a call you can’t take.\n\nStudio ATS is the place where that interest becomes a complete request, in a space you control. It complements your social profiles; it doesn’t replace them.","cta":"See how it works"}'::jsonb, array['instagram', 'facebook', 'réseaux sociaux', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'fr', 1, 'active', p.id, null, 'email', 'objection', 'Les réseaux sociaux ne suffisent pas', null, '{"subject":"Vos réseaux montrent votre travail. Vous apportent-ils des demandes ?","preview":"Pourquoi réseaux sociaux et Studio ATS sont complémentaires.","body":"Bonjour {{firstName}},\n\nVos réseaux montrent bien votre travail — gardez-les. La question est ce qui se passe après l’intérêt : un message perdu parmi d’autres, une demande sans détails, un appel que vous ne pouvez pas prendre.\n\nStudio ATS est l’endroit où cet intérêt devient une demande complète, dans un espace que vous maîtrisez. Il complète vos réseaux ; il ne les remplace pas.","cta":"Voir comment ça marche"}'::jsonb, array['instagram', 'facebook', 'réseaux sociaux', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'en', 1, 'active', p.id, null, 'email', 'no_response', 'Last follow-up', null, '{"subject":"Should I close your file?","preview":"One last message — then I stop.","body":"Hello {{firstName}},\n\nI haven’t heard back, so I’ll assume it isn’t the right time — I won’t follow up again.\n\nIf things change, the page stays available.","cta":"Keep the page"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'fr', 1, 'active', p.id, null, 'email', 'no_response', 'Dernière relance', null, '{"subject":"Je clos votre dossier ?","preview":"Un dernier message — ensuite j’arrête.","body":"Bonjour {{firstName}},\n\nSans nouvelles de votre part, je suppose que ce n’est pas le bon moment — je ne vous relancerai plus.\n\nSi les choses changent, la page reste disponible.","cta":"Garder la page"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'en', 1, 'active', p.id, null, null, 'objection', '“I already have social media.”', null, '{"objection":"“I already have social media.”","meaning":"Social media feels like enough visibility — or they don’t see what’s missing.","questions":["Where do people send you a request today?","What happens to a request that arrives on a Saturday night?"],"short":"Social media shows your work. Studio ATS turns that interest into complete requests, in a place you control.","long":"Keep your social media: it’s great for showing your work. But a DM is not a request — no budget, no timing, lost among other messages, and the platform decides who sees you. Studio ATS is the professional place where interest becomes a complete request you can answer in one go.","nextStep":"Send the sales page and ask them to compare it with their profile."}'::jsonb, array['instagram', 'facebook', 'social media', 'réseaux sociaux', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'fr', 1, 'active', p.id, null, null, 'objection', '« J’ai déjà les réseaux sociaux. »', null, '{"objection":"« J’ai déjà les réseaux sociaux. »","meaning":"Les réseaux semblent suffire pour la visibilité — ou ils ne voient pas ce qui manque.","questions":["Aujourd’hui, où vous envoie-t-on une demande ?","Que devient une demande qui arrive un samedi soir ?"],"short":"Les réseaux montrent votre travail. Studio ATS transforme cet intérêt en demandes complètes, dans un espace que vous maîtrisez.","long":"Gardez vos réseaux : ils sont parfaits pour montrer votre travail. Mais un message privé n’est pas une demande — ni budget, ni délai, perdu parmi d’autres, et c’est la plateforme qui décide qui vous voit. Studio ATS est l’espace professionnel où l’intérêt devient une demande complète, à laquelle on répond en une fois.","nextStep":"Envoyez la page commerciale et proposez-leur de la comparer à leur profil."}'::jsonb, array['instagram', 'facebook', 'social media', 'réseaux sociaux', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'en', 1, 'active', p.id, null, null, 'objection', '“My clients come through word of mouth.”', null, '{"objection":"“My clients come through word of mouth.”","meaning":"They are proud of their reputation — and don’t see the link with being online.","questions":["When a friend recommends you, what does that person do before calling?","Are there quieter periods in the year?"],"short":"Word of mouth brings people to you. Studio ATS makes sure they call you once they’ve looked you up.","long":"That’s a sign of great work. But today, even a recommended client checks online before calling. If they find little, some hesitate or call someone else. Studio ATS doesn’t replace word of mouth: it confirms it.","nextStep":"Suggest they look themselves up as a client would."}'::jsonb, array['bouche-à-oreille', 'word of mouth', 'referrals', 'recommandation']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'fr', 1, 'active', p.id, null, null, 'objection', '« Mes clients viennent par le bouche-à-oreille. »', null, '{"objection":"« Mes clients viennent par le bouche-à-oreille. »","meaning":"Ils sont fiers de leur réputation — et ne voient pas le lien avec le fait d’être en ligne.","questions":["Quand un ami vous recommande, que fait cette personne avant d’appeler ?","Y a-t-il des périodes plus calmes dans l’année ?"],"short":"Le bouche-à-oreille vous amène des gens. Studio ATS fait en sorte qu’ils vous appellent après vous avoir cherché.","long":"C’est le signe d’un excellent travail. Mais aujourd’hui, même un client recommandé vérifie en ligne avant d’appeler. S’il trouve peu de choses, il hésite ou appelle quelqu’un d’autre. Studio ATS ne remplace pas le bouche-à-oreille : il le confirme.","nextStep":"Proposez-leur de se chercher eux-mêmes comme le ferait un client."}'::jsonb, array['bouche-à-oreille', 'word of mouth', 'referrals', 'recommandation']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'en', 1, 'active', p.id, null, null, 'objection', '“I don’t need to sell online.”', null, '{"objection":"“I don’t need to sell online.”","meaning":"They think Studio ATS is an online shop.","questions":["How does a new client contact you today?","What do you need to know before giving a quote?"],"short":"Studio ATS is not an online shop: it helps people who don’t know you yet to trust you and send you a proper request.","long":"You don’t sell online — you sell through conversations and quotes. Studio ATS prepares those conversations: people see your work, understand what you do and send a request with the right details. The sale still happens with you.","nextStep":"Show the “How it works” section of the sales page."}'::jsonb, array['e-commerce', 'vendre en ligne', 'sell online', 'boutique']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je n’ai pas besoin de vendre en ligne. »', null, '{"objection":"« Je n’ai pas besoin de vendre en ligne. »","meaning":"Ils pensent que Studio ATS est une boutique en ligne.","questions":["Comment un nouveau client vous contacte-t-il aujourd’hui ?","Que devez-vous savoir avant de faire un devis ?"],"short":"Studio ATS n’est pas une boutique en ligne : il aide ceux qui ne vous connaissent pas encore à vous faire confiance et à vous envoyer une vraie demande.","long":"Vous ne vendez pas en ligne — vous vendez par la discussion et le devis. Studio ATS prépare ces discussions : on voit votre travail, on comprend ce que vous faites, et on vous envoie une demande avec les bonnes informations. La vente se fait toujours avec vous.","nextStep":"Montrez la section « Comment ça marche » de la page commerciale."}'::jsonb, array['e-commerce', 'vendre en ligne', 'sell online', 'boutique']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'en', 1, 'active', p.id, null, null, 'objection', '“I won’t have time to answer.”', null, '{"objection":"“I won’t have time to answer.”","meaning":"They fear more work or more admin.","questions":["How much time do you spend today on calls that lead nowhere?","What would help you answer faster?"],"short":"Studio ATS is built to save time: requests arrive complete, so you answer once.","long":"It’s precisely for busy people. The Studio ATS team builds and maintains everything. Requests arrive with the details you need, in one place, so you don’t spend time chasing information or returning vague calls.","nextStep":"Offer to send the page so they can look at it in the evening."}'::jsonb, array['temps', 'time', 'busy', 'occupé']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je n’aurai pas le temps de répondre. »', null, '{"objection":"« Je n’aurai pas le temps de répondre. »","meaning":"Ils craignent plus de travail ou d’administratif.","questions":["Combien de temps passez-vous aujourd’hui sur des appels qui ne mènent à rien ?","Qu’est-ce qui vous aiderait à répondre plus vite ?"],"short":"Studio ATS est fait pour gagner du temps : les demandes arrivent complètes, vous répondez en une fois.","long":"C’est justement pour les gens occupés. L’équipe Studio ATS conçoit et maintient tout. Les demandes arrivent avec les informations nécessaires, au même endroit : vous ne perdez plus de temps à courir après des informations ou à rappeler des demandes floues.","nextStep":"Proposez d’envoyer la page pour qu’ils la regardent le soir."}'::jsonb, array['temps', 'time', 'busy', 'occupé']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'en', 1, 'active', p.id, null, null, 'objection', '“It’s too expensive.”', null, '{"objection":"“It’s too expensive.”","meaning":"They compare with a cheap website, or can’t see the value yet.","questions":["What is one new client worth to you?","What are you comparing it with?"],"short":"Compare it with the value of the clients it helps you win — not with the price of a basic website.","long":"Studio ATS is not a basic website: it’s the whole path from first visit to request, built and maintained for you. Many professionals look at it this way: what is a single new client worth? The price is official and identical for everyone — you won’t get a better one elsewhere by negotiating.","nextStep":"Never discount or promise a result. Send the offer section of the page."}'::jsonb, array['prix', 'price', 'cher', 'expensive', 'budget']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'fr', 1, 'active', p.id, null, null, 'objection', '« C’est trop cher. »', null, '{"objection":"« C’est trop cher. »","meaning":"Ils comparent avec un site bon marché, ou ne voient pas encore la valeur.","questions":["Que vous rapporte un nouveau client ?","Avec quoi comparez-vous ?"],"short":"Comparez-le à la valeur des clients qu’il aide à obtenir — pas au prix d’un site basique.","long":"Studio ATS n’est pas un site basique : c’est tout le parcours de la visite à la demande, conçu et maintenu pour vous. Beaucoup de professionnels raisonnent ainsi : que vaut un seul nouveau client ? Le prix est officiel et identique pour tous — il ne se négocie pas.","nextStep":"Ne faites jamais de remise ni de promesse de résultat. Envoyez la section offre de la page."}'::jsonb, array['prix', 'price', 'cher', 'expensive', 'budget']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'en', 1, 'active', p.id, null, null, 'objection', '“I already have a website.”', null, '{"objection":"“I already have a website.”","meaning":"They think it does the same job.","questions":["How many requests does it bring you each month?","What happens after someone fills in your form?"],"short":"Keep it if it works. Studio ATS is about what a site rarely does: qualify requests and help book appointments.","long":"A website presents; Studio ATS converts. The question is not whether you have a site, but whether it turns visitors into complete requests and appointments. If yours already does, great. If not, that’s exactly the part Studio ATS handles.","nextStep":"Ask to look at their current request form together."}'::jsonb, array['site', 'website', 'déjà un site', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'fr', 1, 'active', p.id, null, null, 'objection', '« J’ai déjà un site. »', null, '{"objection":"« J’ai déjà un site. »","meaning":"Ils pensent qu’il fait le même travail.","questions":["Combien de demandes vous apporte-t-il chaque mois ?","Que se passe-t-il après qu’on remplit votre formulaire ?"],"short":"Gardez-le s’il fonctionne. Studio ATS porte sur ce qu’un site fait rarement : qualifier les demandes et faciliter les rendez-vous.","long":"Un site présente ; Studio ATS convertit. La question n’est pas d’avoir un site, mais s’il transforme les visiteurs en demandes complètes et en rendez-vous. Si le vôtre le fait déjà, parfait. Sinon, c’est exactement la partie dont Studio ATS s’occupe.","nextStep":"Proposez de regarder ensemble leur formulaire de contact actuel."}'::jsonb, array['site', 'website', 'déjà un site', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'en', 1, 'active', p.id, null, null, 'objection', '“I need to think about it.”', null, '{"objection":"“I need to think about it.”","meaning":"Something is unclear, or it’s not the right moment.","questions":["What would you need to know to decide?","Is it the timing, the budget or something else?"],"short":"Of course. What’s the one thing you’d need clarified to decide?","long":"Taking time is normal. Usually one question remains — price, timing, or how it would work for them. Ask which one, answer it precisely, then agree on a date to talk again.","nextStep":"Agree on a follow-up date and log it in your CRM."}'::jsonb, array['réfléchir', 'think', 'plus tard', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je dois réfléchir. »', null, '{"objection":"« Je dois réfléchir. »","meaning":"Quelque chose n’est pas clair, ou ce n’est pas le bon moment.","questions":["Que vous faudrait-il savoir pour décider ?","C’est le moment, le budget, ou autre chose ?"],"short":"Bien sûr. Quelle est la chose qu’il faudrait clarifier pour décider ?","long":"Prendre le temps est normal. En général, une question reste en suspens — prix, calendrier, ou fonctionnement pour eux. Demandez laquelle, répondez précisément, puis convenez d’une date pour en reparler.","nextStep":"Convenez d’une date de relance et notez-la dans votre CRM."}'::jsonb, array['réfléchir', 'think', 'plus tard', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'en', 1, 'active', p.id, null, null, 'objection', '“Not now.”', null, '{"objection":"“Not now.”","meaning":"Busy season, or other priorities.","questions":["When would be a better time?","What’s your quieter period?"],"short":"Understood — when would it make sense to talk again?","long":"Respect it and plan: the best moment to set up Studio ATS is often just before a busy period, so it works when requests come in. Ask when to come back and note it.","nextStep":"Set a reminder in the CRM — never insist."}'::jsonb, array['pas maintenant', 'not now', 'timing', 'saison']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'fr', 1, 'active', p.id, null, null, 'objection', '« Pas maintenant. »', null, '{"objection":"« Pas maintenant. »","meaning":"Période chargée, ou autres priorités.","questions":["Quel serait un meilleur moment ?","Quelle est votre période plus calme ?"],"short":"Entendu — quand serait-il pertinent d’en reparler ?","long":"Respectez-le et planifiez : le meilleur moment pour mettre en place Studio ATS est souvent juste avant une période chargée, pour qu’il fonctionne quand les demandes arrivent. Demandez quand revenir vers eux et notez-le.","nextStep":"Programmez un rappel dans le CRM — sans jamais insister."}'::jsonb, array['pas maintenant', 'not now', 'timing', 'saison']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'en', 1, 'active', p.id, null, null, null, 'What it is', null, '{"section":"what_it_is","items":[{"title":"An online commercial studio","body":"Studio ATS is an online commercial studio for professionals whose every new client has real value: it presents their work, qualifies requests and helps book appointments — in one place."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'fr', 1, 'active', p.id, null, null, null, 'Ce que c’est', null, '{"section":"what_it_is","items":[{"title":"Un studio commercial en ligne","body":"Studio ATS est un studio commercial en ligne pour les professionnels dont chaque nouveau client compte : il présente leur travail, qualifie les demandes et facilite la prise de rendez-vous — au même endroit."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'en', 1, 'active', p.id, null, null, null, 'What it does', null, '{"section":"what_it_does","items":[{"title":"From first visit to booked appointment","body":"The site is only one part. Studio ATS covers the whole path: showcase, request, qualification, appointment, follow-up."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'fr', 1, 'active', p.id, null, null, null, 'Ce que ça fait', null, '{"section":"what_it_does","items":[{"title":"De la première visite au rendez-vous","body":"Le site n’est qu’une partie. Studio ATS couvre tout le parcours : vitrine, demande, qualification, rendez-vous, relance."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
