insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'en', 1, 'active', p.id, null, null, null, 'Your first week', 'A recommended action plan — not a promise of results.', '{"disclaimer":"A recommended plan to build a routine. Results depend on your work, your market and your prospects; nothing here is a promise of sales or income.","days":[{"day":1,"title":"Understand Studio ATS","body":"Read Product knowledge and one playbook.","tasks":["Read what Studio ATS is and what’s included","Open the playbook for your target"]},{"day":2,"title":"Choose 20 prospects","body":"Pick one target and list 20 real businesses near you.","tasks":["Choose your target","Add 20 prospects to your CRM"]},{"day":3,"title":"Contact your first prospects","body":"Send your first personalised messages.","tasks":["Send 5 first-contact messages","Create your sales page for the target"]},{"day":4,"title":"Follow up","body":"Follow up with those who haven’t answered — once, briefly.","tasks":["Send follow-ups","Move replies to “Replied”"]},{"day":5,"title":"Run calls","body":"Use the call script with those who replied.","tasks":["Run at least one discovery call","Log the next step for each call"]},{"day":6,"title":"Send relevant sales pages","body":"Send your page to qualified prospects.","tasks":["Send your sales page after each call","Check that the page looks right on mobile"]},{"day":7,"title":"Review","body":"Look at what worked: which message, which target, which channel.","tasks":["Review your page and link performance","Plan next week"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'fr', 1, 'active', p.id, null, null, null, 'Votre première semaine', 'Un plan d’action recommandé — pas une promesse de résultats.', '{"disclaimer":"Un plan recommandé pour prendre un rythme. Les résultats dépendent de votre travail, de votre marché et de vos prospects ; rien ici n’est une promesse de ventes ou de revenus.","days":[{"day":1,"title":"Comprendre Studio ATS","body":"Lisez la fiche produit et un playbook.","tasks":["Lire ce qu’est Studio ATS et ce qui est inclus","Ouvrir le playbook de votre cible"]},{"day":2,"title":"Choisir 20 prospects","body":"Choisissez une cible et listez 20 vraies entreprises près de chez vous.","tasks":["Choisir votre cible","Ajouter 20 prospects au CRM"]},{"day":3,"title":"Contacter vos premiers prospects","body":"Envoyez vos premiers messages personnalisés.","tasks":["Envoyer 5 messages de premier contact","Créer votre page commerciale pour la cible"]},{"day":4,"title":"Relancer","body":"Relancez ceux qui n’ont pas répondu — une fois, brièvement.","tasks":["Envoyer les relances","Passer les réponses en « A répondu »"]},{"day":5,"title":"Faire des appels","body":"Utilisez le script d’appel avec ceux qui ont répondu.","tasks":["Mener au moins un appel découverte","Noter la prochaine étape de chaque appel"]},{"day":6,"title":"Envoyer les pages commerciales","body":"Envoyez votre page aux prospects qualifiés.","tasks":["Envoyer votre page après chaque appel","Vérifier l’affichage de la page sur mobile"]},{"day":7,"title":"Faire le point","body":"Regardez ce qui a marché : quel message, quelle cible, quel canal.","tasks":["Consulter les performances de votre page et de vos liens","Planifier la semaine suivante"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'de', 1, 'active', p.id, null, null, null, 'Studio ATS — Standard-Verkaufsseite', 'Standardstruktur jeder Partner-Verkaufsseite.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Verwandeln Sie Ihren Traffic in Chancen.","heroSubtitle":"Ein Online-Vertriebsstudio für Fachleute, bei denen jeder neue Kunde echten Wert hat. Präsentieren Sie Ihre Arbeit, qualifizieren Sie Anfragen und vereinbaren Sie Termine — an einem Ort.","problemTitle":"Großartige Arbeit. Verlorene Anfragen.","problemBody":"Anfragen kommen über Kontaktformular, soziale Netzwerke, Nachrichten und E-Mail. Niemand weiß, welche ernst gemeint sind, das Nachfassen wird vergessen, und gute Interessenten springen ab.","solutionTitle":"Mehr als eine Website.","solutionBody":"Die Website ist nur ein Teil. Studio ATS ist der gesamte Weg vom ersten Besuch bis zum gebuchten Termin — für Sie konzipiert, eingerichtet und gewartet.","valueTitle":"Was Sie wirklich bekommen","valueItems":["Eine Präsenz, die auf den ersten Blick Vertrauen schafft","Anfragen, die mit den richtigen Informationen ankommen","Jeder Kontakt und jede Anfrage an einem Ort","Nachfassaktionen, die pünktlich rausgehen"],"howTitle":"So funktioniert es","howSteps":[{"title":"Anfrage","body":"Erzählen Sie uns in einem kurzen Formular von Ihrem Unternehmen."},{"title":"Gespräch","body":"Wir klären gemeinsam Ihren Bedarf."},{"title":"Aufbau","body":"Wir gestalten und konfigurieren Ihr Studio ATS."},{"title":"Start","body":"Sie erhalten strukturierte Anfragen."}],"benefitsTitle":"Warum das für Ihr Geschäft zählt","benefits":[{"title":"Vertrauen","body":"Interessenten prüfen Sie online, bevor sie anrufen. Machen Sie diesen ersten Eindruck zählen."},{"title":"Zeit","body":"Kennen Sie Budget, Zeitrahmen und Projektart, bevor Sie zum Telefon greifen."},{"title":"Nichts zu verwalten","body":"Vom Studio ATS-Team gebaut, gehostet und gewartet."}],"includedTitle":"Was enthalten ist","whoTitle":"Für wen","whoBody":"Fachleute und Unternehmen, deren Kunden viel wert sind, mit einem visuellen oder Premium-Angebot und eingehenden Anfragen, die konvertiert werden wollen.","faqTitle":"Fragen, die Sie vielleicht haben","offerTitle":"Ein Angebot. Alles inklusive.","offerNote":"Preis zzgl. MwSt., sofern zutreffend. Endgültige Bedingungen im Vertrag.","ctaTitle":"Bereit, über Ihr Geschäft zu sprechen?","ctaBody":"Hinterlassen Sie Ihre Daten — unverbindlich. Wir melden uns, um Ihren Bedarf zu verstehen."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'de', 1, 'active', p.id, 'artisans', null, null, 'Variante Handwerker', null, '{"template":"studio-default","heroTitle":"Ihre Arbeit ist ausgezeichnet. Ihre Online-Präsenz sollte es auch sein.","heroSubtitle":"Interessenten suchen Sie online, bevor sie anrufen. Studio ATS gibt Ihrem Betrieb eine professionelle Präsenz und sammelt vollständige Anfragen — sogar während Sie auf der Baustelle sind.","problemTitle":"Mundpropaganda reicht nicht mehr.","problemBody":"Wer Sie noch nicht kennt, prüft Sie zuerst online. Findet er wenig, ruft er jemand anderen an — und die Anfragen, die ankommen, sind verstreut und unvollständig.","ctaTitle":"Schauen wir uns Ihren Betrieb gemeinsam an","ctaBody":"Hinterlassen Sie Ihre Daten und beschreiben Sie Ihr Handwerk in einer Zeile. Unverbindlich."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'de', 1, 'active', p.id, null, null, null, 'Mehr qualifizierte Anfragen erhalten', null, '{"promise":"Anfragen, die mit Budget, Zeitrahmen und Details ankommen.","heroTitle":"Erhalten Sie Anfragen, auf die Sie wirklich antworten können.","heroSubtitle":"Studio ATS stellt vor dem ersten Gespräch die richtigen Fragen, sodass jede Anfrage mit den Informationen ankommt, die Sie brauchen."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'de', 1, 'active', p.id, null, null, null, 'Online so professionell wirken, wie Sie sind', null, '{"promise":"Eine Präsenz, die der Qualität der Arbeit entspricht.","heroTitle":"Wirken Sie online so professionell wie im echten Leben.","heroSubtitle":"Interessenten prüfen Sie, bevor sie anrufen. Geben Sie ihnen eine Präsenz, die in Sekunden Vertrauen schafft."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'de', 1, 'active', p.id, null, null, null, 'Keine Anfragen mehr verlieren', null, '{"promise":"Jede Anfrage erfasst und zentralisiert, auch wenn Sie beschäftigt sind.","heroTitle":"Verlieren Sie keine Anfragen mehr, während Sie arbeiten.","heroSubtitle":"Jede Anfrage landet mit den richtigen Details an einem Ort — und das Nachfassen geht pünktlich raus."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'de', 1, 'active', p.id, null, null, null, 'Studio ATS verkaufen — die Methode', 'Die 10 Schritte eines Studio ATS-Verkaufs, für jede Zielgruppe. Öffnen Sie eine Zielgruppe, um ihre Probleme und ihren Ansatz einzubinden.', '{"intro":"Verkaufen Sie das Ergebnis, nicht die Technik. Ihre Aufgabe: die Situation verstehen, zeigen, was heute verloren geht, und die richtige Seite senden.","steps":[{"key":"understand","title":"Sie verstehen","body":"Schauen Sie sich vor dem Kontakt an, wie sie sich heute online präsentieren und wie ein neuer Kunde sie erreichen kann.","bullets":["Website, soziale Profile und Bewertungen prüfen","Notieren Sie eine konkrete Sache, die Ihnen an ihrer Arbeit gefällt"]},{"key":"opening","title":"Einstieg","body":"Beginnen Sie mit ihnen, nicht mit Studio ATS. Eine ehrliche Bemerkung, eine Frage.","bullets":["„Ich bin auf Ihre Arbeit gestoßen auf …“","„Kurze Frage: Wie finden die meisten neuen Kunden zu Ihnen?“"]},{"key":"discovery","title":"Bedarfsanalyse","body":"Fragen Sie, dann hören Sie zu. Lassen Sie sie beschreiben, wie Anfragen ankommen und was danach passiert.","bullets":["Wie kontaktieren neue Kunden Sie heute?","Welche Information fehlt meistens?","Was passiert, wenn Sie nicht sofort antworten können?"]},{"key":"pain","title":"Das Problem erkennen","body":"Benennen Sie das Problem mit ihren Worten. Erfinden Sie keines, das sie nicht haben."},{"key":"present","title":"Studio ATS vorstellen","body":"Verbinden Sie Studio ATS mit dem Problem, das sie gerade beschrieben haben — ein Satz, keine Funktionsliste.","bullets":["„Genau das übernimmt Studio ATS: …“"]},{"key":"value","title":"Den Nutzen zeigen","body":"Sprechen Sie über Ergebnisse: Vertrauen, vollständige Anfragen, gesparte Zeit, nichts zu verwalten. Versprechen Sie nie Zahlen."},{"key":"objections","title":"Einwände behandeln","body":"Ein Einwand ist eine verkleidete Frage. Fragen Sie nach, was dahintersteckt, bevor Sie antworten."},{"key":"offer","title":"Das Angebot senden","body":"Senden Sie Ihre Verkaufsseite für ihre Branche: Sie erklärt alles, und der Preis kommt von Studio ATS."},{"key":"follow_up","title":"Nachfassen","body":"Nach ein paar Tagen keine Antwort? Eine kurze, nützliche Nachricht — dann respektieren Sie die Antwort."},{"key":"close","title":"Abschließen","body":"Vereinbaren Sie einen klaren nächsten Schritt: ein Gespräch, eine Anfrage auf der Seite oder den Online-Kauf."}]}'::jsonb, array['Methode', 'Bedarfsanalyse', 'Abschluss']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'de', 1, 'active', p.id, 'artisans', null, null, 'Studio ATS an einen Handwerker verkaufen', 'Telefon zuerst, kurz, konkret. Handwerker sind beschäftigt: Respektieren Sie ihre Zeit.', '{"intro":"Handwerker kaufen bei Menschen, die ihr Handwerk verstehen. Sprechen Sie über ihre Kunden und ihre Zeit — nie über „Websites“.","steps":[{"key":"understand","title":"Sie verstehen","body":"Sie sind den Großteil des Tages auf der Baustelle, bekommen Aufträge über Mundpropaganda und nehmen Anrufe zwischen zwei Einsätzen an. Ihr Ruf ist ihr wichtigstes Kapital.","bullets":["Suchen Sie sie wie ein Kunde: Was finden Sie?","Notieren Sie Gewerk, Region und die gezeigten Arbeiten"]},{"key":"opening","title":"Einstieg","body":"Rufen Sie früh morgens oder am Feierabend an. Seien Sie kurz und konkret.","bullets":["„Ich habe Sie gesucht wie ein Kunde — darf ich Ihnen sagen, was mir aufgefallen ist? Dauert 2 Minuten.“"]},{"key":"discovery","title":"Bedarfsanalyse","body":"Drei Fragen reichen.","bullets":["Wie finden die meisten neuen Kunden zu Ihnen?","Was passiert, wenn jemand, der Sie nicht kennt, Sie sucht?","Wie viele Anrufe verpassen Sie während eines Einsatzes?"]},{"key":"pain","title":"Das Problem erkennen","body":"Meistens: Mundpropaganda hat Grenzen, der Betrieb wirkt online weniger professionell als in der Realität, Anfragen gehen verloren."},{"key":"present","title":"Studio ATS vorstellen","body":"„Studio ATS gibt Ihrem Betrieb eine professionelle Präsenz, die arbeitet, während Sie auf der Baustelle sind: Man sieht Ihre Arbeiten und schickt Ihnen vollständige Anfragen — Arbeiten, Ort, Zeitrahmen.“"},{"key":"value","title":"Den Nutzen zeigen","body":"Vertrauen bei Menschen, die Sie noch nicht kennen. Anfragen, die Sie in einem Zug beantworten. Nichts selbst zu verwalten."},{"key":"objections","title":"Einwände behandeln","body":"Rechnen Sie mit: „Ich habe schon soziale Netzwerke“, „meine Kunden kommen über Mundpropaganda“, „ich habe keine Zeit“."},{"key":"offer","title":"Das Angebot senden","body":"Senden Sie Ihre Handwerker-Verkaufsseite direkt nach dem Gespräch per SMS oder WhatsApp, solange alles frisch ist."},{"key":"follow_up","title":"Nachfassen","body":"Zwei bis drei Tage später eine kurze Nachricht: „Hatten Sie Zeit, reinzuschauen? Kann ich eine Frage beantworten?“"},{"key":"close","title":"Abschließen","body":"Schlagen Sie den nächsten Schritt vor: eine Anfrage auf der Seite, ein Gespräch mit dem Studio ATS-Team oder den Online-Kauf, sobald verfügbar."}]}'::jsonb, array['Handwerker', 'Telefon', 'Mundpropaganda', 'soziale Netzwerke']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'de', 1, 'active', p.id, null, 'phone', null, 'Bedarfsgespräch (jede Zielgruppe)', '5 Minuten, um zu verstehen, zu qualifizieren und einen nächsten Schritt zu vereinbaren.', '{"intro":"Haken Sie jeden Schritt ab. Sprechen Sie weniger als Ihr Gegenüber.","steps":[{"type":"opening","text":"Hallo {{firstName}}, hier ist {{advisorName}}. Ich rufe an, weil es darum geht, wie neue Kunden {{company}} erreichen — haben Sie 2 Minuten?"},{"type":"question","text":"Wie finden die meisten Ihrer neuen Kunden heute zu Ihnen?"},{"type":"listen","text":"Nur Mundpropaganda? Soziale Netzwerke? Anfragen per Telefon während der Arbeit?","hint":"Notieren Sie ihre genauen Worte."},{"type":"question","text":"Was passiert, wenn jemand, der Sie nicht kennt, Sie online sucht?"},{"type":"problem","text":"Er findet wenig, oder Anfragen kommen verstreut und unvollständig an."},{"type":"response","text":"Genau das übernimmt Studio ATS: eine professionelle Präsenz, die Vertrauen schafft und vollständige Anfragen sammelt — für Sie gebaut und gewartet."},{"type":"objection","text":"„Ich habe schon soziale Netzwerke.“"},{"type":"answer","text":"Soziale Netzwerke zeigen Ihre Arbeit. Studio ATS macht aus dem Interesse eine vollständige Anfrage. Wohin schicken Ihnen die Leute heute eine Anfrage?"},{"type":"cta","text":"Darf ich Ihnen die Seite für Ihre Branche schicken? Sie erklärt alles, inklusive Preis, in 3 Minuten."}]}'::jsonb, array['Telefon', 'Bedarfsanalyse', 'Gespräch']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'de', 1, 'active', p.id, 'artisans', 'phone', null, 'Handwerker — erstes Gespräch', 'Kurzes Gespräch zwischen zwei Einsätzen.', '{"steps":[{"type":"opening","text":"Hallo {{firstName}}, hier ist {{advisorName}}. Ich habe {{company}} gesucht wie ein Kunde — darf ich Ihnen sagen, was mir aufgefallen ist? Zwei Minuten."},{"type":"question","text":"Der Großteil Ihrer Aufträge kommt über Mundpropaganda, richtig?"},{"type":"listen","text":"Stolz auf ihren Ruf; vielleicht ruhigere Phasen; verpasste Anrufe auf der Baustelle."},{"type":"question","text":"Und wenn ein Freund Sie empfiehlt — was findet diese Person, wenn sie Sie sucht?"},{"type":"problem","text":"Wenig oder nichts, das die Qualität der Arbeit zeigt — manche rufen dann jemand anderen an."},{"type":"response","text":"Studio ATS gibt Ihnen eine professionelle Präsenz, die arbeitet, während Sie auf der Baustelle sind: Man sieht Ihre Arbeiten und schickt Ihnen vollständige Anfragen."},{"type":"objection","text":"„Dafür habe ich keine Zeit.“"},{"type":"answer","text":"Genau darum geht es: Das Studio ATS-Team baut und wartet alles. Sie erhalten einfach die Anfragen."},{"type":"cta","text":"Ich schicke Ihnen die Seite für Handwerker per SMS — schauen Sie heute Abend rein, und ich rufe Sie Donnerstag zurück?"}]}'::jsonb, array['Handwerker', 'Telefon', 'Mundpropaganda']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'de', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Erstkontakt — kurze Nachricht', null, '{"text":"Hallo {{firstName}}, ich bin auf {{company}} gestoßen und Ihre Arbeit gefällt mir. Kurze Frage: Wie erreichen Sie neue Kunden heute meistens? Ich arbeite mit Studio ATS, das Fachleuten hilft, Online-Interesse in vollständige Anfragen zu verwandeln. Hier ist ein 3-Minuten-Überblick für Ihre Branche: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'de', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Erstkontakt — LinkedIn', null, '{"text":"Hallo {{firstName}}, ich lese gern, was Sie über {{sector}} teilen. Wenn jemand mit {{company}} zusammenarbeiten möchte — wohin schicken Sie ihn? Ich begleite Fachleute bei Studio ATS, einem Bereich, der ihre Arbeit präsentiert und jede Anfrage qualifiziert. Offen für einen kurzen Blick?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-sms-artisan', 'de', 1, 'active', p.id, 'artisans', 'sms', 'first_contact', 'Handwerker — erste SMS nach einem Anruf', null, '{"text":"Hallo {{firstName}}, danke für das Gespräch. Wie versprochen die Seite für Handwerker (3 Min.): {{affiliateUrl}} — {{advisorName}}"}'::jsonb, array[]::text[], 32, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-short', 'de', 1, 'active', p.id, null, 'whatsapp', 'follow_up', 'Nachfassen — 3 Tage später', null, '{"text":"Hallo {{firstName}}, hatten Sie Gelegenheit, sich die Seite anzusehen, die ich Ihnen geschickt habe? Ich beantworte gern jede Frage in 5 Minuten. {{affiliateUrl}}"}'::jsonb, array[]::text[], 33, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'de', 1, 'active', p.id, null, 'in_person', 'follow_up', 'Nach einem persönlichen Treffen', null, '{"text":"Hallo {{firstName}}, schön, Sie heute kennengelernt zu haben. Wie besprochen hier die Studio ATS-Seite für Ihr Geschäft: {{affiliateUrl}}. Sagen Sie mir, wann Ihnen ein kurzes Gespräch passt. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'de', 1, 'active', p.id, null, 'other', 'no_response', 'Keine Antwort — letzte Nachricht', null, '{"text":"Hallo {{firstName}}, ich möchte Sie nicht stören: Ich melde mich nicht mehr. Falls es Priorität wird, wie neue Kunden {{company}} erreichen, bleibt die Seite verfügbar: {{affiliateUrl}}. Eine schöne Woche."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'de', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'Nach dem Gespräch — Zusammenfassung', null, '{"text":"Danke für Ihre Zeit, {{firstName}}. Kurz zusammengefasst: Sie möchten Anfragen, die vollständig ankommen, und eine Präsenz, die {{company}} widerspiegelt. Alles ist hier erklärt, inklusive Preis: {{affiliateUrl}}. Nächster Schritt wie vereinbart: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'de', 1, 'active', p.id, null, 'other', 'interested', 'Interessiert — nächsten Schritt vereinbaren', null, '{"text":"Super, {{firstName}}! Der einfachste nächste Schritt: Hinterlassen Sie Ihre Anfrage auf dieser Seite, damit das Studio ATS-Team das Gespräch vorbereiten kann: {{affiliateUrl}}. Welcher Tag passt Ihnen?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'proposal-send-page', 'de', 1, 'active', p.id, null, 'other', 'proposal', 'Angebot — das Angebot senden', null, '{"text":"Hallo {{firstName}}, wie versprochen hier das vollständige Studio ATS-Angebot für {{company}}: was enthalten ist, wie es funktioniert und der offizielle Preis. {{affiliateUrl}}"}'::jsonb, array[]::text[], 38, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'de', 1, 'active', p.id, null, 'other', 'objection', 'Einwand — „Ich habe schon soziale Netzwerke“', null, '{"text":"Ich verstehe, {{firstName}} — Ihre sozialen Netzwerke zeigen Ihre Arbeit gut. Studio ATS ersetzt sie nicht: Es verwandelt dieses Interesse in vollständige Anfragen, an einem Ort, den Sie kontrollieren. Wohin schicken Ihnen die Leute heute eine Anfrage?"}'::jsonb, array['instagram', 'facebook', 'soziale Netzwerke', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'closing-checkout', 'de', 1, 'active', p.id, null, 'other', 'closing', 'Abschluss — Nachfrage nach begonnenem Kauf', null, '{"text":"Hallo {{firstName}}, ich habe gesehen, dass Sie sich Studio ATS angeschaut haben. Haben Sie noch eine Frage, bevor Sie sich entscheiden? Ich bin da, wenn Sie darüber sprechen möchten."}'::jsonb, array[]::text[], 40, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'de', 1, 'active', p.id, null, 'email', 'renewal', 'Kunde — freundliche Nachfrage', null, '{"text":"Hallo {{firstName}}, wie läuft Studio ATS bisher für {{company}}? Wenn sich etwas verbessern lässt, sagen Sie es mir, und ich gebe es an das Studio ATS-Team weiter."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'de', 1, 'active', p.id, null, 'email', 'first_contact', 'Erstkontakt', null, '{"subject":"{{company}} — Online-Interesse in Anfragen verwandeln","preview":"Eine kurze Frage dazu, wie neue Kunden Sie erreichen.","body":"Hallo {{firstName}},\n\nich bin auf {{company}} gestoßen und Ihre Arbeit gefällt mir wirklich.\n\nKurze Frage: Wenn jemand Sie online entdeckt — was passiert dann? Viele Fachleute erhalten Anfragen über eine Mischung aus Formularen, sozialen Netzwerken und Nachrichten — ohne die Details, die sie brauchen.\n\nStudio ATS übernimmt genau das: ein professioneller Bereich, der Ihre Arbeit präsentiert, jede Anfrage qualifiziert und bei der Terminbuchung hilft. Er wird für Sie gebaut und gewartet.\n\nHier ist ein 3-Minuten-Überblick für Ihre Branche:","cta":"Überblick ansehen"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'de', 1, 'active', p.id, null, 'email', 'follow_up', 'Nachfassen nach 3 Tagen', null, '{"subject":"Re: {{company}} — Online-Interesse in Anfragen verwandeln","preview":"Ich hole meine Nachricht wieder nach oben.","body":"Hallo {{firstName}},\n\nich hole meine Nachricht nur kurz wieder nach oben. Wenn Ihnen Anfragen ohne die richtigen Details bekannt vorkommen, ist Studio ATS 3 Minuten wert.\n\nWenn es gerade keine Priorität ist, kein Problem — sagen Sie es mir, und ich melde mich nicht mehr.","cta":"Seite ansehen"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'de', 1, 'active', p.id, null, 'email', 'after_call', 'Nach dem Gespräch — Zusammenfassung', null, '{"subject":"Unser Gespräch — nächste Schritte für {{company}}","preview":"Was wir besprochen haben und der nächste Schritt.","body":"Hallo {{firstName}},\n\nvielen Dank für Ihre Zeit heute. Was ich verstanden habe:\n• wie neue Kunden Sie heute erreichen\n• was Sie verbessern möchten\n\nAlles zu Studio ATS — was enthalten ist, wie es funktioniert und der offizielle Preis — steht auf dieser Seite:","cta":"Meine Studio ATS-Seite öffnen"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'de', 1, 'active', p.id, null, 'email', 'proposal', 'Angebot', null, '{"subject":"Das Studio ATS-Angebot für {{company}}","preview":"Alles auf einer Seite, inklusive Preis.","body":"Hallo {{firstName}},\n\nwie versprochen hier das vollständige Studio ATS-Angebot für {{company}}. Sie finden dort, was enthalten ist, wie die Einrichtung abläuft sowie den offiziellen Preis und die Bedingungen.\n\nFür Fragen stehe ich gern zur Verfügung.","cta":"Angebot ansehen"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'de', 1, 'active', p.id, null, 'email', 'objection', 'Soziale Netzwerke reichen nicht', null, '{"subject":"Soziale Netzwerke zeigen Ihre Arbeit. Bringen sie Ihnen Anfragen?","preview":"Warum soziale Netzwerke und Studio ATS sich ergänzen.","body":"Hallo {{firstName}},\n\nIhre sozialen Netzwerke zeigen Ihre Arbeit gut — behalten Sie sie. Die Frage ist, was nach dem Interesse passiert: eine Nachricht, die zwischen anderen untergeht, eine Anfrage ohne Details, ein Anruf, den Sie nicht annehmen können.\n\nStudio ATS ist der Ort, an dem dieses Interesse zu einer vollständigen Anfrage wird, in einem Bereich, den Sie kontrollieren. Es ergänzt Ihre Profile; es ersetzt sie nicht.","cta":"So funktioniert es"}'::jsonb, array['instagram', 'facebook', 'soziale Netzwerke', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'de', 1, 'active', p.id, null, 'email', 'no_response', 'Letztes Nachfassen', null, '{"subject":"Soll ich Ihre Akte schließen?","preview":"Eine letzte Nachricht — dann höre ich auf.","body":"Hallo {{firstName}},\n\nda ich nichts von Ihnen gehört habe, gehe ich davon aus, dass es nicht der richtige Zeitpunkt ist — ich melde mich nicht mehr.\n\nWenn sich etwas ändert, bleibt die Seite verfügbar.","cta":"Seite behalten"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'de', 1, 'active', p.id, null, null, 'objection', '„Ich habe schon soziale Netzwerke.“', null, '{"objection":"„Ich habe schon soziale Netzwerke.“","meaning":"Soziale Netzwerke wirken als genug Sichtbarkeit — oder sie sehen nicht, was fehlt.","questions":["Wohin schicken Ihnen die Leute heute eine Anfrage?","Was passiert mit einer Anfrage, die an einem Samstagabend ankommt?"],"short":"Soziale Netzwerke zeigen Ihre Arbeit. Studio ATS verwandelt dieses Interesse in vollständige Anfragen, an einem Ort, den Sie kontrollieren.","long":"Behalten Sie Ihre sozialen Netzwerke: Sie sind ideal, um Ihre Arbeit zu zeigen. Aber eine Direktnachricht ist keine Anfrage — kein Budget, kein Zeitrahmen, untergegangen zwischen anderen Nachrichten, und die Plattform entscheidet, wer Sie sieht. Studio ATS ist der professionelle Ort, an dem Interesse zu einer vollständigen Anfrage wird, die Sie in einem Zug beantworten können.","nextStep":"Senden Sie die Verkaufsseite und bitten Sie, sie mit dem eigenen Profil zu vergleichen."}'::jsonb, array['instagram', 'facebook', 'soziale Netzwerke', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'de', 1, 'active', p.id, null, null, 'objection', '„Meine Kunden kommen über Mundpropaganda.“', null, '{"objection":"„Meine Kunden kommen über Mundpropaganda.“","meaning":"Sie sind stolz auf ihren Ruf — und sehen keinen Zusammenhang mit der Online-Präsenz.","questions":["Wenn ein Freund Sie empfiehlt — was macht diese Person, bevor sie anruft?","Gibt es ruhigere Phasen im Jahr?"],"short":"Mundpropaganda bringt Menschen zu Ihnen. Studio ATS sorgt dafür, dass sie anrufen, nachdem sie Sie gesucht haben.","long":"Das ist ein Zeichen großartiger Arbeit. Aber heute prüft selbst ein empfohlener Kunde online, bevor er anruft. Findet er wenig, zögern manche oder rufen jemand anderen an. Studio ATS ersetzt Mundpropaganda nicht: Es bestätigt sie.","nextStep":"Schlagen Sie vor, dass sie sich selbst suchen, wie es ein Kunde tun würde."}'::jsonb, array['Mundpropaganda', 'word of mouth', 'Empfehlungen', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'de', 1, 'active', p.id, null, null, 'objection', '„Ich muss nicht online verkaufen.“', null, '{"objection":"„Ich muss nicht online verkaufen.“","meaning":"Sie halten Studio ATS für einen Onlineshop.","questions":["Wie kontaktiert Sie ein neuer Kunde heute?","Was müssen Sie wissen, bevor Sie ein Angebot machen?"],"short":"Studio ATS ist kein Onlineshop: Es hilft Menschen, die Sie noch nicht kennen, Ihnen zu vertrauen und eine richtige Anfrage zu senden.","long":"Sie verkaufen nicht online — Sie verkaufen über Gespräche und Angebote. Studio ATS bereitet diese Gespräche vor: Man sieht Ihre Arbeit, versteht, was Sie tun, und schickt eine Anfrage mit den richtigen Details. Der Verkauf findet weiterhin mit Ihnen statt.","nextStep":"Zeigen Sie den Abschnitt „So funktioniert es“ der Verkaufsseite."}'::jsonb, array['E-Commerce', 'online verkaufen', 'sell online', 'Shop']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'de', 1, 'active', p.id, null, null, 'objection', '„Ich habe keine Zeit zu antworten.“', null, '{"objection":"„Ich habe keine Zeit zu antworten.“","meaning":"Sie befürchten mehr Arbeit oder mehr Verwaltung.","questions":["Wie viel Zeit verbringen Sie heute mit Anrufen, die zu nichts führen?","Was würde Ihnen helfen, schneller zu antworten?"],"short":"Studio ATS ist dafür gemacht, Zeit zu sparen: Anfragen kommen vollständig an, also antworten Sie einmal.","long":"Es ist genau für beschäftigte Menschen gedacht. Das Studio ATS-Team baut und wartet alles. Anfragen kommen mit den nötigen Details an einem Ort an, sodass Sie keine Zeit damit verlieren, Informationen hinterherzulaufen oder vage Anrufe zurückzurufen.","nextStep":"Bieten Sie an, die Seite zu senden, damit sie sie abends ansehen können."}'::jsonb, array['Zeit', 'time', 'beschäftigt', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'de', 1, 'active', p.id, null, null, 'objection', '„Das ist zu teuer.“', null, '{"objection":"„Das ist zu teuer.“","meaning":"Sie vergleichen mit einer günstigen Website oder sehen den Wert noch nicht.","questions":["Was ist Ihnen ein neuer Kunde wert?","Womit vergleichen Sie?"],"short":"Vergleichen Sie es mit dem Wert der Kunden, die es Ihnen zu gewinnen hilft — nicht mit dem Preis einer einfachen Website.","long":"Studio ATS ist keine einfache Website: Es ist der gesamte Weg vom ersten Besuch bis zur Anfrage, für Sie gebaut und gewartet. Viele Fachleute sehen es so: Was ist ein einziger neuer Kunde wert? Der Preis ist offiziell und für alle gleich — durch Verhandeln bekommen Sie ihn nirgendwo günstiger.","nextStep":"Geben Sie nie Rabatt und versprechen Sie kein Ergebnis. Senden Sie den Angebotsabschnitt der Seite."}'::jsonb, array['Preis', 'price', 'teuer', 'expensive', 'Budget']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'de', 1, 'active', p.id, null, null, 'objection', '„Ich habe schon eine Website.“', null, '{"objection":"„Ich habe schon eine Website.“","meaning":"Sie denken, sie erfülle denselben Zweck.","questions":["Wie viele Anfragen bringt sie Ihnen pro Monat?","Was passiert, nachdem jemand Ihr Formular ausgefüllt hat?"],"short":"Behalten Sie sie, wenn sie funktioniert. Bei Studio ATS geht es um das, was eine Website selten tut: Anfragen qualifizieren und Termine erleichtern.","long":"Eine Website präsentiert; Studio ATS konvertiert. Die Frage ist nicht, ob Sie eine Website haben, sondern ob sie Besucher in vollständige Anfragen und Termine verwandelt. Wenn Ihre das schon tut — prima. Wenn nicht, ist das genau der Teil, den Studio ATS übernimmt.","nextStep":"Schlagen Sie vor, sich ihr aktuelles Anfrageformular gemeinsam anzusehen."}'::jsonb, array['Website', 'website', 'schon eine Website', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'de', 1, 'active', p.id, null, null, 'objection', '„Ich muss darüber nachdenken.“', null, '{"objection":"„Ich muss darüber nachdenken.“","meaning":"Etwas ist unklar, oder es ist nicht der richtige Moment.","questions":["Was müssten Sie wissen, um zu entscheiden?","Geht es um den Zeitpunkt, das Budget oder etwas anderes?"],"short":"Natürlich. Was ist die eine Sache, die Sie für die Entscheidung geklärt haben müssten?","long":"Sich Zeit zu nehmen ist normal. Meistens bleibt eine Frage offen — Preis, Zeitplan oder wie es für sie funktionieren würde. Fragen Sie, welche, beantworten Sie sie präzise und vereinbaren Sie dann einen Termin, um wieder zu sprechen.","nextStep":"Vereinbaren Sie einen Termin zum Nachfassen und tragen Sie ihn in Ihr CRM ein."}'::jsonb, array['nachdenken', 'think', 'später', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'de', 1, 'active', p.id, null, null, 'objection', '„Nicht jetzt.“', null, '{"objection":"„Nicht jetzt.“","meaning":"Hochsaison oder andere Prioritäten.","questions":["Wann wäre ein besserer Zeitpunkt?","Wann ist Ihre ruhigere Zeit?"],"short":"Verstanden — wann wäre es sinnvoll, wieder zu sprechen?","long":"Respektieren Sie es und planen Sie: Der beste Moment, Studio ATS einzurichten, ist oft kurz vor einer arbeitsreichen Phase, damit es funktioniert, wenn die Anfragen kommen. Fragen Sie, wann Sie sich wieder melden sollen, und notieren Sie es.","nextStep":"Legen Sie eine Erinnerung im CRM an — bestehen Sie nie darauf."}'::jsonb, array['nicht jetzt', 'not now', 'Timing', 'Saison']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'de', 1, 'active', p.id, null, null, null, 'Was es ist', null, '{"section":"what_it_is","items":[{"title":"Ein Online-Vertriebsstudio","body":"Studio ATS ist ein Online-Vertriebsstudio für Fachleute, bei denen jeder neue Kunde echten Wert hat: Es präsentiert ihre Arbeit, qualifiziert Anfragen und hilft bei der Terminbuchung — an einem Ort."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'de', 1, 'active', p.id, null, null, null, 'Was es tut', null, '{"section":"what_it_does","items":[{"title":"Vom ersten Besuch bis zum gebuchten Termin","body":"Die Website ist nur ein Teil. Studio ATS deckt den gesamten Weg ab: Schaufenster, Anfrage, Qualifizierung, Termin, Nachfassen."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.customer_gets', 'de', 1, 'active', p.id, null, null, null, 'Was der Kunde erhält', null, '{"section":"customer_gets","items":[{"title":"Alles erledigt","body":"Das Studio ATS-Team konzipiert, richtet ein, hostet und wartet. Der Kunde erhält strukturierte Anfragen."},{"title":"Ein Ort","body":"Jeder Kontakt und jede Anfrage an einem Ort, mit Verlauf."}]}'::jsonb, array[]::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.benefits', 'de', 1, 'active', p.id, null, null, null, 'Geschäftlicher Nutzen', null, '{"section":"benefits","items":[{"title":"Vertrauen","body":"Eine Premium-Präsenz, die der Qualität der Arbeit entspricht."},{"title":"Qualifizierte Anfragen","body":"Budget, Zeitrahmen und Projektart sind vor dem ersten Gespräch bekannt."},{"title":"Zeit","body":"Weniger vage Anrufe und vergessenes Nachfassen."}]}'::jsonb, array[]::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.features', 'de', 1, 'active', p.id, null, null, null, 'Funktionen', null, '{"section":"features","items":[{"title":"Präsentieren","body":"Tätigkeit und beste Arbeiten auf einer schnellen Premium-Website zeigen."},{"title":"Konvertieren","body":"Geführte Anfrageformulare verwandeln Besucher in strukturierte Anfragen."},{"title":"Qualifizieren","body":"Budget, Zeitrahmen und Projektart vor dem Gespräch kennen."},{"title":"Zentralisieren","body":"Jeder Kontakt und jede Anfrage an einem Ort, mit vollständigem Verlauf."},{"title":"Buchen","body":"Qualifizierte Interessenten fragen mit wenigen Klicks einen Termin an."},{"title":"Automatisieren","body":"Transaktions-E-Mails und Nachfassaktionen gehen pünktlich raus."},{"title":"Verfolgen","body":"Jede Anfrage vom ersten Besuch bis zum unterschriebenen Kunden verfolgen."},{"title":"Messen","body":"Sehen, welche Seiten, Quellen und Kampagnen echte Chancen bringen."}]}'::jsonb, array[]::text[], 104, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.technical', 'de', 1, 'active', p.id, null, null, null, 'Technische Informationen', null, '{"section":"technical","items":[{"title":"Hosting & Wartung","body":"Inklusive und vom Studio ATS-Team übernommen."},{"title":"Integrationen","body":"Integrationen für Kalender, E-Mail und Analysen. Die genaue Liste wird beim Onboarding bestätigt — versprechen Sie kein bestimmtes Tool."}]}'::jsonb, array[]::text[], 105, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.included', 'de', 1, 'active', p.id, null, null, null, 'Was enthalten ist', null, '{"section":"included","items":[{"title":"Konzeption und Einrichtung","body":"Konzeption und Einrichtung des Studio ATS des Kunden."},{"title":"Portfolio und Verkaufsseiten","body":"Seiten, die die Arbeit und das Angebot präsentieren."},{"title":"Erfassung und Qualifizierung von Anfragen","body":"Geführte Formulare und Qualifizierung."},{"title":"Kontakte und Terminanfragen","body":"Zentralisiert, mit Verlauf."},{"title":"Automatische E-Mails und Nachfassen","body":"Pünktlich versendet."},{"title":"Analysen","body":"Was echte Chancen bringt."},{"title":"Hosting und Wartung","body":"Von Studio ATS übernommen."}]}'::jsonb, array[]::text[], 106, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.pricing', 'de', 1, 'active', p.id, null, null, null, 'Preise', null, '{"section":"pricing","items":[{"title":"Offizieller Preis","body":"Der hier angezeigte Preis stammt aus dem offiziellen Katalog von Studio ATS. Er ist für alle gleich, und Partner ändern oder verhandeln ihn nie."},{"title":"Bedingungen","body":"Die endgültigen Bedingungen stehen im Kundenvertrag."}]}'::jsonb, array[]::text[], 107, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.faq', 'de', 1, 'active', p.id, null, null, null, 'FAQ', null, '{"section":"faq","items":[{"title":"Ist es nur eine Website?","body":"Nein: Die Website ist ein Teil eines vollständigen Wegs vom ersten Besuch bis zum Termin."},{"title":"Wer baut es?","body":"Das Studio ATS-Team konzipiert, richtet ein und wartet es."},{"title":"Kann der Kunde seine sozialen Netzwerke behalten?","body":"Ja. Studio ATS ergänzt soziale Profile."}]}'::jsonb, array[]::text[], 108, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.not_included', 'de', 1, 'draft', p.id, null, null, null, 'Was nicht enthalten ist', null, '{"section":"not_included","items":[{"title":"Von Studio ATS zu bestätigen","body":"Listen Sie auf, was außerhalb des Angebots liegt, bevor Sie diesen Abschnitt veröffentlichen."}]}'::jsonb, array[]::text[], 109, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
