insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'asset', 'studio-public-page', 'de', 1, 'active', p.id, null, null, null, 'Öffentliche Studio ATS-Präsentation', 'Die offizielle Produktseite — teilen Sie sie oder nutzen Sie sie als Live-Demo.', '{"category":"demo","url":"/de/studio","description":"Immer aktuell: Es ist die Live-Produktseite."}'::jsonb, array[]::text[], 200, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'de', 1, 'active', p.id, null, null, null, 'Ihre erste Woche', 'Ein empfohlener Aktionsplan — kein Ergebnisversprechen.', '{"disclaimer":"Ein empfohlener Plan, um eine Routine aufzubauen. Die Ergebnisse hängen von Ihrer Arbeit, Ihrem Markt und Ihren Interessenten ab; nichts hier ist ein Versprechen von Verkäufen oder Einkommen.","days":[{"day":1,"title":"Studio ATS verstehen","body":"Lesen Sie das Produktwissen und ein Playbook.","tasks":["Lesen, was Studio ATS ist und was enthalten ist","Das Playbook für Ihre Zielgruppe öffnen"]},{"day":2,"title":"20 Interessenten auswählen","body":"Wählen Sie eine Zielgruppe und listen Sie 20 echte Unternehmen in Ihrer Nähe auf.","tasks":["Ihre Zielgruppe wählen","20 Interessenten in Ihr CRM eintragen"]},{"day":3,"title":"Ihre ersten Interessenten kontaktieren","body":"Senden Sie Ihre ersten personalisierten Nachrichten.","tasks":["5 Erstkontakt-Nachrichten senden","Ihre Verkaufsseite für die Zielgruppe erstellen"]},{"day":4,"title":"Nachfassen","body":"Fassen Sie bei denen nach, die nicht geantwortet haben — einmal, kurz.","tasks":["Nachfass-Nachrichten senden","Antworten auf „Geantwortet“ setzen"]},{"day":5,"title":"Gespräche führen","body":"Nutzen Sie den Gesprächsleitfaden bei denen, die geantwortet haben.","tasks":["Mindestens ein Bedarfsgespräch führen","Den nächsten Schritt jedes Gesprächs notieren"]},{"day":6,"title":"Passende Verkaufsseiten senden","body":"Senden Sie Ihre Seite an qualifizierte Interessenten.","tasks":["Ihre Verkaufsseite nach jedem Gespräch senden","Prüfen, ob die Seite auf dem Smartphone gut aussieht"]},{"day":7,"title":"Bilanz ziehen","body":"Schauen Sie, was funktioniert hat: welche Nachricht, welche Zielgruppe, welcher Kanal.","tasks":["Performance Ihrer Seite und Links prüfen","Die nächste Woche planen"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'es', 1, 'active', p.id, null, null, null, 'Studio ATS — página de venta estándar', 'Estructura por defecto de todas las páginas de venta de afiliados.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Convierta su tráfico en oportunidades.","heroSubtitle":"Un estudio comercial en línea para profesionales para quienes cada nuevo cliente tiene un valor real. Presente su trabajo, cualifique solicitudes y reserve citas — en un solo lugar.","problemTitle":"Un gran trabajo. Solicitudes perdidas.","problemBody":"Las consultas llegan por formulario, redes sociales, mensajes y correo. Nadie sabe cuáles son serias, los seguimientos se olvidan y los buenos prospectos se enfrían.","solutionTitle":"Más que una web.","solutionBody":"La web es solo una parte. Studio ATS es todo el recorrido, desde la primera visita hasta la cita reservada — diseñado, configurado y mantenido para usted.","valueTitle":"Lo que obtiene realmente","valueItems":["Una presencia que inspira confianza a primera vista","Solicitudes que llegan con la información adecuada","Cada contacto y cada solicitud en un solo lugar","Seguimientos que salen a tiempo"],"howTitle":"Cómo funciona","howSteps":[{"title":"Solicitud","body":"Háblenos de su negocio en un formulario breve."},{"title":"Llamada","body":"Cualificamos juntos sus necesidades."},{"title":"Creación","body":"Diseñamos y configuramos su Studio ATS."},{"title":"Lanzamiento","body":"Empieza a recibir solicitudes estructuradas."}],"benefitsTitle":"Por qué importa para su negocio","benefits":[{"title":"Confianza","body":"Los prospectos le buscan en internet antes de llamar. Cuide esa primera impresión."},{"title":"Tiempo","body":"Conozca presupuesto, plazos y tipo de proyecto antes de descolgar el teléfono."},{"title":"Nada que gestionar","body":"Creado, alojado y mantenido por el equipo de Studio ATS."}],"includedTitle":"Qué incluye","whoTitle":"Para quién es","whoBody":"Profesionales y empresas cuyos clientes valen mucho, con una oferta visual o premium y solicitudes entrantes que convertir.","faqTitle":"Preguntas que puede tener","offerTitle":"Una fórmula. Todo incluido.","offerNote":"Precio sin IVA cuando proceda. Condiciones definitivas en el contrato.","ctaTitle":"¿Listo para hablar de su negocio?","ctaBody":"Déjenos sus datos — sin compromiso. Le responderemos para entender sus necesidades."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'es', 1, 'active', p.id, 'artisans', null, null, 'Variante artesanos', null, '{"template":"studio-default","heroTitle":"Su trabajo es excelente. Su presencia en internet también debería serlo.","heroSubtitle":"Los prospectos le buscan antes de llamar. Studio ATS da a su negocio una presencia profesional y recoge solicitudes completas — incluso mientras usted está trabajando.","problemTitle":"El boca a boca ya no basta.","problemBody":"Quien aún no le conoce le busca primero en internet. Si encuentra poco, llama a otro — y las solicitudes que llegan están dispersas e incompletas.","ctaTitle":"Veamos juntos su negocio","ctaBody":"Déjenos sus datos y describa su oficio en una línea. Sin compromiso."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'es', 1, 'active', p.id, null, null, null, 'Generar más solicitudes cualificadas', null, '{"promise":"Solicitudes que llegan con presupuesto, plazos y detalles.","heroTitle":"Reciba solicitudes a las que realmente pueda responder.","heroSubtitle":"Studio ATS hace las preguntas adecuadas antes de la primera llamada, para que cada solicitud llegue con la información que necesita."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'es', 1, 'active', p.id, null, null, null, 'Parecer en internet tan profesional como es', null, '{"promise":"Una presencia a la altura de la calidad del trabajo.","heroTitle":"Sea tan profesional en internet como en la vida real.","heroSubtitle":"Los prospectos le revisan antes de llamar. Ofrézcales una presencia que inspire confianza en segundos."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'es', 1, 'active', p.id, null, null, null, 'Dejar de perder solicitudes', null, '{"promise":"Cada solicitud captada y centralizada, incluso cuando está ocupado.","heroTitle":"Deje de perder solicitudes mientras trabaja.","heroSubtitle":"Cada solicitud llega a un solo lugar con los datos adecuados — y los seguimientos salen a tiempo."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'es', 1, 'active', p.id, null, null, null, 'Vender Studio ATS — el método', 'Los 10 pasos de una venta de Studio ATS, para cualquier objetivo. Abra un objetivo para incorporar sus problemas y su enfoque.', '{"intro":"Venda el resultado, no la tecnología. Su trabajo: entender su situación, mostrar lo que pierden hoy y enviarles la página adecuada.","steps":[{"key":"understand","title":"Entenderlos","body":"Antes de contactar, mire cómo se presentan hoy en internet y cómo puede llegar a ellos un nuevo cliente.","bullets":["Revise su web, sus perfiles sociales y sus reseñas","Anote algo concreto que le guste de su trabajo"]},{"key":"opening","title":"Apertura","body":"Empiece por ellos, no por Studio ATS. Un comentario sincero, una pregunta.","bullets":["«He visto su trabajo en …»","«Una pregunta rápida: ¿cómo le encuentran la mayoría de sus nuevos clientes?»"]},{"key":"discovery","title":"Descubrimiento","body":"Pregunte y escuche. Deje que describan cómo llegan las solicitudes y qué pasa después.","bullets":["¿Cómo le contactan hoy los nuevos clientes?","¿Qué información suele faltar?","¿Qué pasa cuando no puede responder enseguida?"]},{"key":"pain","title":"Identificar el problema","body":"Nombre el problema con sus palabras. No invente uno que no tienen."},{"key":"present","title":"Presentar Studio ATS","body":"Relacione Studio ATS con el problema que acaban de describir — una frase, no una lista de funciones.","bullets":["«Eso es justo lo que resuelve Studio ATS: …»"]},{"key":"value","title":"Demostrar el valor","body":"Hable de resultados: confianza, solicitudes completas, tiempo ganado, nada que gestionar. Nunca prometa cifras."},{"key":"objections","title":"Gestionar objeciones","body":"Una objeción es una pregunta disfrazada. Pregunte qué hay detrás antes de responder."},{"key":"offer","title":"Enviar la oferta","body":"Envíe su página de venta para su sector: lo explica todo y el precio lo fija Studio ATS."},{"key":"follow_up","title":"Hacer seguimiento","body":"¿Sin respuesta tras unos días? Un seguimiento breve y útil — y luego respete su respuesta."},{"key":"close","title":"Cerrar","body":"Acuerde un siguiente paso claro: una llamada, una solicitud en la página o la compra en línea."}]}'::jsonb, array['método', 'descubrimiento', 'cierre']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'es', 1, 'active', p.id, 'artisans', null, null, 'Vender Studio ATS a un artesano', 'Teléfono primero, breve, concreto. Los artesanos están ocupados: respete su tiempo.', '{"intro":"Los artesanos compran a quien entiende su oficio. Hable de sus clientes y de su tiempo — nunca de «páginas web».","steps":[{"key":"understand","title":"Entenderlos","body":"Pasan la mayor parte del día en la obra, consiguen trabajo por el boca a boca y atienden llamadas entre dos trabajos. Su reputación es su principal activo.","bullets":["Búsquelos como lo haría un cliente: ¿qué encuentra?","Anote su oficio, su zona y los trabajos que muestran"]},{"key":"opening","title":"Apertura","body":"Llame temprano por la mañana o al final del día. Sea breve y concreto.","bullets":["«Le he buscado como lo haría un cliente — ¿le cuento lo que he visto? Son 2 minutos.»"]},{"key":"discovery","title":"Descubrimiento","body":"Con tres preguntas basta.","bullets":["¿Cómo le encuentran la mayoría de sus nuevos clientes?","¿Qué pasa cuando alguien que no le conoce le busca?","¿Cuántas llamadas pierde mientras está en un trabajo?"]},{"key":"pain","title":"Identificar el problema","body":"Normalmente: el boca a boca tiene límites, el negocio parece menos profesional en internet que en la realidad y se pierden solicitudes."},{"key":"present","title":"Presentar Studio ATS","body":"«Studio ATS da a su negocio una presencia profesional que trabaja mientras usted está en la obra: la gente ve sus trabajos y le envía solicitudes completas — trabajo, lugar, plazo.»"},{"key":"value","title":"Demostrar el valor","body":"La confianza de quien aún no le conoce. Solicitudes que se responden de una vez. Nada que gestionar usted mismo."},{"key":"objections","title":"Gestionar objeciones","body":"Espere: «ya tengo redes sociales», «mis clientes llegan por el boca a boca», «no tengo tiempo»."},{"key":"offer","title":"Enviar la oferta","body":"Envíe su página para artesanos por SMS o WhatsApp justo después de la llamada, mientras la conversación está reciente."},{"key":"follow_up","title":"Hacer seguimiento","body":"Dos o tres días después, un mensaje corto: «¿Ha tenido tiempo de mirarla? ¿Le resuelvo alguna duda?»"},{"key":"close","title":"Cerrar","body":"Proponga el siguiente paso: una solicitud en la página, una llamada con el equipo de Studio ATS o la compra en línea cuando esté disponible."}]}'::jsonb, array['artesano', 'teléfono', 'boca a boca', 'redes sociales']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'es', 1, 'active', p.id, null, 'phone', null, 'Llamada de descubrimiento (cualquier objetivo)', '5 minutos para entender, cualificar y acordar un siguiente paso.', '{"intro":"Marque cada paso a medida que avanza. Hable menos que ellos.","steps":[{"type":"opening","text":"Hola {{firstName}}, soy {{advisorName}}. Le llamo por la forma en que los nuevos clientes contactan con {{company}} — ¿tiene 2 minutos?"},{"type":"question","text":"¿Cómo le encuentran hoy la mayoría de sus nuevos clientes?"},{"type":"listen","text":"¿Solo boca a boca? ¿Redes sociales? ¿Llamadas mientras trabaja?","hint":"Anote sus palabras exactas."},{"type":"question","text":"¿Qué pasa cuando alguien que no le conoce le busca en internet?"},{"type":"problem","text":"Encuentra poco, o las solicitudes llegan dispersas e incompletas."},{"type":"response","text":"Eso es lo que resuelve Studio ATS: una presencia profesional que inspira confianza y recoge solicitudes completas — creada y mantenida para usted."},{"type":"objection","text":"«Ya tengo redes sociales.»"},{"type":"answer","text":"Las redes muestran su trabajo. Studio ATS convierte el interés en una solicitud completa. ¿Dónde le envía hoy la gente una solicitud?"},{"type":"cta","text":"¿Le envío la página de su sector? Lo explica todo, precio incluido, en 3 minutos."}]}'::jsonb, array['teléfono', 'descubrimiento', 'llamada']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'es', 1, 'active', p.id, 'artisans', 'phone', null, 'Artesano — primera llamada', 'Llamada breve entre dos trabajos.', '{"steps":[{"type":"opening","text":"Hola {{firstName}}, soy {{advisorName}}. He buscado {{company}} como lo haría un cliente — ¿le cuento lo que he visto? Dos minutos."},{"type":"question","text":"La mayor parte de su trabajo llega por el boca a boca, ¿verdad?"},{"type":"listen","text":"Orgullo por su reputación; quizá épocas más flojas; llamadas perdidas en la obra."},{"type":"question","text":"Y cuando un amigo le recomienda, ¿qué encuentra esa persona cuando le busca?"},{"type":"problem","text":"Poco o nada que refleje la calidad del trabajo — algunos llaman a otro."},{"type":"response","text":"Studio ATS le da una presencia profesional que trabaja mientras usted está en la obra: la gente ve sus trabajos y le envía solicitudes completas."},{"type":"objection","text":"«No tengo tiempo para eso.»"},{"type":"answer","text":"Justamente: el equipo de Studio ATS lo crea y lo mantiene. Usted solo recibe las solicitudes."},{"type":"cta","text":"Le envío por SMS la página para artesanos — écheles un vistazo esta noche y le llamo el jueves, ¿le parece?"}]}'::jsonb, array['artesano', 'teléfono', 'boca a boca']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'es', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Primer contacto — mensaje corto', null, '{"text":"Hola {{firstName}}, he visto {{company}} y me ha gustado su trabajo. Una pregunta rápida: ¿cómo le contactan hoy la mayoría de sus nuevos clientes? Trabajo con Studio ATS, que ayuda a los profesionales a convertir el interés en internet en solicitudes completas. Aquí tiene un resumen de 3 minutos para su sector: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'es', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Primer contacto — LinkedIn', null, '{"text":"Hola {{firstName}}, me gusta lo que comparte sobre {{sector}}. Cuando alguien quiere trabajar con {{company}}, ¿adónde lo envía? Acompaño a profesionales con Studio ATS, un espacio que presenta su trabajo y cualifica cada solicitud. ¿Le apetece echar un vistazo?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-sms-artisan', 'es', 1, 'active', p.id, 'artisans', 'sms', 'first_contact', 'Artesano — primer SMS tras una llamada', null, '{"text":"Hola {{firstName}}, gracias por la llamada. Como le prometí, la página para artesanos (3 min): {{affiliateUrl}} — {{advisorName}}"}'::jsonb, array[]::text[], 32, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-short', 'es', 1, 'active', p.id, null, 'whatsapp', 'follow_up', 'Seguimiento — 3 días después', null, '{"text":"Hola {{firstName}}, ¿ha podido ver la página que le envié? Le resuelvo cualquier duda en 5 minutos. {{affiliateUrl}}"}'::jsonb, array[]::text[], 33, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'es', 1, 'active', p.id, null, 'in_person', 'follow_up', 'Después de un encuentro en persona', null, '{"text":"Hola {{firstName}}, encantado de conocerle hoy. Como hablamos, aquí tiene la página de Studio ATS para su negocio: {{affiliateUrl}}. Dígame cuándo le viene bien una llamada corta. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'es', 1, 'active', p.id, null, 'other', 'no_response', 'Sin respuesta — último mensaje', null, '{"text":"Hola {{firstName}}, no quiero molestarle: no volveré a escribirle. Si mejorar la forma en que los nuevos clientes contactan con {{company}} pasa a ser una prioridad, la página sigue disponible: {{affiliateUrl}}. Que tenga una buena semana."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'es', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'Después de la llamada — resumen', null, '{"text":"Gracias por su tiempo, {{firstName}}. En resumen: quiere solicitudes que lleguen completas y una presencia que refleje {{company}}. Aquí está todo explicado, precio incluido: {{affiliateUrl}}. Siguiente paso, como acordamos: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'es', 1, 'active', p.id, null, 'other', 'interested', 'Interesado — reservar el siguiente paso', null, '{"text":"¡Perfecto, {{firstName}}! El siguiente paso más sencillo: deje su solicitud en esta página para que el equipo de Studio ATS prepare la llamada: {{affiliateUrl}}. ¿Qué día le viene bien?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'proposal-send-page', 'es', 1, 'active', p.id, null, 'other', 'proposal', 'Propuesta — enviar la oferta', null, '{"text":"Hola {{firstName}}, como le prometí, aquí tiene la oferta completa de Studio ATS para {{company}}: qué incluye, cómo funciona y el precio oficial. {{affiliateUrl}}"}'::jsonb, array[]::text[], 38, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'es', 1, 'active', p.id, null, 'other', 'objection', 'Objeción — «Ya tengo redes sociales»', null, '{"text":"Le entiendo, {{firstName}} — sus redes muestran muy bien su trabajo. Studio ATS no las sustituye: convierte ese interés en solicitudes completas, en un espacio que usted controla. ¿Dónde le envía hoy la gente una solicitud?"}'::jsonb, array['instagram', 'facebook', 'redes sociales', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'closing-checkout', 'es', 1, 'active', p.id, null, 'other', 'closing', 'Cierre — tras una compra iniciada', null, '{"text":"Hola {{firstName}}, he visto que estaba mirando Studio ATS. ¿Alguna duda antes de decidir? Estoy disponible si quiere comentarlo."}'::jsonb, array[]::text[], 40, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'es', 1, 'active', p.id, null, 'email', 'renewal', 'Cliente — saludo amistoso', null, '{"text":"Hola {{firstName}}, ¿qué tal le va Studio ATS en {{company}}? Si hay algo que mejorar, dígamelo y se lo traslado al equipo de Studio ATS."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'es', 1, 'active', p.id, null, 'email', 'first_contact', 'Primer contacto', null, '{"subject":"{{company}} — convertir el interés en internet en solicitudes","preview":"Una pregunta rápida sobre cómo le contactan los nuevos clientes.","body":"Hola {{firstName}}:\n\nHe conocido {{company}} y me ha gustado sinceramente su trabajo.\n\nUna pregunta rápida: cuando alguien le descubre en internet, ¿qué pasa después? Muchos profesionales reciben solicitudes por una mezcla de formularios, redes sociales y mensajes — sin los datos que necesitan.\n\nStudio ATS se encarga de eso: un espacio profesional que presenta su trabajo, cualifica cada solicitud y ayuda a reservar la cita. Se crea y se mantiene para usted.\n\nAquí tiene un resumen de 3 minutos para su sector:","cta":"Ver el resumen"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'es', 1, 'active', p.id, null, 'email', 'follow_up', 'Seguimiento a los 3 días', null, '{"subject":"Re: {{company}} — convertir el interés en internet en solicitudes","preview":"Vuelvo a subir este mensaje a su bandeja.","body":"Hola {{firstName}}:\n\nSolo vuelvo a subir mi mensaje. Si le suenan las solicitudes que llegan sin los datos adecuados, Studio ATS merece 3 minutos.\n\nSi ahora no es una prioridad, no hay ningún problema — dígamelo y no volveré a escribirle.","cta":"Ver la página"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'es', 1, 'active', p.id, null, 'email', 'after_call', 'Después de la llamada — resumen', null, '{"subject":"Nuestra llamada — próximos pasos para {{company}}","preview":"Lo que hablamos y el siguiente paso.","body":"Hola {{firstName}}:\n\nGracias por su tiempo hoy. Lo que he entendido:\n• cómo le contactan hoy los nuevos clientes\n• qué le gustaría mejorar\n\nTodo sobre Studio ATS — qué incluye, cómo funciona y el precio oficial — está en esta página:","cta":"Abrir mi página de Studio ATS"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'es', 1, 'active', p.id, null, 'email', 'proposal', 'Propuesta', null, '{"subject":"La oferta de Studio ATS para {{company}}","preview":"Todo en una página, precio incluido.","body":"Hola {{firstName}}:\n\nComo le prometí, aquí tiene la oferta completa de Studio ATS para {{company}}. Encontrará qué incluye, cómo se realiza la puesta en marcha y el precio y las condiciones oficiales.\n\nQuedo a su disposición para cualquier pregunta.","cta":"Ver la oferta"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'es', 1, 'active', p.id, null, 'email', 'objection', 'Las redes sociales no bastan', null, '{"subject":"Sus redes muestran su trabajo. ¿Le traen solicitudes?","preview":"Por qué las redes sociales y Studio ATS se complementan.","body":"Hola {{firstName}}:\n\nSus redes muestran bien su trabajo — consérvelas. La cuestión es qué pasa después del interés: un mensaje perdido entre otros, una solicitud sin detalles, una llamada que no puede atender.\n\nStudio ATS es el lugar donde ese interés se convierte en una solicitud completa, en un espacio que usted controla. Complementa sus perfiles sociales; no los sustituye.","cta":"Ver cómo funciona"}'::jsonb, array['instagram', 'facebook', 'redes sociales', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'es', 1, 'active', p.id, null, 'email', 'no_response', 'Último seguimiento', null, '{"subject":"¿Cierro su expediente?","preview":"Un último mensaje — y lo dejo.","body":"Hola {{firstName}}:\n\nComo no he tenido noticias suyas, entiendo que no es el momento — no volveré a escribirle.\n\nSi las cosas cambian, la página sigue disponible.","cta":"Conservar la página"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'es', 1, 'active', p.id, null, null, 'objection', '«Ya tengo redes sociales.»', null, '{"objection":"«Ya tengo redes sociales.»","meaning":"Las redes les parecen visibilidad suficiente — o no ven lo que falta.","questions":["¿Dónde le envía hoy la gente una solicitud?","¿Qué pasa con una solicitud que llega un sábado por la noche?"],"short":"Las redes muestran su trabajo. Studio ATS convierte ese interés en solicitudes completas, en un espacio que usted controla.","long":"Conserve sus redes: son ideales para mostrar su trabajo. Pero un mensaje privado no es una solicitud — sin presupuesto, sin plazos, perdido entre otros mensajes, y es la plataforma quien decide quién le ve. Studio ATS es el espacio profesional donde el interés se convierte en una solicitud completa que puede responder de una vez.","nextStep":"Envíe la página de venta y propóngales compararla con su perfil."}'::jsonb, array['instagram', 'facebook', 'redes sociales', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'es', 1, 'active', p.id, null, null, 'objection', '«Mis clientes llegan por el boca a boca.»', null, '{"objection":"«Mis clientes llegan por el boca a boca.»","meaning":"Están orgullosos de su reputación — y no ven la relación con estar en internet.","questions":["Cuando un amigo le recomienda, ¿qué hace esa persona antes de llamar?","¿Hay épocas más flojas durante el año?"],"short":"El boca a boca le trae gente. Studio ATS hace que le llamen después de buscarle.","long":"Es señal de un trabajo excelente. Pero hoy, incluso un cliente recomendado consulta internet antes de llamar. Si encuentra poco, algunos dudan o llaman a otro. Studio ATS no sustituye el boca a boca: lo confirma.","nextStep":"Propóngales que se busquen a sí mismos como lo haría un cliente."}'::jsonb, array['boca a boca', 'word of mouth', 'recomendaciones', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'es', 1, 'active', p.id, null, null, 'objection', '«No necesito vender en línea.»', null, '{"objection":"«No necesito vender en línea.»","meaning":"Creen que Studio ATS es una tienda en línea.","questions":["¿Cómo le contacta hoy un nuevo cliente?","¿Qué necesita saber antes de hacer un presupuesto?"],"short":"Studio ATS no es una tienda en línea: ayuda a quien aún no le conoce a confiar en usted y a enviarle una solicitud de verdad.","long":"Usted no vende en línea — vende conversando y presupuestando. Studio ATS prepara esas conversaciones: la gente ve su trabajo, entiende lo que hace y le envía una solicitud con los datos adecuados. La venta sigue haciéndose con usted.","nextStep":"Muestre la sección «Cómo funciona» de la página de venta."}'::jsonb, array['comercio electrónico', 'vender en línea', 'sell online', 'tienda']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'es', 1, 'active', p.id, null, null, 'objection', '«No tendré tiempo de responder.»', null, '{"objection":"«No tendré tiempo de responder.»","meaning":"Temen más trabajo o más papeleo.","questions":["¿Cuánto tiempo dedica hoy a llamadas que no llevan a nada?","¿Qué le ayudaría a responder más rápido?"],"short":"Studio ATS está hecho para ahorrar tiempo: las solicitudes llegan completas, así que responde una sola vez.","long":"Está pensado precisamente para gente ocupada. El equipo de Studio ATS lo crea y lo mantiene todo. Las solicitudes llegan con los datos necesarios, en un solo lugar: ya no pierde tiempo persiguiendo información ni devolviendo llamadas imprecisas.","nextStep":"Ofrezca enviarles la página para que la miren por la noche."}'::jsonb, array['tiempo', 'time', 'ocupado', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'es', 1, 'active', p.id, null, null, 'objection', '«Es demasiado caro.»', null, '{"objection":"«Es demasiado caro.»","meaning":"Lo comparan con una web barata, o aún no ven el valor.","questions":["¿Cuánto vale para usted un nuevo cliente?","¿Con qué lo está comparando?"],"short":"Compárelo con el valor de los clientes que le ayuda a conseguir — no con el precio de una web básica.","long":"Studio ATS no es una web básica: es todo el recorrido desde la primera visita hasta la solicitud, creado y mantenido para usted. Muchos profesionales lo ven así: ¿cuánto vale un solo cliente nuevo? El precio es oficial e igual para todos — no conseguirá uno mejor negociando en otro sitio.","nextStep":"Nunca haga descuentos ni prometa resultados. Envíe la sección de oferta de la página."}'::jsonb, array['precio', 'price', 'caro', 'expensive', 'presupuesto']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'es', 1, 'active', p.id, null, null, 'objection', '«Ya tengo una web.»', null, '{"objection":"«Ya tengo una web.»","meaning":"Creen que hace el mismo trabajo.","questions":["¿Cuántas solicitudes le trae cada mes?","¿Qué pasa después de que alguien rellena su formulario?"],"short":"Consérvela si funciona. Studio ATS se ocupa de lo que una web rara vez hace: cualificar solicitudes y facilitar las citas.","long":"Una web presenta; Studio ATS convierte. La cuestión no es si tiene web, sino si convierte a los visitantes en solicitudes completas y citas. Si la suya ya lo hace, perfecto. Si no, esa es exactamente la parte de la que se ocupa Studio ATS.","nextStep":"Proponga revisar juntos su formulario de contacto actual."}'::jsonb, array['web', 'website', 'ya tengo web', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'es', 1, 'active', p.id, null, null, 'objection', '«Tengo que pensarlo.»', null, '{"objection":"«Tengo que pensarlo.»","meaning":"Algo no está claro, o no es el momento.","questions":["¿Qué necesitaría saber para decidir?","¿Es el momento, el presupuesto u otra cosa?"],"short":"Por supuesto. ¿Qué es lo único que necesitaría aclarar para decidir?","long":"Tomarse tiempo es normal. Normalmente queda una pregunta pendiente — precio, calendario o cómo funcionaría en su caso. Pregunte cuál, respóndala con precisión y acuerden una fecha para volver a hablar.","nextStep":"Acuerde una fecha de seguimiento y anótela en su CRM."}'::jsonb, array['pensarlo', 'think', 'más tarde', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'es', 1, 'active', p.id, null, null, 'objection', '«Ahora no.»', null, '{"objection":"«Ahora no.»","meaning":"Temporada alta u otras prioridades.","questions":["¿Cuándo sería un mejor momento?","¿Cuál es su época más tranquila?"],"short":"Entendido — ¿cuándo tendría sentido volver a hablar?","long":"Respételo y planifique: el mejor momento para poner en marcha Studio ATS suele ser justo antes de una época de mucho trabajo, para que funcione cuando lleguen las solicitudes. Pregunte cuándo volver a contactar y anótelo.","nextStep":"Programe un recordatorio en el CRM — sin insistir nunca."}'::jsonb, array['ahora no', 'not now', 'momento', 'temporada']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'es', 1, 'active', p.id, null, null, null, 'Qué es', null, '{"section":"what_it_is","items":[{"title":"Un estudio comercial en línea","body":"Studio ATS es un estudio comercial en línea para profesionales para quienes cada nuevo cliente tiene un valor real: presenta su trabajo, cualifica las solicitudes y ayuda a reservar citas — en un solo lugar."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'es', 1, 'active', p.id, null, null, null, 'Qué hace', null, '{"section":"what_it_does","items":[{"title":"De la primera visita a la cita reservada","body":"La web es solo una parte. Studio ATS cubre todo el recorrido: escaparate, solicitud, cualificación, cita y seguimiento."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.customer_gets', 'es', 1, 'active', p.id, null, null, null, 'Qué recibe el cliente', null, '{"section":"customer_gets","items":[{"title":"Llave en mano","body":"El equipo de Studio ATS lo diseña, lo configura, lo aloja y lo mantiene. El cliente recibe solicitudes estructuradas."},{"title":"Un solo lugar","body":"Cada contacto y cada solicitud en un solo lugar, con el historial."}]}'::jsonb, array[]::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.benefits', 'es', 1, 'active', p.id, null, null, null, 'Beneficios para el negocio', null, '{"section":"benefits","items":[{"title":"Confianza","body":"Una presencia premium a la altura de la calidad del trabajo."},{"title":"Solicitudes cualificadas","body":"Presupuesto, plazos y tipo de proyecto conocidos antes de la primera llamada."},{"title":"Tiempo","body":"Menos llamadas imprecisas y menos seguimientos olvidados."}]}'::jsonb, array[]::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.features', 'es', 1, 'active', p.id, null, null, null, 'Funciones', null, '{"section":"features","items":[{"title":"Mostrar","body":"Presentar la actividad y los mejores trabajos con una web premium y rápida."},{"title":"Convertir","body":"Formularios guiados convierten a los visitantes en solicitudes estructuradas."},{"title":"Cualificar","body":"Conocer presupuesto, plazos y tipo de proyecto antes de la llamada."},{"title":"Centralizar","body":"Cada contacto y cada solicitud en un solo lugar, con todo el historial."},{"title":"Reservar","body":"Los prospectos cualificados solicitan una cita en pocos clics."},{"title":"Automatizar","body":"Los correos transaccionales y los seguimientos salen a tiempo."},{"title":"Seguir","body":"Seguir cada solicitud desde la primera visita hasta el cliente firmado."},{"title":"Medir","body":"Ver qué páginas, fuentes y campañas aportan oportunidades reales."}]}'::jsonb, array[]::text[], 104, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.technical', 'es', 1, 'active', p.id, null, null, null, 'Información técnica', null, '{"section":"technical","items":[{"title":"Alojamiento y mantenimiento","body":"Incluidos y gestionados por el equipo de Studio ATS."},{"title":"Integraciones","body":"Integraciones de calendario, correo y analítica. La lista exacta se confirma en la puesta en marcha — no prometa una herramienta concreta."}]}'::jsonb, array[]::text[], 105, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.included', 'es', 1, 'active', p.id, null, null, null, 'Qué incluye', null, '{"section":"included","items":[{"title":"Diseño y puesta en marcha","body":"Diseño y puesta en marcha del Studio ATS del cliente."},{"title":"Portfolio y páginas comerciales","body":"Páginas que presentan el trabajo y la oferta."},{"title":"Captación y cualificación de solicitudes","body":"Formularios guiados y cualificación."},{"title":"Contactos y solicitudes de cita","body":"Centralizados, con el historial."},{"title":"Correos y seguimientos automáticos","body":"Enviados a tiempo."},{"title":"Analítica","body":"Lo que aporta oportunidades reales."},{"title":"Alojamiento y mantenimiento","body":"Gestionados por Studio ATS."}]}'::jsonb, array[]::text[], 106, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.pricing', 'es', 1, 'active', p.id, null, null, null, 'Precios', null, '{"section":"pricing","items":[{"title":"Precio oficial","body":"El precio que se muestra aquí procede del catálogo oficial de Studio ATS. Es igual para todos y los afiliados nunca lo modifican ni lo negocian."},{"title":"Condiciones","body":"Las condiciones definitivas figuran en el contrato del cliente."}]}'::jsonb, array[]::text[], 107, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.faq', 'es', 1, 'active', p.id, null, null, null, 'Preguntas frecuentes', null, '{"section":"faq","items":[{"title":"¿Es solo una web?","body":"No: la web es una parte de un recorrido completo, desde la primera visita hasta la cita."},{"title":"¿Quién lo crea?","body":"El equipo de Studio ATS lo diseña, lo pone en marcha y lo mantiene."},{"title":"¿Puede el cliente conservar sus redes sociales?","body":"Sí. Studio ATS complementa los perfiles sociales."}]}'::jsonb, array[]::text[], 108, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.not_included', 'es', 1, 'draft', p.id, null, null, null, 'Qué no incluye', null, '{"section":"not_included","items":[{"title":"Pendiente de confirmación por Studio ATS","body":"Enumere lo que queda fuera de la oferta antes de publicar esta sección."}]}'::jsonb, array[]::text[], 109, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.limitations', 'es', 1, 'draft', p.id, null, null, null, 'Limitaciones', null, '{"section":"limitations","items":[{"title":"Pendiente de confirmación por Studio ATS","body":"Documente con honestidad las limitaciones conocidas antes de publicar esta sección."}]}'::jsonb, array[]::text[], 110, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'asset', 'studio-public-page', 'es', 1, 'active', p.id, null, null, null, 'Presentación pública de Studio ATS', 'La página oficial del producto — compártala o úsela como demo en directo.', '{"category":"demo","url":"/es/studio","description":"Siempre actualizada: es la página del producto en línea."}'::jsonb, array[]::text[], 200, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'es', 1, 'active', p.id, null, null, null, 'Su primera semana', 'Un plan de acción recomendado — no una promesa de resultados.', '{"disclaimer":"Un plan recomendado para crear una rutina. Los resultados dependen de su trabajo, su mercado y sus prospectos; nada de esto es una promesa de ventas ni de ingresos.","days":[{"day":1,"title":"Entender Studio ATS","body":"Lea el conocimiento del producto y un playbook.","tasks":["Leer qué es Studio ATS y qué incluye","Abrir el playbook de su objetivo"]},{"day":2,"title":"Elegir 20 prospectos","body":"Elija un objetivo y haga una lista de 20 negocios reales cerca de usted.","tasks":["Elegir su objetivo","Añadir 20 prospectos a su CRM"]},{"day":3,"title":"Contactar a sus primeros prospectos","body":"Envíe sus primeros mensajes personalizados.","tasks":["Enviar 5 mensajes de primer contacto","Crear su página de venta para el objetivo"]},{"day":4,"title":"Hacer seguimiento","body":"Haga seguimiento a quienes no han respondido — una vez, brevemente.","tasks":["Enviar los seguimientos","Pasar las respuestas a «Ha respondido»"]},{"day":5,"title":"Hacer llamadas","body":"Use el guion de llamada con quienes han respondido.","tasks":["Hacer al menos una llamada de descubrimiento","Anotar el siguiente paso de cada llamada"]},{"day":6,"title":"Enviar las páginas de venta","body":"Envíe su página a los prospectos cualificados.","tasks":["Enviar su página después de cada llamada","Comprobar que la página se ve bien en el móvil"]},{"day":7,"title":"Hacer balance","body":"Revise qué ha funcionado: qué mensaje, qué objetivo, qué canal.","tasks":["Revisar el rendimiento de su página y sus enlaces","Planificar la semana siguiente"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'pt', 1, 'active', p.id, null, null, null, 'Studio ATS — página de venda padrão', 'Estrutura por defeito de todas as páginas de venda dos afiliados.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Transforme o seu tráfego em oportunidades.","heroSubtitle":"Um estúdio comercial online para profissionais para quem cada novo cliente tem valor real. Apresente o seu trabalho, qualifique pedidos e marque reuniões — num só lugar.","problemTitle":"Um ótimo trabalho. Pedidos perdidos.","problemBody":"Os pedidos chegam por formulário, redes sociais, mensagens e e-mail. Ninguém sabe quais são sérios, os seguimentos são esquecidos e os bons contactos arrefecem.","solutionTitle":"Mais do que um site.","solutionBody":"O site é apenas uma parte. A Studio ATS é todo o percurso, da primeira visita à reunião marcada — concebido, configurado e mantido para si.","valueTitle":"O que recebe realmente","valueItems":["Uma presença que inspira confiança à primeira vista","Pedidos que chegam com a informação certa","Cada contacto e cada pedido num só lugar","Seguimentos enviados a tempo"],"howTitle":"Como funciona","howSteps":[{"title":"Pedido","body":"Fale-nos do seu negócio num formulário curto."},{"title":"Chamada","body":"Qualificamos juntos as suas necessidades."},{"title":"Construção","body":"Concebemos e configuramos a sua Studio ATS."},{"title":"Lançamento","body":"Começa a receber pedidos estruturados."}],"benefitsTitle":"Porque é importante para o seu negócio","benefits":[{"title":"Confiança","body":"Os contactos procuram-no online antes de ligar. Cuide dessa primeira impressão."},{"title":"Tempo","body":"Conheça orçamento, prazos e tipo de projeto antes de pegar no telefone."},{"title":"Nada para gerir","body":"Construído, alojado e mantido pela equipa Studio ATS."}],"includedTitle":"O que está incluído","whoTitle":"Para quem é","whoBody":"Profissionais e empresas cujos clientes valem muito, com uma oferta visual ou premium e pedidos recebidos para converter.","faqTitle":"Perguntas que pode ter","offerTitle":"Uma fórmula. Tudo incluído.","offerNote":"Preço sem IVA, quando aplicável. Condições finais no contrato.","ctaTitle":"Pronto para falar do seu negócio?","ctaBody":"Deixe os seus dados — sem compromisso. Entraremos em contacto para perceber as suas necessidades."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'pt', 1, 'active', p.id, 'artisans', null, null, 'Variante artesãos', null, '{"template":"studio-default","heroTitle":"O seu trabalho é excelente. A sua presença online também deve ser.","heroSubtitle":"Os contactos procuram-no antes de ligar. A Studio ATS dá ao seu negócio uma presença profissional e recolhe pedidos completos — mesmo enquanto está a trabalhar.","problemTitle":"O passa-palavra já não chega.","problemBody":"Quem ainda não o conhece procura-o primeiro online. Se encontrar pouco, liga a outra pessoa — e os pedidos que chegam estão dispersos e incompletos.","ctaTitle":"Vamos olhar juntos para o seu negócio","ctaBody":"Deixe os seus dados e descreva o seu ofício numa linha. Sem compromisso."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'pt', 1, 'active', p.id, null, null, null, 'Gerar mais pedidos qualificados', null, '{"promise":"Pedidos que chegam com orçamento, prazos e detalhes.","heroTitle":"Receba pedidos a que consegue mesmo responder.","heroSubtitle":"A Studio ATS faz as perguntas certas antes da primeira chamada, para que cada pedido chegue com a informação de que precisa."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'pt', 1, 'active', p.id, null, null, null, 'Parecer tão profissional online como é', null, '{"promise":"Uma presença à altura da qualidade do trabalho.","heroTitle":"Seja tão profissional online como na vida real.","heroSubtitle":"Os contactos verificam-no antes de ligar. Dê-lhes uma presença que inspira confiança em segundos."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'pt', 1, 'active', p.id, null, null, null, 'Deixar de perder pedidos', null, '{"promise":"Cada pedido captado e centralizado, mesmo quando está ocupado.","heroTitle":"Deixe de perder pedidos enquanto trabalha.","heroSubtitle":"Cada pedido chega a um só lugar com os detalhes certos — e os seguimentos são enviados a tempo."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'pt', 1, 'active', p.id, null, null, null, 'Vender a Studio ATS — o método', 'Os 10 passos de uma venda Studio ATS, para qualquer alvo. Abra um alvo para incluir os seus problemas e a sua abordagem.', '{"intro":"Venda o resultado, não a tecnologia. O seu trabalho: perceber a situação, mostrar o que perdem hoje e enviar a página certa.","steps":[{"key":"understand","title":"Compreendê-los","body":"Antes de contactar, veja como se apresentam hoje online e como um novo cliente os pode contactar.","bullets":["Veja o site, os perfis sociais e as avaliações","Anote algo concreto de que gosta no trabalho deles"]},{"key":"opening","title":"Abertura","body":"Comece por eles, não pela Studio ATS. Um comentário sincero, uma pergunta.","bullets":["«Descobri o seu trabalho em …»","«Uma pergunta rápida: como é que a maioria dos novos clientes o encontra?»"]},{"key":"discovery","title":"Descoberta","body":"Pergunte e depois ouça. Deixe-os descrever como chegam os pedidos e o que acontece a seguir.","bullets":["Como é que os novos clientes o contactam hoje?","Que informação falta normalmente?","O que acontece quando não consegue responder logo?"]},{"key":"pain","title":"Identificar o problema","body":"Nomeie o problema com as palavras deles. Não invente um problema que não têm."},{"key":"present","title":"Apresentar a Studio ATS","body":"Ligue a Studio ATS ao problema que acabaram de descrever — uma frase, não uma lista de funcionalidades.","bullets":["«É exatamente disso que a Studio ATS trata: …»"]},{"key":"value","title":"Demonstrar o valor","body":"Fale de resultados: confiança, pedidos completos, tempo poupado, nada para gerir. Nunca prometa números."},{"key":"objections","title":"Tratar objeções","body":"Uma objeção é uma pergunta disfarçada. Pergunte o que está por trás antes de responder."},{"key":"offer","title":"Enviar a oferta","body":"Envie a sua página de venda para o setor deles: explica tudo e o preço vem da Studio ATS."},{"key":"follow_up","title":"Fazer seguimento","body":"Sem resposta após alguns dias? Um seguimento curto e útil — depois respeite a resposta."},{"key":"close","title":"Fechar","body":"Combine um próximo passo claro: uma chamada, um pedido na página ou a compra online."}]}'::jsonb, array['método', 'descoberta', 'fecho']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'pt', 1, 'active', p.id, 'artisans', null, null, 'Vender a Studio ATS a um artesão', 'Telefone primeiro, curto, concreto. Os artesãos estão ocupados: respeite o tempo deles.', '{"intro":"Os artesãos compram a quem percebe o ofício deles. Fale dos clientes e do tempo deles — nunca de «sites».","steps":[{"key":"understand","title":"Compreendê-los","body":"Passam a maior parte do dia em obra, conseguem trabalho pelo passa-palavra e atendem chamadas entre dois trabalhos. A reputação é o seu principal trunfo.","bullets":["Procure-os como faria um cliente: o que encontra?","Anote o ofício, a zona e os trabalhos que mostram"]},{"key":"opening","title":"Abertura","body":"Ligue cedo de manhã ou ao fim do dia. Seja breve e concreto.","bullets":["«Procurei-o como faria um cliente — posso dizer-lhe o que reparei? São 2 minutos.»"]},{"key":"discovery","title":"Descoberta","body":"Três perguntas chegam.","bullets":["Como é que a maioria dos novos clientes o encontra?","O que acontece quando alguém que não o conhece o procura?","Quantas chamadas perde enquanto está numa obra?"]},{"key":"pain","title":"Identificar o problema","body":"Normalmente: o passa-palavra tem limites, o negócio parece menos profissional online do que na realidade e perdem-se pedidos."},{"key":"present","title":"Apresentar a Studio ATS","body":"«A Studio ATS dá ao seu negócio uma presença profissional que trabalha enquanto está em obra: as pessoas veem os seus trabalhos e enviam-lhe pedidos completos — trabalho, local, prazo.»"},{"key":"value","title":"Demonstrar o valor","body":"A confiança de quem ainda não o conhece. Pedidos a que responde de uma só vez. Nada para gerir."},{"key":"objections","title":"Tratar objeções","body":"Conte com: «já tenho redes sociais», «os meus clientes vêm pelo passa-palavra», «não tenho tempo»."},{"key":"offer","title":"Enviar a oferta","body":"Envie a sua página para artesãos por SMS ou WhatsApp logo a seguir à chamada, enquanto a conversa está fresca."},{"key":"follow_up","title":"Fazer seguimento","body":"Dois a três dias depois, uma mensagem curta: «Teve tempo de ver? Posso esclarecer alguma dúvida?»"},{"key":"close","title":"Fechar","body":"Proponha o próximo passo: um pedido na página, uma chamada com a equipa Studio ATS ou a compra online quando disponível."}]}'::jsonb, array['artesão', 'telefone', 'passa-palavra', 'redes sociais']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'pt', 1, 'active', p.id, null, 'phone', null, 'Chamada de descoberta (qualquer alvo)', '5 minutos para perceber, qualificar e combinar um próximo passo.', '{"intro":"Assinale cada passo à medida que avança. Fale menos do que eles.","steps":[{"type":"opening","text":"Olá {{firstName}}, fala {{advisorName}}. Estou a ligar sobre a forma como os novos clientes contactam a {{company}} — tem 2 minutos?"},{"type":"question","text":"Como é que a maioria dos seus novos clientes o encontra hoje?"},{"type":"listen","text":"Só passa-palavra? Redes sociais? Pedidos por telefone durante o trabalho?","hint":"Anote as palavras exatas."},{"type":"question","text":"O que acontece quando alguém que não o conhece o procura online?"},{"type":"problem","text":"Encontra pouco, ou os pedidos chegam dispersos e incompletos."},{"type":"response","text":"É disso que a Studio ATS trata: uma presença profissional que inspira confiança e recolhe pedidos completos — construída e mantida para si."},{"type":"objection","text":"«Já tenho redes sociais.»"},{"type":"answer","text":"As redes mostram o seu trabalho. A Studio ATS transforma o interesse num pedido completo. Onde é que as pessoas lhe enviam um pedido hoje?"},{"type":"cta","text":"Posso enviar-lhe a página do seu setor? Explica tudo, incluindo o preço, em 3 minutos."}]}'::jsonb, array['telefone', 'descoberta', 'chamada']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'pt', 1, 'active', p.id, 'artisans', 'phone', null, 'Artesão — primeira chamada', 'Chamada curta entre dois trabalhos.', '{"steps":[{"type":"opening","text":"Olá {{firstName}}, fala {{advisorName}}. Procurei a {{company}} como faria um cliente — posso dizer-lhe o que reparei? Dois minutos."},{"type":"question","text":"A maior parte do seu trabalho vem pelo passa-palavra, certo?"},{"type":"listen","text":"Orgulho na reputação; talvez períodos mais calmos; chamadas perdidas em obra."},{"type":"question","text":"E quando um amigo o recomenda, o que encontra essa pessoa quando o procura?"},{"type":"problem","text":"Pouco ou nada que reflita a qualidade do trabalho — algumas pessoas ligam a outro."},{"type":"response","text":"A Studio ATS dá-lhe uma presença profissional que trabalha enquanto está em obra: as pessoas veem os seus trabalhos e enviam-lhe pedidos completos."},{"type":"objection","text":"«Não tenho tempo para isso.»"},{"type":"answer","text":"É precisamente isso: a equipa Studio ATS constrói e mantém tudo. O senhor só recebe os pedidos."},{"type":"cta","text":"Envio-lhe por SMS a página para artesãos — veja hoje à noite e ligo-lhe na quinta-feira?"}]}'::jsonb, array['artesão', 'telefone', 'passa-palavra']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'pt', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Primeiro contacto — mensagem curta', null, '{"text":"Olá {{firstName}}, descobri a {{company}} e gostei do seu trabalho. Uma pergunta rápida: como é que a maioria dos novos clientes o contacta hoje? Trabalho com a Studio ATS, que ajuda profissionais a transformar o interesse online em pedidos completos. Aqui fica um resumo de 3 minutos para o seu setor: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'pt', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Primeiro contacto — LinkedIn', null, '{"text":"Olá {{firstName}}, gosto do que partilha sobre {{sector}}. Quando alguém quer trabalhar com a {{company}}, para onde o encaminha? Acompanho profissionais na Studio ATS, um espaço que apresenta o trabalho deles e qualifica cada pedido. Aberto a uma vista de olhos rápida?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
