insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-short', 'pt', 1, 'active', p.id, null, 'whatsapp', 'follow_up', 'Seguimento — 3 dias depois', null, '{"text":"Olá {{firstName}}, teve oportunidade de ver a página que lhe enviei? Respondo com gosto a qualquer dúvida em 5 minutos. {{affiliateUrl}}"}'::jsonb, array[]::text[], 33, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'pt', 1, 'active', p.id, null, 'in_person', 'follow_up', 'Depois de um encontro presencial', null, '{"text":"Olá {{firstName}}, foi um prazer conhecê-lo hoje. Como combinado, aqui fica a página Studio ATS para o seu negócio: {{affiliateUrl}}. Diga-me quando lhe dá jeito uma chamada curta. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'pt', 1, 'active', p.id, null, 'other', 'no_response', 'Sem resposta — última mensagem', null, '{"text":"Olá {{firstName}}, não o quero incomodar: não volto a insistir. Se melhorar a forma como os novos clientes contactam a {{company}} se tornar uma prioridade, a página continua disponível: {{affiliateUrl}}. Boa semana."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'pt', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'Depois da chamada — resumo', null, '{"text":"Obrigado pelo seu tempo, {{firstName}}. Em resumo: quer pedidos que cheguem completos e uma presença à imagem da {{company}}. Está tudo explicado aqui, incluindo o preço: {{affiliateUrl}}. Próximo passo, como combinado: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'pt', 1, 'active', p.id, null, 'other', 'interested', 'Interessado — marcar o próximo passo', null, '{"text":"Ótimo, {{firstName}}! O próximo passo mais simples: deixe o seu pedido nesta página para que a equipa Studio ATS prepare a chamada: {{affiliateUrl}}. Que dia lhe dá jeito?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'proposal-send-page', 'pt', 1, 'active', p.id, null, 'other', 'proposal', 'Proposta — enviar a oferta', null, '{"text":"Olá {{firstName}}, como prometido, aqui fica a oferta Studio ATS completa para a {{company}}: o que está incluído, como funciona e o preço oficial. {{affiliateUrl}}"}'::jsonb, array[]::text[], 38, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'pt', 1, 'active', p.id, null, 'other', 'objection', 'Objeção — «Já tenho redes sociais»', null, '{"text":"Compreendo, {{firstName}} — as suas redes mostram bem o seu trabalho. A Studio ATS não as substitui: transforma esse interesse em pedidos completos, num espaço que controla. Onde é que as pessoas lhe enviam um pedido hoje?"}'::jsonb, array['instagram', 'facebook', 'redes sociais', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'closing-checkout', 'pt', 1, 'active', p.id, null, 'other', 'closing', 'Fecho — depois de uma compra iniciada', null, '{"text":"Olá {{firstName}}, vi que estava a ver a Studio ATS. Alguma dúvida antes de decidir? Estou disponível se quiser falar sobre isso."}'::jsonb, array[]::text[], 40, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'pt', 1, 'active', p.id, null, 'email', 'renewal', 'Cliente — contacto amigável', null, '{"text":"Olá {{firstName}}, como está a correr a Studio ATS na {{company}}? Se houver algo a melhorar, diga-me e passo à equipa Studio ATS."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'pt', 1, 'active', p.id, null, 'email', 'first_contact', 'Primeiro contacto', null, '{"subject":"{{company}} — transformar o interesse online em pedidos","preview":"Uma pergunta rápida sobre como os novos clientes o contactam.","body":"Olá {{firstName}},\n\nDescobri a {{company}} e gostei sinceramente do seu trabalho.\n\nUma pergunta rápida: quando alguém o descobre online, o que acontece a seguir? Muitos profissionais recebem pedidos por uma mistura de formulários, redes sociais e mensagens — sem os detalhes de que precisam.\n\nA Studio ATS trata disso: um espaço profissional que apresenta o seu trabalho, qualifica cada pedido e ajuda a marcar a reunião. É construído e mantido para si.\n\nAqui fica um resumo de 3 minutos para o seu setor:","cta":"Ver o resumo"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'pt', 1, 'active', p.id, null, 'email', 'follow_up', 'Seguimento após 3 dias', null, '{"subject":"Re: {{company}} — transformar o interesse online em pedidos","preview":"Volto a pôr esta mensagem no topo da sua caixa.","body":"Olá {{firstName}},\n\nVolto apenas a pôr a minha mensagem no topo. Se pedidos sem os detalhes certos lhe soam familiares, a Studio ATS merece 3 minutos.\n\nSe não for uma prioridade neste momento, não há problema — diga-me e não volto a insistir.","cta":"Ver a página"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'pt', 1, 'active', p.id, null, 'email', 'after_call', 'Depois da chamada — resumo', null, '{"subject":"A nossa conversa — próximos passos para a {{company}}","preview":"O que falámos e o próximo passo.","body":"Olá {{firstName}},\n\nObrigado pelo seu tempo hoje. O que percebi:\n• como os novos clientes o contactam hoje\n• o que gostaria de melhorar\n\nTudo sobre a Studio ATS — o que está incluído, como funciona e o preço oficial — está nesta página:","cta":"Abrir a minha página Studio ATS"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'pt', 1, 'active', p.id, null, 'email', 'proposal', 'Proposta', null, '{"subject":"A oferta Studio ATS para a {{company}}","preview":"Tudo numa página, incluindo o preço.","body":"Olá {{firstName}},\n\nComo prometido, aqui fica a oferta Studio ATS completa para a {{company}}. Encontra o que está incluído, como decorre a configuração e o preço e as condições oficiais.\n\nFico ao dispor para qualquer dúvida.","cta":"Ver a oferta"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'pt', 1, 'active', p.id, null, 'email', 'objection', 'As redes sociais não chegam', null, '{"subject":"As suas redes mostram o seu trabalho. Trazem-lhe pedidos?","preview":"Porque é que as redes sociais e a Studio ATS se complementam.","body":"Olá {{firstName}},\n\nAs suas redes mostram bem o seu trabalho — mantenha-as. A questão é o que acontece depois do interesse: uma mensagem perdida entre outras, um pedido sem detalhes, uma chamada que não pode atender.\n\nA Studio ATS é o lugar onde esse interesse se torna um pedido completo, num espaço que controla. Complementa os seus perfis sociais; não os substitui.","cta":"Ver como funciona"}'::jsonb, array['instagram', 'facebook', 'redes sociais', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'pt', 1, 'active', p.id, null, 'email', 'no_response', 'Último seguimento', null, '{"subject":"Posso fechar o seu processo?","preview":"Uma última mensagem — depois paro.","body":"Olá {{firstName}},\n\nComo não tive notícias suas, presumo que não seja o momento certo — não volto a insistir.\n\nSe as coisas mudarem, a página continua disponível.","cta":"Guardar a página"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'pt', 1, 'active', p.id, null, null, 'objection', '«Já tenho redes sociais.»', null, '{"objection":"«Já tenho redes sociais.»","meaning":"As redes parecem visibilidade suficiente — ou não veem o que falta.","questions":["Onde é que as pessoas lhe enviam um pedido hoje?","O que acontece a um pedido que chega num sábado à noite?"],"short":"As redes mostram o seu trabalho. A Studio ATS transforma esse interesse em pedidos completos, num espaço que controla.","long":"Mantenha as suas redes: são ótimas para mostrar o seu trabalho. Mas uma mensagem privada não é um pedido — sem orçamento, sem prazo, perdida entre outras mensagens, e é a plataforma que decide quem o vê. A Studio ATS é o espaço profissional onde o interesse se torna um pedido completo a que responde de uma só vez.","nextStep":"Envie a página de venda e proponha que a comparem com o perfil deles."}'::jsonb, array['instagram', 'facebook', 'redes sociais', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'pt', 1, 'active', p.id, null, null, 'objection', '«Os meus clientes vêm pelo passa-palavra.»', null, '{"objection":"«Os meus clientes vêm pelo passa-palavra.»","meaning":"Têm orgulho na reputação — e não veem a ligação com estar online.","questions":["Quando um amigo o recomenda, o que faz essa pessoa antes de ligar?","Há períodos mais calmos durante o ano?"],"short":"O passa-palavra traz-lhe pessoas. A Studio ATS garante que lhe ligam depois de o procurarem.","long":"É sinal de um excelente trabalho. Mas hoje até um cliente recomendado verifica online antes de ligar. Se encontrar pouco, alguns hesitam ou ligam a outro. A Studio ATS não substitui o passa-palavra: confirma-o.","nextStep":"Sugira que se procurem a si próprios como faria um cliente."}'::jsonb, array['passa-palavra', 'word of mouth', 'recomendações', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'pt', 1, 'active', p.id, null, null, 'objection', '«Não preciso de vender online.»', null, '{"objection":"«Não preciso de vender online.»","meaning":"Pensam que a Studio ATS é uma loja online.","questions":["Como é que um novo cliente o contacta hoje?","O que precisa de saber antes de fazer um orçamento?"],"short":"A Studio ATS não é uma loja online: ajuda quem ainda não o conhece a confiar em si e a enviar-lhe um pedido a sério.","long":"Não vende online — vende pela conversa e pelo orçamento. A Studio ATS prepara essas conversas: as pessoas veem o seu trabalho, percebem o que faz e enviam um pedido com os detalhes certos. A venda continua a acontecer consigo.","nextStep":"Mostre a secção «Como funciona» da página de venda."}'::jsonb, array['comércio eletrónico', 'vender online', 'sell online', 'loja']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'pt', 1, 'active', p.id, null, null, 'objection', '«Não vou ter tempo para responder.»', null, '{"objection":"«Não vou ter tempo para responder.»","meaning":"Receiam mais trabalho ou mais burocracia.","questions":["Quanto tempo passa hoje em chamadas que não levam a nada?","O que o ajudaria a responder mais depressa?"],"short":"A Studio ATS foi feita para poupar tempo: os pedidos chegam completos, por isso responde uma só vez.","long":"É precisamente para pessoas ocupadas. A equipa Studio ATS constrói e mantém tudo. Os pedidos chegam com os detalhes necessários, num só lugar: deixa de perder tempo a correr atrás de informação ou a devolver chamadas vagas.","nextStep":"Ofereça-se para enviar a página para que a vejam à noite."}'::jsonb, array['tempo', 'time', 'ocupado', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'pt', 1, 'active', p.id, null, null, 'objection', '«É demasiado caro.»', null, '{"objection":"«É demasiado caro.»","meaning":"Comparam com um site barato, ou ainda não veem o valor.","questions":["Quanto vale para si um novo cliente?","Está a comparar com quê?"],"short":"Compare com o valor dos clientes que o ajuda a conquistar — não com o preço de um site básico.","long":"A Studio ATS não é um site básico: é todo o percurso da primeira visita ao pedido, construído e mantido para si. Muitos profissionais veem assim: quanto vale um único novo cliente? O preço é oficial e igual para todos — não vai conseguir melhor a negociar noutro lado.","nextStep":"Nunca faça descontos nem prometa resultados. Envie a secção da oferta da página."}'::jsonb, array['preço', 'price', 'caro', 'expensive', 'orçamento']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'pt', 1, 'active', p.id, null, null, 'objection', '«Já tenho um site.»', null, '{"objection":"«Já tenho um site.»","meaning":"Acham que faz o mesmo trabalho.","questions":["Quantos pedidos lhe traz por mês?","O que acontece depois de alguém preencher o seu formulário?"],"short":"Mantenha-o se funciona. A Studio ATS trata do que um site raramente faz: qualificar pedidos e facilitar reuniões.","long":"Um site apresenta; a Studio ATS converte. A questão não é ter um site, mas se ele transforma visitantes em pedidos completos e reuniões. Se o seu já o faz, ótimo. Se não, é exatamente essa a parte de que a Studio ATS trata.","nextStep":"Proponha ver juntos o formulário de contacto atual."}'::jsonb, array['site', 'website', 'já tenho site', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'pt', 1, 'active', p.id, null, null, 'objection', '«Tenho de pensar.»', null, '{"objection":"«Tenho de pensar.»","meaning":"Algo não está claro, ou não é o momento certo.","questions":["O que precisaria de saber para decidir?","É o momento, o orçamento ou outra coisa?"],"short":"Claro. Qual é a única coisa que precisaria de esclarecer para decidir?","long":"Tirar tempo é normal. Normalmente fica uma pergunta em aberto — preço, calendário ou como funcionaria no caso deles. Pergunte qual, responda com precisão e combinem uma data para voltar a falar.","nextStep":"Combine uma data de seguimento e registe-a no seu CRM."}'::jsonb, array['pensar', 'think', 'mais tarde', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'pt', 1, 'active', p.id, null, null, 'objection', '«Agora não.»', null, '{"objection":"«Agora não.»","meaning":"Época alta, ou outras prioridades.","questions":["Quando seria um melhor momento?","Qual é a sua época mais calma?"],"short":"Entendido — quando faria sentido voltarmos a falar?","long":"Respeite e planeie: o melhor momento para pôr a Studio ATS a funcionar é muitas vezes pouco antes de uma época movimentada, para estar a funcionar quando os pedidos chegam. Pergunte quando voltar a contactar e registe.","nextStep":"Programe um lembrete no CRM — sem nunca insistir."}'::jsonb, array['agora não', 'not now', 'timing', 'época']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'pt', 1, 'active', p.id, null, null, null, 'O que é', null, '{"section":"what_it_is","items":[{"title":"Um estúdio comercial online","body":"A Studio ATS é um estúdio comercial online para profissionais para quem cada novo cliente tem valor real: apresenta o trabalho deles, qualifica pedidos e ajuda a marcar reuniões — num só lugar."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'pt', 1, 'active', p.id, null, null, null, 'O que faz', null, '{"section":"what_it_does","items":[{"title":"Da primeira visita à reunião marcada","body":"O site é apenas uma parte. A Studio ATS cobre todo o percurso: montra, pedido, qualificação, reunião e seguimento."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.customer_gets', 'pt', 1, 'active', p.id, null, null, null, 'O que o cliente recebe', null, '{"section":"customer_gets","items":[{"title":"Chave na mão","body":"A equipa Studio ATS concebe, configura, aloja e mantém. O cliente recebe pedidos estruturados."},{"title":"Um só lugar","body":"Cada contacto e cada pedido num só lugar, com histórico."}]}'::jsonb, array[]::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.benefits', 'pt', 1, 'active', p.id, null, null, null, 'Benefícios para o negócio', null, '{"section":"benefits","items":[{"title":"Confiança","body":"Uma presença premium à altura da qualidade do trabalho."},{"title":"Pedidos qualificados","body":"Orçamento, prazos e tipo de projeto conhecidos antes da primeira chamada."},{"title":"Tempo","body":"Menos chamadas vagas e menos seguimentos esquecidos."}]}'::jsonb, array[]::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.features', 'pt', 1, 'active', p.id, null, null, null, 'Funcionalidades', null, '{"section":"features","items":[{"title":"Mostrar","body":"Apresentar a atividade e os melhores trabalhos com um site premium e rápido."},{"title":"Converter","body":"Formulários guiados transformam visitantes em pedidos estruturados."},{"title":"Qualificar","body":"Conhecer orçamento, prazos e tipo de projeto antes da chamada."},{"title":"Centralizar","body":"Cada contacto e cada pedido num só lugar, com todo o histórico."},{"title":"Marcar","body":"Os contactos qualificados pedem uma reunião em poucos cliques."},{"title":"Automatizar","body":"E-mails transacionais e seguimentos enviados a tempo."},{"title":"Acompanhar","body":"Acompanhar cada pedido da primeira visita ao cliente com contrato assinado."},{"title":"Medir","body":"Ver que páginas, fontes e campanhas trazem oportunidades reais."}]}'::jsonb, array[]::text[], 104, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.technical', 'pt', 1, 'active', p.id, null, null, null, 'Informação técnica', null, '{"section":"technical","items":[{"title":"Alojamento e manutenção","body":"Incluídos e tratados pela equipa Studio ATS."},{"title":"Integrações","body":"Integrações de calendário, e-mail e análises. A lista exata é confirmada no arranque — não prometa uma ferramenta específica."}]}'::jsonb, array[]::text[], 105, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
