insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.pricing', 'pt', 1, 'active', p.id, null, null, null, 'Preços', null, '{"section":"pricing","items":[{"title":"Preço oficial","body":"O preço aqui apresentado vem do catálogo oficial da Studio ATS. É igual para todos e os afiliados nunca o alteram nem o negociam."},{"title":"Condições","body":"As condições finais constam do contrato do cliente."}]}'::jsonb, array[]::text[], 107, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.faq', 'pt', 1, 'active', p.id, null, null, null, 'Perguntas frequentes', null, '{"section":"faq","items":[{"title":"É apenas um site?","body":"Não: o site é uma parte de um percurso completo, da primeira visita à reunião."},{"title":"Quem o constrói?","body":"A equipa Studio ATS concebe, configura e mantém."},{"title":"O cliente pode manter as redes sociais?","body":"Sim. A Studio ATS complementa os perfis sociais."}]}'::jsonb, array[]::text[], 108, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
