insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'pt', 1, 'active', p.id, null, null, null, 'A sua primeira semana', 'Um plano de ação recomendado — não uma promessa de resultados.', '{"disclaimer":"Um plano recomendado para criar uma rotina. Os resultados dependem do seu trabalho, do seu mercado e dos seus contactos; nada aqui é uma promessa de vendas ou de rendimento.","days":[{"day":1,"title":"Perceber a Studio ATS","body":"Leia o conhecimento do produto e um playbook.","tasks":["Ler o que é a Studio ATS e o que está incluído","Abrir o playbook do seu alvo"]},{"day":2,"title":"Escolher 20 contactos","body":"Escolha um alvo e faça uma lista de 20 negócios reais perto de si.","tasks":["Escolher o seu alvo","Adicionar 20 contactos ao seu CRM"]},{"day":3,"title":"Contactar os primeiros contactos","body":"Envie as suas primeiras mensagens personalizadas.","tasks":["Enviar 5 mensagens de primeiro contacto","Criar a sua página de venda para o alvo"]},{"day":4,"title":"Fazer seguimento","body":"Faça seguimento de quem não respondeu — uma vez, de forma breve.","tasks":["Enviar os seguimentos","Passar as respostas para «Respondeu»"]},{"day":5,"title":"Fazer chamadas","body":"Use o guião de chamada com quem respondeu.","tasks":["Fazer pelo menos uma chamada de descoberta","Registar o próximo passo de cada chamada"]},{"day":6,"title":"Enviar as páginas de venda","body":"Envie a sua página aos contactos qualificados.","tasks":["Enviar a sua página depois de cada chamada","Verificar se a página fica bem no telemóvel"]},{"day":7,"title":"Fazer o balanço","body":"Veja o que funcionou: que mensagem, que alvo, que canal.","tasks":["Rever o desempenho da sua página e dos seus links","Planear a semana seguinte"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'it', 1, 'active', p.id, null, null, null, 'Studio ATS — pagina di vendita standard', 'Struttura predefinita di tutte le pagine di vendita degli affiliati.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Trasforma il tuo traffico in opportunità.","heroSubtitle":"Uno studio commerciale online per professionisti per cui ogni nuovo cliente ha un valore reale. Presenta il tuo lavoro, qualifica le richieste e fissa appuntamenti — in un unico posto.","problemTitle":"Un ottimo lavoro. Richieste perse.","problemBody":"Le richieste arrivano da modulo, social network, messaggi ed e-mail. Nessuno sa quali sono serie, i follow-up vengono dimenticati e i buoni contatti si raffreddano.","solutionTitle":"Più di un sito web.","solutionBody":"Il sito è solo una parte. Studio ATS è l’intero percorso, dalla prima visita all’appuntamento fissato — progettato, configurato e mantenuto per te.","valueTitle":"Cosa ottieni davvero","valueItems":["Una presenza che ispira fiducia al primo sguardo","Richieste che arrivano con le informazioni giuste","Ogni contatto e ogni richiesta in un unico posto","Follow-up inviati al momento giusto"],"howTitle":"Come funziona","howSteps":[{"title":"Richiesta","body":"Raccontaci la tua attività in un breve modulo."},{"title":"Chiamata","body":"Definiamo insieme le tue esigenze."},{"title":"Realizzazione","body":"Progettiamo e configuriamo il tuo Studio ATS."},{"title":"Lancio","body":"Inizi a ricevere richieste strutturate."}],"benefitsTitle":"Perché conta per la tua attività","benefits":[{"title":"Fiducia","body":"I contatti ti cercano online prima di chiamare. Cura quella prima impressione."},{"title":"Tempo","body":"Conosci budget, tempi e tipo di progetto prima di alzare il telefono."},{"title":"Niente da gestire","body":"Costruito, ospitato e mantenuto dal team Studio ATS."}],"includedTitle":"Cosa è incluso","whoTitle":"Per chi è","whoBody":"Professionisti e aziende i cui clienti valgono molto, con un’offerta visiva o premium e richieste in arrivo da convertire.","faqTitle":"Domande che potresti avere","offerTitle":"Un’unica formula. Tutto incluso.","offerNote":"Prezzo IVA esclusa ove applicabile. Condizioni definitive nel contratto.","ctaTitle":"Pronto a parlare della tua attività?","ctaBody":"Lascia i tuoi dati — senza impegno. Ti ricontatteremo per capire le tue esigenze."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'it', 1, 'active', p.id, 'artisans', null, null, 'Variante artigiani', null, '{"template":"studio-default","heroTitle":"Il tuo lavoro è eccellente. Anche la tua presenza online dovrebbe esserlo.","heroSubtitle":"I contatti ti cercano prima di chiamare. Studio ATS dà alla tua attività una presenza professionale e raccoglie richieste complete — anche mentre sei al lavoro.","problemTitle":"Il passaparola non basta più.","problemBody":"Chi non ti conosce ancora ti cerca prima online. Se trova poco, chiama qualcun altro — e le richieste che arrivano sono sparse e incomplete.","ctaTitle":"Guardiamo insieme la tua attività","ctaBody":"Lascia i tuoi dati e descrivi il tuo mestiere in una riga. Senza impegno."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'it', 1, 'active', p.id, null, null, null, 'Generare più richieste qualificate', null, '{"promise":"Richieste che arrivano con budget, tempi e dettagli.","heroTitle":"Ricevi richieste a cui puoi davvero rispondere.","heroSubtitle":"Studio ATS fa le domande giuste prima della prima chiamata, così ogni richiesta arriva con le informazioni che ti servono."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'it', 1, 'active', p.id, null, null, null, 'Apparire online professionale come sei', null, '{"promise":"Una presenza all’altezza della qualità del lavoro.","heroTitle":"Sii professionale online come nella realtà.","heroSubtitle":"I contatti ti controllano prima di chiamare. Offri loro una presenza che ispira fiducia in pochi secondi."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'it', 1, 'active', p.id, null, null, null, 'Smettere di perdere richieste', null, '{"promise":"Ogni richiesta raccolta e centralizzata, anche quando sei impegnato.","heroTitle":"Smetti di perdere richieste mentre lavori.","heroSubtitle":"Ogni richiesta arriva in un unico posto con i dettagli giusti — e i follow-up partono al momento giusto."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'it', 1, 'active', p.id, null, null, null, 'Vendere Studio ATS — il metodo', 'I 10 passaggi di una vendita Studio ATS, per qualsiasi target. Apri un target per inserirne problemi e approccio.', '{"intro":"Vendi il risultato, non la tecnologia. Il tuo compito: capire la loro situazione, mostrare cosa perdono oggi e inviare la pagina giusta.","steps":[{"key":"understand","title":"Capirli","body":"Prima di contattarli, guarda come si presentano oggi online e come un nuovo cliente può raggiungerli.","bullets":["Controlla sito, profili social e recensioni","Annota una cosa precisa che ti piace del loro lavoro"]},{"key":"opening","title":"Apertura","body":"Parti da loro, non da Studio ATS. Un’osservazione sincera, una domanda.","bullets":["«Ho visto il vostro lavoro su …»","«Una domanda veloce: come vi trovano la maggior parte dei nuovi clienti?»"]},{"key":"discovery","title":"Scoperta","body":"Fai domande, poi ascolta. Lascia che descrivano come arrivano le richieste e cosa succede dopo.","bullets":["Come vi contattano oggi i nuovi clienti?","Quale informazione manca di solito?","Cosa succede quando non potete rispondere subito?"]},{"key":"pain","title":"Individuare il problema","body":"Dai un nome al problema con le loro parole. Non inventarne uno che non hanno."},{"key":"present","title":"Presentare Studio ATS","body":"Collega Studio ATS al problema che hanno appena descritto — una frase, non un elenco di funzioni.","bullets":["«È esattamente ciò di cui si occupa Studio ATS: …»"]},{"key":"value","title":"Dimostrare il valore","body":"Parla di risultati: fiducia, richieste complete, tempo risparmiato, niente da gestire. Non promettere mai numeri."},{"key":"objections","title":"Gestire le obiezioni","body":"Un’obiezione è una domanda travestita. Chiedi cosa c’è dietro prima di rispondere."},{"key":"offer","title":"Inviare l’offerta","body":"Invia la tua pagina di vendita per il loro settore: spiega tutto e il prezzo lo stabilisce Studio ATS."},{"key":"follow_up","title":"Fare follow-up","body":"Nessuna risposta dopo qualche giorno? Un follow-up breve e utile — poi rispetta la loro risposta."},{"key":"close","title":"Chiudere","body":"Concorda un passo successivo chiaro: una chiamata, una richiesta sulla pagina o l’acquisto online."}]}'::jsonb, array['metodo', 'scoperta', 'chiusura']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'it', 1, 'active', p.id, 'artisans', null, null, 'Vendere Studio ATS a un artigiano', 'Prima il telefono, breve e concreto. Gli artigiani sono impegnati: rispetta il loro tempo.', '{"intro":"Gli artigiani comprano da chi capisce il loro mestiere. Parla dei loro clienti e del loro tempo — mai di «siti web».","steps":[{"key":"understand","title":"Capirli","body":"Passano gran parte della giornata in cantiere, lavorano col passaparola e rispondono al telefono tra un intervento e l’altro. La reputazione è il loro patrimonio principale.","bullets":["Cercali come farebbe un cliente: cosa trovi?","Annota mestiere, zona e lavori che mostrano"]},{"key":"opening","title":"Apertura","body":"Chiama al mattino presto o a fine giornata. Sii breve e preciso.","bullets":["«Vi ho cercato come farebbe un cliente — posso dirvi cosa ho notato? Due minuti.»"]},{"key":"discovery","title":"Scoperta","body":"Bastano tre domande.","bullets":["Come vi trovano la maggior parte dei nuovi clienti?","Cosa succede quando qualcuno che non vi conosce vi cerca?","Quante chiamate perdete durante un lavoro?"]},{"key":"pain","title":"Individuare il problema","body":"Di solito: il passaparola ha dei limiti, l’attività sembra meno professionale online che nella realtà, le richieste si perdono."},{"key":"present","title":"Presentare Studio ATS","body":"«Studio ATS dà alla vostra attività una presenza professionale che lavora mentre siete in cantiere: le persone vedono i vostri lavori e vi inviano richieste complete — lavoro, luogo, tempi.»"},{"key":"value","title":"Dimostrare il valore","body":"La fiducia di chi non vi conosce ancora. Richieste a cui si risponde in una volta. Niente da gestire in prima persona."},{"key":"objections","title":"Gestire le obiezioni","body":"Aspettati: «ho già i social», «i miei clienti arrivano col passaparola», «non ho tempo»."},{"key":"offer","title":"Inviare l’offerta","body":"Invia la tua pagina per artigiani via SMS o WhatsApp subito dopo la chiamata, finché la conversazione è fresca."},{"key":"follow_up","title":"Fare follow-up","body":"Due o tre giorni dopo, un messaggio breve: «Avete avuto tempo di guardare? Posso rispondere a qualche domanda?»"},{"key":"close","title":"Chiudere","body":"Proponi il passo successivo: una richiesta sulla pagina, una chiamata con il team Studio ATS o l’acquisto online quando disponibile."}]}'::jsonb, array['artigiano', 'telefono', 'passaparola', 'social network']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'it', 1, 'active', p.id, null, 'phone', null, 'Chiamata conoscitiva (qualsiasi target)', '5 minuti per capire, qualificare e concordare un passo successivo.', '{"intro":"Spunta ogni passaggio man mano. Parla meno di loro.","steps":[{"type":"opening","text":"Buongiorno {{firstName}}, sono {{advisorName}}. La chiamo per parlare di come i nuovi clienti contattano {{company}} — ha 2 minuti?"},{"type":"question","text":"Come la trovano oggi la maggior parte dei suoi nuovi clienti?"},{"type":"listen","text":"Solo passaparola? Social? Richieste al telefono mentre lavora?","hint":"Annota le loro parole esatte."},{"type":"question","text":"Cosa succede quando qualcuno che non la conosce la cerca online?"},{"type":"problem","text":"Trova poco, oppure le richieste arrivano sparse e incomplete."},{"type":"response","text":"È ciò di cui si occupa Studio ATS: una presenza professionale che ispira fiducia e raccoglie richieste complete — costruita e mantenuta per lei."},{"type":"objection","text":"«Ho già i social.»"},{"type":"answer","text":"I social mostrano il suo lavoro. Studio ATS trasforma l’interesse in una richiesta completa. Oggi dove le inviano una richiesta?"},{"type":"cta","text":"Posso inviarle la pagina del suo settore? Spiega tutto, prezzo incluso, in 3 minuti."}]}'::jsonb, array['telefono', 'scoperta', 'chiamata']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'it', 1, 'active', p.id, 'artisans', 'phone', null, 'Artigiano — prima chiamata', 'Chiamata breve tra due lavori.', '{"steps":[{"type":"opening","text":"Buongiorno {{firstName}}, sono {{advisorName}}. Ho cercato {{company}} come farebbe un cliente — posso dirle cosa ho notato? Due minuti."},{"type":"question","text":"La maggior parte del suo lavoro arriva dal passaparola, giusto?"},{"type":"listen","text":"Orgoglio per la reputazione; forse periodi più calmi; chiamate perse in cantiere."},{"type":"question","text":"E quando un amico la consiglia, cosa trova quella persona quando la cerca?"},{"type":"problem","text":"Poco o nulla che rifletta la qualità del lavoro — alcuni chiamano qualcun altro."},{"type":"response","text":"Studio ATS le dà una presenza professionale che lavora mentre lei è in cantiere: le persone vedono i suoi lavori e le inviano richieste complete."},{"type":"objection","text":"«Non ho tempo per queste cose.»"},{"type":"answer","text":"Proprio per questo: il team Studio ATS lo costruisce e lo mantiene. Lei riceve semplicemente le richieste."},{"type":"cta","text":"Le mando via SMS la pagina per artigiani — ci dà un’occhiata stasera e la richiamo giovedì?"}]}'::jsonb, array['artigiano', 'telefono', 'passaparola']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'it', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Primo contatto — messaggio breve', null, '{"text":"Buongiorno {{firstName}}, ho scoperto {{company}} e mi è piaciuto il vostro lavoro. Una domanda veloce: come vi contattano oggi la maggior parte dei nuovi clienti? Lavoro con Studio ATS, che aiuta i professionisti a trasformare l’interesse online in richieste complete. Ecco una panoramica di 3 minuti per il vostro settore: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'it', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Primo contatto — LinkedIn', null, '{"text":"Buongiorno {{firstName}}, apprezzo ciò che condivide su {{sector}}. Quando qualcuno vuole lavorare con {{company}}, dove lo indirizza? Accompagno i professionisti su Studio ATS, uno spazio che presenta il loro lavoro e qualifica ogni richiesta. Le va di dare un’occhiata?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-sms-artisan', 'it', 1, 'active', p.id, 'artisans', 'sms', 'first_contact', 'Artigiano — primo SMS dopo una chiamata', null, '{"text":"Buongiorno {{firstName}}, grazie per la chiacchierata. Come promesso, la pagina per artigiani (3 min): {{affiliateUrl}} — {{advisorName}}"}'::jsonb, array[]::text[], 32, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-short', 'it', 1, 'active', p.id, null, 'whatsapp', 'follow_up', 'Follow-up — 3 giorni dopo', null, '{"text":"Buongiorno {{firstName}}, ha avuto modo di guardare la pagina che le ho inviato? Rispondo volentieri a qualsiasi domanda in 5 minuti. {{affiliateUrl}}"}'::jsonb, array[]::text[], 33, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'it', 1, 'active', p.id, null, 'in_person', 'follow_up', 'Dopo un incontro di persona', null, '{"text":"Buongiorno {{firstName}}, è stato un piacere conoscerla oggi. Come concordato, ecco la pagina Studio ATS per la sua attività: {{affiliateUrl}}. Mi dica quando le va bene una breve chiamata. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'it', 1, 'active', p.id, null, 'other', 'no_response', 'Nessuna risposta — ultimo messaggio', null, '{"text":"Buongiorno {{firstName}}, non voglio disturbarla: non la ricontatterò più. Se migliorare il modo in cui i nuovi clienti contattano {{company}} diventerà una priorità, la pagina resta disponibile: {{affiliateUrl}}. Buona settimana."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'it', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'Dopo la chiamata — riepilogo', null, '{"text":"Grazie per il suo tempo, {{firstName}}. In sintesi: desidera richieste che arrivino complete e una presenza che rispecchi {{company}}. Qui è spiegato tutto, prezzo incluso: {{affiliateUrl}}. Prossimo passo come concordato: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'it', 1, 'active', p.id, null, 'other', 'interested', 'Interessato — fissare il passo successivo', null, '{"text":"Perfetto, {{firstName}}! Il passo più semplice: lasci la sua richiesta su questa pagina così il team Studio ATS può preparare la chiamata: {{affiliateUrl}}. Che giorno le va bene?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'proposal-send-page', 'it', 1, 'active', p.id, null, 'other', 'proposal', 'Proposta — inviare l’offerta', null, '{"text":"Buongiorno {{firstName}}, come promesso, ecco l’offerta completa di Studio ATS per {{company}}: cosa è incluso, come funziona e il prezzo ufficiale. {{affiliateUrl}}"}'::jsonb, array[]::text[], 38, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'it', 1, 'active', p.id, null, 'other', 'objection', 'Obiezione — «Ho già i social»', null, '{"text":"La capisco, {{firstName}} — i suoi social mostrano bene il suo lavoro. Studio ATS non li sostituisce: trasforma quell’interesse in richieste complete, in uno spazio che controlla lei. Oggi dove le inviano una richiesta?"}'::jsonb, array['instagram', 'facebook', 'social network', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'closing-checkout', 'it', 1, 'active', p.id, null, 'other', 'closing', 'Chiusura — dopo un acquisto iniziato', null, '{"text":"Buongiorno {{firstName}}, ho visto che stava guardando Studio ATS. Ha qualche domanda prima di decidere? Sono disponibile se vuole parlarne."}'::jsonb, array[]::text[], 40, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'it', 1, 'active', p.id, null, 'email', 'renewal', 'Cliente — un saluto', null, '{"text":"Buongiorno {{firstName}}, come sta andando Studio ATS per {{company}}? Se qualcosa si può migliorare, me lo dica e lo riferirò al team Studio ATS."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'it', 1, 'active', p.id, null, 'email', 'first_contact', 'Primo contatto', null, '{"subject":"{{company}} — trasformare l’interesse online in richieste","preview":"Una domanda veloce su come la contattano i nuovi clienti.","body":"Buongiorno {{firstName}},\n\nho scoperto {{company}} e il vostro lavoro mi è piaciuto davvero.\n\nUna domanda veloce: quando qualcuno vi scopre online, cosa succede dopo? Molti professionisti ricevono richieste da un mix di moduli, social e messaggi — senza i dettagli di cui hanno bisogno.\n\nStudio ATS se ne occupa: uno spazio professionale che presenta il vostro lavoro, qualifica ogni richiesta e aiuta a fissare l’appuntamento. Viene costruito e mantenuto per voi.\n\nEcco una panoramica di 3 minuti per il vostro settore:","cta":"Vedi la panoramica"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'it', 1, 'active', p.id, null, 'email', 'follow_up', 'Follow-up dopo 3 giorni', null, '{"subject":"Re: {{company}} — trasformare l’interesse online in richieste","preview":"Riporto questo messaggio in cima alla sua casella.","body":"Buongiorno {{firstName}},\n\nriporto semplicemente in alto il mio messaggio. Se le richieste che arrivano senza i dettagli giusti le suonano familiari, Studio ATS vale 3 minuti.\n\nSe ora non è una priorità, nessun problema — me lo dica e non la ricontatterò.","cta":"Vedi la pagina"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'it', 1, 'active', p.id, null, 'email', 'after_call', 'Dopo la chiamata — riepilogo', null, '{"subject":"La nostra chiamata — prossimi passi per {{company}}","preview":"Cosa ci siamo detti e il prossimo passo.","body":"Buongiorno {{firstName}},\n\ngrazie per il tempo che mi ha dedicato oggi. Ciò che ho capito:\n• come la contattano oggi i nuovi clienti\n• cosa vorrebbe migliorare\n\nTutto su Studio ATS — cosa è incluso, come funziona e il prezzo ufficiale — è su questa pagina:","cta":"Apri la mia pagina Studio ATS"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'it', 1, 'active', p.id, null, 'email', 'proposal', 'Proposta', null, '{"subject":"L’offerta Studio ATS per {{company}}","preview":"Tutto in una pagina, prezzo incluso.","body":"Buongiorno {{firstName}},\n\ncome promesso, ecco l’offerta completa di Studio ATS per {{company}}. Troverà cosa è incluso, come si svolge la configurazione e il prezzo e le condizioni ufficiali.\n\nResto a disposizione per qualsiasi domanda.","cta":"Vedi l’offerta"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'it', 1, 'active', p.id, null, 'email', 'objection', 'I social non bastano', null, '{"subject":"I suoi social mostrano il suo lavoro. Le portano richieste?","preview":"Perché social e Studio ATS sono complementari.","body":"Buongiorno {{firstName}},\n\ni suoi social mostrano bene il suo lavoro — li tenga. La questione è cosa succede dopo l’interesse: un messaggio perso tra tanti, una richiesta senza dettagli, una chiamata a cui non può rispondere.\n\nStudio ATS è il luogo in cui quell’interesse diventa una richiesta completa, in uno spazio che controlla lei. Completa i suoi profili social; non li sostituisce.","cta":"Scopri come funziona"}'::jsonb, array['instagram', 'facebook', 'social network', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'it', 1, 'active', p.id, null, 'email', 'no_response', 'Ultimo follow-up', null, '{"subject":"Chiudo la sua pratica?","preview":"Un ultimo messaggio — poi mi fermo.","body":"Buongiorno {{firstName}},\n\nnon avendo sue notizie, immagino non sia il momento giusto — non la ricontatterò più.\n\nSe le cose cambiano, la pagina resta disponibile.","cta":"Conserva la pagina"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'it', 1, 'active', p.id, null, null, 'objection', '«Ho già i social.»', null, '{"objection":"«Ho già i social.»","meaning":"I social sembrano una visibilità sufficiente — oppure non vedono cosa manca.","questions":["Oggi dove le inviano una richiesta?","Che fine fa una richiesta che arriva il sabato sera?"],"short":"I social mostrano il suo lavoro. Studio ATS trasforma quell’interesse in richieste complete, in uno spazio che controlla lei.","long":"Tenga i suoi social: sono ottimi per mostrare il suo lavoro. Ma un messaggio privato non è una richiesta — niente budget, niente tempi, perso tra altri messaggi, ed è la piattaforma a decidere chi la vede. Studio ATS è lo spazio professionale in cui l’interesse diventa una richiesta completa, a cui si risponde in una volta.","nextStep":"Invia la pagina di vendita e proponi di confrontarla con il loro profilo."}'::jsonb, array['instagram', 'facebook', 'social network', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'it', 1, 'active', p.id, null, null, 'objection', '«I miei clienti arrivano col passaparola.»', null, '{"objection":"«I miei clienti arrivano col passaparola.»","meaning":"Sono orgogliosi della loro reputazione — e non vedono il legame con la presenza online.","questions":["Quando un amico la consiglia, cosa fa quella persona prima di chiamare?","Ci sono periodi più calmi durante l’anno?"],"short":"Il passaparola le porta le persone. Studio ATS fa sì che la chiamino dopo averla cercata.","long":"È il segno di un ottimo lavoro. Ma oggi anche un cliente consigliato controlla online prima di chiamare. Se trova poco, qualcuno esita o chiama qualcun altro. Studio ATS non sostituisce il passaparola: lo conferma.","nextStep":"Suggerisci di cercarsi da soli come farebbe un cliente."}'::jsonb, array['passaparola', 'word of mouth', 'raccomandazioni', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'it', 1, 'active', p.id, null, null, 'objection', '«Non ho bisogno di vendere online.»', null, '{"objection":"«Non ho bisogno di vendere online.»","meaning":"Pensano che Studio ATS sia un negozio online.","questions":["Come la contatta oggi un nuovo cliente?","Cosa deve sapere prima di fare un preventivo?"],"short":"Studio ATS non è un negozio online: aiuta chi non la conosce ancora a fidarsi e a inviarle una vera richiesta.","long":"Lei non vende online — vende parlando e facendo preventivi. Studio ATS prepara quelle conversazioni: le persone vedono il suo lavoro, capiscono cosa fa e le inviano una richiesta con i dettagli giusti. La vendita avviene sempre con lei.","nextStep":"Mostra la sezione «Come funziona» della pagina di vendita."}'::jsonb, array['e-commerce', 'vendere online', 'sell online', 'negozio']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'it', 1, 'active', p.id, null, null, 'objection', '«Non avrò tempo di rispondere.»', null, '{"objection":"«Non avrò tempo di rispondere.»","meaning":"Temono più lavoro o più burocrazia.","questions":["Quanto tempo passa oggi in chiamate che non portano a nulla?","Cosa l’aiuterebbe a rispondere più in fretta?"],"short":"Studio ATS è fatto per risparmiare tempo: le richieste arrivano complete, quindi risponde una volta sola.","long":"È pensato proprio per chi è impegnato. Il team Studio ATS costruisce e mantiene tutto. Le richieste arrivano con i dettagli necessari, in un unico posto: non perde più tempo a rincorrere informazioni o a richiamare richieste vaghe.","nextStep":"Proponi di inviare la pagina perché la guardino la sera."}'::jsonb, array['tempo', 'time', 'impegnato', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'it', 1, 'active', p.id, null, null, 'objection', '«È troppo caro.»', null, '{"objection":"«È troppo caro.»","meaning":"Lo confrontano con un sito economico, o non ne vedono ancora il valore.","questions":["Quanto vale per lei un nuovo cliente?","Con cosa lo sta confrontando?"],"short":"Lo confronti con il valore dei clienti che l’aiuta a ottenere — non con il prezzo di un sito base.","long":"Studio ATS non è un sito base: è l’intero percorso dalla prima visita alla richiesta, costruito e mantenuto per lei. Molti professionisti ragionano così: quanto vale un solo nuovo cliente? Il prezzo è ufficiale e uguale per tutti — trattando altrove non ne otterrà uno migliore.","nextStep":"Non fare mai sconti né promettere risultati. Invia la sezione offerta della pagina."}'::jsonb, array['prezzo', 'price', 'caro', 'expensive', 'budget']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'it', 1, 'active', p.id, null, null, 'objection', '«Ho già un sito.»', null, '{"objection":"«Ho già un sito.»","meaning":"Pensano che faccia lo stesso lavoro.","questions":["Quante richieste le porta ogni mese?","Cosa succede dopo che qualcuno compila il suo modulo?"],"short":"Lo tenga se funziona. Studio ATS riguarda ciò che un sito fa raramente: qualificare le richieste e facilitare gli appuntamenti.","long":"Un sito presenta; Studio ATS converte. La domanda non è se ha un sito, ma se trasforma i visitatori in richieste complete e appuntamenti. Se il suo lo fa già, perfetto. Altrimenti, è esattamente la parte di cui si occupa Studio ATS.","nextStep":"Proponi di guardare insieme il loro attuale modulo di contatto."}'::jsonb, array['sito', 'website', 'ho già un sito', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'it', 1, 'active', p.id, null, null, 'objection', '«Devo pensarci.»', null, '{"objection":"«Devo pensarci.»","meaning":"Qualcosa non è chiaro, oppure non è il momento giusto.","questions":["Cosa le servirebbe sapere per decidere?","È una questione di tempi, di budget o di altro?"],"short":"Certo. Qual è l’unica cosa che le servirebbe chiarire per decidere?","long":"Prendersi del tempo è normale. Di solito resta una domanda aperta — prezzo, tempistiche o come funzionerebbe nel loro caso. Chiedi quale, rispondi con precisione, poi fissa una data per riparlarne.","nextStep":"Fissa una data di follow-up e annotala nel tuo CRM."}'::jsonb, array['pensarci', 'think', 'più tardi', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'it', 1, 'active', p.id, null, null, 'objection', '«Non adesso.»', null, '{"objection":"«Non adesso.»","meaning":"Alta stagione, o altre priorità.","questions":["Quale sarebbe un momento migliore?","Qual è il suo periodo più tranquillo?"],"short":"Capito — quando avrebbe senso riparlarne?","long":"Rispettalo e pianifica: il momento migliore per avviare Studio ATS è spesso poco prima di un periodo intenso, così funziona quando arrivano le richieste. Chiedi quando ricontattarli e annotalo.","nextStep":"Imposta un promemoria nel CRM — senza mai insistere."}'::jsonb, array['non adesso', 'not now', 'tempistica', 'stagione']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'it', 1, 'active', p.id, null, null, null, 'Che cos’è', null, '{"section":"what_it_is","items":[{"title":"Uno studio commerciale online","body":"Studio ATS è uno studio commerciale online per professionisti per cui ogni nuovo cliente ha un valore reale: presenta il loro lavoro, qualifica le richieste e aiuta a fissare appuntamenti — in un unico posto."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'it', 1, 'active', p.id, null, null, null, 'Cosa fa', null, '{"section":"what_it_does","items":[{"title":"Dalla prima visita all’appuntamento fissato","body":"Il sito è solo una parte. Studio ATS copre l’intero percorso: vetrina, richiesta, qualificazione, appuntamento, follow-up."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
