insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.benefits', 'it', 1, 'active', p.id, null, null, null, 'Vantaggi per l’attività', null, '{"section":"benefits","items":[{"title":"Fiducia","body":"Una presenza premium all’altezza della qualità del lavoro."},{"title":"Richieste qualificate","body":"Budget, tempi e tipo di progetto noti prima della prima chiamata."},{"title":"Tempo","body":"Meno chiamate vaghe e meno follow-up dimenticati."}]}'::jsonb, array[]::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.features', 'it', 1, 'active', p.id, null, null, null, 'Funzionalità', null, '{"section":"features","items":[{"title":"Mostrare","body":"Presentare l’attività e i lavori migliori con un sito premium e veloce."},{"title":"Convertire","body":"Moduli guidati trasformano i visitatori in richieste strutturate."},{"title":"Qualificare","body":"Conoscere budget, tempi e tipo di progetto prima della chiamata."},{"title":"Centralizzare","body":"Ogni contatto e ogni richiesta in un unico posto, con tutta la cronologia."},{"title":"Prenotare","body":"I contatti qualificati richiedono un appuntamento in pochi clic."},{"title":"Automatizzare","body":"E-mail transazionali e follow-up inviati al momento giusto."},{"title":"Seguire","body":"Seguire ogni richiesta dalla prima visita al cliente firmato."},{"title":"Misurare","body":"Vedere quali pagine, fonti e campagne portano opportunità reali."}]}'::jsonb, array[]::text[], 104, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.technical', 'it', 1, 'active', p.id, null, null, null, 'Informazioni tecniche', null, '{"section":"technical","items":[{"title":"Hosting e manutenzione","body":"Inclusi e gestiti dal team Studio ATS."},{"title":"Integrazioni","body":"Integrazioni con calendario, e-mail e analisi. L’elenco esatto viene confermato all’avvio — non promettere uno strumento specifico."}]}'::jsonb, array[]::text[], 105, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
