insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.faq', 'it', 1, 'active', p.id, null, null, null, 'FAQ', null, '{"section":"faq","items":[{"title":"È solo un sito web?","body":"No: il sito è una parte di un percorso completo, dalla prima visita all’appuntamento."},{"title":"Chi lo realizza?","body":"Il team Studio ATS lo progetta, lo configura e lo mantiene."},{"title":"Il cliente può tenere i suoi social?","body":"Sì. Studio ATS completa i profili social."}]}'::jsonb, array[]::text[], 108, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
