insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'it', 1, 'active', p.id, null, null, null, 'La tua prima settimana', 'Un piano d’azione consigliato — non una promessa di risultati.', '{"disclaimer":"Un piano consigliato per creare una routine. I risultati dipendono dal tuo lavoro, dal tuo mercato e dai tuoi contatti; nulla qui è una promessa di vendite o di guadagni.","days":[{"day":1,"title":"Capire Studio ATS","body":"Leggi la conoscenza del prodotto e un playbook.","tasks":["Leggere cos’è Studio ATS e cosa è incluso","Aprire il playbook del tuo target"]},{"day":2,"title":"Scegliere 20 contatti","body":"Scegli un target ed elenca 20 attività reali vicino a te.","tasks":["Scegliere il tuo target","Aggiungere 20 contatti al CRM"]},{"day":3,"title":"Contattare i primi contatti","body":"Invia i tuoi primi messaggi personalizzati.","tasks":["Inviare 5 messaggi di primo contatto","Creare la tua pagina di vendita per il target"]},{"day":4,"title":"Fare follow-up","body":"Ricontatta chi non ha risposto — una volta, brevemente.","tasks":["Inviare i follow-up","Spostare le risposte in «Ha risposto»"]},{"day":5,"title":"Fare chiamate","body":"Usa lo script di chiamata con chi ha risposto.","tasks":["Fare almeno una chiamata conoscitiva","Annotare il passo successivo di ogni chiamata"]},{"day":6,"title":"Inviare le pagine di vendita","body":"Invia la tua pagina ai contatti qualificati.","tasks":["Inviare la tua pagina dopo ogni chiamata","Verificare che la pagina si veda bene da smartphone"]},{"day":7,"title":"Fare il punto","body":"Guarda cosa ha funzionato: quale messaggio, quale target, quale canale.","tasks":["Controllare le performance della tua pagina e dei tuoi link","Pianificare la settimana successiva"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'nl', 1, 'active', p.id, null, null, null, 'Studio ATS — standaard verkooppagina', 'Standaardstructuur van elke verkooppagina van partners.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Maak van je verkeer kansen.","heroSubtitle":"Een online verkoopstudio voor professionals voor wie elke nieuwe klant echte waarde heeft. Presenteer je werk, kwalificeer aanvragen en plan afspraken — op één plek.","problemTitle":"Mooi werk. Verloren aanvragen.","problemBody":"Aanvragen komen binnen via formulier, sociale media, berichten en e-mail. Niemand weet welke serieus zijn, opvolging wordt vergeten en goede prospects haken af.","solutionTitle":"Meer dan een website.","solutionBody":"De website is maar één onderdeel. Studio ATS is het hele traject van eerste bezoek tot geplande afspraak — voor jou ontworpen, ingericht en onderhouden.","valueTitle":"Wat je echt krijgt","valueItems":["Een uitstraling die meteen vertrouwen wekt","Aanvragen die binnenkomen met de juiste informatie","Elk contact en elke aanvraag op één plek","Opvolging die op tijd verstuurd wordt"],"howTitle":"Hoe het werkt","howSteps":[{"title":"Aanvraag","body":"Vertel ons in een kort formulier over je bedrijf."},{"title":"Gesprek","body":"Samen brengen we je behoeften in kaart."},{"title":"Bouw","body":"Wij ontwerpen en configureren je Studio ATS."},{"title":"Lancering","body":"Je begint gestructureerde aanvragen te ontvangen."}],"benefitsTitle":"Waarom het belangrijk is voor je bedrijf","benefits":[{"title":"Vertrouwen","body":"Prospects zoeken je online op voordat ze bellen. Zorg dat die eerste indruk klopt."},{"title":"Tijd","body":"Ken budget, timing en type project voordat je de telefoon pakt."},{"title":"Niets te beheren","body":"Gebouwd, gehost en onderhouden door het Studio ATS-team."}],"includedTitle":"Wat erbij zit","whoTitle":"Voor wie","whoBody":"Professionals en bedrijven met waardevolle klanten, een visueel of premium aanbod en binnenkomende aanvragen om te converteren.","faqTitle":"Vragen die je misschien hebt","offerTitle":"Eén pakket. Alles inbegrepen.","offerNote":"Prijs excl. btw waar van toepassing. Definitieve voorwaarden in het contract.","ctaTitle":"Klaar om over je bedrijf te praten?","ctaBody":"Laat je gegevens achter — vrijblijvend. We nemen contact op om je behoeften te begrijpen."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'nl', 1, 'active', p.id, 'artisans', null, null, 'Variant vakmensen', null, '{"template":"studio-default","heroTitle":"Je werk is uitstekend. Je online aanwezigheid hoort dat ook te zijn.","heroSubtitle":"Prospects zoeken je op voordat ze bellen. Studio ATS geeft je bedrijf een professionele uitstraling en verzamelt complete aanvragen — ook terwijl je aan het werk bent.","problemTitle":"Mond-tot-mondreclame is niet meer genoeg.","problemBody":"Wie je nog niet kent, zoekt je eerst online op. Vinden ze weinig, dan bellen ze iemand anders — en de aanvragen die wel binnenkomen zijn versnipperd en onvolledig.","ctaTitle":"Laten we samen naar je bedrijf kijken","ctaBody":"Laat je gegevens achter en beschrijf je vak in één regel. Vrijblijvend."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'nl', 1, 'active', p.id, null, null, null, 'Meer gekwalificeerde aanvragen genereren', null, '{"promise":"Aanvragen die binnenkomen met budget, timing en details.","heroTitle":"Ontvang aanvragen waar je echt op kunt reageren.","heroSubtitle":"Studio ATS stelt vóór het eerste gesprek de juiste vragen, zodat elke aanvraag binnenkomt met de informatie die je nodig hebt."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'nl', 1, 'active', p.id, null, null, null, 'Online net zo professioneel overkomen als je bent', null, '{"promise":"Een uitstraling die past bij de kwaliteit van het werk.","heroTitle":"Kom online net zo professioneel over als in het echt.","heroSubtitle":"Prospects checken je voordat ze bellen. Geef ze een uitstraling die binnen enkele seconden vertrouwen wekt."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'nl', 1, 'active', p.id, null, null, null, 'Geen aanvragen meer verliezen', null, '{"promise":"Elke aanvraag vastgelegd en gecentraliseerd, ook als je druk bent.","heroTitle":"Verlies geen aanvragen meer terwijl je werkt.","heroSubtitle":"Elke aanvraag komt op één plek binnen met de juiste details — en opvolging gaat op tijd de deur uit."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'nl', 1, 'active', p.id, null, null, null, 'Studio ATS verkopen — de methode', 'De 10 stappen van een Studio ATS-verkoop, voor elke doelgroep. Open een doelgroep om haar problemen en invalshoek toe te voegen.', '{"intro":"Verkoop het resultaat, niet de technologie. Jouw taak: hun situatie begrijpen, laten zien wat ze vandaag mislopen en de juiste pagina sturen.","steps":[{"key":"understand","title":"Ze begrijpen","body":"Kijk vóór het contact hoe ze zich nu online presenteren en hoe een nieuwe klant ze kan bereiken.","bullets":["Bekijk hun website, sociale profielen en reviews","Noteer één concreet ding dat je goed vindt aan hun werk"]},{"key":"opening","title":"Opening","body":"Begin bij hen, niet bij Studio ATS. Eén oprechte opmerking, één vraag.","bullets":["“Ik zag jullie werk op …”","“Korte vraag: hoe vinden de meeste nieuwe klanten jullie?”"]},{"key":"discovery","title":"Verkenning","body":"Vraag en luister. Laat ze vertellen hoe aanvragen binnenkomen en wat er daarna gebeurt.","bullets":["Hoe nemen nieuwe klanten nu contact op?","Welke informatie ontbreekt meestal?","Wat gebeurt er als je niet meteen kunt reageren?"]},{"key":"pain","title":"Het probleem vinden","body":"Benoem het probleem in hun woorden. Verzin er geen dat ze niet hebben."},{"key":"present","title":"Studio ATS presenteren","body":"Koppel Studio ATS aan het probleem dat ze net beschreven — één zin, geen lijst met functies.","bullets":["“Dat is precies wat Studio ATS regelt: …”"]},{"key":"value","title":"De waarde aantonen","body":"Praat over resultaten: vertrouwen, complete aanvragen, tijdwinst, niets te beheren. Beloof nooit cijfers."},{"key":"objections","title":"Bezwaren behandelen","body":"Een bezwaar is een verkapte vraag. Vraag wat erachter zit voordat je antwoordt."},{"key":"offer","title":"Het aanbod versturen","body":"Stuur je verkooppagina voor hun sector: die legt alles uit en de prijs komt van Studio ATS."},{"key":"follow_up","title":"Opvolgen","body":"Na een paar dagen geen reactie? Eén korte, nuttige opvolging — en respecteer daarna hun antwoord."},{"key":"close","title":"Afsluiten","body":"Spreek een duidelijke volgende stap af: een gesprek, een aanvraag op de pagina of de online aankoop."}]}'::jsonb, array['methode', 'verkenning', 'afsluiten']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'nl', 1, 'active', p.id, 'artisans', null, null, 'Studio ATS verkopen aan een vakman', 'Eerst bellen, kort en concreet. Vakmensen hebben het druk: respecteer hun tijd.', '{"intro":"Vakmensen kopen van mensen die hun vak begrijpen. Praat over hun klanten en hun tijd — nooit over “websites”.","steps":[{"key":"understand","title":"Ze begrijpen","body":"Ze zijn het grootste deel van de dag op de klus, krijgen werk via mond-tot-mondreclame en nemen de telefoon op tussen twee klussen door. Hun reputatie is hun belangrijkste bezit.","bullets":["Zoek ze op zoals een klant zou doen: wat vind je?","Noteer hun vak, regio en het soort klussen dat ze laten zien"]},{"key":"opening","title":"Opening","body":"Bel vroeg in de ochtend of aan het eind van de dag. Wees kort en concreet.","bullets":["“Ik heb jullie opgezocht zoals een klant dat zou doen — mag ik vertellen wat me opviel? Het duurt 2 minuten.”"]},{"key":"discovery","title":"Verkenning","body":"Drie vragen zijn genoeg.","bullets":["Hoe vinden de meeste nieuwe klanten jullie?","Wat gebeurt er als iemand die jullie niet kent jullie opzoekt?","Hoeveel oproepen mis je tijdens een klus?"]},{"key":"pain","title":"Het probleem vinden","body":"Meestal: mond-tot-mondreclame heeft grenzen, het bedrijf oogt online minder professioneel dan in werkelijkheid, aanvragen raken zoek."},{"key":"present","title":"Studio ATS presenteren","body":"“Studio ATS geeft je bedrijf een professionele uitstraling die voor je werkt terwijl je op de klus bent: mensen zien je werk en sturen je complete aanvragen — klus, plaats, planning.”"},{"key":"value","title":"De waarde aantonen","body":"Vertrouwen bij mensen die je nog niet kennen. Aanvragen die je in één keer beantwoordt. Niets om zelf te beheren."},{"key":"objections","title":"Bezwaren behandelen","body":"Reken op: “ik heb al sociale media”, “mijn klanten komen via mond-tot-mondreclame”, “ik heb geen tijd”."},{"key":"offer","title":"Het aanbod versturen","body":"Stuur je pagina voor vakmensen per sms of WhatsApp direct na het gesprek, nu het nog vers is."},{"key":"follow_up","title":"Opvolgen","body":"Twee tot drie dagen later één kort bericht: “Heb je tijd gehad om te kijken? Kan ik een vraag beantwoorden?”"},{"key":"close","title":"Afsluiten","body":"Stel de volgende stap voor: een aanvraag op de pagina, een gesprek met het Studio ATS-team of de online aankoop zodra die beschikbaar is."}]}'::jsonb, array['vakman', 'telefoon', 'mond-tot-mond', 'sociale media']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'nl', 1, 'active', p.id, null, 'phone', null, 'Verkennend gesprek (elke doelgroep)', '5 minuten om te begrijpen, te kwalificeren en een volgende stap af te spreken.', '{"intro":"Vink elke stap af terwijl je verdergaat. Praat minder dan zij.","steps":[{"type":"opening","text":"Hallo {{firstName}}, met {{advisorName}}. Ik bel over hoe nieuwe klanten {{company}} bereiken — heeft u 2 minuten?"},{"type":"question","text":"Hoe vinden de meeste nieuwe klanten u vandaag?"},{"type":"listen","text":"Alleen mond-tot-mondreclame? Sociale media? Telefoontjes tijdens het werk?","hint":"Noteer hun exacte woorden."},{"type":"question","text":"Wat gebeurt er als iemand die u niet kent u online opzoekt?"},{"type":"problem","text":"Ze vinden weinig, of aanvragen komen versnipperd en onvolledig binnen."},{"type":"response","text":"Dat is wat Studio ATS regelt: een professionele uitstraling die vertrouwen wekt en complete aanvragen verzamelt — voor u gebouwd en onderhouden."},{"type":"objection","text":"“Ik heb al sociale media.”"},{"type":"answer","text":"Sociale media laten uw werk zien. Studio ATS maakt van die interesse een complete aanvraag. Waar sturen mensen u nu een aanvraag?"},{"type":"cta","text":"Mag ik u de pagina voor uw sector sturen? Die legt alles uit, inclusief de prijs, in 3 minuten."}]}'::jsonb, array['telefoon', 'verkenning', 'gesprek']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'nl', 1, 'active', p.id, 'artisans', 'phone', null, 'Vakman — eerste gesprek', 'Kort gesprek tussen twee klussen door.', '{"steps":[{"type":"opening","text":"Hallo {{firstName}}, met {{advisorName}}. Ik heb {{company}} opgezocht zoals een klant dat zou doen — mag ik vertellen wat me opviel? Twee minuten."},{"type":"question","text":"Het meeste werk komt via mond-tot-mondreclame, toch?"},{"type":"listen","text":"Trots op hun reputatie; misschien rustigere periodes; gemiste oproepen op de klus."},{"type":"question","text":"En als een vriend u aanraadt, wat vindt die persoon dan als hij u opzoekt?"},{"type":"problem","text":"Weinig of niets dat de kwaliteit van het werk laat zien — sommigen bellen dan iemand anders."},{"type":"response","text":"Studio ATS geeft u een professionele uitstraling die voor u werkt terwijl u op de klus bent: mensen zien uw werk en sturen u complete aanvragen."},{"type":"objection","text":"“Daar heb ik geen tijd voor.”"},{"type":"answer","text":"Precies daarom: het Studio ATS-team bouwt en onderhoudt het. U ontvangt gewoon de aanvragen."},{"type":"cta","text":"Ik stuur u de pagina voor vakmensen per sms — kijkt u er vanavond even naar, dan bel ik donderdag terug?"}]}'::jsonb, array['vakman', 'telefoon', 'mond-tot-mond']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'nl', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Eerste contact — kort bericht', null, '{"text":"Hallo {{firstName}}, ik kwam {{company}} tegen en vond jullie werk mooi. Korte vraag: hoe bereiken de meeste nieuwe klanten jullie nu? Ik werk met Studio ATS, dat professionals helpt om online interesse om te zetten in complete aanvragen. Hier is een overzicht van 3 minuten voor jullie sector: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'nl', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Eerste contact — LinkedIn', null, '{"text":"Hallo {{firstName}}, ik lees graag wat je deelt over {{sector}}. Als iemand met {{company}} wil samenwerken, waar stuur je diegene dan naartoe? Ik begeleid professionals met Studio ATS, een omgeving die hun werk presenteert en elke aanvraag kwalificeert. Zin in een korte blik?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
