insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'nl', 1, 'active', p.id, null, 'in_person', 'follow_up', 'Na een persoonlijke ontmoeting', null, '{"text":"Hallo {{firstName}}, leuk je vandaag te ontmoeten. Zoals besproken hier de Studio ATS-pagina voor je bedrijf: {{affiliateUrl}}. Laat me weten wanneer een kort gesprek je uitkomt. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'nl', 1, 'active', p.id, null, 'other', 'no_response', 'Geen reactie — laatste bericht', null, '{"text":"Hallo {{firstName}}, ik wil je niet lastigvallen: ik stop met opvolgen. Als het een prioriteit wordt hoe nieuwe klanten {{company}} bereiken, blijft de pagina beschikbaar: {{affiliateUrl}}. Fijne week."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
