insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'nl', 1, 'active', p.id, null, 'other', 'interested', 'Geïnteresseerd — de volgende stap plannen', null, '{"text":"Top, {{firstName}}! De eenvoudigste volgende stap: laat je aanvraag achter op deze pagina, zodat het Studio ATS-team het gesprek kan voorbereiden: {{affiliateUrl}}. Welke dag komt je uit?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
