insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'nl', 1, 'active', p.id, null, 'other', 'objection', 'Bezwaar — “Ik heb al sociale media”', null, '{"text":"Ik begrijp het, {{firstName}} — je sociale media laten je werk goed zien. Studio ATS vervangt ze niet: het zet die interesse om in complete aanvragen, op een plek die jij beheert. Waar sturen mensen je nu een aanvraag?"}'::jsonb, array['instagram', 'facebook', 'sociale media', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
