insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'nl', 1, 'active', p.id, null, 'email', 'renewal', 'Klant — even informeren', null, '{"text":"Hallo {{firstName}}, hoe bevalt Studio ATS tot nu toe bij {{company}}? Als iets beter kan, laat het me weten, dan geef ik het door aan het Studio ATS-team."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'nl', 1, 'active', p.id, null, 'email', 'first_contact', 'Eerste contact', null, '{"subject":"{{company}} — online interesse omzetten in aanvragen","preview":"Een korte vraag over hoe nieuwe klanten u bereiken.","body":"Hallo {{firstName}},\n\nIk kwam {{company}} tegen en vond uw werk oprecht mooi.\n\nKorte vraag: als iemand u online ontdekt, wat gebeurt er dan? Veel professionals krijgen aanvragen via een mix van formulieren, sociale media en berichten — zonder de details die ze nodig hebben.\n\nStudio ATS regelt dat: een professionele omgeving die uw werk presenteert, elke aanvraag kwalificeert en helpt de afspraak te plannen. Hij wordt voor u gebouwd en onderhouden.\n\nHier is een overzicht van 3 minuten voor uw sector:","cta":"Bekijk het overzicht"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'nl', 1, 'active', p.id, null, 'email', 'follow_up', 'Opvolging na 3 dagen', null, '{"subject":"Re: {{company}} — online interesse omzetten in aanvragen","preview":"Ik zet dit bericht weer bovenaan in uw inbox.","body":"Hallo {{firstName}},\n\nIk zet mijn bericht even terug bovenaan. Als aanvragen zonder de juiste details u bekend voorkomen, is Studio ATS 3 minuten waard.\n\nAls het nu geen prioriteit is, geen enkel probleem — laat het me weten, dan volg ik niet meer op.","cta":"Bekijk de pagina"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'nl', 1, 'active', p.id, null, 'email', 'after_call', 'Na het gesprek — samenvatting', null, '{"subject":"Ons gesprek — volgende stappen voor {{company}}","preview":"Wat we bespraken en de volgende stap.","body":"Hallo {{firstName}},\n\nBedankt voor uw tijd vandaag. Wat ik begreep:\n• hoe nieuwe klanten u nu bereiken\n• wat u graag zou verbeteren\n\nAlles over Studio ATS — wat erbij zit, hoe het werkt en de officiële prijs — staat op deze pagina:","cta":"Mijn Studio ATS-pagina openen"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'nl', 1, 'active', p.id, null, 'email', 'proposal', 'Voorstel', null, '{"subject":"Het Studio ATS-aanbod voor {{company}}","preview":"Alles op één pagina, inclusief prijs.","body":"Hallo {{firstName}},\n\nZoals beloofd hier het volledige Studio ATS-aanbod voor {{company}}. U vindt wat erbij zit, hoe de inrichting verloopt en de officiële prijs en voorwaarden.\n\nIk sta klaar voor al uw vragen.","cta":"Bekijk het aanbod"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'nl', 1, 'active', p.id, null, 'email', 'objection', 'Sociale media zijn niet genoeg', null, '{"subject":"Uw sociale media laten uw werk zien. Leveren ze ook aanvragen op?","preview":"Waarom sociale media en Studio ATS elkaar aanvullen.","body":"Hallo {{firstName}},\n\nUw sociale media laten uw werk goed zien — houd ze. De vraag is wat er na de interesse gebeurt: een bericht dat tussen andere verdwijnt, een aanvraag zonder details, een oproep die u niet kunt aannemen.\n\nStudio ATS is de plek waar die interesse een complete aanvraag wordt, in een omgeving die u beheert. Het vult uw sociale profielen aan; het vervangt ze niet.","cta":"Bekijk hoe het werkt"}'::jsonb, array['instagram', 'facebook', 'sociale media', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'nl', 1, 'active', p.id, null, 'email', 'no_response', 'Laatste opvolging', null, '{"subject":"Zal ik uw dossier sluiten?","preview":"Eén laatste bericht — daarna stop ik.","body":"Hallo {{firstName}},\n\nIk heb niets van u gehoord, dus ik neem aan dat het niet het juiste moment is — ik volg niet meer op.\n\nAls er iets verandert, blijft de pagina beschikbaar.","cta":"De pagina bewaren"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'nl', 1, 'active', p.id, null, null, 'objection', '“Ik heb al sociale media.”', null, '{"objection":"“Ik heb al sociale media.”","meaning":"Sociale media voelen als genoeg zichtbaarheid — of ze zien niet wat er ontbreekt.","questions":["Waar sturen mensen u nu een aanvraag?","Wat gebeurt er met een aanvraag die op zaterdagavond binnenkomt?"],"short":"Sociale media laten uw werk zien. Studio ATS zet die interesse om in complete aanvragen, op een plek die u beheert.","long":"Houd uw sociale media: ze zijn ideaal om uw werk te laten zien. Maar een privébericht is geen aanvraag — geen budget, geen timing, verloren tussen andere berichten, en het platform bepaalt wie u ziet. Studio ATS is de professionele plek waar interesse een complete aanvraag wordt die u in één keer kunt beantwoorden.","nextStep":"Stuur de verkooppagina en vraag ze die te vergelijken met hun profiel."}'::jsonb, array['instagram', 'facebook', 'sociale media', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'nl', 1, 'active', p.id, null, null, 'objection', '“Mijn klanten komen via mond-tot-mondreclame.”', null, '{"objection":"“Mijn klanten komen via mond-tot-mondreclame.”","meaning":"Ze zijn trots op hun reputatie — en zien het verband met online zichtbaarheid niet.","questions":["Als een vriend u aanraadt, wat doet die persoon voordat hij belt?","Zijn er rustigere periodes in het jaar?"],"short":"Mond-tot-mondreclame brengt mensen bij u. Studio ATS zorgt dat ze u bellen nadat ze u hebben opgezocht.","long":"Dat is een teken van uitstekend werk. Maar tegenwoordig checkt zelfs een aanbevolen klant u online voordat hij belt. Vindt hij weinig, dan twijfelen sommigen of bellen ze iemand anders. Studio ATS vervangt mond-tot-mondreclame niet: het bevestigt die.","nextStep":"Stel voor dat ze zichzelf opzoeken zoals een klant dat zou doen."}'::jsonb, array['mond-tot-mond', 'word of mouth', 'aanbevelingen', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'nl', 1, 'active', p.id, null, null, 'objection', '“Ik hoef niet online te verkopen.”', null, '{"objection":"“Ik hoef niet online te verkopen.”","meaning":"Ze denken dat Studio ATS een webshop is.","questions":["Hoe neemt een nieuwe klant nu contact met u op?","Wat moet u weten voordat u een offerte maakt?"],"short":"Studio ATS is geen webshop: het helpt mensen die u nog niet kennen om u te vertrouwen en een echte aanvraag te sturen.","long":"U verkoopt niet online — u verkoopt via gesprekken en offertes. Studio ATS bereidt die gesprekken voor: mensen zien uw werk, begrijpen wat u doet en sturen een aanvraag met de juiste details. De verkoop gebeurt nog steeds met u.","nextStep":"Laat het onderdeel “Hoe het werkt” van de verkooppagina zien."}'::jsonb, array['e-commerce', 'online verkopen', 'sell online', 'webshop']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'nl', 1, 'active', p.id, null, null, 'objection', '“Ik heb geen tijd om te reageren.”', null, '{"objection":"“Ik heb geen tijd om te reageren.”","meaning":"Ze vrezen meer werk of meer administratie.","questions":["Hoeveel tijd besteedt u nu aan telefoontjes die nergens toe leiden?","Wat zou u helpen sneller te reageren?"],"short":"Studio ATS is gemaakt om tijd te besparen: aanvragen komen compleet binnen, dus u reageert één keer.","long":"Het is juist bedoeld voor drukke mensen. Het Studio ATS-team bouwt en onderhoudt alles. Aanvragen komen met de nodige details op één plek binnen, zodat u geen tijd meer kwijt bent aan informatie najagen of vage telefoontjes terugbellen.","nextStep":"Bied aan de pagina te sturen zodat ze die ’s avonds kunnen bekijken."}'::jsonb, array['tijd', 'time', 'druk', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'nl', 1, 'active', p.id, null, null, 'objection', '“Het is te duur.”', null, '{"objection":"“Het is te duur.”","meaning":"Ze vergelijken met een goedkope website, of zien de waarde nog niet.","questions":["Wat is één nieuwe klant voor u waard?","Waarmee vergelijkt u het?"],"short":"Vergelijk het met de waarde van de klanten die het u helpt te winnen — niet met de prijs van een eenvoudige website.","long":"Studio ATS is geen eenvoudige website: het is het hele traject van eerste bezoek tot aanvraag, voor u gebouwd en onderhouden. Veel professionals bekijken het zo: wat is één nieuwe klant waard? De prijs is officieel en voor iedereen gelijk — door te onderhandelen krijgt u hem nergens lager.","nextStep":"Geef nooit korting en beloof geen resultaat. Stuur het aanbodgedeelte van de pagina."}'::jsonb, array['prijs', 'price', 'duur', 'expensive', 'budget']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'nl', 1, 'active', p.id, null, null, 'objection', '“Ik heb al een website.”', null, '{"objection":"“Ik heb al een website.”","meaning":"Ze denken dat die hetzelfde doet.","questions":["Hoeveel aanvragen levert die u per maand op?","Wat gebeurt er nadat iemand uw formulier heeft ingevuld?"],"short":"Houd hem als hij werkt. Studio ATS draait om wat een website zelden doet: aanvragen kwalificeren en afspraken makkelijker maken.","long":"Een website presenteert; Studio ATS converteert. De vraag is niet of u een website heeft, maar of die bezoekers omzet in complete aanvragen en afspraken. Doet de uwe dat al, prima. Zo niet, dan is dat precies het deel dat Studio ATS regelt.","nextStep":"Stel voor om samen naar hun huidige contactformulier te kijken."}'::jsonb, array['website', 'site', 'al een website', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'nl', 1, 'active', p.id, null, null, 'objection', '“Ik moet erover nadenken.”', null, '{"objection":"“Ik moet erover nadenken.”","meaning":"Er is iets onduidelijk, of het is niet het juiste moment.","questions":["Wat zou u moeten weten om te beslissen?","Gaat het om de timing, het budget of iets anders?"],"short":"Natuurlijk. Wat is het ene punt dat u verduidelijkt wilt hebben om te beslissen?","long":"Bedenktijd nemen is normaal. Meestal blijft er één vraag over — prijs, planning of hoe het voor hen zou werken. Vraag welke, beantwoord die precies en spreek dan een datum af om elkaar weer te spreken.","nextStep":"Spreek een datum voor opvolging af en zet die in je CRM."}'::jsonb, array['nadenken', 'think', 'later', 'bedenktijd']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'nl', 1, 'active', p.id, null, null, 'objection', '“Nu even niet.”', null, '{"objection":"“Nu even niet.”","meaning":"Druk seizoen, of andere prioriteiten.","questions":["Wanneer zou een beter moment zijn?","Wanneer is uw rustigere periode?"],"short":"Begrepen — wanneer zou het zinvol zijn om elkaar weer te spreken?","long":"Respecteer het en plan vooruit: het beste moment om Studio ATS op te zetten is vaak vlak voor een drukke periode, zodat het werkt wanneer de aanvragen binnenkomen. Vraag wanneer je terug mag komen en noteer het.","nextStep":"Zet een herinnering in het CRM — dring nooit aan."}'::jsonb, array['nu niet', 'not now', 'timing', 'seizoen']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_is', 'nl', 1, 'active', p.id, null, null, null, 'Wat het is', null, '{"section":"what_it_is","items":[{"title":"Een online verkoopstudio","body":"Studio ATS is een online verkoopstudio voor professionals voor wie elke nieuwe klant echte waarde heeft: het presenteert hun werk, kwalificeert aanvragen en helpt afspraken te plannen — op één plek."}]}'::jsonb, array[]::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.what_it_does', 'nl', 1, 'active', p.id, null, null, null, 'Wat het doet', null, '{"section":"what_it_does","items":[{"title":"Van eerste bezoek tot geplande afspraak","body":"De website is maar één onderdeel. Studio ATS dekt het hele traject: etalage, aanvraag, kwalificatie, afspraak en opvolging."}]}'::jsonb, array[]::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.customer_gets', 'nl', 1, 'active', p.id, null, null, null, 'Wat de klant krijgt', null, '{"section":"customer_gets","items":[{"title":"Volledig verzorgd","body":"Het Studio ATS-team ontwerpt, richt in, host en onderhoudt. De klant ontvangt gestructureerde aanvragen."},{"title":"Eén plek","body":"Elk contact en elke aanvraag op één plek, met historie."}]}'::jsonb, array[]::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.benefits', 'nl', 1, 'active', p.id, null, null, null, 'Zakelijke voordelen', null, '{"section":"benefits","items":[{"title":"Vertrouwen","body":"Een premium uitstraling die past bij de kwaliteit van het werk."},{"title":"Gekwalificeerde aanvragen","body":"Budget, timing en type project bekend vóór het eerste gesprek."},{"title":"Tijd","body":"Minder vage telefoontjes en vergeten opvolging."}]}'::jsonb, array[]::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.features', 'nl', 1, 'active', p.id, null, null, null, 'Functies', null, '{"section":"features","items":[{"title":"Presenteren","body":"De activiteit en het beste werk tonen op een snelle premium website."},{"title":"Converteren","body":"Begeleide aanvraagformulieren maken van bezoekers gestructureerde aanvragen."},{"title":"Kwalificeren","body":"Budget, timing en type project kennen vóór het gesprek."},{"title":"Centraliseren","body":"Elk contact en elke aanvraag op één plek, met volledige historie."},{"title":"Plannen","body":"Gekwalificeerde prospects vragen in een paar klikken een afspraak aan."},{"title":"Automatiseren","body":"Transactionele e-mails en opvolging gaan op tijd de deur uit."},{"title":"Volgen","body":"Elke aanvraag volgen van eerste bezoek tot getekende klant."},{"title":"Meten","body":"Zien welke pagina’s, bronnen en campagnes echte kansen opleveren."}]}'::jsonb, array[]::text[], 104, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.technical', 'nl', 1, 'active', p.id, null, null, null, 'Technische informatie', null, '{"section":"technical","items":[{"title":"Hosting & onderhoud","body":"Inbegrepen en verzorgd door het Studio ATS-team."},{"title":"Integraties","body":"Integraties met agenda, e-mail en analytics. De exacte lijst wordt bij de onboarding bevestigd — beloof geen specifieke tool."}]}'::jsonb, array[]::text[], 105, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
