insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'knowledge', 'studio.faq', 'nl', 1, 'active', p.id, null, null, null, 'Veelgestelde vragen', null, '{"section":"faq","items":[{"title":"Is het gewoon een website?","body":"Nee: de website is een onderdeel van een compleet traject van eerste bezoek tot afspraak."},{"title":"Wie bouwt het?","body":"Het Studio ATS-team ontwerpt, richt in en onderhoudt het."},{"title":"Kan de klant zijn sociale media houden?","body":"Ja. Studio ATS vult sociale profielen aan."}]}'::jsonb, array[]::text[], 108, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
