insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'asset', 'studio-public-page', 'nl', 1, 'active', p.id, null, null, null, 'Openbare presentatie van Studio ATS', 'De officiële productpagina — deel hem of gebruik hem als live demo.', '{"category":"demo","url":"/nl/studio","description":"Altijd actueel: het is de live productpagina."}'::jsonb, array[]::text[], 200, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'nl', 1, 'active', p.id, null, null, null, 'Je eerste week', 'Een aanbevolen actieplan — geen belofte van resultaten.', '{"disclaimer":"Een aanbevolen plan om een routine op te bouwen. Resultaten hangen af van je werk, je markt en je prospects; niets hiervan is een belofte van verkopen of inkomsten.","days":[{"day":1,"title":"Studio ATS begrijpen","body":"Lees de productkennis en één playbook.","tasks":["Lezen wat Studio ATS is en wat erbij zit","Het playbook voor je doelgroep openen"]},{"day":2,"title":"20 prospects kiezen","body":"Kies één doelgroep en maak een lijst van 20 echte bedrijven bij jou in de buurt.","tasks":["Je doelgroep kiezen","20 prospects in je CRM zetten"]},{"day":3,"title":"Je eerste prospects benaderen","body":"Stuur je eerste gepersonaliseerde berichten.","tasks":["5 berichten voor eerste contact sturen","Je verkooppagina voor de doelgroep maken"]},{"day":4,"title":"Opvolgen","body":"Volg op bij wie niet heeft gereageerd — één keer, kort.","tasks":["Opvolgberichten sturen","Antwoorden naar “Heeft geantwoord” verplaatsen"]},{"day":5,"title":"Gesprekken voeren","body":"Gebruik het belscript bij wie heeft gereageerd.","tasks":["Minstens één verkennend gesprek voeren","De volgende stap van elk gesprek noteren"]},{"day":6,"title":"Passende verkooppagina’s sturen","body":"Stuur je pagina naar gekwalificeerde prospects.","tasks":["Je verkooppagina na elk gesprek sturen","Controleren of de pagina er goed uitziet op mobiel"]},{"day":7,"title":"Terugblikken","body":"Kijk wat werkte: welk bericht, welke doelgroep, welk kanaal.","tasks":["De prestaties van je pagina en links bekijken","De volgende week plannen"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'ar', 1, 'active', p.id, null, null, null, 'Studio ATS — صفحة البيع القياسية', 'البنية الافتراضية لكل صفحات البيع الخاصة بالشركاء.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"حوّل زياراتك إلى فرص.","heroSubtitle":"استوديو تجاري عبر الإنترنت للمهنيين الذين يحمل كل عميل جديد لديهم قيمة حقيقية. اعرض أعمالك، وأهّل الطلبات، واحجز المواعيد — في مكان واحد.","problemTitle":"عمل رائع. وطلبات ضائعة.","problemBody":"تصل الاستفسارات عبر نموذج الاتصال ووسائل التواصل الاجتماعي والرسائل والبريد الإلكتروني. لا أحد يعرف أيّها جادّ، وتُنسى المتابعات، ويفتر اهتمام العملاء المحتملين الجيدين.","solutionTitle":"أكثر من موقع إلكتروني.","solutionBody":"الموقع جزء واحد فقط. Studio ATS هو المسار الكامل من الزيارة الأولى حتى الموعد المحجوز — مصمَّم ومهيَّأ ومصون من أجلك.","valueTitle":"ما تحصل عليه فعلًا","valueItems":["حضور يبعث على الثقة من النظرة الأولى","طلبات تصل مع المعلومات الصحيحة","كل جهة اتصال وكل طلب في مكان واحد","متابعات تُرسل في وقتها"],"howTitle":"كيف يعمل","howSteps":[{"title":"الطلب","body":"حدّثنا عن نشاطك في نموذج قصير."},{"title":"المكالمة","body":"نحدد احتياجاتك معًا."},{"title":"البناء","body":"نصمّم Studio ATS الخاص بك ونهيّئه."},{"title":"الإطلاق","body":"تبدأ في تلقي طلبات منظَّمة."}],"benefitsTitle":"لماذا يهم ذلك لنشاطك","benefits":[{"title":"الثقة","body":"يبحث عنك العملاء المحتملون على الإنترنت قبل الاتصال. اجعل الانطباع الأول مميزًا."},{"title":"الوقت","body":"اعرف الميزانية والتوقيت ونوع المشروع قبل أن ترفع الهاتف."},{"title":"لا شيء تديره","body":"يبنيه فريق Studio ATS ويستضيفه ويصونه."}],"includedTitle":"ما هو مشمول","whoTitle":"لمن هذا","whoBody":"مهنيون وشركات عملاؤهم ذوو قيمة عالية، ولديهم عرض بصري أو فاخر وطلبات واردة تحتاج إلى تحويل.","faqTitle":"أسئلة قد تخطر ببالك","offerTitle":"باقة واحدة. كل شيء مشمول.","offerNote":"السعر دون ضريبة القيمة المضافة عند الاقتضاء. الشروط النهائية في العقد.","ctaTitle":"مستعد للحديث عن نشاطك؟","ctaBody":"اترك بياناتك — دون أي التزام. سنعود إليك لفهم احتياجاتك."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'ar', 1, 'active', p.id, 'artisans', null, null, 'نسخة الحِرفيين', null, '{"template":"studio-default","heroTitle":"عملك ممتاز. ويجب أن يكون حضورك على الإنترنت كذلك.","heroSubtitle":"يبحث عنك العملاء المحتملون قبل الاتصال. يمنح Studio ATS نشاطك حضورًا مهنيًا ويجمع طلبات كاملة — حتى وأنت في موقع العمل.","problemTitle":"التوصية الشفهية لم تعد كافية.","problemBody":"من لا يعرفك بعد يبحث عنك أولًا على الإنترنت. إن وجد القليل، اتصل بغيرك — والطلبات التي تصل تكون مبعثرة وناقصة.","ctaTitle":"لننظر معًا في نشاطك","ctaBody":"اترك بياناتك وصِف حرفتك في سطر واحد. دون أي التزام."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'ar', 1, 'active', p.id, null, null, null, 'الحصول على طلبات أكثر تأهيلًا', null, '{"promise":"طلبات تصل مع الميزانية والتوقيت والتفاصيل.","heroTitle":"تلقَّ طلبات يمكنك الرد عليها فعلًا.","heroSubtitle":"يطرح Studio ATS الأسئلة الصحيحة قبل المكالمة الأولى، لتصل كل طلبية بالمعلومات التي تحتاجها."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'ar', 1, 'active', p.id, null, null, null, 'الظهور على الإنترنت بالاحترافية التي أنت عليها', null, '{"promise":"حضور يليق بجودة العمل.","heroTitle":"كن محترفًا على الإنترنت كما أنت في الواقع.","heroSubtitle":"يتحقق منك العملاء المحتملون قبل الاتصال. امنحهم حضورًا يبعث على الثقة في ثوانٍ."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'ar', 1, 'active', p.id, null, null, null, 'التوقف عن خسارة الطلبات', null, '{"promise":"كل طلب يُلتقط ويُجمع، حتى وأنت مشغول.","heroTitle":"توقّف عن خسارة الطلبات أثناء عملك.","heroSubtitle":"يصل كل طلب إلى مكان واحد بالتفاصيل الصحيحة — وتُرسل المتابعات في وقتها."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'ar', 1, 'active', p.id, null, null, null, 'بيع Studio ATS — الطريقة', 'الخطوات العشر لبيع Studio ATS، لأي فئة. افتح فئة لإدراج مشكلاتها وزاويتها.', '{"intro":"بِع النتيجة، لا التقنية. مهمتك: أن تفهم وضعهم، وتُريهم ما يخسرونه اليوم، وترسل لهم الصفحة المناسبة.","steps":[{"key":"understand","title":"افهمهم","body":"قبل التواصل، انظر كيف يقدّمون أنفسهم اليوم على الإنترنت وكيف يمكن لعميل جديد الوصول إليهم.","bullets":["راجع موقعهم وحساباتهم الاجتماعية والتقييمات","دوّن شيئًا محددًا يعجبك في عملهم"]},{"key":"opening","title":"الافتتاح","body":"ابدأ بهم، لا بـ Studio ATS. ملاحظة صادقة وسؤال واحد.","bullets":["«اطّلعت على عملكم على …»","«سؤال سريع: كيف يجدكم معظم العملاء الجدد؟»"]},{"key":"discovery","title":"الاستكشاف","body":"اسأل ثم استمع. دعهم يصفون كيف تصل الطلبات وماذا يحدث بعد ذلك.","bullets":["كيف يتواصل معكم العملاء الجدد اليوم؟","ما المعلومة التي تنقص عادةً؟","ماذا يحدث عندما لا تستطيعون الرد فورًا؟"]},{"key":"pain","title":"حدّد المشكلة","body":"سمِّ المشكلة بكلماتهم. لا تختلق مشكلة ليست لديهم."},{"key":"present","title":"قدّم Studio ATS","body":"اربط Studio ATS بالمشكلة التي وصفوها للتو — جملة واحدة، لا قائمة ميزات.","bullets":["«هذا بالضبط ما يتولاه Studio ATS: …»"]},{"key":"value","title":"أثبت القيمة","body":"تحدّث عن النتائج: الثقة، والطلبات الكاملة، والوقت الموفَّر، ولا شيء يُدار. لا تَعِد بأرقام أبدًا."},{"key":"objections","title":"عالج الاعتراضات","body":"الاعتراض سؤال متنكّر. اسأل عمّا وراءه قبل أن تجيب."},{"key":"offer","title":"أرسل العرض","body":"أرسل صفحة البيع الخاصة بقطاعهم: إنها تشرح كل شيء، والسعر يحدده Studio ATS."},{"key":"follow_up","title":"تابِع","body":"لا رد بعد بضعة أيام؟ متابعة واحدة قصيرة ومفيدة — ثم احترم ردّهم."},{"key":"close","title":"أغلق الصفقة","body":"اتفق على خطوة تالية واضحة: مكالمة، أو طلب عبر الصفحة، أو الشراء عبر الإنترنت."}]}'::jsonb, array['الطريقة', 'الاستكشاف', 'الإغلاق']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'ar', 1, 'active', p.id, 'artisans', null, null, 'بيع Studio ATS لحِرفي', 'الهاتف أولًا، باختصار ووضوح. الحِرفيون مشغولون: احترم وقتهم.', '{"intro":"يشتري الحِرفيون ممن يفهم حرفتهم. تحدّث عن عملائهم ووقتهم — لا عن «المواقع الإلكترونية» أبدًا.","steps":[{"key":"understand","title":"افهمهم","body":"يقضون معظم اليوم في مواقع العمل، ويحصلون على الأعمال بالتوصية الشفهية، ويردّون على المكالمات بين مهمّتين. سمعتهم هي أهم ما يملكون.","bullets":["ابحث عنهم كما يفعل العميل: ماذا تجد؟","دوّن حرفتهم ومنطقتهم ونوع الأعمال التي يعرضونها"]},{"key":"opening","title":"الافتتاح","body":"اتصل في الصباح الباكر أو في نهاية اليوم. كن موجزًا ومحددًا.","bullets":["«بحثت عنكم كما يفعل العميل — هل أخبركم بما لاحظته؟ الأمر يستغرق دقيقتين.»"]},{"key":"discovery","title":"الاستكشاف","body":"ثلاثة أسئلة تكفي.","bullets":["كيف يجدكم معظم العملاء الجدد؟","ماذا يحدث عندما يبحث عنكم شخص لا يعرفكم؟","كم مكالمة تفوتكم أثناء العمل؟"]},{"key":"pain","title":"حدّد المشكلة","body":"عادةً: للتوصية الشفهية حدود، ويبدو النشاط أقل احترافية على الإنترنت مما هو في الواقع، وتضيع الطلبات."},{"key":"present","title":"قدّم Studio ATS","body":"«يمنح Studio ATS نشاطكم حضورًا مهنيًا يعمل بينما أنتم في موقع العمل: يرى الناس أعمالكم ويرسلون إليكم طلبات كاملة — العمل والمكان والتوقيت.»"},{"key":"value","title":"أثبت القيمة","body":"ثقة من لا يعرفونكم بعد. طلبات تُجاب دفعة واحدة. لا شيء تديرونه بأنفسكم."},{"key":"objections","title":"عالج الاعتراضات","body":"توقّع: «لديّ وسائل تواصل اجتماعي»، «عملائي يأتون بالتوصية»، «ليس لديّ وقت»."},{"key":"offer","title":"أرسل العرض","body":"أرسل صفحة الحِرفيين برسالة نصية أو WhatsApp مباشرة بعد المكالمة، ما دام الحديث حاضرًا."},{"key":"follow_up","title":"تابِع","body":"بعد يومين أو ثلاثة، رسالة قصيرة: «هل سنحت لكم فرصة الاطلاع؟ هل لديكم سؤال؟»"},{"key":"close","title":"أغلق الصفقة","body":"اقترح الخطوة التالية: طلب عبر الصفحة، أو مكالمة مع فريق Studio ATS، أو الشراء عبر الإنترنت عند توفره."}]}'::jsonb, array['حِرفي', 'الهاتف', 'التوصية الشفهية', 'وسائل التواصل الاجتماعي']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'ar', 1, 'active', p.id, null, 'phone', null, 'مكالمة استكشافية (لأي فئة)', '5 دقائق للفهم والتأهيل والاتفاق على خطوة تالية.', '{"intro":"ضع علامة على كل خطوة كلما تقدّمت. تحدّث أقل منهم.","steps":[{"type":"opening","text":"مرحبًا {{firstName}}، معك {{advisorName}}. أتصل بخصوص الطريقة التي يتواصل بها العملاء الجدد مع {{company}} — هل لديك دقيقتان؟"},{"type":"question","text":"كيف يجدك معظم عملائك الجدد اليوم؟"},{"type":"listen","text":"التوصية الشفهية فقط؟ وسائل التواصل الاجتماعي؟ مكالمات أثناء العمل؟","hint":"دوّن كلماتهم بالضبط."},{"type":"question","text":"ماذا يحدث عندما يبحث عنك شخص لا يعرفك على الإنترنت؟"},{"type":"problem","text":"يجد القليل، أو تصل الطلبات مبعثرة وناقصة."},{"type":"response","text":"هذا ما يتولاه Studio ATS: حضور مهني يبعث على الثقة ويجمع طلبات كاملة — يُبنى ويُصان من أجلك."},{"type":"objection","text":"«لديّ وسائل تواصل اجتماعي بالفعل.»"},{"type":"answer","text":"وسائل التواصل تعرض عملك. ويحوّل Studio ATS الاهتمام إلى طلب كامل. أين يرسل إليك الناس طلباتهم اليوم؟"},{"type":"cta","text":"هل أرسل لك صفحة قطاعك؟ تشرح كل شيء، بما في ذلك السعر، في 3 دقائق."}]}'::jsonb, array['الهاتف', 'الاستكشاف', 'مكالمة']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'ar', 1, 'active', p.id, 'artisans', 'phone', null, 'حِرفي — المكالمة الأولى', 'مكالمة قصيرة بين مهمّتين.', '{"steps":[{"type":"opening","text":"مرحبًا {{firstName}}، معك {{advisorName}}. بحثت عن {{company}} كما يفعل العميل — هل أخبرك بما لاحظته؟ دقيقتان."},{"type":"question","text":"معظم أعمالك تأتي بالتوصية الشفهية، صحيح؟"},{"type":"listen","text":"فخر بالسمعة؛ ربما فترات أهدأ؛ مكالمات فائتة في موقع العمل."},{"type":"question","text":"وعندما يوصي بك صديق، ماذا يجد ذلك الشخص عندما يبحث عنك؟"},{"type":"problem","text":"القليل أو لا شيء يعكس جودة العمل — فيتصل بعضهم بغيرك."},{"type":"response","text":"يمنحك Studio ATS حضورًا مهنيًا يعمل بينما أنت في موقع العمل: يرى الناس أعمالك ويرسلون إليك طلبات كاملة."},{"type":"objection","text":"«ليس لديّ وقت لهذا.»"},{"type":"answer","text":"هذا بالضبط هو الهدف: يبنيه فريق Studio ATS ويصونه. وأنت تتلقى الطلبات فقط."},{"type":"cta","text":"سأرسل لك صفحة الحِرفيين برسالة نصية — ألقِ نظرة الليلة، وأتصل بك يوم الخميس؟"}]}'::jsonb, array['حِرفي', 'الهاتف', 'التوصية الشفهية']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'ar', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'التواصل الأول — رسالة قصيرة', null, '{"text":"مرحبًا {{firstName}}، اطّلعت على {{company}} وأعجبني عملكم. سؤال سريع: كيف يتواصل معكم معظم العملاء الجدد اليوم؟ أعمل مع Studio ATS الذي يساعد المهنيين على تحويل الاهتمام على الإنترنت إلى طلبات كاملة. إليكم لمحة مدتها 3 دقائق عن قطاعكم: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'ar', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'التواصل الأول — LinkedIn', null, '{"text":"مرحبًا {{firstName}}، يعجبني ما تشاركه عن {{sector}}. عندما يرغب شخص في العمل مع {{company}}، إلى أين توجّهه؟ أرافق المهنيين في Studio ATS، وهي مساحة تعرض أعمالهم وتؤهّل كل طلب. هل تودّ إلقاء نظرة سريعة؟"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-sms-artisan', 'ar', 1, 'active', p.id, 'artisans', 'sms', 'first_contact', 'حِرفي — أول رسالة نصية بعد مكالمة', null, '{"text":"مرحبًا {{firstName}}، شكرًا على المكالمة. كما وعدتك، صفحة الحِرفيين (3 دقائق): {{affiliateUrl}} — {{advisorName}}"}'::jsonb, array[]::text[], 32, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
