insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'follow-up-in-person', 'ar', 1, 'active', p.id, null, 'in_person', 'follow_up', 'بعد لقاء شخصي', null, '{"text":"مرحبًا {{firstName}}، سعدت بلقائك اليوم. كما اتفقنا، إليك صفحة Studio ATS الخاصة بنشاطك: {{affiliateUrl}}. أخبرني متى يناسبك إجراء مكالمة قصيرة. {{advisorName}}"}'::jsonb, array[]::text[], 34, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'no-response-last', 'ar', 1, 'active', p.id, null, 'other', 'no_response', 'لا رد — الرسالة الأخيرة', null, '{"text":"مرحبًا {{firstName}}، لا أريد إزعاجك: لن أتابع بعد الآن. إذا أصبح تحسين طريقة تواصل العملاء الجدد مع {{company}} أولوية، فالصفحة تبقى متاحة: {{affiliateUrl}}. أتمنى لك أسبوعًا طيبًا."}'::jsonb, array[]::text[], 35, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'ar', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'بعد المكالمة — ملخّص', null, '{"text":"شكرًا على وقتك يا {{firstName}}. باختصار: تريد طلبات تصل كاملة وحضورًا يعكس {{company}}. كل شيء مشروح هنا، بما في ذلك السعر: {{affiliateUrl}}. الخطوة التالية كما اتفقنا: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'ar', 1, 'active', p.id, null, 'other', 'interested', 'مهتم — حجز الخطوة التالية', null, '{"text":"رائع يا {{firstName}}! أبسط خطوة تالية: اترك طلبك على هذه الصفحة ليحضّر فريق Studio ATS المكالمة: {{affiliateUrl}}. أي يوم يناسبك؟"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'proposal-send-page', 'ar', 1, 'active', p.id, null, 'other', 'proposal', 'العرض — إرسال العرض', null, '{"text":"مرحبًا {{firstName}}، كما وعدتك، إليك عرض Studio ATS الكامل لـ {{company}}: ما هو مشمول، وكيف يعمل، والسعر الرسمي. {{affiliateUrl}}"}'::jsonb, array[]::text[], 38, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'ar', 1, 'active', p.id, null, 'other', 'objection', 'اعتراض — «لديّ وسائل تواصل اجتماعي بالفعل»', null, '{"text":"أفهمك يا {{firstName}} — وسائل التواصل الخاصة بك تعرض عملك جيدًا. لا يحلّ Studio ATS محلّها: بل يحوّل ذلك الاهتمام إلى طلبات كاملة، في مساحة تتحكم بها. أين يرسل إليك الناس طلباتهم اليوم؟"}'::jsonb, array['instagram', 'facebook', 'وسائل التواصل الاجتماعي', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'closing-checkout', 'ar', 1, 'active', p.id, null, 'other', 'closing', 'الإغلاق — بعد بدء الشراء', null, '{"text":"مرحبًا {{firstName}}، رأيت أنك كنت تطّلع على Studio ATS. هل لديك سؤال قبل أن تقرر؟ أنا متاح إن أردت الحديث عن الأمر."}'::jsonb, array[]::text[], 40, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'renewal-check-in', 'ar', 1, 'active', p.id, null, 'email', 'renewal', 'عميل — سؤال ودّي', null, '{"text":"مرحبًا {{firstName}}، كيف تسير الأمور مع Studio ATS في {{company}} حتى الآن؟ إن كان هناك ما يمكن تحسينه، أخبرني وسأنقله إلى فريق Studio ATS."}'::jsonb, array[]::text[], 41, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-first-contact', 'ar', 1, 'active', p.id, null, 'email', 'first_contact', 'التواصل الأول', null, '{"subject":"{{company}} — تحويل الاهتمام على الإنترنت إلى طلبات","preview":"سؤال سريع عن كيفية تواصل العملاء الجدد معك.","body":"مرحبًا {{firstName}}،\n\nاطّلعت على {{company}} وأعجبني عملكم حقًا.\n\nسؤال سريع: عندما يكتشفكم أحد على الإنترنت، ماذا يحدث بعد ذلك؟ يتلقى كثير من المهنيين الطلبات عبر خليط من النماذج ووسائل التواصل والرسائل — دون التفاصيل التي يحتاجونها.\n\nيتولى Studio ATS ذلك: مساحة مهنية تعرض أعمالكم، وتؤهّل كل طلب، وتساعد على حجز الموعد. تُبنى وتُصان من أجلكم.\n\nإليكم لمحة مدتها 3 دقائق عن قطاعكم:","cta":"عرض اللمحة"}'::jsonb, array[]::text[], 50, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-follow-up', 'ar', 1, 'active', p.id, null, 'email', 'follow_up', 'متابعة بعد 3 أيام', null, '{"subject":"رد: {{company}} — تحويل الاهتمام على الإنترنت إلى طلبات","preview":"أعيد هذه الرسالة إلى أعلى بريدك.","body":"مرحبًا {{firstName}}،\n\nأعيد رسالتي فقط إلى أعلى بريدك. إن كانت الطلبات التي تصل دون التفاصيل الصحيحة أمرًا مألوفًا لديك، فإن Studio ATS يستحق 3 دقائق.\n\nوإن لم يكن الأمر أولوية الآن، فلا مشكلة إطلاقًا — أخبرني ولن أتابع بعد ذلك.","cta":"عرض الصفحة"}'::jsonb, array[]::text[], 51, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-call', 'ar', 1, 'active', p.id, null, 'email', 'after_call', 'بعد المكالمة — ملخّص', null, '{"subject":"مكالمتنا — الخطوات التالية لـ {{company}}","preview":"ما ناقشناه والخطوة التالية.","body":"مرحبًا {{firstName}}،\n\nشكرًا على وقتك اليوم. ما فهمته:\n• كيف يتواصل معك العملاء الجدد اليوم\n• ما تودّ تحسينه\n\nكل ما يتعلق بـ Studio ATS — ما هو مشمول وكيف يعمل والسعر الرسمي — موجود في هذه الصفحة:","cta":"فتح صفحتي في Studio ATS"}'::jsonb, array[]::text[], 52, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-proposal', 'ar', 1, 'active', p.id, null, 'email', 'proposal', 'العرض', null, '{"subject":"عرض Studio ATS لـ {{company}}","preview":"كل شيء في صفحة واحدة، بما في ذلك السعر.","body":"مرحبًا {{firstName}}،\n\nكما وعدتك، إليك عرض Studio ATS الكامل لـ {{company}}. ستجد فيه ما هو مشمول، وكيف يجري الإعداد، والسعر والشروط الرسمية.\n\nأنا في خدمتك لأي سؤال.","cta":"عرض العرض"}'::jsonb, array[]::text[], 53, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-social-not-enough', 'ar', 1, 'active', p.id, null, 'email', 'objection', 'وسائل التواصل الاجتماعي لا تكفي', null, '{"subject":"وسائل التواصل تعرض عملك. هل تجلب لك طلبات؟","preview":"لماذا تتكامل وسائل التواصل الاجتماعي وStudio ATS.","body":"مرحبًا {{firstName}}،\n\nوسائل التواصل الخاصة بك تعرض عملك جيدًا — احتفظ بها. السؤال هو ماذا يحدث بعد الاهتمام: رسالة تضيع بين غيرها، أو طلب بلا تفاصيل، أو مكالمة لا تستطيع الرد عليها.\n\nStudio ATS هو المكان الذي يتحول فيه هذا الاهتمام إلى طلب كامل، في مساحة تتحكم بها. إنه يكمّل حساباتك الاجتماعية؛ ولا يحلّ محلّها.","cta":"شاهد كيف يعمل"}'::jsonb, array['instagram', 'facebook', 'وسائل التواصل الاجتماعي', 'social media']::text[], 54, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-last-follow-up', 'ar', 1, 'active', p.id, null, 'email', 'no_response', 'المتابعة الأخيرة', null, '{"subject":"هل أغلق ملفك؟","preview":"رسالة أخيرة — ثم أتوقف.","body":"مرحبًا {{firstName}}،\n\nبما أنني لم أتلقَّ ردًا، أفترض أن الوقت غير مناسب — لن أتابع بعد الآن.\n\nإذا تغيّرت الأمور، فالصفحة تبقى متاحة.","cta":"الاحتفاظ بالصفحة"}'::jsonb, array[]::text[], 55, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-social-media', 'ar', 1, 'active', p.id, null, null, 'objection', '«لديّ وسائل تواصل اجتماعي بالفعل.»', null, '{"objection":"«لديّ وسائل تواصل اجتماعي بالفعل.»","meaning":"تبدو لهم وسائل التواصل ظهورًا كافيًا — أو لا يرون ما ينقص.","questions":["أين يرسل إليك الناس طلباتهم اليوم؟","ماذا يحدث لطلب يصل مساء السبت؟"],"short":"وسائل التواصل تعرض عملك. ويحوّل Studio ATS هذا الاهتمام إلى طلبات كاملة، في مساحة تتحكم بها.","long":"احتفظ بوسائل التواصل: إنها ممتازة لعرض عملك. لكن الرسالة الخاصة ليست طلبًا — لا ميزانية ولا توقيت، وتضيع بين رسائل أخرى، والمنصة هي من تقرر من يراك. Studio ATS هو المكان المهني الذي يتحول فيه الاهتمام إلى طلب كامل يمكنك الرد عليه دفعة واحدة.","nextStep":"أرسل صفحة البيع واقترح عليهم مقارنتها بحسابهم."}'::jsonb, array['instagram', 'facebook', 'وسائل التواصل الاجتماعي', 'social media', 'tiktok']::text[], 70, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'word-of-mouth', 'ar', 1, 'active', p.id, null, null, 'objection', '«عملائي يأتون بالتوصية الشفهية.»', null, '{"objection":"«عملائي يأتون بالتوصية الشفهية.»","meaning":"هم فخورون بسمعتهم — ولا يرون علاقة ذلك بالحضور على الإنترنت.","questions":["عندما يوصي بك صديق، ماذا يفعل ذلك الشخص قبل الاتصال؟","هل هناك فترات أهدأ خلال السنة؟"],"short":"التوصية الشفهية تجلب إليك الناس. وStudio ATS يضمن أن يتصلوا بك بعد البحث عنك.","long":"هذا دليل على عمل ممتاز. لكن اليوم، حتى العميل الموصى به يتحقق على الإنترنت قبل الاتصال. إن وجد القليل، يتردد بعضهم أو يتصل بغيرك. لا يحلّ Studio ATS محل التوصية الشفهية: بل يؤكدها.","nextStep":"اقترح عليهم أن يبحثوا عن أنفسهم كما يفعل العميل."}'::jsonb, array['التوصية الشفهية', 'word of mouth', 'التوصيات', 'referrals']::text[], 71, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-online-selling', 'ar', 1, 'active', p.id, null, null, 'objection', '«لا أحتاج إلى البيع عبر الإنترنت.»', null, '{"objection":"«لا أحتاج إلى البيع عبر الإنترنت.»","meaning":"يظنون أن Studio ATS متجر إلكتروني.","questions":["كيف يتواصل معك عميل جديد اليوم؟","ما الذي تحتاج إلى معرفته قبل تقديم عرض سعر؟"],"short":"Studio ATS ليس متجرًا إلكترونيًا: إنه يساعد من لا يعرفونك بعد على الثقة بك وإرسال طلب حقيقي إليك.","long":"أنت لا تبيع عبر الإنترنت — بل تبيع عبر الحديث وعروض الأسعار. يحضّر Studio ATS هذه المحادثات: يرى الناس عملك، ويفهمون ما تقدّمه، ويرسلون طلبًا بالتفاصيل الصحيحة. يبقى البيع معك أنت.","nextStep":"اعرض قسم «كيف يعمل» في صفحة البيع."}'::jsonb, array['التجارة الإلكترونية', 'البيع عبر الإنترنت', 'sell online', 'متجر']::text[], 72, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-time', 'ar', 1, 'active', p.id, null, null, 'objection', '«لن يكون لديّ وقت للرد.»', null, '{"objection":"«لن يكون لديّ وقت للرد.»","meaning":"يخشون مزيدًا من العمل أو الأعمال الإدارية.","questions":["كم من الوقت تقضي اليوم في مكالمات لا تؤدي إلى شيء؟","ما الذي يساعدك على الرد بسرعة أكبر؟"],"short":"صُمّم Studio ATS لتوفير الوقت: تصل الطلبات كاملة، فترد مرة واحدة.","long":"إنه مصمّم تحديدًا للمشغولين. يبني فريق Studio ATS كل شيء ويصونه. تصل الطلبات بالتفاصيل اللازمة إلى مكان واحد، فلا تضيّع وقتك في ملاحقة المعلومات أو معاودة الاتصال بطلبات غامضة.","nextStep":"اعرض إرسال الصفحة ليطّلعوا عليها مساءً."}'::jsonb, array['الوقت', 'time', 'مشغول', 'busy']::text[], 73, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'too-expensive', 'ar', 1, 'active', p.id, null, null, 'objection', '«إنه مكلف جدًا.»', null, '{"objection":"«إنه مكلف جدًا.»","meaning":"يقارنونه بموقع رخيص، أو لا يرون القيمة بعد.","questions":["كم يساوي عميل جديد بالنسبة إليك؟","بماذا تقارنه؟"],"short":"قارنه بقيمة العملاء الذين يساعدك على كسبهم — لا بسعر موقع بسيط.","long":"Studio ATS ليس موقعًا بسيطًا: إنه المسار الكامل من الزيارة الأولى حتى الطلب، يُبنى ويُصان من أجلك. يرى كثير من المهنيين الأمر هكذا: كم يساوي عميل جديد واحد؟ السعر رسمي وموحّد للجميع — لن تحصل على سعر أفضل بالتفاوض في مكان آخر.","nextStep":"لا تقدّم خصمًا ولا تَعِد بنتيجة أبدًا. أرسل قسم العرض من الصفحة."}'::jsonb, array['السعر', 'price', 'مكلف', 'expensive', 'الميزانية']::text[], 74, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-website', 'ar', 1, 'active', p.id, null, null, 'objection', '«لديّ موقع بالفعل.»', null, '{"objection":"«لديّ موقع بالفعل.»","meaning":"يظنون أنه يؤدي المهمة نفسها.","questions":["كم طلبًا يجلب لك شهريًا؟","ماذا يحدث بعد أن يملأ أحدهم نموذجك؟"],"short":"احتفظ به إن كان يعمل. يركّز Studio ATS على ما نادرًا ما يفعله الموقع: تأهيل الطلبات وتسهيل المواعيد.","long":"الموقع يعرض؛ وStudio ATS يحوّل. السؤال ليس هل لديك موقع، بل هل يحوّل الزوار إلى طلبات كاملة ومواعيد. إن كان موقعك يفعل ذلك، فممتاز. وإن لم يكن، فهذا بالضبط الجزء الذي يتولاه Studio ATS.","nextStep":"اقترح أن تنظرا معًا في نموذج الاتصال الحالي لديهم."}'::jsonb, array['موقع', 'website', 'لديّ موقع', 'already']::text[], 75, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'think-about-it', 'ar', 1, 'active', p.id, null, null, 'objection', '«أحتاج إلى التفكير.»', null, '{"objection":"«أحتاج إلى التفكير.»","meaning":"هناك أمر غير واضح، أو أن الوقت غير مناسب.","questions":["ما الذي تحتاج إلى معرفته لتقرر؟","هل المسألة في التوقيت أم الميزانية أم شيء آخر؟"],"short":"بالتأكيد. ما الأمر الوحيد الذي تحتاج إلى توضيحه لتقرر؟","long":"أخذ الوقت أمر طبيعي. عادةً يبقى سؤال معلّق — السعر أو الجدول الزمني أو كيف سيعمل في حالتهم. اسأل عنه، وأجب بدقة، ثم اتفقا على موعد للحديث مجددًا.","nextStep":"اتفق على موعد للمتابعة وسجّله في CRM."}'::jsonb, array['التفكير', 'think', 'لاحقًا', 'later']::text[], 76, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'not-now', 'ar', 1, 'active', p.id, null, null, 'objection', '«ليس الآن.»', null, '{"objection":"«ليس الآن.»","meaning":"موسم مزدحم، أو أولويات أخرى.","questions":["متى يكون الوقت أنسب؟","ما فترتك الأهدأ؟"],"short":"مفهوم — متى يكون من المناسب أن نتحدث مجددًا؟","long":"احترم ذلك وخطّط: أفضل وقت لإعداد Studio ATS غالبًا ما يكون قبيل فترة مزدحمة، ليعمل عندما تصل الطلبات. اسأل متى تعود إليهم ودوّن ذلك.","nextStep":"ضع تذكيرًا في CRM — دون إلحاح أبدًا."}'::jsonb, array['ليس الآن', 'not now', 'التوقيت', 'الموسم']::text[], 77, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
